INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('html-base','structure',1,1,'published','{"it":"La struttura di una pagina","en":"The structure of a page"}','[{"t":"p","text":{"it":"HTML descrive il **contenuto** di una pagina usando i `tag`: parole tra parentesi angolari. Quasi tutti si aprono e si chiudono, e quello che sta in mezzo è il contenuto dell’elemento.","en":"HTML describes the **content** of a page using `tags`: words between angle brackets. Most of them open and close, and what sits in between is the content of the element."}},{"t":"code","code":"<!doctype html>\\n<html lang=\\"it\\">\\n  <head>\\n    <meta charset=\\"utf-8\\">\\n    <title>La mia pagina</title>\\n  </head>\\n  <body>\\n    <h1>Ciao mondo</h1>\\n  </body>\\n</html>","lang":"html"},{"t":"p","text":{"it":"`<!doctype html>` dice al browser che è una pagina moderna. Dentro `<head>` vanno le informazioni sulla pagina, che non si vedono nella pagina stessa. Dentro `<body>` va tutto ciò che si vede.","en":"`<!doctype html>` tells the browser this is a modern page. `<head>` holds information about the page, which is not shown on the page itself. `<body>` holds everything that is visible."}},{"t":"tip","text":{"it":"Il contenuto di `<title>` è il testo che compare nella scheda del browser.","en":"The content of `<title>` is the text shown on the browser tab."}}]','{"lang":"html","prompt":{"it":"Scrivi nel `body` un titolo `h1` con il testo **Ciao mondo**.","en":"Write an `h1` heading in the `body` with the text **Ciao mondo**."},"start":"<!doctype html>\\n<html lang=\\"it\\">\\n  <head>\\n    <title>Prima pagina</title>\\n  </head>\\n  <body>\\n\\n  </body>\\n</html>","html":"","checks":[{"sel":"h1","text":"","label":{"it":"C’è un titolo `h1`","en":"There is an `h1` heading"}},{"sel":"h1","text":"Ciao mondo","label":{"it":"Il titolo dice «Ciao mondo»","en":"The heading says “Ciao mondo”"}}],"hint":"<h1>Ciao mondo</h1>"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('html-base','text',2,1,'published','{"it":"Titoli e paragrafi","en":"Headings and paragraphs"}','[{"t":"p","text":{"it":"I titoli vanno da `<h1>` a `<h6>`: `<h1>` è il più importante e di solito ce n’è uno per pagina. I paragrafi si scrivono con `<p>`.","en":"Headings go from `<h1>` to `<h6>`: `<h1>` is the most important and there is usually one per page. Paragraphs use `<p>`."}},{"t":"code","code":"<h1>Ricette</h1>\\n<h2>Primi piatti</h2>\\n<p>La pasta si cuoce in acqua <strong>salata</strong>.</p>\\n<p>Il sugo va <em>assaggiato</em> spesso.</p>","lang":"html"},{"t":"p","text":{"it":"`<strong>` indica un testo importante e `<em>` un’enfasi: comunicano un significato, non solo un aspetto. `<br>` va a capo e non ha tag di chiusura.","en":"`<strong>` marks important text and `<em>` emphasis: they carry meaning, not just looks. `<br>` is a line break and has no closing tag."}},{"t":"tip","text":{"it":"Scegli il titolo per la sua importanza, non per la sua grandezza: all’aspetto ci penserà il CSS.","en":"Choose a heading for its importance, not its size: CSS will take care of the look."}}]','{"lang":"html","prompt":{"it":"Aggiungi un titolo `h2` e un paragrafo `p` che contenga una parola in `strong`.","en":"Add an `h2` heading and a `p` paragraph containing a word in `strong`."},"start":"<h1>Il mio blog</h1>","html":"","checks":[{"sel":"h2","text":"","label":{"it":"C’è un titolo `h2`","en":"There is an `h2` heading"}},{"sel":"p","text":"","label":{"it":"C’è un paragrafo","en":"There is a paragraph"}},{"sel":"p strong","text":"","label":{"it":"Il paragrafo contiene `strong`","en":"The paragraph contains `strong`"}}],"hint":"<h2>Le novità</h2>\\n<p>Un testo <strong>importante</strong>.</p>"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('html-base','links',3,1,'published','{"it":"Link e immagini","en":"Links and images"}','[{"t":"p","text":{"it":"Gli **attributi** aggiungono informazioni a un tag e si scrivono nel tag di apertura, come `nome=\\"valore\\"`. Un link è un tag `<a>` con l’attributo `href`.","en":"**Attributes** add information to a tag and go in the opening tag, as `name=\\"value\\"`. A link is an `<a>` tag with the `href` attribute."}},{"t":"code","code":"<a href=\\"https://example.com\\">Vai al sito</a>\\n<a href=\\"contatti.html\\">Contatti</a>\\n<img src=\\"gatto.jpg\\" alt=\\"Un gatto rosso che dorme\\">","lang":"html"},{"t":"p","text":{"it":"`<img>` mostra un’immagine: `src` dice dove si trova il file, `alt` la descrive a chi non può vederla. Anche `<img>` non ha tag di chiusura.","en":"`<img>` shows an image: `src` says where the file is, `alt` describes it to whoever cannot see it. `<img>` has no closing tag either."}},{"t":"tip","text":{"it":"Un `alt` utile descrive ciò che l’immagine comunica. Se è solo decorativa, scrivi `alt=\\"\\"`.","en":"A useful `alt` describes what the image conveys. If it is only decorative, write `alt=\\"\\"`."}}]','{"lang":"html","prompt":{"it":"Crea un link a `https://example.com` con il testo **Scopri** e un’immagine `logo.png` con un `alt`.","en":"Create a link to `https://example.com` with the text **Scopri** and a `logo.png` image with an `alt`."},"start":"","html":"","checks":[{"sel":"a[href=\\"https://example.com\\"]","text":"","label":{"it":"Il link punta a example.com","en":"The link points to example.com"}},{"sel":"a","text":"Scopri","label":{"it":"Il testo del link è «Scopri»","en":"The link text is “Scopri”"}},{"sel":"img[src=\\"logo.png\\"]","text":"","label":{"it":"C’è l’immagine `logo.png`","en":"There is the `logo.png` image"}},{"sel":"img[alt]:not([alt=\\"\\"])","text":"","label":{"it":"L’immagine ha un `alt`","en":"The image has an `alt`"}}],"hint":"<a href=\\"https://example.com\\">Scopri</a>\\n<img src=\\"logo.png\\" alt=\\"Logo\\">"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('html-base','lists',4,1,'published','{"it":"Le liste","en":"Lists"}','[{"t":"p","text":{"it":"`<ul>` crea una lista puntata, `<ol>` una numerata. Ogni voce è un `<li>`, in entrambi i casi.","en":"`<ul>` creates a bulleted list, `<ol>` a numbered one. Each item is an `<li>`, in both cases."}},{"t":"code","code":"<ul>\\n  <li>Pane</li>\\n  <li>Latte</li>\\n</ul>\\n\\n<ol>\\n  <li>Accendi il forno</li>\\n  <li>Inforna</li>\\n</ol>","lang":"html"},{"t":"p","text":{"it":"Una lista può stare dentro un’altra: la lista interna va **dentro** un `<li>`. Usa `<ol>` quando l’ordine conta.","en":"A list can sit inside another: the inner list goes **inside** an `<li>`. Use `<ol>` when the order matters."}}]','{"lang":"html","prompt":{"it":"Crea una lista numerata con tre passaggi.","en":"Create a numbered list with three steps."},"start":"","html":"","checks":[{"sel":"ol","text":"","label":{"it":"C’è una lista numerata","en":"There is a numbered list"}},{"sel":"ol > li:nth-child(3)","text":"","label":{"it":"Ha almeno tre voci","en":"It has at least three items"}}],"hint":"<ol>\\n  <li>Uno</li>\\n  <li>Due</li>\\n  <li>Tre</li>\\n</ol>"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('html-base','tables',5,2,'published','{"it":"Le tabelle","en":"Tables"}','[{"t":"p","text":{"it":"Le tabelle servono a mostrare **dati**, non a impaginare. `<table>` contiene righe `<tr>`, che contengono celle: `<th>` per le intestazioni e `<td>` per i dati.","en":"Tables are for showing **data**, not for page layout. `<table>` contains `<tr>` rows, which contain cells: `<th>` for headers and `<td>` for data."}},{"t":"code","code":"<table>\\n  <thead>\\n    <tr><th>Città</th><th>Abitanti</th></tr>\\n  </thead>\\n  <tbody>\\n    <tr><td>Udine</td><td>97 000</td></tr>\\n  </tbody>\\n</table>","lang":"html"},{"t":"p","text":{"it":"`<thead>` e `<tbody>` separano intestazione e dati. `colspan=\\"2\\"` fa occupare a una cella due colonne, `rowspan=\\"2\\"` due righe.","en":"`<thead>` and `<tbody>` separate header and data. `colspan=\\"2\\"` makes a cell span two columns, `rowspan=\\"2\\"` two rows."}}]','{"lang":"html","prompt":{"it":"Crea una tabella con una riga di intestazione (`th`) e una riga di dati (`td`).","en":"Create a table with a header row (`th`) and a data row (`td`)."},"start":"<table>\\n\\n</table>","html":"","checks":[{"sel":"table tr th","text":"","label":{"it":"C’è una cella `th`","en":"There is a `th` cell"}},{"sel":"table tr td","text":"","label":{"it":"C’è una cella `td`","en":"There is a `td` cell"}},{"sel":"table tr:nth-of-type(1)","text":"","label":{"it":"Le celle stanno in una riga `tr`","en":"The cells sit in a `tr` row"}}],"hint":"<tr><th>Nome</th></tr>\\n<tr><td>Sav</td></tr>"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('html-base','forms',6,2,'published','{"it":"I primi moduli","en":"First forms"}','[{"t":"p","text":{"it":"`<form>` raccoglie i dati dell’utente. Ogni campo `<input>` ha un `type` e un `name`, il nome con cui il dato viene inviato.","en":"`<form>` collects data from the user. Each `<input>` field has a `type` and a `name`, the name the data is sent with."}},{"t":"code","code":"<form action=\\"/iscriviti\\" method=\\"post\\">\\n  <label for=\\"mail\\">Email</label>\\n  <input id=\\"mail\\" name=\\"mail\\" type=\\"email\\" required>\\n  <button type=\\"submit\\">Iscriviti</button>\\n</form>","lang":"html"},{"t":"p","text":{"it":"`<label>` è collegata al campo tramite `for` e `id`: toccando l’etichetta si attiva il campo. `required` rende il campo obbligatorio e `type=\\"email\\"` fa controllare al browser il formato.","en":"`<label>` is tied to the field through `for` and `id`: tapping the label activates the field. `required` makes the field mandatory and `type=\\"email\\"` has the browser check the format."}},{"t":"tip","text":{"it":"Ogni campo deve avere una `label`: un segnaposto `placeholder` non basta, perché sparisce quando si scrive.","en":"Every field needs a `label`: a `placeholder` is not enough, because it disappears while typing."}}]','{"lang":"html","prompt":{"it":"Completa il modulo: un campo `email` obbligatorio con la sua `label` e un pulsante di invio.","en":"Complete the form: a required `email` field with its `label` and a submit button."},"start":"<form>\\n\\n</form>","html":"","checks":[{"sel":"form input[type=\\"email\\"]","text":"","label":{"it":"C’è un campo email","en":"There is an email field"}},{"sel":"form input[required]","text":"","label":{"it":"Il campo è obbligatorio","en":"The field is required"}},{"sel":"form label[for]","text":"","label":{"it":"C’è una `label` con `for`","en":"There is a `label` with `for`"}},{"sel":"form button, form input[type=\\"submit\\"]","text":"","label":{"it":"C’è un pulsante","en":"There is a button"}}],"hint":"<label for=\\"m\\">Email</label>\\n<input id=\\"m\\" type=\\"email\\" required>\\n<button>Invia</button>"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('html-base','entities',7,2,'published','{"it":"Caratteri speciali e commenti","en":"Special characters and comments"}','[{"t":"p","text":{"it":"Alcuni caratteri hanno un significato per l’HTML: per mostrare `<` si scrive un’**entità**, come `&lt;`. Le entità iniziano con `&` e finiscono con `;`.","en":"Some characters mean something to HTML: to show `<` you write an **entity**, like `&lt;`. Entities start with `&` and end with `;`."}},{"t":"code","code":"<p>2 &lt; 3 &amp; 3 &gt; 2</p>\\n<p>Fucina &copy; 2026</p>\\n<!-- Questo non si vede nella pagina -->","lang":"html"},{"t":"p","text":{"it":"I commenti `<!-- … -->` sono note per chi legge il codice: il browser li ignora, ma chiunque può leggerli aprendo il sorgente.","en":"Comments `<!-- … -->` are notes for those reading the code: the browser ignores them, but anyone can read them in the source."}}]','{"lang":"html","prompt":{"it":"Scrivi un paragrafo che contenga l’entità `&copy;`.","en":"Write a paragraph containing the `&copy;` entity."},"start":"<!-- scrivi qui sotto -->","html":"","checks":[{"sel":"p","text":"","label":{"it":"C’è un paragrafo","en":"There is a paragraph"}},{"re":"&copy;","label":{"it":"Usi l’entità `&copy;`","en":"You use the `&copy;` entity"}}],"hint":"<p>Fucina &copy; 2026</p>"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('html-base','page-project',8,2,'published','{"it":"Progetto: la tua prima pagina","en":"Project: your first page"}','[{"t":"p","text":{"it":"Ora metti tutto insieme: una pagina con titolo, testo, immagine, lista e link. Ogni pezzo lo conosci già: la bravura sta nell’**ordine**.","en":"Now put it all together: a page with a heading, text, an image, a list and a link. You already know every piece: the skill is in the **order**."}},{"t":"code","code":"<h1>Ciao, sono Sav</h1>\\n<img src=\\"me.jpg\\" alt=\\"La mia foto\\">\\n<p>Imparo a costruire siti.</p>\\n<ul>\\n  <li>HTML</li>\\n  <li>CSS</li>\\n</ul>\\n<a href=\\"contatti.html\\">Scrivimi</a>","lang":"html"},{"t":"tip","text":{"it":"Scrivi prima il contenuto, poi pensa allo stile: una pagina ben strutturata è già mezza fatta.","en":"Write the content first, then think about style: a well-structured page is already half done."}}]','{"lang":"html","prompt":{"it":"Crea una pagina con un `h1`, un `p`, una lista `ul` con almeno un `li` e un link `a`.","en":"Create a page with an `h1`, a `p`, a `ul` list with at least one `li` and an `a` link."},"start":"","html":"","checks":[{"sel":"h1","text":"","label":{"it":"C’è un titolo","en":"There is a heading"}},{"sel":"p","text":"","label":{"it":"C’è un paragrafo","en":"There is a paragraph"}},{"sel":"ul li","text":"","label":{"it":"C’è una lista","en":"There is a list"}},{"sel":"a","text":"","label":{"it":"C’è un link","en":"There is a link"}}],"hint":"<h1>Ciao</h1>\\n<p>Testo</p>\\n<ul><li>Uno</li></ul>\\n<a href=\\"#\\">Link</a>"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('html-intermediate','attributes',1,1,'published','{"it":"Attributi globali","en":"Global attributes"}','[{"t":"p","text":{"it":"Alcuni attributi valgono su quasi tutti i tag: `id` identifica un elemento, `class` lo raggruppa, `title` aggiunge un suggerimento, `hidden` lo nasconde, `lang` ne indica la lingua.","en":"Some attributes work on almost every tag: `id` identifies an element, `class` groups it, `title` adds a tooltip, `hidden` hides it, `lang` states its language."}},{"t":"code","code":"<p id=\\"intro\\" class=\\"nota grande\\" lang=\\"en\\" title=\\"Una nota\\">Hello!</p>\\n<div hidden>Non mi vedi</div>","lang":"html"},{"t":"p","text":{"it":"Un elemento può avere più classi separate da spazi, ma un solo `id`, unico in tutta la pagina.","en":"An element can have several classes separated by spaces, but only one `id`, unique in the whole page."}}]','{"lang":"html","prompt":{"it":"Crea un paragrafo con `id=\\"intro\\"` e le classi `nota` e `grande`.","en":"Create a paragraph with `id=\\"intro\\"` and the classes `nota` and `grande`."},"start":"","html":"","checks":[{"sel":"p#intro","text":"","label":{"it":"Il paragrafo ha l’id","en":"The paragraph has the id"}},{"sel":"p.nota.grande","text":"","label":{"it":"Ha entrambe le classi","en":"It has both classes"}}],"hint":"<p id=\\"intro\\" class=\\"nota grande\\">Ciao</p>"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('html-intermediate','anchors',2,1,'published','{"it":"Link interni e percorsi","en":"Internal links and paths"}','[{"t":"p","text":{"it":"Un link può portare a un punto della stessa pagina: `href=\\"#contatti\\"` salta all’elemento con `id=\\"contatti\\"`. I percorsi **relativi** partono dalla pagina attuale, quelli **assoluti** includono tutto l’indirizzo.","en":"A link can lead to a spot in the same page: `href=\\"#contatti\\"` jumps to the element with `id=\\"contatti\\"`. **Relative** paths start from the current page, **absolute** ones include the whole address."}},{"t":"code","code":"<a href=\\"#contatti\\">Vai ai contatti</a>\\n<a href=\\"chi-siamo.html\\">Stessa cartella</a>\\n<a href=\\"../index.html\\">Cartella sopra</a>\\n<a href=\\"https://esempio.it/\\">Altro sito</a>\\n<a href=\\"mailto:ciao@esempio.it\\">Scrivimi</a>","lang":"html"},{"t":"p","text":{"it":"`mailto:` apre l’email e `tel:` il telefono. `../` sale di una cartella.","en":"`mailto:` opens email and `tel:` the phone. `../` goes up one folder."}}]','{"lang":"html","prompt":{"it":"Crea un link che salta a `#fine` e un `div` con `id=\\"fine\\"`.","en":"Create a link that jumps to `#fine` and a `div` with `id=\\"fine\\"`."},"start":"","html":"","checks":[{"sel":"a[href=\\"#fine\\"]","text":"","label":{"it":"Il link punta a #fine","en":"The link points to #fine"}},{"sel":"div#fine","text":"","label":{"it":"Il `div` ha l’id","en":"The `div` has the id"}}],"hint":"<a href=\\"#fine\\">Vai</a>\\n<div id=\\"fine\\">Fine</div>"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('html-intermediate','rich-text',3,1,'published','{"it":"Testo ricco","en":"Rich text"}','[{"t":"p","text":{"it":"Oltre a `strong` ed `em` esistono tag per ogni sfumatura del testo: `blockquote` per le citazioni, `code` per il codice, `pre` per il testo preformattato, `abbr` per le sigle, `mark` per evidenziare.","en":"Besides `strong` and `em` there are tags for every shade of text: `blockquote` for quotes, `code` for code, `pre` for preformatted text, `abbr` for abbreviations, `mark` for highlights."}},{"t":"code","code":"<blockquote>Il codice è poesia.</blockquote>\\n<p>Usa <code>console.log</code> per il <abbr title=\\"debug\\">dbg</abbr>.</p>\\n<p>La parola <mark>chiave</mark> è qui.</p>\\n<pre>  rispetta\\n    gli spazi</pre>","lang":"html"},{"t":"p","text":{"it":"`pre` mantiene spazi e a capo così come li scrivi. Tutti gli altri tag li riducono a un solo spazio.","en":"`pre` keeps spaces and line breaks exactly as written. All other tags reduce them to a single space."}}]','{"lang":"html","prompt":{"it":"Scrivi un `blockquote` e un paragrafo con dentro una parola in `mark`.","en":"Write a `blockquote` and a paragraph with a word in `mark`."},"start":"","html":"","checks":[{"sel":"blockquote","text":"","label":{"it":"C’è la citazione","en":"The quote is there"}},{"sel":"p mark","text":"","label":{"it":"C’è la parola evidenziata","en":"The highlighted word is there"}}],"hint":"<blockquote>Forgia!</blockquote>\\n<p>Una <mark>parola</mark>.</p>"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('html-intermediate','embed',4,2,'published','{"it":"Iframe e contenuti esterni","en":"Iframes and embedded content"}','[{"t":"p","text":{"it":"`iframe` inserisce un’altra pagina nella tua: mappe, video, widget. Dagli sempre un `title`, per chi usa un lettore di schermo.","en":"`iframe` puts another page inside yours: maps, videos, widgets. Always give it a `title`, for screen reader users."}},{"t":"code","code":"<iframe\\n  src=\\"https://esempio.it/mappa\\"\\n  title=\\"La nostra sede\\"\\n  width=\\"400\\" height=\\"300\\"\\n  loading=\\"lazy\\"></iframe>","lang":"html"},{"t":"p","text":{"it":"Un `iframe` carica codice di altri: con `sandbox` limiti quello che può fare, e `loading=\\"lazy\\"` evita di caricarlo finché non serve.","en":"An `iframe` loads other people’s code: `sandbox` limits what it can do, and `loading=\\"lazy\\"` avoids loading it until needed."}}]','{"lang":"html","prompt":{"it":"Inserisci un `iframe` con `src=\\"mappa.html\\"`, un `title` e `loading=\\"lazy\\"`.","en":"Add an `iframe` with `src=\\"mappa.html\\"`, a `title` and `loading=\\"lazy\\"`."},"start":"","html":"","checks":[{"sel":"iframe[src=\\"mappa.html\\"]","text":"","label":{"it":"Il `src` è giusto","en":"The `src` is right"}},{"sel":"iframe[title]","text":"","label":{"it":"C’è il `title`","en":"The `title` is there"}},{"sel":"iframe[loading=\\"lazy\\"]","text":"","label":{"it":"Il caricamento è pigro","en":"Loading is lazy"}}],"hint":"<iframe src=\\"mappa.html\\" title=\\"Mappa\\" loading=\\"lazy\\"></iframe>"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('html-intermediate','more-inputs',5,2,'published','{"it":"Campi per ogni esigenza","en":"A field for every need"}','[{"t":"p","text":{"it":"I campi moderni fanno molto da soli: `date` apre un calendario, `range` un cursore, `color` una tavolozza, `number` accetta solo cifre, `search` è fatto per le ricerche.","en":"Modern fields do a lot by themselves: `date` opens a calendar, `range` a slider, `color` a palette, `number` takes digits only, `search` is made for searching."}},{"t":"code","code":"<input type=\\"date\\" min=\\"2026-01-01\\">\\n<input type=\\"range\\" min=\\"0\\" max=\\"10\\" step=\\"2\\">\\n<input type=\\"color\\" value=\\"#FF5B2E\\">\\n<select name=\\"corso\\">\\n  <option value=\\"html\\">HTML</option>\\n  <option value=\\"css\\" selected>CSS</option>\\n</select>","lang":"html"},{"t":"p","text":{"it":"In `select`, `selected` indica l’opzione scelta all’inizio. `value` è ciò che riceve il server, il testo è ciò che vede l’utente.","en":"In `select`, `selected` marks the option chosen at the start. `value` is what the server gets, the text is what the user sees."}}]','{"lang":"html","prompt":{"it":"Crea un campo `range` da `0` a `10` e un campo `date`.","en":"Create a `range` field from `0` to `10` and a `date` field."},"start":"","html":"","checks":[{"sel":"input[type=\\"range\\"][min=\\"0\\"][max=\\"10\\"]","text":"","label":{"it":"Il cursore va da 0 a 10","en":"The slider goes from 0 to 10"}},{"sel":"input[type=\\"date\\"]","text":"","label":{"it":"C’è la data","en":"The date is there"}}],"hint":"<input type=\\"range\\" min=\\"0\\" max=\\"10\\">\\n<input type=\\"date\\">"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('html-advanced','semantic',1,2,'published','{"it":"HTML semantico","en":"Semantic HTML"}','[{"t":"p","text":{"it":"I tag semantici dicono **che cosa è** un blocco, non come appare. Motori di ricerca e screen reader li usano per capire la pagina.","en":"Semantic tags say **what a block is**, not how it looks. Search engines and screen readers use them to understand the page."}},{"t":"code","code":"<header>Logo e titolo</header>\\n<nav>Menu principale</nav>\\n<main>\\n  <article>\\n    <h1>Una notizia</h1>\\n    <section>Una parte della notizia</section>\\n  </article>\\n  <aside>Articoli correlati</aside>\\n</main>\\n<footer>Contatti</footer>","lang":"html"},{"t":"p","text":{"it":"`<main>` è il contenuto principale e ce n’è uno solo per pagina. `<article>` è un contenuto che ha senso da solo; `<section>` è una parte tematica, di solito con un titolo. `<div>` non ha significato: usalo solo per raggruppare a fini di stile.","en":"`<main>` is the main content and there is only one per page. `<article>` is content that stands on its own; `<section>` is a thematic part, usually with a heading. `<div>` has no meaning: use it only to group for styling."}}]','{"lang":"html","prompt":{"it":"Struttura la pagina con `header`, `main` contenente un `article`, e `footer`.","en":"Structure the page with `header`, `main` containing an `article`, and `footer`."},"start":"<body>\\n\\n</body>","html":"","checks":[{"sel":"header","text":"","label":{"it":"C’è un `header`","en":"There is a `header`"}},{"sel":"main article","text":"","label":{"it":"Il `main` contiene un `article`","en":"`main` contains an `article`"}},{"sel":"footer","text":"","label":{"it":"C’è un `footer`","en":"There is a `footer`"}}],"hint":"<header>…</header>\\n<main><article>…</article></main>\\n<footer>…</footer>"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('html-advanced','rich-forms',2,2,'published','{"it":"Moduli ricchi e validazione","en":"Rich forms and validation"}','[{"t":"p","text":{"it":"Il `type` giusto mostra la tastiera adatta e dà controlli gratuiti: `email`, `url`, `tel`, `number`, `date`, `range`, `color`.","en":"The right `type` shows the suitable keyboard and gives free checks: `email`, `url`, `tel`, `number`, `date`, `range`, `color`."}},{"t":"code","code":"<fieldset>\\n  <legend>Taglia</legend>\\n  <label><input type=\\"radio\\" name=\\"taglia\\" value=\\"s\\"> S</label>\\n  <label><input type=\\"radio\\" name=\\"taglia\\" value=\\"m\\"> M</label>\\n</fieldset>\\n\\n<label for=\\"eta\\">Età</label>\\n<input id=\\"eta\\" type=\\"number\\" min=\\"18\\" max=\\"99\\">\\n\\n<label for=\\"cap\\">CAP</label>\\n<input id=\\"cap\\" pattern=\\"[0-9]{5}\\" title=\\"5 cifre\\">\\n\\n<select name=\\"paese\\">\\n  <option value=\\"it\\">Italia</option>\\n</select>","lang":"html"},{"t":"p","text":{"it":"`<fieldset>` e `<legend>` raggruppano campi legati tra loro. I `radio` con lo stesso `name` si escludono a vicenda. `min`, `max` e `pattern` validano il dato nel browser.","en":"`<fieldset>` and `<legend>` group related fields. `radio` inputs with the same `name` exclude one another. `min`, `max` and `pattern` validate the value in the browser."}},{"t":"tip","text":{"it":"La validazione del browser aiuta l’utente, ma il server deve sempre ricontrollare i dati.","en":"Browser validation helps the user, but the server must always check the data again."}}]','{"lang":"html","prompt":{"it":"Crea un `fieldset` con `legend` e due `radio` con lo stesso `name` «piano».","en":"Create a `fieldset` with a `legend` and two `radio` inputs with the same `name` “piano”."},"start":"<form>\\n\\n</form>","html":"","checks":[{"sel":"fieldset legend","text":"","label":{"it":"Il `fieldset` ha una `legend`","en":"The `fieldset` has a `legend`"}},{"sel":"fieldset input[type=\\"radio\\"][name=\\"piano\\"]","text":"","label":{"it":"C’è un `radio` «piano»","en":"There is a “piano” `radio`"}},{"sel":"fieldset input[type=\\"radio\\"][name=\\"piano\\"] ~ input[type=\\"radio\\"][name=\\"piano\\"], fieldset label ~ label input[type=\\"radio\\"][name=\\"piano\\"]","text":"","label":{"it":"Ce ne sono due","en":"There are two of them"}}],"hint":"<fieldset>\\n  <legend>Piano</legend>\\n  <label><input type=\\"radio\\" name=\\"piano\\"> A</label>\\n  <label><input type=\\"radio\\" name=\\"piano\\"> B</label>\\n</fieldset>"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('html-advanced','media',3,2,'published','{"it":"Immagini responsive, audio e video","en":"Responsive images, audio and video"}','[{"t":"p","text":{"it":"`<picture>` e `srcset` fanno scegliere al browser il file più adatto allo schermo: si scaricano meno dati sui telefoni.","en":"`<picture>` and `srcset` let the browser choose the best file for the screen: phones download less data."}},{"t":"code","code":"<picture>\\n  <source srcset=\\"foto.avif\\" type=\\"image/avif\\">\\n  <img src=\\"foto.jpg\\" alt=\\"Il porto al tramonto\\"\\n       width=\\"800\\" height=\\"600\\" loading=\\"lazy\\">\\n</picture>\\n\\n<video src=\\"corso.mp4\\" controls poster=\\"anteprima.jpg\\">\\n  <track kind=\\"captions\\" src=\\"sottotitoli.vtt\\" srclang=\\"it\\">\\n</video>","lang":"html"},{"t":"p","text":{"it":"`width` e `height` riservano lo spazio ed evitano che la pagina salti durante il caricamento. `loading=\\"lazy\\"` rimanda le immagini lontane dallo schermo. In `<video>` e `<audio>` l’attributo `controls` mostra i comandi.","en":"`width` and `height` reserve the space and stop the page jumping while it loads. `loading=\\"lazy\\"` delays images far from the screen. In `<video>` and `<audio>` the `controls` attribute shows the player buttons."}}]','{"lang":"html","prompt":{"it":"Inserisci un `video` con i `controls` e un’immagine con `loading=\\"lazy\\"` e `alt`.","en":"Add a `video` with `controls` and an image with `loading=\\"lazy\\"` and `alt`."},"start":"","html":"","checks":[{"sel":"video[controls]","text":"","label":{"it":"Il video ha i comandi","en":"The video has controls"}},{"sel":"img[loading=\\"lazy\\"]","text":"","label":{"it":"L’immagine è lazy","en":"The image is lazy"}},{"sel":"img[alt]:not([alt=\\"\\"])","text":"","label":{"it":"L’immagine ha un `alt`","en":"The image has an `alt`"}}],"hint":"<video src=\\"v.mp4\\" controls></video>\\n<img src=\\"a.jpg\\" alt=\\"Foto\\" loading=\\"lazy\\">"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('html-advanced','a11y',4,2,'published','{"it":"Accessibilità","en":"Accessibility"}','[{"t":"p","text":{"it":"Una pagina accessibile funziona per tutti, anche da tastiera e con uno screen reader. La prima regola è usare il tag giusto: un `<button>` è già raggiungibile e attivabile con la tastiera, un `<div>` no.","en":"An accessible page works for everyone, keyboard and screen reader included. The first rule is using the right tag: a `<button>` can already be reached and activated with the keyboard, a `<div>` cannot."}},{"t":"code","code":"<button type=\\"button\\" aria-label=\\"Chiudi\\">✕</button>\\n\\n<nav aria-label=\\"Principale\\">…</nav>\\n\\n<p id=\\"aiuto\\">Almeno 8 caratteri</p>\\n<input type=\\"password\\" aria-describedby=\\"aiuto\\">","lang":"html"},{"t":"p","text":{"it":"Gli attributi `aria-*` aggiungono informazioni dove l’HTML non basta: `aria-label` dà un nome a un elemento senza testo, `aria-describedby` collega una descrizione. Rispetta l’ordine dei titoli, senza saltare livelli.","en":"`aria-*` attributes add information where HTML is not enough: `aria-label` names an element with no text, `aria-describedby` links a description. Keep headings in order, without skipping levels."}},{"t":"tip","text":{"it":"La regola d’oro di ARIA: se esiste un tag HTML adatto, usa quello.","en":"The golden rule of ARIA: if a suitable HTML tag exists, use it."}}]','{"lang":"html","prompt":{"it":"Sostituisci il `div` con un vero `button` e dagli un `aria-label` «Chiudi».","en":"Replace the `div` with a real `button` and give it the `aria-label` “Chiudi”."},"start":"<div onclick=\\"chiudi()\\">✕</div>","html":"","checks":[{"sel":"button","text":"","label":{"it":"C’è un `button`","en":"There is a `button`"}},{"sel":"button[aria-label=\\"Chiudi\\"]","text":"","label":{"it":"Ha l’`aria-label` giusto","en":"It has the right `aria-label`"}}],"hint":"<button aria-label=\\"Chiudi\\">✕</button>"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('html-advanced','meta',5,3,'published','{"it":"Metadati e tag interattivi","en":"Metadata and interactive tags"}','[{"t":"p","text":{"it":"In `<head>` i metadati spiegano la pagina agli altri programmi. `viewport` è indispensabile sui telefoni, `description` è il testo che i motori di ricerca possono mostrare, i tag Open Graph definiscono l’anteprima dei link condivisi.","en":"In `<head>`, metadata explains the page to other programs. `viewport` is essential on phones, `description` is the text search engines can show, Open Graph tags define the preview of shared links."}},{"t":"code","code":"<meta name=\\"viewport\\" content=\\"width=device-width, initial-scale=1\\">\\n<meta name=\\"description\\" content=\\"Corsi di HTML e CSS\\">\\n<meta property=\\"og:title\\" content=\\"Fucina\\">\\n<link rel=\\"stylesheet\\" href=\\"style.css\\">","lang":"html"},{"t":"p","text":{"it":"Alcuni tag sono interattivi senza JavaScript: `<details>` e `<summary>` creano una sezione apribile, `<dialog>` una finestra.","en":"Some tags are interactive with no JavaScript: `<details>` and `<summary>` create a collapsible section, `<dialog>` a window."}},{"t":"code","code":"<details>\\n  <summary>Come funziona?</summary>\\n  <p>Si apre con un tocco.</p>\\n</details>","lang":"html"}]','{"lang":"html","prompt":{"it":"Crea un `details` con un `summary` e un paragrafo.","en":"Create a `details` with a `summary` and a paragraph."},"start":"","html":"","checks":[{"sel":"details summary","text":"","label":{"it":"C’è un `summary` in `details`","en":"There is a `summary` in `details`"}},{"sel":"details p","text":"","label":{"it":"C’è un paragrafo da aprire","en":"There is a paragraph to reveal"}}],"hint":"<details>\\n  <summary>Titolo</summary>\\n  <p>Testo</p>\\n</details>"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('html-advanced','data-attrs',6,3,'published','{"it":"Attributi data e template","en":"Data attributes and templates"}','[{"t":"p","text":{"it":"Gli attributi `data-*` conservano informazioni personalizzate su un elemento: li leggeranno CSS e JavaScript. Il nome dopo `data-` lo scegli tu.","en":"`data-*` attributes keep custom information on an element, for CSS and JavaScript to read. You choose the name after `data-`."}},{"t":"code","code":"<button data-prodotto=\\"42\\" data-colore=\\"rosso\\">Compra</button>\\n\\n<template id=\\"riga\\">\\n  <li class=\\"voce\\"></li>\\n</template>","lang":"html"},{"t":"p","text":{"it":"`<template>` contiene HTML che il browser non mostra: è uno stampo da copiare al momento giusto.","en":"`<template>` holds HTML the browser does not show: it is a mould to copy at the right moment."}}]','{"lang":"html","prompt":{"it":"Crea un `button` con l’attributo `data-prezzo` uguale a `10`.","en":"Create a `button` with the `data-prezzo` attribute equal to `10`."},"start":"","html":"","checks":[{"sel":"button[data-prezzo=\\"10\\"]","text":"","label":{"it":"Il bottone ha `data-prezzo=\\"10\\"`","en":"The button has `data-prezzo=\\"10\\"`"}}],"hint":"<button data-prezzo=\\"10\\">Compra</button>"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('html-advanced','seo',7,3,'published','{"it":"SEO e condivisione","en":"SEO and sharing"}','[{"t":"p","text":{"it":"I motori di ricerca leggono `title` e `description`. Le reti sociali leggono i tag **Open Graph**, che decidono titolo e immagine quando condividi un link.","en":"Search engines read `title` and `description`. Social networks read **Open Graph** tags, which set the title and image when you share a link."}},{"t":"code","code":"<title>Fucina: impara il web giocando</title>\\n<meta name=\\"description\\" content=\\"Corsi a livelli di HTML e CSS.\\">\\n<meta property=\\"og:title\\" content=\\"Fucina\\">\\n<meta property=\\"og:image\\" content=\\"https://esempio.it/og.png\\">\\n<link rel=\\"canonical\\" href=\\"https://esempio.it/\\">","lang":"html"},{"t":"p","text":{"it":"`canonical` indica l’indirizzo ufficiale di una pagina raggiungibile da più URL, così i motori non la considerano un doppione.","en":"`canonical` gives the official address of a page reachable from several URLs, so engines do not treat it as a duplicate."}}]','{"lang":"html","prompt":{"it":"Aggiungi nel `head` un `meta` con `name=\\"description\\"`.","en":"Add to the `head` a `meta` with `name=\\"description\\"`."},"start":"<head>\\n  <title>Fucina</title>\\n</head>","html":"","checks":[{"re":"<meta[^>]+name=\\"description\\"","label":{"it":"C’è la description","en":"The description is there"}}],"hint":"<head>\\n  <title>Fucina</title>\\n  <meta name=\\"description\\" content=\\"Impara\\">\\n</head>"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('css-base','selectors',1,1,'published','{"it":"Regole e selettori","en":"Rules and selectors"}','[{"t":"p","text":{"it":"Il CSS descrive l’**aspetto** della pagina con delle regole. Una regola ha un selettore, che sceglie gli elementi, e delle dichiarazioni `proprietà: valore`.","en":"CSS describes the **look** of the page with rules. A rule has a selector, which picks the elements, and `property: value` declarations."}},{"t":"code","code":"p { color: navy; }          /* tutti i paragrafi */\\n.nota { font-size: 14px; }  /* la classe nota */\\n#box { width: 200px; }      /* l’id box */\\nnav a { color: red; }       /* i link dentro nav */\\na:hover { color: green; }   /* il link sotto al mouse */","lang":"css"},{"t":"p","text":{"it":"Una classe si riusa quante volte vuoi, un `id` è unico nella pagina. `:hover` è una pseudo-classe: indica uno stato dell’elemento. Lo spazio tra due selettori significa «dentro».","en":"A class can be reused as often as you want, an `id` is unique in the page. `:hover` is a pseudo-class: it marks a state of the element. The space between two selectors means “inside”."}}]','{"lang":"css","prompt":{"it":"Colora i paragrafi con la classe `nota` di rosso (`red`) e imposta a `200px` la larghezza dell’id `box`.","en":"Colour the paragraphs with the `nota` class red (`red`) and set the width of the `box` id to `200px`."},"start":"/* Scrivi qui le tue regole */","html":"<h1 class=\\"titolo\\">Fucina</h1>\\n<p>Il primo paragrafo.</p>\\n<p class=\\"nota\\">Una nota.</p>\\n<div id=\\"box\\">Una scatola</div>\\n<a href=\\"#\\">Un link</a>","checks":[{"sel":".nota","prop":"color","value":"rgb(255, 0, 0)","label":{"it":"La nota è rossa","en":"The note is red"}},{"sel":"#box","prop":"width","value":"200px","label":{"it":"Il box è largo 200px","en":"The box is 200px wide"}}],"hint":".nota { color: red; }\\n#box { width: 200px; }"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('css-base','colors',2,1,'published','{"it":"Colori e testi","en":"Colours and text"}','[{"t":"p","text":{"it":"Un colore si può scrivere in molti modi: per nome, in esadecimale, in `rgb()` o in `hsl()`. L’ultimo numero o la barra indicano la trasparenza.","en":"A colour can be written in many ways: by name, in hexadecimal, in `rgb()` or in `hsl()`. A final value after a slash sets the transparency."}},{"t":"code","code":"h1 {\\n  color: #E8590C;\\n  background-color: rgb(255 240 230);\\n  font-family: Georgia, serif;\\n  font-size: 2rem;\\n  font-weight: 700;\\n  line-height: 1.3;\\n  text-align: center;\\n}","lang":"css"},{"t":"p","text":{"it":"`font-family` indica un elenco di caratteri, dal preferito al generico. `rem` è relativo alla dimensione di base del documento: si adatta alle impostazioni dell’utente meglio di `px`.","en":"`font-family` lists fonts, from the preferred one to a generic one. `rem` is relative to the base size of the document: it respects user settings better than `px`."}},{"t":"tip","text":{"it":"Controlla sempre il contrasto: un testo poco leggibile è un testo perso.","en":"Always check the contrast: text that is hard to read is lost text."}}]','{"lang":"css","prompt":{"it":"Centra il testo di `.titolo` e rendilo di colore `#E8590C`.","en":"Centre the text of `.titolo` and give it the colour `#E8590C`."},"start":".titolo {\\n\\n}","html":"<h1 class=\\"titolo\\">Fucina</h1>\\n<p>Il primo paragrafo.</p>\\n<p class=\\"nota\\">Una nota.</p>\\n<div id=\\"box\\">Una scatola</div>\\n<a href=\\"#\\">Un link</a>","checks":[{"sel":".titolo","prop":"text-align","value":"center","label":{"it":"Il titolo è centrato","en":"The heading is centred"}},{"sel":".titolo","prop":"color","value":"rgb(232, 89, 12)","label":{"it":"Il colore è #E8590C","en":"The colour is #E8590C"}}],"hint":".titolo {\\n  text-align: center;\\n  color: #E8590C;\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('css-base','box',3,1,'published','{"it":"Il box model","en":"The box model"}','[{"t":"p","text":{"it":"Ogni elemento è una scatola fatta di quattro strati: il **contenuto**, il `padding` (spazio interno), il `border` e il `margin` (spazio esterno).","en":"Every element is a box made of four layers: the **content**, the `padding` (inner space), the `border` and the `margin` (outer space)."}},{"t":"code","code":"* { box-sizing: border-box; }\\n\\n.card {\\n  width: 300px;\\n  padding: 16px;\\n  border: 1px solid #ccc;\\n  margin: 0 auto;\\n  border-radius: 12px;\\n}","lang":"css"},{"t":"p","text":{"it":"Con `box-sizing: border-box` la larghezza comprende padding e bordo, ed è molto più facile fare i conti. `margin: 0 auto` centra un blocco con una larghezza. Con due valori, il primo è sopra e sotto, il secondo a destra e sinistra.","en":"With `box-sizing: border-box` the width includes padding and border, which makes the maths far easier. `margin: 0 auto` centres a block with a width. With two values, the first is top and bottom, the second right and left."}}]','{"lang":"css","prompt":{"it":"Dai a `#box` un `padding` di `20px` e un `border-radius` di `12px`.","en":"Give `#box` a `padding` of `20px` and a `border-radius` of `12px`."},"start":"#box {\\n  background: #ffe8d6;\\n}","html":"<h1 class=\\"titolo\\">Fucina</h1>\\n<p>Il primo paragrafo.</p>\\n<p class=\\"nota\\">Una nota.</p>\\n<div id=\\"box\\">Una scatola</div>\\n<a href=\\"#\\">Un link</a>","checks":[{"sel":"#box","prop":"padding-top","value":"20px","label":{"it":"Il padding è 20px","en":"The padding is 20px"}},{"sel":"#box","prop":"border-top-left-radius","value":"12px","label":{"it":"Gli angoli sono arrotondati","en":"The corners are rounded"}}],"hint":"padding: 20px;\\nborder-radius: 12px;"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('css-base','display',4,1,'published','{"it":"Display: blocchi e righe","en":"Display: blocks and inlines"}','[{"t":"p","text":{"it":"`display` decide come si comporta la scatola. Un elemento `block` occupa tutta la riga, come `<p>` e `<div>`. Un elemento `inline` scorre nel testo, come `<a>` e `<strong>`, e ignora `width` e `height`.","en":"`display` decides how the box behaves. A `block` element takes the whole line, like `<p>` and `<div>`. An `inline` element flows in the text, like `<a>` and `<strong>`, and ignores `width` and `height`."}},{"t":"code","code":"a.bottone { display: inline-block; padding: 8px 16px; }\\n.nascosto { display: none; }\\n.invisibile { visibility: hidden; }","lang":"css"},{"t":"p","text":{"it":"`inline-block` scorre nel testo ma accetta le dimensioni. `display: none` toglie l’elemento dalla pagina, mentre `visibility: hidden` lo nasconde lasciando il suo spazio.","en":"`inline-block` flows in the text but accepts sizes. `display: none` takes the element off the page, while `visibility: hidden` hides it and leaves its space."}}]','{"lang":"css","prompt":{"it":"Fai diventare il link un `inline-block` con `padding` di `10px`, e nascondi `.nota` con `display: none`.","en":"Turn the link into an `inline-block` with `10px` of `padding`, and hide `.nota` with `display: none`."},"start":"","html":"<h1 class=\\"titolo\\">Fucina</h1>\\n<p>Il primo paragrafo.</p>\\n<p class=\\"nota\\">Una nota.</p>\\n<div id=\\"box\\">Una scatola</div>\\n<a href=\\"#\\">Un link</a>","checks":[{"sel":"a","prop":"display","value":"inline-block","label":{"it":"Il link è inline-block","en":"The link is inline-block"}},{"sel":"a","prop":"padding-left","value":"10px","label":{"it":"Il link ha 10px di padding","en":"The link has 10px of padding"}},{"sel":".nota","prop":"display","value":"none","label":{"it":"La nota è nascosta","en":"The note is hidden"}}],"hint":"a { display: inline-block; padding: 10px; }\\n.nota { display: none; }"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('css-base','position',5,2,'published','{"it":"Il posizionamento","en":"Positioning"}','[{"t":"p","text":{"it":"`position` sposta gli elementi fuori dal flusso normale. Il valore predefinito è `static`. Con `relative` l’elemento resta al suo posto e fa da riferimento per i figli `absolute`.","en":"`position` moves elements out of the normal flow. The default value is `static`. With `relative` the element stays in place and acts as a reference for `absolute` children."}},{"t":"code","code":".card { position: relative; }\\n.etichetta { position: absolute; top: 8px; right: 8px; }\\n.barra { position: sticky; top: 0; }\\n.chat { position: fixed; bottom: 16px; right: 16px; z-index: 10; }","lang":"css"},{"t":"p","text":{"it":"`fixed` resta fermo rispetto allo schermo, `sticky` scorre e poi si ferma alla soglia indicata. `z-index` decide chi sta sopra tra gli elementi posizionati.","en":"`fixed` stays still relative to the screen, `sticky` scrolls and then stops at the given threshold. `z-index` decides who is on top among positioned elements."}}]','{"lang":"css","prompt":{"it":"Rendi `#box` `relative` e sposta `.nota` in `absolute` con `top: 0`.","en":"Make `#box` `relative` and move `.nota` to `absolute` with `top: 0`."},"start":"","html":"<h1 class=\\"titolo\\">Fucina</h1>\\n<p>Il primo paragrafo.</p>\\n<p class=\\"nota\\">Una nota.</p>\\n<div id=\\"box\\">Una scatola</div>\\n<a href=\\"#\\">Un link</a>","checks":[{"sel":"#box","prop":"position","value":"relative","label":{"it":"Il box è relative","en":"The box is relative"}},{"sel":".nota","prop":"position","value":"absolute","label":{"it":"La nota è absolute","en":"The note is absolute"}},{"sel":".nota","prop":"top","value":"0px","label":{"it":"La nota è in alto","en":"The note is at the top"}}],"hint":"#box { position: relative; }\\n.nota { position: absolute; top: 0; }"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('css-base','cascade',6,2,'published','{"it":"Cascata e specificità","en":"Cascade and specificity"}','[{"t":"p","text":{"it":"Quando più regole riguardano lo stesso elemento, vince quella con la **specificità** maggiore. L’`id` batte la classe, la classe batte il tag. A parità di specificità vince l’ultima scritta.","en":"When several rules target the same element, the one with the higher **specificity** wins. An `id` beats a class, a class beats a tag. With equal specificity the last one written wins."}},{"t":"code","code":"p { color: black; }        /* 0,0,1 */\\n.nota { color: blue; }     /* 0,1,0 → vince */\\np.nota { color: green; }   /* 0,1,1 → vince ancora */\\n#box { color: red; }       /* 1,0,0 → batte tutte */","lang":"css"},{"t":"p","text":{"it":"Alcune proprietà, come `color` e `font-family`, si **ereditano** dai genitori; altre, come `margin` e `border`, no. `!important` scavalca tutto: evitalo, perché rende il CSS difficile da correggere.","en":"Some properties, like `color` and `font-family`, are **inherited** from parents; others, like `margin` and `border`, are not. `!important` overrides everything: avoid it, because it makes CSS hard to fix."}}]','{"lang":"css","prompt":{"it":"Rendi blu (`blue`) il testo di `p.nota` senza toccare la regola esistente e senza `!important`.","en":"Make the text of `p.nota` blue (`blue`) without touching the existing rule and without `!important`."},"start":".nota { color: red; }","html":"<h1 class=\\"titolo\\">Fucina</h1>\\n<p>Il primo paragrafo.</p>\\n<p class=\\"nota\\">Una nota.</p>\\n<div id=\\"box\\">Una scatola</div>\\n<a href=\\"#\\">Un link</a>","checks":[{"sel":"p.nota","prop":"color","value":"rgb(0, 0, 255)","label":{"it":"La nota è blu","en":"The note is blue"}},{"re":"^(?![\\\\s\\\\S]*!important)","label":{"it":"Niente `!important`","en":"No `!important`"}}],"hint":"p.nota { color: blue; }"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('css-base','backgrounds',7,2,'published','{"it":"Sfondi e ombre","en":"Backgrounds and shadows"}','[{"t":"p","text":{"it":"`background` può essere un colore, un’immagine o una sfumatura. `box-shadow` aggiunge un’ombra alla scatola, `text-shadow` al testo.","en":"`background` can be a colour, an image or a gradient. `box-shadow` adds a shadow to the box, `text-shadow` to the text."}},{"t":"code","code":".card {\\n  background: linear-gradient(135deg, #FF5B2E, #FFC53D);\\n  box-shadow: 0 4px 12px rgb(0 0 0 / .25);\\n}","lang":"css"},{"t":"p","text":{"it":"I valori di `box-shadow` sono: spostamento orizzontale, verticale, sfocatura e colore.","en":"The values of `box-shadow` are: horizontal offset, vertical offset, blur and colour."}}]','{"lang":"css","prompt":{"it":"Dai a `#box` lo sfondo `rgb(255, 197, 61)` e angoli da `16px`.","en":"Give `#box` the background `rgb(255, 197, 61)` and `16px` corners."},"start":"#box {\\n\\n}","html":"<h1 class=\\"titolo\\">Fucina</h1>\\n<p>Il primo paragrafo.</p>\\n<p class=\\"nota\\">Una nota.</p>\\n<div id=\\"box\\">Una scatola</div>\\n<a href=\\"#\\">Un link</a>","checks":[{"sel":"#box","prop":"background-color","value":"rgb(255, 197, 61)","label":{"it":"Lo sfondo è giusto","en":"The background is right"}},{"sel":"#box","prop":"border-top-left-radius","value":"16px","label":{"it":"Gli angoli sono arrotondati","en":"The corners are rounded"}}],"hint":"#box {\\n  background: rgb(255, 197, 61);\\n  border-radius: 16px;\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('css-base','units',8,2,'published','{"it":"Unità di misura","en":"Units"}','[{"t":"p","text":{"it":"`px` è fisso, `%` dipende dal contenitore, `em` dalla dimensione del testo dell’elemento, `rem` da quella della radice, `vw` e `vh` dallo schermo.","en":"`px` is fixed, `%` depends on the container, `em` on the element’s text size, `rem` on the root’s, `vw` and `vh` on the screen."}},{"t":"code","code":".box {\\n  width: 50%;       /* metà del contenitore */\\n  padding: 1.5rem;  /* 24px con base 16px */\\n  height: 100vh;    /* tutta l’altezza dello schermo */\\n}","lang":"css"},{"t":"tip","text":{"it":"Per i testi preferisci `rem`: rispetta le impostazioni di chi legge.","en":"For text prefer `rem`: it respects the reader’s settings."}}]','{"lang":"css","prompt":{"it":"Imposta `#box` a una larghezza di `50%` e un `padding` di `1rem`.","en":"Set `#box` to a width of `50%` and a `padding` of `1rem`."},"start":"#box {\\n\\n}","html":"<h1 class=\\"titolo\\">Fucina</h1>\\n<p>Il primo paragrafo.</p>\\n<p class=\\"nota\\">Una nota.</p>\\n<div id=\\"box\\">Una scatola</div>\\n<a href=\\"#\\">Un link</a>","checks":[{"re":"width\\\\s*:\\\\s*50%","label":{"it":"La larghezza è 50%","en":"The width is 50%"}},{"re":"padding\\\\s*:\\\\s*1rem","label":{"it":"Il padding è 1rem","en":"The padding is 1rem"}}],"hint":"#box {\\n  width: 50%;\\n  padding: 1rem;\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('css-intermediate','combinators',1,1,'published','{"it":"Combinatori e attributi","en":"Combinators and attributes"}','[{"t":"p","text":{"it":"I combinatori legano due selettori: lo spazio significa «dentro», `>` «figlio diretto», `+` «subito dopo», `~` «fratelli successivi». Con le parentesi quadre scegli in base a un attributo.","en":"Combinators link two selectors: a space means “inside”, `>` “direct child”, `+` “right after”, `~` “following siblings”. Square brackets pick by attribute."}},{"t":"code","code":"ul > li { list-style: none; }\\nh1 + p { font-size: 1.2rem; }\\na[href^=\\"https\\"] { color: green; }\\ninput[type=\\"email\\"] { border-color: blue; }","lang":"css"},{"t":"p","text":{"it":"`^=` significa «inizia con», `$=` «finisce con», `*=` «contiene».","en":"`^=` means “starts with”, `$=` “ends with”, `*=` “contains”."}}]','{"lang":"css","prompt":{"it":"Togli i pallini ai figli diretti di `.lista` (`list-style-type: none`) e rendi blu (`blue`) il `.nota` subito dopo `.titolo`.","en":"Remove the bullets from the direct children of `.lista` (`list-style-type: none`) and make blue (`blue`) the `.nota` right after `.titolo`."},"start":"","html":"<nav class=\\"menu\\"><a href=\\"#\\">Home</a><a href=\\"#\\">Corsi</a></nav>\\n<h1 class=\\"titolo\\">Fucina</h1>\\n<p class=\\"nota\\">Una nota.</p>\\n<ul class=\\"lista\\"><li>Uno</li><li>Due</li><li>Tre</li></ul>\\n<button class=\\"btn\\">Inizia</button>","checks":[{"sel":".lista li","prop":"list-style-type","value":"none","label":{"it":"Niente pallini","en":"No bullets"}},{"sel":".nota","prop":"color","value":"rgb(0, 0, 255)","label":{"it":"La nota è blu","en":"The note is blue"}}],"hint":".lista > li {\\n  list-style-type: none;\\n}\\n.titolo + .nota {\\n  color: blue;\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('css-intermediate','states',2,1,'published','{"it":"Stati e interazioni","en":"States and interactions"}','[{"t":"p","text":{"it":"Le pseudo-classi reagiscono a quello che fa l’utente: `:hover` al passaggio, `:active` alla pressione, `:focus` sul campo attivo, `:focus-visible` quando si usa la tastiera, `:disabled` sui controlli spenti.","en":"Pseudo-classes react to what the user does: `:hover` on passing over, `:active` on pressing, `:focus` on the active field, `:focus-visible` when using the keyboard, `:disabled` on switched-off controls."}},{"t":"code","code":".btn:hover { background: tomato; }\\n.btn:active { transform: translateY(2px); }\\n.btn:focus-visible { outline: 3px solid gold; }\\n.btn:disabled { opacity: .5; cursor: not-allowed; }\\ninput:invalid { border-color: red; }","lang":"css"},{"t":"tip","text":{"it":"Non togliere mai `outline` senza sostituirlo: chi usa la tastiera si perderebbe.","en":"Never remove `outline` without replacing it: keyboard users would get lost."}}]','{"lang":"css","prompt":{"it":"Scrivi `.btn:hover` con `background: tomato` e `.btn:focus-visible` con un `outline`.","en":"Write `.btn:hover` with `background: tomato` and `.btn:focus-visible` with an `outline`."},"start":"","html":"<nav class=\\"menu\\"><a href=\\"#\\">Home</a><a href=\\"#\\">Corsi</a></nav>\\n<h1 class=\\"titolo\\">Fucina</h1>\\n<p class=\\"nota\\">Una nota.</p>\\n<ul class=\\"lista\\"><li>Uno</li><li>Due</li><li>Tre</li></ul>\\n<button class=\\"btn\\">Inizia</button>","checks":[{"re":"\\\\.btn:hover\\\\s*\\\\{[^}]*tomato","label":{"it":"`:hover` è tomato","en":"`:hover` is tomato"}},{"re":"\\\\.btn:focus-visible\\\\s*\\\\{[^}]*outline","label":{"it":"`:focus-visible` ha un outline","en":"`:focus-visible` has an outline"}}],"hint":".btn:hover {\\n  background: tomato;\\n}\\n.btn:focus-visible {\\n  outline: 3px solid gold;\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('css-intermediate','typography',3,1,'published','{"it":"Tipografia","en":"Typography"}','[{"t":"p","text":{"it":"Il testo è quasi tutto il web. `line-height` dà respiro, `letter-spacing` spazia le lettere, `text-transform` cambia maiuscole e minuscole, `font-weight` il peso. Un buon testo sta tra 45 e 75 caratteri per riga.","en":"Text is nearly all of the web. `line-height` gives room, `letter-spacing` spaces letters, `text-transform` changes case, `font-weight` the weight. Good text sits between 45 and 75 characters per line."}},{"t":"code","code":"@font-face {\\n  font-family: \\"Forgia\\";\\n  src: url(\\"forgia.woff2\\") format(\\"woff2\\");\\n  font-display: swap;\\n}\\np {\\n  font-family: \\"Forgia\\", sans-serif;\\n  line-height: 1.6;\\n  max-width: 65ch;\\n}","lang":"css"},{"t":"p","text":{"it":"`ch` è la larghezza del carattere zero: `65ch` è una riga comoda. `font-display: swap` mostra subito il testo mentre il font arriva.","en":"`ch` is the width of the zero character: `65ch` is a comfortable line. `font-display: swap` shows text at once while the font arrives."}}]','{"lang":"css","prompt":{"it":"Dai a `.nota` un `line-height` di `1.6` e `text-transform: uppercase`.","en":"Give `.nota` a `line-height` of `1.6` and `text-transform: uppercase`."},"start":".nota {\\n\\n}","html":"<nav class=\\"menu\\"><a href=\\"#\\">Home</a><a href=\\"#\\">Corsi</a></nav>\\n<h1 class=\\"titolo\\">Fucina</h1>\\n<p class=\\"nota\\">Una nota.</p>\\n<ul class=\\"lista\\"><li>Uno</li><li>Due</li><li>Tre</li></ul>\\n<button class=\\"btn\\">Inizia</button>","checks":[{"re":"line-height\\\\s*:\\\\s*1\\\\.6","label":{"it":"L’interlinea è 1.6","en":"The line height is 1.6"}},{"sel":".nota","prop":"text-transform","value":"uppercase","label":{"it":"Il testo è in maiuscolo","en":"The text is uppercase"}}],"hint":".nota {\\n  line-height: 1.6;\\n  text-transform: uppercase;\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('css-intermediate','overflow',4,2,'published','{"it":"Overflow e livelli","en":"Overflow and layers"}','[{"t":"p","text":{"it":"Quando il contenuto è più grande della scatola, `overflow` decide che cosa fare: `visible` lo lascia uscire, `hidden` lo taglia, `auto` aggiunge le barre se servono. `z-index` sceglie chi sta sopra tra gli elementi posizionati.","en":"When content is bigger than its box, `overflow` decides what to do: `visible` lets it out, `hidden` cuts it, `auto` adds scrollbars if needed. `z-index` picks who is on top among positioned elements."}},{"t":"code","code":".riquadro {\\n  height: 120px;\\n  overflow: auto;\\n}\\n.finestra {\\n  position: fixed;\\n  z-index: 10;\\n}\\n.testo {\\n  white-space: nowrap;\\n  overflow: hidden;\\n  text-overflow: ellipsis;\\n}","lang":"css"},{"t":"p","text":{"it":"Le ultime tre regole, insieme, troncano una riga con i puntini di sospensione.","en":"The last three rules, together, cut a line with an ellipsis."}}]','{"lang":"css","prompt":{"it":"Dai a `.lista` un `height` di `40px` e `overflow: auto`.","en":"Give `.lista` a `height` of `40px` and `overflow: auto`."},"start":".lista {\\n\\n}","html":"<nav class=\\"menu\\"><a href=\\"#\\">Home</a><a href=\\"#\\">Corsi</a></nav>\\n<h1 class=\\"titolo\\">Fucina</h1>\\n<p class=\\"nota\\">Una nota.</p>\\n<ul class=\\"lista\\"><li>Uno</li><li>Due</li><li>Tre</li></ul>\\n<button class=\\"btn\\">Inizia</button>","checks":[{"sel":".lista","prop":"height","value":"40px","label":{"it":"L’altezza è 40px","en":"The height is 40px"}},{"sel":".lista","prop":"overflow-y","value":"auto","label":{"it":"Si scorre se serve","en":"It scrolls if needed"}}],"hint":".lista {\\n  height: 40px;\\n  overflow: auto;\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('css-intermediate','components',5,2,'published','{"it":"Bottoni e menu","en":"Buttons and menus"}','[{"t":"p","text":{"it":"Con quello che sai puoi già costruire componenti veri. Un bottone è una scatola con padding, angoli, colori e stati. Un menu è una lista di link senza pallini, con gli elementi in riga.","en":"With what you know you can already build real components. A button is a box with padding, corners, colours and states. A menu is a list of links without bullets, with items in a row."}},{"t":"code","code":".btn {\\n  display: inline-block;\\n  padding: 10px 18px;\\n  border: 0;\\n  border-radius: 12px;\\n  background: #FF5B2E;\\n  color: white;\\n  cursor: pointer;\\n}\\n.menu a {\\n  display: inline-block;\\n  padding: 8px 12px;\\n  text-decoration: none;\\n}","lang":"css"},{"t":"tip","text":{"it":"Un bottone deve essere facile da toccare: almeno 44 pixel di altezza su telefono.","en":"A button must be easy to tap: at least 44 pixels high on phones."}}]','{"lang":"css","prompt":{"it":"Stila `.btn`: `padding` di `12px`, `border-radius` di `12px`, `cursor: pointer`.","en":"Style `.btn`: `padding` of `12px`, `border-radius` of `12px`, `cursor: pointer`."},"start":".btn {\\n\\n}","html":"<nav class=\\"menu\\"><a href=\\"#\\">Home</a><a href=\\"#\\">Corsi</a></nav>\\n<h1 class=\\"titolo\\">Fucina</h1>\\n<p class=\\"nota\\">Una nota.</p>\\n<ul class=\\"lista\\"><li>Uno</li><li>Due</li><li>Tre</li></ul>\\n<button class=\\"btn\\">Inizia</button>","checks":[{"sel":".btn","prop":"padding-top","value":"12px","label":{"it":"Il padding è 12px","en":"The padding is 12px"}},{"sel":".btn","prop":"border-top-left-radius","value":"12px","label":{"it":"Gli angoli sono tondi","en":"The corners are round"}},{"sel":".btn","prop":"cursor","value":"pointer","label":{"it":"Il cursore è giusto","en":"The cursor is right"}}],"hint":".btn {\\n  padding: 12px;\\n  border-radius: 12px;\\n  cursor: pointer;\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('css-advanced','flex',1,2,'published','{"it":"Flexbox","en":"Flexbox"}','[{"t":"p","text":{"it":"Flexbox dispone i figli lungo **una dimensione**. Si attiva sul contenitore con `display: flex`.","en":"Flexbox lays out children along **one dimension**. You turn it on for the container with `display: flex`."}},{"t":"code","code":".lista {\\n  display: flex;\\n  flex-direction: row;\\n  justify-content: space-between; /* asse principale */\\n  align-items: center;            /* asse trasversale */\\n  gap: 16px;\\n  flex-wrap: wrap;\\n}\\n.card { flex: 1; }","lang":"css"},{"t":"p","text":{"it":"`justify-content` distribuisce lungo l’asse principale, `align-items` lungo quello perpendicolare. `gap` è lo spazio tra i figli. `flex: 1` su un figlio gli fa prendere lo spazio libero.","en":"`justify-content` distributes along the main axis, `align-items` along the cross axis. `gap` is the space between children. `flex: 1` on a child makes it take the free space."}},{"t":"tip","text":{"it":"Con `flex-direction: column` gli assi si scambiano: `justify-content` lavora in verticale.","en":"With `flex-direction: column` the axes swap: `justify-content` works vertically."}}]','{"lang":"css","prompt":{"it":"Disponi `.lista` in flex, con `gap` di `16px` e `justify-content: space-between`.","en":"Lay out `.lista` with flex, with a `gap` of `16px` and `justify-content: space-between`."},"start":".card { background: #ffe8d6; padding: 12px; }\\n\\n.lista {\\n\\n}","html":"<div class=\\"lista\\">\\n  <div class=\\"card\\">Uno</div>\\n  <div class=\\"card\\">Due</div>\\n  <div class=\\"card\\">Tre</div>\\n</div>","checks":[{"sel":".lista","prop":"display","value":"flex","label":{"it":"La lista è flex","en":"The list is flex"}},{"sel":".lista","prop":"row-gap","value":"16px","label":{"it":"Il gap è 16px","en":"The gap is 16px"}},{"sel":".lista","prop":"justify-content","value":"space-between","label":{"it":"I figli sono distribuiti","en":"The children are distributed"}}],"hint":"display: flex;\\ngap: 16px;\\njustify-content: space-between;"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('css-advanced','grid',2,2,'published','{"it":"CSS Grid","en":"CSS Grid"}','[{"t":"p","text":{"it":"Grid dispone gli elementi in **due dimensioni**: righe e colonne insieme. L’unità `fr` è una frazione dello spazio libero.","en":"Grid lays out elements in **two dimensions**: rows and columns together. The `fr` unit is a fraction of the free space."}},{"t":"code","code":".lista {\\n  display: grid;\\n  grid-template-columns: 200px 1fr 1fr;\\n  gap: 12px;\\n}\\n.hero { grid-column: 1 / 3; } /* dalla linea 1 alla 3 */\\n\\n/* Colonne che si adattano da sole */\\n.galleria {\\n  display: grid;\\n  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));\\n}","lang":"css"},{"t":"p","text":{"it":"`repeat(3, 1fr)` crea tre colonne uguali. `minmax()` fissa un minimo e un massimo: insieme a `auto-fit` ottieni una griglia responsive senza media query.","en":"`repeat(3, 1fr)` creates three equal columns. `minmax()` sets a minimum and a maximum: together with `auto-fit` you get a responsive grid with no media queries."}},{"t":"tip","text":{"it":"Flexbox per una riga di elementi, Grid per una vera impaginazione a righe e colonne.","en":"Flexbox for a row of items, Grid for a real layout of rows and columns."}}]','{"lang":"css","prompt":{"it":"Trasforma `.lista` in una griglia di tre colonne uguali con `gap` di `12px`.","en":"Turn `.lista` into a grid of three equal columns with a `gap` of `12px`."},"start":".card { background: #ffe8d6; padding: 12px; }","html":"<div class=\\"lista\\">\\n  <div class=\\"card\\">Uno</div>\\n  <div class=\\"card\\">Due</div>\\n  <div class=\\"card\\">Tre</div>\\n</div>","checks":[{"sel":".lista","prop":"display","value":"grid","label":{"it":"La lista è una griglia","en":"The list is a grid"}},{"sel":".lista","prop":"row-gap","value":"12px","label":{"it":"Il gap è 12px","en":"The gap is 12px"}},{"re":"grid-template-columns\\\\s*:\\\\s*(repeat\\\\(\\\\s*3\\\\s*,\\\\s*1fr\\\\s*\\\\)|1fr\\\\s+1fr\\\\s+1fr)","label":{"it":"Ci sono tre colonne uguali","en":"There are three equal columns"}}],"hint":".lista {\\n  display: grid;\\n  grid-template-columns: repeat(3, 1fr);\\n  gap: 12px;\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('css-advanced','responsive',3,2,'published','{"it":"Responsive design","en":"Responsive design"}','[{"t":"p","text":{"it":"Una pagina responsive si adatta a ogni schermo. Si parte dal telefono e con le **media query** si aggiungono regole per gli schermi più grandi: è il metodo *mobile first*.","en":"A responsive page adapts to every screen. You start from the phone and add rules for larger screens with **media queries**: that is the *mobile first* method."}},{"t":"code","code":".lista { display: grid; gap: 12px; }\\n\\n@media (min-width: 700px) {\\n  .lista { grid-template-columns: 1fr 1fr; }\\n}\\n\\nimg { max-width: 100%; height: auto; }\\nh1 { font-size: clamp(1.5rem, 5vw, 3rem); }","lang":"css"},{"t":"p","text":{"it":"`clamp(min, ideale, max)` fa crescere un valore entro due limiti. `vw` è l’1% della larghezza dello schermo. `max-width: 100%` impedisce alle immagini di uscire dal contenitore.","en":"`clamp(min, ideal, max)` grows a value within two limits. `vw` is 1% of the screen width. `max-width: 100%` stops images overflowing their container."}}]','{"lang":"css","prompt":{"it":"Scrivi una media query `min-width: 700px` che metta `.lista` in `display: flex`.","en":"Write a `min-width: 700px` media query that sets `.lista` to `display: flex`."},"start":"","html":"<div class=\\"lista\\">\\n  <div class=\\"card\\">Uno</div>\\n  <div class=\\"card\\">Due</div>\\n  <div class=\\"card\\">Tre</div>\\n</div>","checks":[{"re":"@media[^{]*min-width\\\\s*:\\\\s*700px","label":{"it":"C’è la media query","en":"The media query is there"}},{"re":"@media[^{]*\\\\{[^}]*\\\\.lista\\\\s*\\\\{[^}]*display\\\\s*:\\\\s*flex","label":{"it":"Dentro c’è `.lista` in flex","en":"`.lista` is flex inside it"}}],"hint":"@media (min-width: 700px) {\\n  .lista { display: flex; }\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('css-advanced','variables',4,2,'published','{"it":"Variabili e funzioni CSS","en":"CSS variables and functions"}','[{"t":"p","text":{"it":"Le **proprietà personalizzate** iniziano con `--` e si leggono con `var()`. A differenza delle variabili di Sass esistono nel browser, quindi si possono cambiare dal vivo, ad esempio per il tema scuro.","en":"**Custom properties** start with `--` and are read with `var()`. Unlike Sass variables they exist in the browser, so they can change live, for a dark theme for example."}},{"t":"code","code":":root { --brand: #E8590C; --spazio: 16px; }\\n\\n.card {\\n  color: var(--brand);\\n  padding: calc(var(--spazio) * 2);\\n  border-color: var(--bordo, #ccc); /* valore di riserva */\\n}\\n\\n@media (prefers-color-scheme: dark) {\\n  :root { --brand: #FFA94D; }\\n}","lang":"css"},{"t":"p","text":{"it":"`calc()` fa i conti anche tra unità diverse, come `calc(100% - 40px)`. Il secondo argomento di `var()` è il valore di riserva, usato se la variabile non esiste.","en":"`calc()` does maths even between different units, as in `calc(100% - 40px)`. The second argument of `var()` is the fallback, used if the variable does not exist."}}]','{"lang":"css","prompt":{"it":"Dichiara `--brand: #E8590C` in `:root` e usala come `color` di `.card`.","en":"Declare `--brand: #E8590C` in `:root` and use it as the `color` of `.card`."},"start":"","html":"<div class=\\"lista\\">\\n  <div class=\\"card\\">Uno</div>\\n  <div class=\\"card\\">Due</div>\\n  <div class=\\"card\\">Tre</div>\\n</div>","checks":[{"re":":root\\\\s*\\\\{[^}]*--brand\\\\s*:\\\\s*#e8590c","label":{"it":"La variabile è dichiarata","en":"The variable is declared"}},{"re":"\\\\.card\\\\s*\\\\{[^}]*color\\\\s*:\\\\s*var\\\\(\\\\s*--brand","label":{"it":"`.card` usa `var(--brand)`","en":"`.card` uses `var(--brand)`"}},{"sel":".card","prop":"color","value":"rgb(232, 89, 12)","label":{"it":"Il colore è applicato","en":"The colour is applied"}}],"hint":":root { --brand: #E8590C; }\\n.card { color: var(--brand); }"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('css-advanced','motion',5,3,'published','{"it":"Transizioni e animazioni","en":"Transitions and animations"}','[{"t":"p","text":{"it":"`transition` anima il passaggio tra due stati. `transform` sposta, ruota e ingrandisce senza disturbare l’impaginazione, ed è molto fluido.","en":"`transition` animates the change between two states. `transform` moves, rotates and scales without disturbing the layout, and is very smooth."}},{"t":"code","code":".card { transition: transform .2s ease; }\\n.card:hover { transform: translateY(-4px) scale(1.02); }\\n\\n@keyframes pulsa {\\n  from { opacity: 1; }\\n  to   { opacity: .4; }\\n}\\n.scintilla { animation: pulsa 1s infinite alternate; }","lang":"css"},{"t":"p","text":{"it":"`@keyframes` definisce i passaggi di un’animazione e `animation` la applica. Rispetta chi chiede meno movimento con la media query `prefers-reduced-motion`.","en":"`@keyframes` defines the steps of an animation and `animation` applies it. Respect those who ask for less motion with the `prefers-reduced-motion` media query."}},{"t":"tip","text":{"it":"Anima `transform` e `opacity`: sono le proprietà più leggere per il browser.","en":"Animate `transform` and `opacity`: they are the lightest properties for the browser."}}]','{"lang":"css","prompt":{"it":"Aggiungi a `.card` una `transition` su `transform` e su `.card:hover` un `transform` a piacere.","en":"Add a `transition` on `transform` to `.card` and any `transform` on `.card:hover`."},"start":".card { background: #ffe8d6; padding: 12px; }","html":"<div class=\\"lista\\">\\n  <div class=\\"card\\">Uno</div>\\n  <div class=\\"card\\">Due</div>\\n  <div class=\\"card\\">Tre</div>\\n</div>","checks":[{"re":"transition\\\\s*:[^;}]*transform","label":{"it":"C’è la transizione","en":"The transition is there"}},{"re":"\\\\.card:hover\\\\s*\\\\{[^}]*transform\\\\s*:","label":{"it":"C’è il `transform` su hover","en":"There is a `transform` on hover"}}],"hint":".card { transition: transform .2s; }\\n.card:hover { transform: scale(1.05); }"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('css-advanced','pseudo',6,3,'published','{"it":"Pseudo-elementi","en":"Pseudo-elements"}','[{"t":"p","text":{"it":"`::before` e `::after` creano un elemento finto dentro quello scelto, senza toccare l’HTML. Hanno sempre bisogno di `content`.","en":"`::before` and `::after` create a fake element inside the chosen one, without touching the HTML. They always need `content`."}},{"t":"code","code":".nuovo::before {\\n  content: \\"★ \\";\\n  color: gold;\\n}\\nli:nth-child(odd) { background: #eee; }\\np:first-child { font-weight: 700; }","lang":"css"},{"t":"p","text":{"it":"Le pseudo-classi strutturali come `:nth-child()` scelgono gli elementi in base alla posizione: `odd`, `even` o una formula.","en":"Structural pseudo-classes like `:nth-child()` pick elements by position: `odd`, `even` or a formula."}}]','{"lang":"css","prompt":{"it":"Aggiungi prima di `.nota` il testo `\\"→ \\"` con `::before`.","en":"Add the text `\\"→ \\"` before `.nota` using `::before`."},"start":"","html":"<h1 class=\\"titolo\\">Fucina</h1>\\n<p>Il primo paragrafo.</p>\\n<p class=\\"nota\\">Una nota.</p>\\n<div id=\\"box\\">Una scatola</div>\\n<a href=\\"#\\">Un link</a>","checks":[{"re":"\\\\.nota::before","label":{"it":"Usi `.nota::before`","en":"You use `.nota::before`"}},{"re":"content\\\\s*:","label":{"it":"C’è `content`","en":"`content` is there"}}],"hint":".nota::before {\\n  content: \\"→ \\";\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('css-advanced','modern',7,3,'published','{"it":"CSS moderno","en":"Modern CSS"}','[{"t":"p","text":{"it":"Il CSS di oggi sa annidare le regole, scegliere un genitore con `:has()` e adattare un componente al suo contenitore con le **container query**.","en":"Today’s CSS can nest rules, pick a parent with `:has()` and adapt a component to its container with **container queries**."}},{"t":"code","code":".card {\\n  container-type: inline-size;\\n  &:hover { outline: 2px solid; }\\n}\\n.card:has(img) { padding: 0; }\\n@container (min-width: 400px) {\\n  .titolo { font-size: 2rem; }\\n}","lang":"css"},{"t":"p","text":{"it":"`:has()` è il «selettore genitore» atteso per anni: sceglie un elemento in base a ciò che contiene.","en":"`:has()` is the long-awaited “parent selector”: it picks an element by what it contains."}}]','{"lang":"css","prompt":{"it":"Con `:has()`, scrivi la regola `.card:has(img)` con `padding: 0`.","en":"Using `:has()`, write the rule `.card:has(img)` with `padding: 0`."},"start":"","html":"<h1 class=\\"titolo\\">Fucina</h1>\\n<p>Il primo paragrafo.</p>\\n<p class=\\"nota\\">Una nota.</p>\\n<div id=\\"box\\">Una scatola</div>\\n<a href=\\"#\\">Un link</a>","checks":[{"re":"\\\\.card:has\\\\(img\\\\)","label":{"it":"Usi `:has(img)`","en":"You use `:has(img)`"}},{"re":"padding\\\\s*:\\\\s*0","label":{"it":"Il padding è 0","en":"The padding is 0"}}],"hint":".card:has(img) {\\n  padding: 0;\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('css-animations','transitions',1,2,'published','{"it":"Transizioni","en":"Transitions"}','[{"t":"p","text":{"it":"Una **transizione** rende graduale un cambiamento. Indichi la proprietà, la durata e, se vuoi, la curva e il ritardo.","en":"A **transition** makes a change gradual. You give the property, the duration and, if you want, the curve and the delay."}},{"t":"code","code":".btn {\\n  background: tomato;\\n  transition: background-color .3s ease, transform .2s;\\n}\\n.btn:hover {\\n  background: gold;\\n  transform: scale(1.05);\\n}","lang":"css"},{"t":"p","text":{"it":"Si scrive sullo stato normale, non su `:hover`: così vale sia all’andata che al ritorno.","en":"It goes on the normal state, not on `:hover`: so it works both ways."}}]','{"lang":"css","prompt":{"it":"Dai a `.btn` una `transition` su `transform` di `.2s`, e su `:hover` un `transform: scale(1.1)`.","en":"Give `.btn` a `transition` on `transform` of `.2s`, and on `:hover` a `transform: scale(1.1)`."},"start":"","html":"<div class=\\"card\\">Una card</div>\\n<button class=\\"btn\\">Inizia</button>\\n<div class=\\"palla\\"></div>","checks":[{"re":"\\\\.btn\\\\s*\\\\{[^}]*transition\\\\s*:\\\\s*transform\\\\s+\\\\.?0?\\\\.2s","label":{"it":"La transizione è giusta","en":"The transition is right"}},{"re":"\\\\.btn:hover\\\\s*\\\\{[^}]*scale\\\\(1\\\\.1\\\\)","label":{"it":"Si ingrandisce al passaggio","en":"It grows on hover"}}],"hint":".btn {\\n  transition: transform .2s;\\n}\\n.btn:hover {\\n  transform: scale(1.1);\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('css-animations','transforms',2,2,'published','{"it":"Trasformazioni","en":"Transforms"}','[{"t":"p","text":{"it":"`transform` sposta, ruota, ingrandisce e inclina un elemento senza disturbare gli altri. È anche la proprietà più veloce da animare.","en":"`transform` moves, rotates, scales and skews an element without disturbing the others. It is also the fastest property to animate."}},{"t":"code","code":".card {\\n  transform: translateX(20px) rotate(5deg) scale(1.1);\\n  transform-origin: top left;\\n}","lang":"css"},{"t":"p","text":{"it":"L’ordine conta: ogni funzione agisce sul risultato della precedente. `transform-origin` sceglie il punto attorno a cui avviene tutto.","en":"Order matters: each function acts on the result of the previous one. `transform-origin` picks the point everything happens around."}}]','{"lang":"css","prompt":{"it":"Ruota `.card` di `45deg` e spostala di `20px` a destra.","en":"Rotate `.card` by `45deg` and move it `20px` to the right."},"start":".card {\\n\\n}","html":"<div class=\\"card\\">Una card</div>\\n<button class=\\"btn\\">Inizia</button>\\n<div class=\\"palla\\"></div>","checks":[{"re":"rotate\\\\(45deg\\\\)","label":{"it":"Ruota di 45 gradi","en":"It rotates by 45 degrees"}},{"re":"translateX\\\\(20px\\\\)|translate\\\\(20px","label":{"it":"Si sposta di 20px","en":"It moves by 20px"}}],"hint":".card {\\n  transform: translateX(20px) rotate(45deg);\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('css-animations','keyframes',3,2,'published','{"it":"Keyframes","en":"Keyframes"}','[{"t":"p","text":{"it":"Le transizioni vanno da A a B. Con `@keyframes` disegni una storia a più tappe, che può ripetersi da sola, senza bisogno di un `:hover`.","en":"Transitions go from A to B. With `@keyframes` you draw a story of several stages, which can repeat by itself, with no `:hover` needed."}},{"t":"code","code":"@keyframes rimbalzo {\\n  0%   { transform: translateY(0); }\\n  50%  { transform: translateY(-30px); }\\n  100% { transform: translateY(0); }\\n}\\n.palla {\\n  animation: rimbalzo 1s ease-in-out infinite;\\n}","lang":"css"},{"t":"p","text":{"it":"`animation` riassume nome, durata, curva e ripetizioni. `infinite` non si ferma mai, `alternate` torna indietro ogni due giri.","en":"`animation` sums up name, duration, curve and repeats. `infinite` never stops, `alternate` goes back every second round."}}]','{"lang":"css","prompt":{"it":"Crea `@keyframes pulsa` e applicalo a `.palla` con `animation: pulsa 1s infinite`.","en":"Create `@keyframes pulsa` and apply it to `.palla` with `animation: pulsa 1s infinite`."},"start":"","html":"<div class=\\"card\\">Una card</div>\\n<button class=\\"btn\\">Inizia</button>\\n<div class=\\"palla\\"></div>","checks":[{"re":"@keyframes\\\\s+pulsa","label":{"it":"I keyframes esistono","en":"The keyframes exist"}},{"re":"\\\\.palla\\\\s*\\\\{[^}]*animation\\\\s*:\\\\s*pulsa\\\\s+1s\\\\s+infinite","label":{"it":"La palla pulsa","en":"The ball pulses"}}],"hint":"@keyframes pulsa {\\n  from { opacity: 1; }\\n  to { opacity: .4; }\\n}\\n.palla {\\n  animation: pulsa 1s infinite;\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('css-animations','timing',4,3,'published','{"it":"Tempi e curve","en":"Timing and curves"}','[{"t":"p","text":{"it":"La stessa animazione cambia carattere con la curva: `linear` è meccanica, `ease-out` frena alla fine, `ease-in` parte piano. Con `cubic-bezier()` crei la tua, anche con un rimbalzo.","en":"The same animation changes character with its curve: `linear` is mechanical, `ease-out` brakes at the end, `ease-in` starts slowly. With `cubic-bezier()` you make your own, even with a bounce."}},{"t":"code","code":".card {\\n  animation-name: entra;\\n  animation-duration: .4s;\\n  animation-delay: .1s;\\n  animation-timing-function: cubic-bezier(.3, 1.5, .5, 1);\\n  animation-fill-mode: backwards;\\n}","lang":"css"},{"t":"p","text":{"it":"`animation-fill-mode` decide lo stato prima e dopo: `forwards` mantiene l’ultima tappa, `backwards` applica subito la prima durante il ritardo.","en":"`animation-fill-mode` decides the state before and after: `forwards` keeps the last stage, `backwards` applies the first at once during the delay."}}]','{"lang":"css","prompt":{"it":"Dai a `.card` un `animation-delay` di `.2s` e un `animation-fill-mode` di `forwards`.","en":"Give `.card` an `animation-delay` of `.2s` and an `animation-fill-mode` of `forwards`."},"start":".card {\\n\\n}","html":"<div class=\\"card\\">Una card</div>\\n<button class=\\"btn\\">Inizia</button>\\n<div class=\\"palla\\"></div>","checks":[{"re":"animation-delay\\\\s*:\\\\s*0?\\\\.2s","label":{"it":"Il ritardo è giusto","en":"The delay is right"}},{"re":"animation-fill-mode\\\\s*:\\\\s*forwards","label":{"it":"Mantiene l’ultima tappa","en":"It keeps the last stage"}}],"hint":".card {\\n  animation-delay: .2s;\\n  animation-fill-mode: forwards;\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('css-animations','respect',5,3,'published','{"it":"Prestazioni e rispetto","en":"Performance and respect"}','[{"t":"p","text":{"it":"Anima `transform` e `opacity`: il browser li gestisce senza ricalcolare la pagina. Animare `width` o `top` costa molto di più e può scattare.","en":"Animate `transform` and `opacity`: the browser handles them without recalculating the page. Animating `width` or `top` costs far more and can stutter."}},{"t":"code","code":"@media (prefers-reduced-motion: reduce) {\\n  * {\\n    animation: none !important;\\n    transition: none !important;\\n  }\\n}","lang":"css"},{"t":"p","text":{"it":"Alcune persone stanno male con il movimento: `prefers-reduced-motion` rispetta la loro impostazione di sistema. Un’animazione deve spiegare, non distrarre.","en":"Some people feel ill with movement: `prefers-reduced-motion` respects their system setting. An animation must explain, not distract."}}]','{"lang":"css","prompt":{"it":"Scrivi la media query `prefers-reduced-motion: reduce` che mette `animation: none` su `.palla`.","en":"Write the `prefers-reduced-motion: reduce` media query that sets `animation: none` on `.palla`."},"start":"","html":"<div class=\\"card\\">Una card</div>\\n<button class=\\"btn\\">Inizia</button>\\n<div class=\\"palla\\"></div>","checks":[{"re":"@media\\\\s*\\\\(prefers-reduced-motion:\\\\s*reduce\\\\)","label":{"it":"La media query è giusta","en":"The media query is right"}},{"re":"\\\\.palla\\\\s*\\\\{[^}]*animation\\\\s*:\\\\s*none","label":{"it":"L’animazione si ferma","en":"The animation stops"}}],"hint":"@media (prefers-reduced-motion: reduce) {\\n  .palla {\\n    animation: none;\\n  }\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('scss','intro',1,2,'published','{"it":"Variabili e compilazione","en":"Variables and compilation"}','[{"t":"p","text":{"it":"SCSS è una sintassi di **Sass**, un preprocessore: scrivi in `.scss` e un compilatore produce il normale `.css` che il browser legge. Ogni file CSS valido è anche SCSS valido.","en":"SCSS is a syntax of **Sass**, a preprocessor: you write `.scss` and a compiler produces the normal `.css` the browser reads. Every valid CSS file is also valid SCSS."}},{"t":"code","code":"$brand: #E8590C;\\n$spazio: 16px;\\n\\n.card {\\n  color: $brand;\\n  padding: $spazio * 2;\\n}","lang":"scss"},{"t":"p","text":{"it":"Le variabili iniziano con `$` e vengono sostituite durante la compilazione, quindi nel CSS finale non esistono più. Si compila con `sass stile.scss stile.css`.","en":"Variables start with `$` and are replaced during compilation, so they no longer exist in the final CSS. You compile with `sass style.scss style.css`."}},{"t":"tip","text":{"it":"Le variabili `$` non cambiano nel browser: per un tema dal vivo servono le variabili CSS.","en":"`$` variables do not change in the browser: a live theme needs CSS variables."}}]','{"lang":"scss","prompt":{"it":"Dichiara la variabile `$brand` con il valore `#E8590C` e usala come `color` di `.titolo`.","en":"Declare the `$brand` variable with the value `#E8590C` and use it as the `color` of `.titolo`."},"start":"","html":"","checks":[{"re":"\\\\$brand\\\\s*:\\\\s*#e8590c\\\\s*;","label":{"it":"La variabile è dichiarata","en":"The variable is declared"}},{"re":"\\\\.titolo\\\\s*\\\\{[^}]*color\\\\s*:\\\\s*\\\\$brand","label":{"it":"`.titolo` la usa","en":"`.titolo` uses it"}}],"hint":"$brand: #E8590C;\\n.titolo { color: $brand; }"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('scss','nesting',2,2,'published','{"it":"Annidamento e parent selector","en":"Nesting and the parent selector"}','[{"t":"p","text":{"it":"In SCSS le regole si scrivono una dentro l’altra, seguendo la struttura dell’HTML. Il simbolo `&` indica il selettore genitore.","en":"In SCSS rules are written inside one another, following the structure of the HTML. The `&` symbol stands for the parent selector."}},{"t":"code","code":".menu {\\n  padding: 8px;\\n\\n  a {\\n    color: navy;\\n\\n    &:hover { color: red; }\\n  }\\n\\n  &--aperto { display: block; }\\n}","lang":"scss"},{"t":"p","text":{"it":"Viene compilato in `.menu a`, `.menu a:hover` e `.menu--aperto`. Non annidare troppo: oltre tre livelli i selettori diventano lunghi e difficili da sovrascrivere.","en":"It compiles to `.menu a`, `.menu a:hover` and `.menu--aperto`. Do not nest too deep: past three levels selectors become long and hard to override."}}]','{"lang":"scss","prompt":{"it":"Dentro `.card` annida `a` e, con `&:hover`, cambia il `color` del link.","en":"Inside `.card` nest `a` and, with `&:hover`, change the `color` of the link."},"start":".card {\\n\\n}","html":"","checks":[{"re":"\\\\.card\\\\s*\\\\{[\\\\s\\\\S]*\\\\ba\\\\s*\\\\{","label":{"it":"`a` è annidato in `.card`","en":"`a` is nested in `.card`"}},{"re":"&:hover\\\\s*\\\\{[^}]*color\\\\s*:","label":{"it":"C’è `&:hover` con `color`","en":"There is `&:hover` with `color`"}}],"hint":"a {\\n  &:hover { color: red; }\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('scss','mixins',3,2,'published','{"it":"Mixin ed extend","en":"Mixins and extend"}','[{"t":"p","text":{"it":"Un **mixin** è un blocco di regole riutilizzabile, anche con parametri. Si definisce con `@mixin` e si inserisce con `@include`.","en":"A **mixin** is a reusable block of rules, parameters included. It is defined with `@mixin` and inserted with `@include`."}},{"t":"code","code":"@mixin centrato($direzione: row) {\\n  display: flex;\\n  flex-direction: $direzione;\\n  justify-content: center;\\n  align-items: center;\\n}\\n\\n.hero { @include centrato(column); }\\n\\n%bottone { padding: 8px 16px; border-radius: 8px; }\\n.salva { @extend %bottone; }","lang":"scss"},{"t":"p","text":{"it":"`$direzione: row` è un valore predefinito. `@extend` fa condividere lo stesso selettore; `%bottone` è un segnaposto, che non produce CSS finché qualcuno non lo estende.","en":"`$direzione: row` is a default value. `@extend` makes rules share a selector; `%bottone` is a placeholder, which produces no CSS until something extends it."}}]','{"lang":"scss","prompt":{"it":"Definisci il mixin `ombra` con un parametro `$colore` e usalo con `@include` in `.card`.","en":"Define the `ombra` mixin with a `$colore` parameter and use it with `@include` in `.card`."},"start":"","html":"","checks":[{"re":"@mixin\\\\s+ombra\\\\s*\\\\(\\\\s*\\\\$colore","label":{"it":"Il mixin ha il parametro","en":"The mixin has the parameter"}},{"re":"\\\\.card\\\\s*\\\\{[^}]*@include\\\\s+ombra\\\\s*\\\\(","label":{"it":"`.card` lo include","en":"`.card` includes it"}}],"hint":"@mixin ombra($colore) {\\n  box-shadow: 0 2px 8px $colore;\\n}\\n.card { @include ombra(gray); }"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('scss','modules',4,3,'published','{"it":"Moduli, mappe e cicli","en":"Modules, maps and loops"}','[{"t":"p","text":{"it":"Il codice si divide in file chiamati **partial**, con il nome che inizia per `_`. Si caricano con `@use`, che dà a ogni file il suo spazio dei nomi. `@import` è deprecato.","en":"Code is split into files called **partials**, whose name starts with `_`. They are loaded with `@use`, which gives each file its own namespace. `@import` is deprecated."}},{"t":"code","code":"// _colori.scss\\n$brand: #E8590C;\\n\\n// stile.scss\\n@use \\"sass:color\\";\\n@use \\"colori\\";\\n\\n.card { color: colori.$brand; }\\n.scuro { color: color.adjust(colori.$brand, $lightness: -10%); }\\n\\n$temi: (ok: green, errore: red);\\n\\n@each $nome, $tinta in $temi {\\n  .avviso-#{$nome} { color: $tinta; }\\n}","lang":"scss"},{"t":"p","text":{"it":"Le mappe sono coppie chiave-valore. `@each` le percorre e `#{ }` inserisce un valore dentro un nome: da poche righe nascono molte classi.","en":"Maps are key-value pairs. `@each` loops over them and `#{ }` puts a value inside a name: a few lines create many classes."}}]','{"lang":"scss","prompt":{"it":"Carica il modulo `colori` con `@use` e scrivi un `@each` sulla mappa `$temi`.","en":"Load the `colori` module with `@use` and write an `@each` over the `$temi` map."},"start":"$temi: (ok: green, errore: red);","html":"","checks":[{"re":"@use\\\\s+[\\"'']colori[\\"'']","label":{"it":"C’è `@use \\"colori\\"`","en":"There is `@use \\"colori\\"`"}},{"re":"@each\\\\s+\\\\$\\\\w+\\\\s*,\\\\s*\\\\$\\\\w+\\\\s+in\\\\s+\\\\$temi","label":{"it":"C’è l’`@each` su `$temi`","en":"There is the `@each` over `$temi`"}}],"hint":"@use \\"colori\\";\\n@each $nome, $tinta in $temi {\\n  .avviso-#{$nome} { color: $tinta; }\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('scss','functions',5,3,'published','{"it":"Funzioni e operatori","en":"Functions and operators"}','[{"t":"p","text":{"it":"SCSS sa fare i conti e offre funzioni per i colori. Con `@function` scrivi le tue: restituiscono un valore con `@return`.","en":"SCSS can do maths and has colour functions. With `@function` you write your own: they give back a value with `@return`."}},{"t":"code","code":"@use \\"sass:color\\";\\n@use \\"sass:math\\";\\n\\n@function spazio($n) {\\n  @return $n * 8px;\\n}\\n.card {\\n  padding: spazio(2);\\n  width: math.div(100%, 3);\\n  background: color.adjust(#FF5B2E, $lightness: 20%);\\n}","lang":"scss"},{"t":"p","text":{"it":"Un mixin scrive regole, una funzione restituisce un valore da usare in una proprietà.","en":"A mixin writes rules, a function gives back a value to use in a property."}}]','{"lang":"scss","prompt":{"it":"Scrivi una funzione `doppio($n)` che restituisce `$n * 2`.","en":"Write a function `doppio($n)` that gives back `$n * 2`."},"start":"","html":"","checks":[{"re":"@function\\\\s+doppio\\\\(\\\\$n\\\\)","label":{"it":"Definisci `doppio`","en":"You define `doppio`"}},{"re":"@return\\\\s+\\\\$n\\\\s*\\\\*\\\\s*2","label":{"it":"Restituisci il doppio","en":"You give back the double"}}],"hint":"@function doppio($n) {\\n  @return $n * 2;\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('scss','architecture',6,3,'published','{"it":"Organizzare i file","en":"Organising the files"}','[{"t":"p","text":{"it":"In un progetto grande lo stile si divide in **file parziali**, che iniziano con `_`, e un file principale li raccoglie con `@use`.","en":"In a large project style is split into **partial files**, starting with `_`, and a main file gathers them with `@use`."}},{"t":"code","code":"// main.scss\\n@use \\"base/reset\\";\\n@use \\"base/variabili\\";\\n@use \\"componenti/bottoni\\";\\n@use \\"pagine/home\\";","lang":"scss"},{"t":"p","text":{"it":"I file parziali non diventano CSS da soli: finiscono tutti nel file compilato. Così il browser scarica un solo foglio di stile.","en":"Partial files do not become CSS on their own: they all end up in the compiled file. So the browser downloads one stylesheet."}}]','{"lang":"scss","prompt":{"it":"In `main.scss`, importa con `@use` i parziali `reset` e `bottoni`.","en":"In `main.scss`, load the partials `reset` and `bottoni` with `@use`."},"start":"// main.scss","html":"","checks":[{"re":"@use\\\\s+\\"reset\\"","label":{"it":"Carichi `reset`","en":"You load `reset`"}},{"re":"@use\\\\s+\\"bottoni\\"","label":{"it":"Carichi `bottoni`","en":"You load `bottoni`"}}],"hint":"@use \\"reset\\";\\n@use \\"bottoni\\";"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('sass','indented',1,2,'published','{"it":"La sintassi indentata","en":"The indented syntax"}','[{"t":"p","text":{"it":"I file `.sass` usano lo stesso linguaggio di SCSS ma senza `{ }` e senza `;`. I blocchi sono definiti dal **rientro**, un po’ come in Python.","en":"`.sass` files use the same language as SCSS but with no `{ }` and no `;`. Blocks are defined by **indentation**, a bit like Python."}},{"t":"code","code":"$brand: #E8590C\\n\\n.card\\n  color: $brand\\n  padding: 16px\\n\\n  a\\n    color: navy\\n\\n    &:hover\\n      color: red","lang":"sass"},{"t":"p","text":{"it":"Ogni dichiarazione sta su una riga e il rientro deve essere coerente in tutto il file. Il risultato compilato è identico a quello di SCSS: cambia solo come si scrive.","en":"Each declaration sits on its own line and the indentation must be consistent across the file. The compiled result is identical to SCSS: only the writing changes."}}]','{"lang":"sass","prompt":{"it":"Riscrivi in Sass: `.titolo { color: red; }`","en":"Rewrite in Sass: `.titolo { color: red; }`"},"start":"","html":"","checks":[{"re":"^\\\\s*\\\\.titolo\\\\s*$","label":{"it":"Il selettore sta da solo sulla riga","en":"The selector stands alone on its line"}},{"re":"^[ \\\\t]+color:\\\\s*red\\\\s*$","label":{"it":"`color: red` è rientrato, senza `;`","en":"`color: red` is indented, with no `;`"}}],"hint":".titolo\\n  color: red"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('sass','mixins',2,2,'published','{"it":"Mixin con = e +","en":"Mixins with = and +"}','[{"t":"p","text":{"it":"La sintassi indentata ha una scorciatoia: `=` definisce un mixin, come `@mixin`, e `+` lo include, come `@include`.","en":"The indented syntax has a shortcut: `=` defines a mixin, like `@mixin`, and `+` includes it, like `@include`."}},{"t":"code","code":"=centrato($direzione: row)\\n  display: flex\\n  flex-direction: $direzione\\n  justify-content: center\\n\\n.hero\\n  +centrato(column)","lang":"sass"},{"t":"p","text":{"it":"Anche le forme lunghe `@mixin` e `@include` funzionano, ma le scorciatoie sono l’uso più comune. Le altre regole, come `@use`, `@each` e `@if`, si scrivono come in SCSS, senza graffe.","en":"The long forms `@mixin` and `@include` work too, but the shortcuts are the more common use. Other rules, such as `@use`, `@each` and `@if`, are written as in SCSS, with no braces."}}]','{"lang":"sass","prompt":{"it":"Definisci con `=` il mixin `tondo` con `border-radius: 50%` e includilo con `+` in `.avatar`.","en":"Define the `tondo` mixin with `=`, with `border-radius: 50%`, and include it with `+` in `.avatar`."},"start":"","html":"","checks":[{"re":"^=tondo\\\\b","label":{"it":"Il mixin è definito con `=`","en":"The mixin is defined with `=`"}},{"re":"^[ \\\\t]+border-radius:\\\\s*50%\\\\s*$","label":{"it":"Ha `border-radius: 50%`","en":"It has `border-radius: 50%`"}},{"re":"^\\\\.avatar\\\\s*\\\\n[ \\\\t]+\\\\+tondo","label":{"it":"`.avatar` lo include con `+`","en":"`.avatar` includes it with `+`"}}],"hint":"=tondo\\n  border-radius: 50%\\n\\n.avatar\\n  +tondo"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('sass','choose',3,2,'published','{"it":"Sass o SCSS?","en":"Sass or SCSS?"}','[{"t":"p","text":{"it":"I due formati fanno le stesse cose. SCSS è il più diffuso perché è un’estensione del CSS: si copia del CSS esistente e funziona. Sass è più sintetico, ma non accetta il CSS così com’è.","en":"The two formats do the same things. SCSS is more common because it extends CSS: paste existing CSS and it works. Sass is more concise, but it does not accept CSS as it is."}},{"t":"code","code":"sass --watch stile.sass:stile.css\\nsass-convert stile.scss stile.sass   # vecchi strumenti\\nsass --style=compressed stile.scss stile.css","lang":"bash"},{"t":"p","text":{"it":"Con `--watch` il compilatore ricompila a ogni salvataggio; con `--style=compressed` il CSS esce minimizzato per la pubblicazione. In un progetto si sceglie un solo formato, anche se Sass può caricare file di entrambi i tipi.","en":"With `--watch` the compiler rebuilds on every save; with `--style=compressed` the CSS comes out minified for publishing. In a project you pick one format, although Sass can load files of both kinds."}},{"t":"tip","text":{"it":"In un team conviene SCSS, salvo una preferenza chiara: chi conosce il CSS lo legge subito.","en":"In a team SCSS is the safer choice, unless there is a clear preference: anyone who knows CSS reads it at once."}}]',NULL);
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('sass','maps-sass',4,3,'published','{"it":"Variabili e mappe in Sass","en":"Variables and maps in Sass"}','[{"t":"p","text":{"it":"Nella sintassi indentata variabili e mappe funzionano come in SCSS: cambiano solo graffe e punti e virgola.","en":"In the indented syntax variables and maps work as in SCSS: only braces and semicolons change."}},{"t":"code","code":"$temi: (ok: green, ko: red)\\n\\n@each $nome, $tinta in $temi\\n  .avviso-#{$nome}\\n    color: $tinta","lang":"sass"},{"t":"p","text":{"it":"Una mappa si scrive su una riga sola: nella sintassi indentata andare a capo ha un significato.","en":"A map is written on one line: in the indented syntax a line break has a meaning."}}]','{"lang":"sass","prompt":{"it":"Definisci `$brand: orange` e usalo come `color` di `.titolo`.","en":"Define `$brand: orange` and use it as the `color` of `.titolo`."},"start":"","html":"","checks":[{"re":"^\\\\$brand:\\\\s*orange","label":{"it":"Definisci `$brand`","en":"You define `$brand`"}},{"re":"^\\\\s+color:\\\\s*\\\\$brand\\\\s*$","label":{"it":"Lo usi, senza punto e virgola","en":"You use it, with no semicolon"}}],"hint":"$brand: orange\\n.titolo\\n  color: $brand"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('sass','convert',5,3,'published','{"it":"Da SCSS a Sass","en":"From SCSS to Sass"}','[{"t":"p","text":{"it":"Passare da una sintassi all’altra è meccanico: togli graffe e punti e virgola, usa `=` al posto di `@mixin` e `+` al posto di `@include` se vuoi la forma breve.","en":"Moving between syntaxes is mechanical: remove braces and semicolons, use `=` for `@mixin` and `+` for `@include` if you want the short form."}},{"t":"code","code":"// SCSS\\n.card { color: red; .titolo { margin: 0; } }\\n\\n// Sass\\n.card\\n  color: red\\n  .titolo\\n    margin: 0","lang":"sass"},{"t":"p","text":{"it":"Il comando `sass-convert` lo faceva da solo in passato: oggi conviene scegliere una sintassi e restare coerenti.","en":"The `sass-convert` command used to do it for you: today it is best to pick one syntax and stay consistent."}}]','{"lang":"sass","prompt":{"it":"Riscrivi in Sass: `.box { color: red; }`","en":"Rewrite in Sass: `.box { color: red; }`"},"start":"","html":"","checks":[{"re":"^\\\\.box\\\\s*$","label":{"it":"Il selettore è senza graffa","en":"The selector has no brace"}},{"re":"^\\\\s+color:\\\\s*red\\\\s*$","label":{"it":"La proprietà è rientrata e senza `;`","en":"The property is indented with no `;`"}}],"hint":".box\\n  color: red"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('tailwind','utilities',1,1,'published','{"it":"Le classi di utilità","en":"Utility classes"}','[{"t":"p","text":{"it":"Tailwind non ha componenti già pronti: ha migliaia di **classi piccole**, una per ogni proprietà. `p-4` mette il padding, `text-lg` ingrandisce il testo, `bg-white` colora lo sfondo. Si combinano direttamente nell’HTML.","en":"Tailwind has no ready-made components: it has thousands of **small classes**, one per property. `p-4` sets padding, `text-lg` enlarges text, `bg-white` colours the background. You combine them right in the HTML."}},{"t":"code","code":"<div class=\\"p-4 bg-white rounded-lg shadow\\">\\n  <h2 class=\\"text-lg font-bold\\">Ciao</h2>\\n  <p class=\\"text-gray-600\\">Stile con le classi.</p>\\n</div>","lang":"html"},{"t":"p","text":{"it":"I numeri seguono una scala: `p-1` è 0,25rem, `p-4` è 1rem, `p-8` è 2rem. Lo stesso vale per `m-`, `gap-`, `w-` e `h-`.","en":"Numbers follow a scale: `p-1` is 0.25rem, `p-4` is 1rem, `p-8` is 2rem. The same goes for `m-`, `gap-`, `w-` and `h-`."}}]','{"lang":"html","prompt":{"it":"Dai al `<div>` le classi `p-4`, `bg-white` e `rounded-lg`.","en":"Give the `<div>` the classes `p-4`, `bg-white` and `rounded-lg`."},"start":"<div class=\\"\\">Carta</div>","html":"","checks":[{"re":"class=\\"[^\\"]*\\\\bp-4\\\\b","label":{"it":"C’è `p-4`","en":"There is `p-4`"}},{"re":"class=\\"[^\\"]*\\\\bbg-white\\\\b","label":{"it":"C’è `bg-white`","en":"There is `bg-white`"}},{"re":"class=\\"[^\\"]*\\\\brounded-lg\\\\b","label":{"it":"C’è `rounded-lg`","en":"There is `rounded-lg`"}}],"hint":"<div class=\\"p-4 bg-white rounded-lg\\">Carta</div>"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('tailwind','flex-grid',2,1,'published','{"it":"Flex e griglie","en":"Flex and grids"}','[{"t":"p","text":{"it":"`flex` attiva Flexbox; `items-center` allinea in verticale, `justify-between` distribuisce in orizzontale, `gap-4` spazia gli elementi.","en":"`flex` turns on Flexbox; `items-center` aligns vertically, `justify-between` spreads horizontally, `gap-4` spaces the items."}},{"t":"code","code":"<nav class=\\"flex items-center justify-between gap-4 p-4\\">\\n  <a href=\\"/\\">Logo</a>\\n  <ul class=\\"flex gap-6\\"><li>Corsi</li><li>Giochi</li></ul>\\n</nav>\\n<section class=\\"grid grid-cols-3 gap-4\\">\\n  <div>1</div><div>2</div><div>3</div>\\n</section>","lang":"html"},{"t":"p","text":{"it":"`grid grid-cols-3` crea tre colonne uguali; `col-span-2` fa occupare due colonne a un elemento.","en":"`grid grid-cols-3` makes three equal columns; `col-span-2` makes an item take two columns."}}]','{"lang":"html","prompt":{"it":"Rendi il `<header>` un flex con `items-center` e `justify-between`.","en":"Make the `<header>` a flex with `items-center` and `justify-between`."},"start":"<header class=\\"\\">\\n  <strong>Fucina</strong>\\n  <a href=\\"#\\">Entra</a>\\n</header>","html":"","checks":[{"re":"<header class=\\"[^\\"]*\\\\bflex\\\\b","label":{"it":"È un flex","en":"It is a flex"}},{"re":"<header class=\\"[^\\"]*\\\\bitems-center\\\\b","label":{"it":"Allineato al centro","en":"Centred"}},{"re":"<header class=\\"[^\\"]*\\\\bjustify-between\\\\b","label":{"it":"Distribuito ai lati","en":"Spread to the sides"}}],"hint":"<header class=\\"flex items-center justify-between\\">"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('tailwind','responsive',3,1,'published','{"it":"Schermi diversi","en":"Different screens"}','[{"t":"p","text":{"it":"Tailwind è **mobile first**: una classe senza prefisso vale ovunque, una con `md:` vale da 768px in su, `lg:` da 1024px. Così scrivi il telefono e poi aggiungi lo schermo grande.","en":"Tailwind is **mobile first**: a class without a prefix works everywhere, one with `md:` from 768px up, `lg:` from 1024px. You write the phone first and then add the big screen."}},{"t":"code","code":"<div class=\\"grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4\\">\\n  …\\n</div>\\n<p class=\\"text-base md:text-lg\\">Testo che cresce</p>\\n<aside class=\\"hidden lg:block\\">Solo su desktop</aside>","lang":"html"},{"t":"p","text":{"it":"`hidden lg:block` nasconde un elemento sui telefoni e lo mostra su schermi grandi.","en":"`hidden lg:block` hides an element on phones and shows it on large screens."}}]','{"lang":"html","prompt":{"it":"Fai una griglia di 1 colonna che diventa di 3 da `md` in su.","en":"Make a grid of 1 column that becomes 3 from `md` up."},"start":"<section class=\\"\\">\\n  <div>A</div><div>B</div><div>C</div>\\n</section>","html":"","checks":[{"re":"class=\\"[^\\"]*\\\\bgrid-cols-1\\\\b","label":{"it":"Una colonna di base","en":"One column by default"}},{"re":"class=\\"[^\\"]*\\\\bmd:grid-cols-3\\\\b","label":{"it":"Tre colonne da `md`","en":"Three columns from `md`"}}],"hint":"<section class=\\"grid grid-cols-1 md:grid-cols-3\\">"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('tailwind','states',4,2,'published','{"it":"Stati, colori e tema scuro","en":"States, colours and dark mode"}','[{"t":"p","text":{"it":"I prefissi di stato applicano una classe solo in certi momenti: `hover:` al passaggio del mouse, `focus:` quando un campo è attivo, `disabled:` sui controlli disattivati. `dark:` vale con il tema scuro.","en":"State prefixes apply a class only at certain moments: `hover:` on mouse over, `focus:` when a field is active, `disabled:` on disabled controls. `dark:` applies with the dark theme."}},{"t":"code","code":"<button class=\\"bg-orange-500 hover:bg-orange-600 focus:ring-4\\n               text-white px-4 py-2 rounded-full\\n               disabled:opacity-50 dark:bg-orange-400\\">\\n  Salva\\n</button>","lang":"html"},{"t":"p","text":{"it":"I colori hanno una scala da 50 (chiarissimo) a 950 (scurissimo): `bg-orange-500` è il tono medio.","en":"Colours have a scale from 50 (lightest) to 950 (darkest): `bg-orange-500` is the middle shade."}}]','{"lang":"html","prompt":{"it":"Al bottone aggiungi `hover:bg-orange-600` e `focus:ring-4`.","en":"Add `hover:bg-orange-600` and `focus:ring-4` to the button."},"start":"<button class=\\"bg-orange-500 text-white px-4 py-2\\">Vai</button>","html":"","checks":[{"re":"class=\\"[^\\"]*\\\\bhover:bg-orange-600\\\\b","label":{"it":"Cambia al passaggio del mouse","en":"It changes on hover"}},{"re":"class=\\"[^\\"]*\\\\bfocus:ring-4\\\\b","label":{"it":"Si vede quando ha il focus","en":"It shows when focused"}}],"hint":"<button class=\\"bg-orange-500 hover:bg-orange-600 focus:ring-4 text-white px-4 py-2\\">Vai</button>"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('tailwind','config',5,2,'published','{"it":"Componenti e configurazione","en":"Components and configuration"}','[{"t":"p","text":{"it":"Le stesse classi ripetute in molti punti si raccolgono in un **componente** (in React, Vue, un partial…) oppure con `@apply` in un file CSS. Il file di configurazione o il blocco `@theme` aggiunge colori e font del tuo marchio.","en":"The same classes repeated in many places go into a **component** (in React, Vue, a partial…) or into a CSS file with `@apply`. The configuration file or the `@theme` block adds your brand’s colours and fonts."}},{"t":"code","code":"@import \\"tailwindcss\\";\\n\\n@theme {\\n  --color-brace: #ff5b2e;\\n  --font-display: \\"Fredoka\\", sans-serif;\\n}\\n\\n.btn {\\n  @apply px-4 py-2 rounded-full bg-brace text-white;\\n}","lang":"css"},{"t":"p","text":{"it":"Tailwind genera solo le classi che usi davvero: il CSS finale resta piccolo.","en":"Tailwind only generates the classes you actually use: the final CSS stays small."}}]','{"lang":"css","prompt":{"it":"Crea la regola `.card` che con `@apply` usa `p-6`, `rounded-xl` e `shadow`.","en":"Create the rule `.card` that uses `p-6`, `rounded-xl` and `shadow` with `@apply`."},"start":"","html":"<div class=\\"card\\">Carta</div>","checks":[{"re":"\\\\.card\\\\s*\\\\{[^}]*@apply[^;]*\\\\bp-6\\\\b","label":{"it":"C’è `p-6`","en":"There is `p-6`"}},{"re":"@apply[^;]*\\\\brounded-xl\\\\b","label":{"it":"C’è `rounded-xl`","en":"There is `rounded-xl`"}},{"re":"@apply[^;]*\\\\bshadow\\\\b","label":{"it":"C’è `shadow`","en":"There is `shadow`"}}],"hint":".card {\\n  @apply p-6 rounded-xl shadow;\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('js-base','variables',1,1,'published','{"it":"Variabili e tipi","en":"Variables and types"}','[{"t":"p","text":{"it":"JavaScript dà vita alle pagine. Una **variabile** è una scatola con un nome: `const` non si può riassegnare, `let` sì. I tipi di base sono numeri, stringhe, booleani, `null` e `undefined`.","en":"JavaScript brings pages to life. A **variable** is a box with a name: `const` cannot be reassigned, `let` can. The basic types are numbers, strings, booleans, `null` and `undefined`."}},{"t":"code","code":"const nome = \\"Sav\\";\\nlet punti = 10;\\npunti = punti + 5;\\nconsole.log(nome, punti); // Sav 15\\nconsole.log(typeof punti); // \\"number\\"","lang":"js"},{"t":"tip","text":{"it":"Usa `const` di partenza e passa a `let` solo se il valore deve cambiare.","en":"Start with `const` and move to `let` only if the value must change."}}]','{"lang":"js","prompt":{"it":"Crea una costante `nome` con il tuo nome e una variabile `punti` con `let`, uguale a `0`.","en":"Create a constant `nome` with your name and a variable `punti` with `let`, equal to `0`."},"start":"","html":"","checks":[{"re":"const\\\\s+nome\\\\s*=\\\\s*[\\"'']","label":{"it":"`nome` è una costante stringa","en":"`nome` is a string constant"}},{"re":"let\\\\s+punti\\\\s*=\\\\s*0","label":{"it":"`punti` parte da 0","en":"`punti` starts from 0"}}],"hint":"const nome = \\"Sav\\";\\nlet punti = 0;"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('js-base','operators',2,1,'published','{"it":"Operatori e stringhe","en":"Operators and strings"}','[{"t":"p","text":{"it":"Con i numeri usi `+ - * / %`. Il `%` dà il resto di una divisione. Per i confronti usa sempre `===`, che controlla anche il tipo. Le stringhe si uniscono con i **template literal**, tra apici inversi.","en":"With numbers you use `+ - * / %`. `%` gives the remainder of a division. For comparisons always use `===`, which also checks the type. Strings join with **template literals**, between backticks."}},{"t":"code","code":"const a = 7 % 2;      // 1\\n5 === \\"5\\";            // false\\n5 == \\"5\\";             // true: da evitare\\nconst nome = \\"Sav\\";\\nconst saluto = `Ciao ${nome}!`;\\nsaluto.length;        // 9\\nsaluto.toUpperCase(); // \\"CIAO SAV!\\"","lang":"js"},{"t":"p","text":{"it":"`&&` significa «e», `||` «oppure», `!` «non».","en":"`&&` means “and”, `||` “or”, `!` “not”."}}]','{"lang":"js","prompt":{"it":"Crea `saluto` con un template literal che contenga `${nome}`.","en":"Create `saluto` with a template literal containing `${nome}`."},"start":"const nome = \\"Sav\\";","html":"","checks":[{"re":"saluto\\\\s*=\\\\s*`[^`]*\\\\$\\\\{nome\\\\}[^`]*`","label":{"it":"Il template contiene `${nome}`","en":"The template contains `${nome}`"}}],"hint":"const nome = \\"Sav\\";\\nconst saluto = `Ciao ${nome}!`;"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('js-base','conditions',3,1,'published','{"it":"Condizioni","en":"Conditions"}','[{"t":"p","text":{"it":"`if` esegue un blocco solo se una condizione è vera. `else` copre il caso contrario. Il **ternario** è la versione breve, utile per scegliere un valore.","en":"`if` runs a block only if a condition is true. `else` covers the opposite case. The **ternary** is the short version, handy for choosing a value."}},{"t":"code","code":"if (punti >= 100) {\\n  console.log(\\"Grande!\\");\\n} else if (punti >= 50) {\\n  console.log(\\"Bene\\");\\n} else {\\n  console.log(\\"Continua\\");\\n}\\nconst stato = punti > 0 ? \\"attivo\\" : \\"fermo\\";","lang":"js"},{"t":"p","text":{"it":"Alcuni valori contano come falsi: `0`, `\\"\\"`, `null`, `undefined`, `NaN`, `false`. Tutti gli altri contano come veri.","en":"Some values count as false: `0`, `\\"\\"`, `null`, `undefined`, `NaN`, `false`. All the others count as true."}}]','{"lang":"js","prompt":{"it":"Scrivi un `if` che con `punti >= 10` assegna `premio = true`, altrimenti `premio = false`.","en":"Write an `if` that with `punti >= 10` sets `premio = true`, otherwise `premio = false`."},"start":"let premio;","html":"","checks":[{"re":"if\\\\s*\\\\(\\\\s*punti\\\\s*>=\\\\s*10\\\\s*\\\\)","label":{"it":"La condizione è giusta","en":"The condition is right"}},{"re":"else","label":{"it":"C’è `else`","en":"`else` is there"}},{"re":"premio\\\\s*=\\\\s*true","label":{"it":"Assegni true","en":"You set true"}}],"hint":"let premio;\\nif (punti >= 10) {\\n  premio = true;\\n} else {\\n  premio = false;\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('js-base','loops',4,1,'published','{"it":"Cicli","en":"Loops"}','[{"t":"p","text":{"it":"Un **ciclo** ripete un blocco. `for` conta, `while` continua finché una condizione è vera, `for…of` scorre gli elementi di una lista.","en":"A **loop** repeats a block. `for` counts, `while` goes on while a condition is true, `for…of` walks the items of a list."}},{"t":"code","code":"for (let i = 0; i < 3; i++) {\\n  console.log(i); // 0, 1, 2\\n}\\nlet n = 3;\\nwhile (n > 0) {\\n  n--;\\n}\\nfor (const nome of [\\"Ada\\", \\"Sav\\"]) {\\n  console.log(nome);\\n}","lang":"js"},{"t":"p","text":{"it":"`break` esce dal ciclo, `continue` salta al giro dopo. Attenzione ai cicli che non finiscono mai: bloccano la pagina.","en":"`break` leaves the loop, `continue` jumps to the next round. Watch out for loops that never end: they freeze the page."}}]','{"lang":"js","prompt":{"it":"Scrivi un ciclo `for` che somma in `totale` i numeri da 1 a 5.","en":"Write a `for` loop that adds the numbers from 1 to 5 into `totale`."},"start":"let totale = 0;","html":"","checks":[{"re":"for\\\\s*\\\\(\\\\s*let\\\\s+i\\\\s*=\\\\s*1\\\\s*;\\\\s*i\\\\s*<=\\\\s*5\\\\s*;\\\\s*i\\\\+\\\\+\\\\s*\\\\)","label":{"it":"Il ciclo va da 1 a 5","en":"The loop goes from 1 to 5"}},{"re":"totale\\\\s*(\\\\+=\\\\s*i|=\\\\s*totale\\\\s*\\\\+\\\\s*i)","label":{"it":"Sommi `i` a `totale`","en":"You add `i` to `totale`"}}],"hint":"let totale = 0;\\nfor (let i = 1; i <= 5; i++) {\\n  totale += i;\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('js-base','functions',5,2,'published','{"it":"Funzioni","en":"Functions"}','[{"t":"p","text":{"it":"Una **funzione** è un pezzo di codice con un nome, da riusare. Riceve dei **parametri** e con `return` restituisce un risultato. Le **arrow function** sono la forma breve.","en":"A **function** is a named piece of code to reuse. It takes **parameters** and with `return` gives back a result. **Arrow functions** are the short form."}},{"t":"code","code":"function somma(a, b) {\\n  return a + b;\\n}\\nconst doppio = n => n * 2;\\nconst saluta = (nome = \\"amico\\") => `Ciao ${nome}`;\\n\\nsomma(2, 3);   // 5\\ndoppio(4);     // 8\\nsaluta();      // \\"Ciao amico\\"","lang":"js"},{"t":"p","text":{"it":"Dopo `return` la funzione finisce. Senza `return` restituisce `undefined`. Le variabili create dentro non si vedono da fuori.","en":"After `return` the function ends. Without `return` it gives back `undefined`. Variables created inside cannot be seen from outside."}}]','{"lang":"js","prompt":{"it":"Scrivi una funzione `area(b, h)` che restituisce `b * h`.","en":"Write a function `area(b, h)` that gives back `b * h`."},"start":"","html":"","checks":[{"re":"(function\\\\s+area\\\\s*\\\\(\\\\s*b\\\\s*,\\\\s*h\\\\s*\\\\)|area\\\\s*=\\\\s*\\\\(\\\\s*b\\\\s*,\\\\s*h\\\\s*\\\\)\\\\s*=>)","label":{"it":"`area` riceve `b` e `h`","en":"`area` takes `b` and `h`"}},{"re":"(return\\\\s+b\\\\s*\\\\*\\\\s*h|=>\\\\s*b\\\\s*\\\\*\\\\s*h)","label":{"it":"Restituisce il prodotto","en":"It gives back the product"}}],"hint":"function area(b, h) {\\n  return b * h;\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('js-base','arrays',6,2,'published','{"it":"Array","en":"Arrays"}','[{"t":"p","text":{"it":"Un **array** è una lista ordinata. Si parte a contare da `0`. `push` aggiunge in fondo, `pop` toglie l’ultimo, `length` dice quanti sono.","en":"An **array** is an ordered list. Counting starts at `0`. `push` adds to the end, `pop` removes the last, `length` says how many."}},{"t":"code","code":"const corsi = [\\"HTML\\", \\"CSS\\"];\\ncorsi.push(\\"JS\\");\\ncorsi[0];        // \\"HTML\\"\\ncorsi.length;    // 3\\ncorsi.includes(\\"CSS\\"); // true\\ncorsi.indexOf(\\"JS\\");   // 2","lang":"js"},{"t":"p","text":{"it":"Anche se `const`, un array può cambiare contenuto: `const` blocca solo la riassegnazione della variabile.","en":"Even if `const`, an array can change its content: `const` only blocks reassigning the variable."}}]','{"lang":"js","prompt":{"it":"Crea l’array `frutti` con due elementi e aggiungine un terzo con `push`.","en":"Create the array `frutti` with two items and add a third with `push`."},"start":"","html":"","checks":[{"re":"frutti\\\\s*=\\\\s*\\\\[[^\\\\]]+,[^\\\\]]+\\\\]","label":{"it":"L’array ha due elementi","en":"The array has two items"}},{"re":"frutti\\\\.push\\\\(","label":{"it":"Usi `push`","en":"You use `push`"}}],"hint":"const frutti = [\\"mela\\", \\"pera\\"];\\nfrutti.push(\\"uva\\");"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('js-base','objects',7,2,'published','{"it":"Oggetti","en":"Objects"}','[{"t":"p","text":{"it":"Un **oggetto** raggruppa dati con un nome: coppie chiave e valore. Si legge con il punto, oppure con le parentesi quadre se il nome è in una variabile.","en":"An **object** groups named data: key and value pairs. You read it with a dot, or with square brackets if the name is in a variable."}},{"t":"code","code":"const utente = {\\n  nome: \\"Sav\\",\\n  punti: 10,\\n  saluta() {\\n    return `Ciao ${this.nome}`;\\n  },\\n};\\nutente.punti = 20;\\nutente[\\"nome\\"];   // \\"Sav\\"\\nObject.keys(utente); // [\\"nome\\", \\"punti\\", \\"saluta\\"]","lang":"js"},{"t":"p","text":{"it":"Una funzione dentro un oggetto si chiama **metodo**: con `this` accede all’oggetto stesso.","en":"A function inside an object is called a **method**: with `this` it reaches the object itself."}}]','{"lang":"js","prompt":{"it":"Crea l’oggetto `libro` con `titolo` e `pagine`, poi cambia `pagine` a `100`.","en":"Create the object `libro` with `titolo` and `pagine`, then change `pagine` to `100`."},"start":"","html":"","checks":[{"re":"libro\\\\s*=\\\\s*\\\\{[\\\\s\\\\S]*titolo\\\\s*:[\\\\s\\\\S]*pagine\\\\s*:","label":{"it":"L’oggetto ha le due chiavi","en":"The object has both keys"}},{"re":"libro\\\\.pagine\\\\s*=\\\\s*100","label":{"it":"Cambi `pagine`","en":"You change `pagine`"}}],"hint":"const libro = { titolo: \\"Fucina\\", pagine: 50 };\\nlibro.pagine = 100;"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('js-intermediate','dom',1,2,'published','{"it":"Il DOM","en":"The DOM"}','[{"t":"p","text":{"it":"Il **DOM** è la pagina vista da JavaScript: un albero di elementi. `querySelector` ne trova uno con un selettore CSS, poi puoi cambiarne testo, classi e attributi.","en":"The **DOM** is the page as JavaScript sees it: a tree of elements. `querySelector` finds one with a CSS selector, then you can change its text, classes and attributes."}},{"t":"code","code":"const titolo = document.querySelector(\\"h1\\");\\ntitolo.textContent = \\"Ciao!\\";\\ntitolo.classList.add(\\"grande\\");\\nconst voci = document.querySelectorAll(\\"li\\");\\nconst nuovo = document.createElement(\\"p\\");\\nnuovo.textContent = \\"Nuovo\\";\\ndocument.body.append(nuovo);","lang":"js"},{"t":"tip","text":{"it":"Usa `textContent` per i testi degli utenti: `innerHTML` può eseguire codice nascosto.","en":"Use `textContent` for user text: `innerHTML` can run hidden code."}}]','{"lang":"js","prompt":{"it":"Trova `h1` con `querySelector` e cambiane il testo in `Fucina`.","en":"Find `h1` with `querySelector` and change its text to `Fucina`."},"start":"","html":"","checks":[{"re":"document\\\\.querySelector\\\\(\\\\s*[\\"'']h1[\\"'']\\\\s*\\\\)","label":{"it":"Trovi il titolo","en":"You find the heading"}},{"re":"\\\\.textContent\\\\s*=\\\\s*[\\"'']Fucina[\\"'']","label":{"it":"Cambi il testo","en":"You change the text"}}],"hint":"const t = document.querySelector(\\"h1\\");\\nt.textContent = \\"Fucina\\";"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('js-intermediate','events',2,2,'published','{"it":"Eventi","en":"Events"}','[{"t":"p","text":{"it":"Un **evento** è qualcosa che succede: un click, un tasto, un invio. Con `addEventListener` dici che cosa fare quando accade.","en":"An **event** is something that happens: a click, a key, a submit. With `addEventListener` you say what to do when it occurs."}},{"t":"code","code":"const btn = document.querySelector(\\"button\\");\\nbtn.addEventListener(\\"click\\", () => {\\n  btn.textContent = \\"Fatto!\\";\\n});\\n\\nconst form = document.querySelector(\\"form\\");\\nform.addEventListener(\\"submit\\", e => {\\n  e.preventDefault();\\n  console.log(new FormData(form).get(\\"email\\"));\\n});","lang":"js"},{"t":"p","text":{"it":"La funzione riceve un oggetto evento: `e.target` è l’elemento coinvolto, `e.preventDefault()` ferma il comportamento normale, come il ricaricamento di un modulo.","en":"The function gets an event object: `e.target` is the element involved, `e.preventDefault()` stops the normal behaviour, like a form reloading."}}]','{"lang":"js","prompt":{"it":"Aggiungi a `btn` un ascoltatore di `click` che esegue `conta++`.","en":"Add to `btn` a `click` listener that runs `conta++`."},"start":"let conta = 0;","html":"","checks":[{"re":"btn\\\\.addEventListener\\\\(\\\\s*[\\"'']click[\\"'']","label":{"it":"Ascolti il click","en":"You listen to the click"}},{"re":"conta\\\\+\\\\+","label":{"it":"Il contatore sale","en":"The counter goes up"}}],"hint":"let conta = 0;\\nbtn.addEventListener(\\"click\\", () => {\\n  conta++;\\n});"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('js-intermediate','array-methods',3,2,'published','{"it":"map, filter e reduce","en":"map, filter and reduce"}','[{"t":"p","text":{"it":"Gli array hanno metodi potenti. `map` trasforma ogni elemento, `filter` tiene quelli che superano una prova, `find` restituisce il primo adatto, `reduce` riduce tutto a un valore.","en":"Arrays have powerful methods. `map` transforms each item, `filter` keeps those passing a test, `find` gives back the first match, `reduce` boils it all down to one value."}},{"t":"code","code":"const n = [1, 2, 3, 4];\\nn.map(x => x * 2);        // [2, 4, 6, 8]\\nn.filter(x => x % 2 === 0); // [2, 4]\\nn.find(x => x > 2);       // 3\\nn.reduce((a, x) => a + x, 0); // 10\\nn.some(x => x > 3);       // true","lang":"js"},{"t":"p","text":{"it":"`map` e `filter` creano un nuovo array e non toccano l’originale. Si possono concatenare.","en":"`map` and `filter` create a new array and leave the original alone. They can be chained."}}]','{"lang":"js","prompt":{"it":"Da `prezzi`, crea `cari` con `filter` tenendo quelli sopra `10`.","en":"From `prezzi`, create `cari` with `filter`, keeping those above `10`."},"start":"const prezzi = [5, 12, 30];","html":"","checks":[{"re":"cari\\\\s*=\\\\s*prezzi\\\\.filter\\\\(","label":{"it":"Usi `filter`","en":"You use `filter`"}},{"re":">\\\\s*10","label":{"it":"Il limite è 10","en":"The limit is 10"}}],"hint":"const prezzi = [5, 12, 30];\\nconst cari = prezzi.filter(p => p > 10);"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('js-intermediate','modern-syntax',4,3,'published','{"it":"Sintassi moderna","en":"Modern syntax"}','[{"t":"p","text":{"it":"La **destrutturazione** estrae valori in un colpo. Lo **spread** `...` copia e unisce. `?.` legge in sicurezza una proprietà che può mancare, `??` dà un valore di riserva.","en":"**Destructuring** pulls out values in one go. **Spread** `...` copies and merges. `?.` safely reads a property that may be missing, `??` gives a fallback value."}},{"t":"code","code":"const utente = { nome: \\"Sav\\", punti: 10 };\\nconst { nome, punti } = utente;\\nconst [primo, secondo] = [\\"a\\", \\"b\\"];\\n\\nconst copia = { ...utente, punti: 20 };\\nconst tutti = [...listaA, ...listaB];\\n\\nutente.indirizzo?.via;     // undefined, nessun errore\\nconst n = utente.vite ?? 3; // 3","lang":"js"},{"t":"p","text":{"it":"`??` scatta solo con `null` e `undefined`: a differenza di `||` non scarta `0` e `\\"\\"`.","en":"`??` only fires on `null` and `undefined`: unlike `||` it does not discard `0` and `\\"\\"`."}}]','{"lang":"js","prompt":{"it":"Estrai `titolo` da `libro` con la destrutturazione.","en":"Pull `titolo` out of `libro` with destructuring."},"start":"const libro = { titolo: \\"Fucina\\", pagine: 50 };","html":"","checks":[{"re":"const\\\\s*\\\\{\\\\s*titolo[^}]*\\\\}\\\\s*=\\\\s*libro","label":{"it":"Destrutturi `libro`","en":"You destructure `libro`"}}],"hint":"const libro = { titolo: \\"Fucina\\", pagine: 50 };\\nconst { titolo } = libro;"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('js-intermediate','json-storage',5,3,'published','{"it":"JSON e localStorage","en":"JSON and localStorage"}','[{"t":"p","text":{"it":"**JSON** è il formato di testo con cui viaggiano i dati. `JSON.stringify` trasforma un valore in testo, `JSON.parse` fa il contrario. `localStorage` conserva testi nel browser, anche dopo la chiusura.","en":"**JSON** is the text format data travels in. `JSON.stringify` turns a value into text, `JSON.parse` does the opposite. `localStorage` keeps text in the browser, even after closing."}},{"t":"code","code":"const dati = { punti: 10 };\\nconst testo = JSON.stringify(dati); // ''{\\"punti\\":10}''\\nlocalStorage.setItem(\\"gioco\\", testo);\\n\\nconst salvato = localStorage.getItem(\\"gioco\\");\\nconst letto = salvato ? JSON.parse(salvato) : null;","lang":"js"},{"t":"tip","text":{"it":"`localStorage` è visibile a tutti gli script della pagina: mai password o token.","en":"`localStorage` is visible to all the scripts on the page: never passwords or tokens."}}]','{"lang":"js","prompt":{"it":"Salva `dati` in `localStorage` con la chiave `gioco`, usando `JSON.stringify`.","en":"Save `dati` in `localStorage` with the key `gioco`, using `JSON.stringify`."},"start":"const dati = { punti: 10 };","html":"","checks":[{"re":"localStorage\\\\.setItem\\\\(\\\\s*[\\"'']gioco[\\"'']","label":{"it":"Usi la chiave giusta","en":"You use the right key"}},{"re":"JSON\\\\.stringify\\\\(\\\\s*dati\\\\s*\\\\)","label":{"it":"Converti in testo","en":"You convert to text"}}],"hint":"const dati = { punti: 10 };\\nlocalStorage.setItem(\\"gioco\\", JSON.stringify(dati));"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('js-intermediate','dates-errors',6,3,'published','{"it":"Date, timer ed errori","en":"Dates, timers and errors"}','[{"t":"p","text":{"it":"`Date` lavora con date e orari. `setTimeout` esegue qualcosa dopo un’attesa, `setInterval` a intervalli. `try…catch` gestisce gli errori senza fermare tutto il programma.","en":"`Date` works with dates and times. `setTimeout` runs something after a wait, `setInterval` at intervals. `try…catch` handles errors without stopping the whole program."}},{"t":"code","code":"const ora = new Date();\\nora.getFullYear();\\n\\nsetTimeout(() => console.log(\\"Dopo 1 secondo\\"), 1000);\\nconst id = setInterval(tick, 500);\\nclearInterval(id);\\n\\ntry {\\n  JSON.parse(\\"rotto\\");\\n} catch (errore) {\\n  console.log(\\"Dati non validi\\");\\n}","lang":"js"},{"t":"p","text":{"it":"I tempi si indicano in millisecondi. Conserva l’id di `setInterval` per poterlo fermare.","en":"Times are given in milliseconds. Keep the id of `setInterval` so you can stop it."}}]','{"lang":"js","prompt":{"it":"Con `setTimeout`, esegui `fine()` dopo `2000` millisecondi.","en":"With `setTimeout`, run `fine()` after `2000` milliseconds."},"start":"","html":"","checks":[{"re":"setTimeout\\\\(","label":{"it":"Usi `setTimeout`","en":"You use `setTimeout`"}},{"re":"fine","label":{"it":"Chiami `fine`","en":"You call `fine`"}},{"re":"2000","label":{"it":"Aspetti 2 secondi","en":"You wait 2 seconds"}}],"hint":"setTimeout(fine, 2000);"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('js-advanced','promises',1,2,'published','{"it":"Promise","en":"Promises"}','[{"t":"p","text":{"it":"Una **Promise** rappresenta un risultato che arriverà: può riuscire o fallire. Con `then` dici che cosa fare col valore, con `catch` come gestire l’errore.","en":"A **Promise** stands for a result yet to come: it can succeed or fail. With `then` you say what to do with the value, with `catch` how to handle the error."}},{"t":"code","code":"function attendi(ms) {\\n  return new Promise(resolve => setTimeout(resolve, ms));\\n}\\nattendi(500)\\n  .then(() => \\"fatto\\")\\n  .then(testo => console.log(testo))\\n  .catch(errore => console.error(errore))\\n  .finally(() => console.log(\\"fine\\"));\\n\\nPromise.all([a(), b()]).then(([x, y]) => usa(x, y));","lang":"js"},{"t":"p","text":{"it":"`Promise.all` aspetta più operazioni insieme e fallisce se ne fallisce una. Ogni `then` riceve quello restituito dal precedente.","en":"`Promise.all` waits for several operations together and fails if one fails. Each `then` gets what the previous one gave back."}}]','{"lang":"js","prompt":{"it":"Sulla promise `carica()`, stampa il risultato con `then` e gestisci gli errori con `catch`.","en":"On the promise `carica()`, print the result with `then` and handle errors with `catch`."},"start":"","html":"","checks":[{"re":"carica\\\\(\\\\)\\\\s*\\\\.then\\\\(","label":{"it":"Usi `then`","en":"You use `then`"}},{"re":"\\\\.catch\\\\(","label":{"it":"Usi `catch`","en":"You use `catch`"}}],"hint":"carica()\\n  .then(r => console.log(r))\\n  .catch(e => console.error(e));"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('js-advanced','async',2,2,'published','{"it":"async e await","en":"async and await"}','[{"t":"p","text":{"it":"`async` e `await` fanno sembrare lineare il codice asincrono. `await` aspetta una Promise senza bloccare la pagina, e si scrive solo dentro una funzione `async`.","en":"`async` and `await` make asynchronous code look linear. `await` waits for a Promise without freezing the page, and goes only inside an `async` function."}},{"t":"code","code":"async function profilo(id) {\\n  try {\\n    const utente = await carica(id);\\n    const punti = await caricaPunti(utente);\\n    return { utente, punti };\\n  } catch (e) {\\n    console.error(e);\\n    return null;\\n  }\\n}\\nconst [a, b] = await Promise.all([x(), y()]);","lang":"js"},{"t":"p","text":{"it":"Una funzione `async` restituisce sempre una Promise. Se due operazioni non dipendono l’una dall’altra, lanciale insieme con `Promise.all`: è più veloce.","en":"An `async` function always gives back a Promise. If two operations do not depend on each other, start them together with `Promise.all`: it is faster."}}]','{"lang":"js","prompt":{"it":"Scrivi `async function leggi()` che fa `await carica()` e restituisce il risultato.","en":"Write `async function leggi()` that does `await carica()` and gives back the result."},"start":"","html":"","checks":[{"re":"async\\\\s+function\\\\s+leggi\\\\s*\\\\(","label":{"it":"La funzione è `async`","en":"The function is `async`"}},{"re":"await\\\\s+carica\\\\(\\\\)","label":{"it":"Aspetti il risultato","en":"You wait for the result"}},{"re":"return","label":{"it":"Lo restituisci","en":"You give it back"}}],"hint":"async function leggi() {\\n  const r = await carica();\\n  return r;\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('js-advanced','fetch',3,2,'published','{"it":"Fetch e API","en":"Fetch and APIs"}','[{"t":"p","text":{"it":"`fetch` parla con un server. Restituisce una risposta: controlla `ok`, poi leggi il corpo con `json()`. Per inviare dati usi `POST` con un corpo in JSON.","en":"`fetch` talks to a server. It gives back a response: check `ok`, then read the body with `json()`. To send data you use `POST` with a JSON body."}},{"t":"code","code":"const r = await fetch(\\"/api/punti\\");\\nif (!r.ok) throw new Error(`Errore ${r.status}`);\\nconst dati = await r.json();\\n\\nawait fetch(\\"/api/punti\\", {\\n  method: \\"POST\\",\\n  headers: { \\"Content-Type\\": \\"application/json\\" },\\n  body: JSON.stringify({ punti: 10 }),\\n});","lang":"js"},{"t":"p","text":{"it":"Attenzione: `fetch` non fallisce su un errore 404 o 500, solo su problemi di rete. Per questo va controllato `r.ok`.","en":"Careful: `fetch` does not fail on a 404 or 500, only on network problems. That is why you check `r.ok`."}}]','{"lang":"js","prompt":{"it":"In una funzione `async`, fai `fetch(\\"/api/corsi\\")`, controlla `r.ok` e leggi `r.json()`.","en":"In an `async` function, do `fetch(\\"/api/corsi\\")`, check `r.ok` and read `r.json()`."},"start":"","html":"","checks":[{"re":"await\\\\s+fetch\\\\(\\\\s*[\\"'']\\\\/api\\\\/corsi[\\"'']\\\\s*\\\\)","label":{"it":"Chiami l’API","en":"You call the API"}},{"re":"r\\\\.ok","label":{"it":"Controlli `ok`","en":"You check `ok`"}},{"re":"await\\\\s+r\\\\.json\\\\(\\\\)","label":{"it":"Leggi il JSON","en":"You read the JSON"}}],"hint":"async function corsi() {\\n  const r = await fetch(\\"/api/corsi\\");\\n  if (!r.ok) throw new Error(\\"Errore\\");\\n  return await r.json();\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('js-advanced','modules',4,3,'published','{"it":"Moduli","en":"Modules"}','[{"t":"p","text":{"it":"I **moduli** dividono il codice in file. `export` rende disponibile qualcosa, `import` lo usa. Nella pagina si caricano con `type=\\"module\\"`.","en":"**Modules** split code into files. `export` makes something available, `import` uses it. In the page they load with `type=\\"module\\"`."}},{"t":"code","code":"// punti.js\\nexport const MAX = 100;\\nexport function somma(a, b) { return a + b; }\\nexport default class Gioco {}\\n\\n// app.js\\nimport Gioco, { MAX, somma } from \\"./punti.js\\";\\nconst pesante = await import(\\"./grafici.js\\");","lang":"js"},{"t":"p","text":{"it":"Ogni modulo ha il suo ambito: le variabili non finiscono più nello spazio globale. `import()` come funzione carica un modulo solo quando serve.","en":"Each module has its own scope: variables no longer end up in the global space. `import()` as a function loads a module only when needed."}}]','{"lang":"js","prompt":{"it":"Esporta la funzione `doppio` e la costante `MAX`.","en":"Export the function `doppio` and the constant `MAX`."},"start":"","html":"","checks":[{"re":"export\\\\s+function\\\\s+doppio","label":{"it":"Esporti `doppio`","en":"You export `doppio`"}},{"re":"export\\\\s+const\\\\s+MAX","label":{"it":"Esporti `MAX`","en":"You export `MAX`"}}],"hint":"export function doppio(n) {\\n  return n * 2;\\n}\\nexport const MAX = 100;"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('js-advanced','classes',5,3,'published','{"it":"Classi","en":"Classes"}','[{"t":"p","text":{"it":"Una **classe** è lo stampo di oggetti simili. `constructor` li prepara, i metodi definiscono che cosa sanno fare, `extends` eredita da un’altra classe.","en":"A **class** is the mould for similar objects. `constructor` prepares them, methods define what they can do, `extends` inherits from another class."}},{"t":"code","code":"class Eroe {\\n  #vite = 3;\\n  constructor(nome) {\\n    this.nome = nome;\\n  }\\n  get vite() { return this.#vite; }\\n  colpisci() { this.#vite--; }\\n}\\nclass Mago extends Eroe {\\n  constructor(nome) {\\n    super(nome);\\n    this.magia = 10;\\n  }\\n}\\nconst m = new Mago(\\"Ada\\");","lang":"js"},{"t":"p","text":{"it":"`#` rende un campo privato: da fuori non si tocca. Nel costruttore di una sottoclasse `super()` va chiamato prima di usare `this`.","en":"`#` makes a field private: it cannot be touched from outside. In a subclass constructor `super()` must be called before using `this`."}}]','{"lang":"js","prompt":{"it":"Crea la classe `Gatto` con un `constructor(nome)` e un metodo `miagola()`.","en":"Create the class `Gatto` with a `constructor(nome)` and a `miagola()` method."},"start":"","html":"","checks":[{"re":"class\\\\s+Gatto","label":{"it":"La classe esiste","en":"The class exists"}},{"re":"constructor\\\\s*\\\\(\\\\s*nome\\\\s*\\\\)","label":{"it":"Ha il costruttore","en":"It has the constructor"}},{"re":"miagola\\\\s*\\\\(\\\\s*\\\\)\\\\s*\\\\{","label":{"it":"Ha il metodo","en":"It has the method"}}],"hint":"class Gatto {\\n  constructor(nome) {\\n    this.nome = nome;\\n  }\\n  miagola() {\\n    return \\"Miao\\";\\n  }\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('js-advanced','closures',6,3,'published','{"it":"Closure e ciclo degli eventi","en":"Closures and the event loop"}','[{"t":"p","text":{"it":"Una **closure** è una funzione che ricorda le variabili di dove è nata, anche dopo. JavaScript esegue una cosa alla volta: il **ciclo degli eventi** prende dalle code i compiti in attesa quando il codice in corso è finito.","en":"A **closure** is a function that remembers the variables of where it was born, even later. JavaScript runs one thing at a time: the **event loop** takes waiting jobs from the queues when the running code has finished."}},{"t":"code","code":"function contatore() {\\n  let n = 0;\\n  return () => ++n;\\n}\\nconst conta = contatore();\\nconta(); // 1\\nconta(); // 2\\n\\nconsole.log(\\"A\\");\\nsetTimeout(() => console.log(\\"B\\"), 0);\\nPromise.resolve().then(() => console.log(\\"C\\"));\\nconsole.log(\\"D\\");\\n// A D C B","lang":"js"},{"t":"p","text":{"it":"Le Promise (microtask) passano prima dei timer: per questo `C` arriva prima di `B`, anche con attesa zero.","en":"Promises (microtasks) go before timers: that is why `C` comes before `B`, even with a zero wait."}}]','{"lang":"js","prompt":{"it":"Scrivi `creaContatore()` che restituisce una funzione: a ogni chiamata fa `++n`.","en":"Write `creaContatore()` that gives back a function: each call does `++n`."},"start":"","html":"","checks":[{"re":"function\\\\s+creaContatore","label":{"it":"La funzione esiste","en":"The function exists"}},{"re":"let\\\\s+n\\\\s*=\\\\s*0","label":{"it":"`n` sta nella funzione esterna","en":"`n` lives in the outer function"}},{"re":"return\\\\s+(\\\\(\\\\)\\\\s*=>|function)","label":{"it":"Restituisci una funzione","en":"You give back a function"}},{"re":"\\\\+\\\\+n|n\\\\+\\\\+","label":{"it":"`n` cresce","en":"`n` grows"}}],"hint":"function creaContatore() {\\n  let n = 0;\\n  return () => ++n;\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('ts','types',1,2,'published','{"it":"Perché i tipi","en":"Why types"}','[{"t":"p","text":{"it":"**TypeScript** è JavaScript con i tipi. Dici che cosa contiene una variabile e il compilatore segnala gli errori prima ancora di eseguire. Il browser non lo legge: viene compilato in JavaScript.","en":"**TypeScript** is JavaScript with types. You say what a variable holds and the compiler flags errors before anything runs. The browser does not read it: it is compiled to JavaScript."}},{"t":"code","code":"let nome: string = \\"Sav\\";\\nlet punti: number = 10;\\nlet attivo: boolean = true;\\nlet voti: number[] = [7, 8];\\n\\npunti = \\"tanti\\"; // Errore: non è un number\\nlet vite = 3;    // tipo dedotto: number","lang":"ts"},{"t":"p","text":{"it":"Spesso il tipo non serve scriverlo: TypeScript lo **deduce** dal valore. `any` spegne i controlli: evitalo.","en":"Often you need not write the type: TypeScript **infers** it from the value. `any` switches checks off: avoid it."}}]','{"lang":"ts","prompt":{"it":"Dichiara `nome` di tipo `string` e `voti` come array di `number`.","en":"Declare `nome` of type `string` and `voti` as an array of `number`."},"start":"","html":"","checks":[{"re":"nome\\\\s*:\\\\s*string","label":{"it":"`nome` è una stringa","en":"`nome` is a string"}},{"re":"voti\\\\s*:\\\\s*number\\\\[\\\\]","label":{"it":"`voti` è un array di numeri","en":"`voti` is an array of numbers"}}],"hint":"let nome: string = \\"Sav\\";\\nlet voti: number[] = [7, 8];"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('ts','functions',2,2,'published','{"it":"Funzioni tipizzate","en":"Typed functions"}','[{"t":"p","text":{"it":"Si tipizzano parametri e risultato. Un parametro con `?` è facoltativo, uno con `=` ha un valore di default. `void` indica che una funzione non restituisce nulla.","en":"You type parameters and the result. A parameter with `?` is optional, one with `=` has a default value. `void` means a function gives back nothing."}},{"t":"code","code":"function somma(a: number, b: number): number {\\n  return a + b;\\n}\\nfunction saluta(nome: string, titolo?: string): string {\\n  return titolo ? `${titolo} ${nome}` : nome;\\n}\\nconst log = (testo: string): void => console.log(testo);","lang":"ts"},{"t":"p","text":{"it":"Il tipo del risultato si può dedurre, ma scriverlo è una buona abitudine: è un piccolo contratto.","en":"The result type can be inferred, but writing it is a good habit: it is a small contract."}}]','{"lang":"ts","prompt":{"it":"Scrivi `doppio(n: number): number` che restituisce `n * 2`.","en":"Write `doppio(n: number): number` that gives back `n * 2`."},"start":"","html":"","checks":[{"re":"doppio\\\\s*\\\\(\\\\s*n\\\\s*:\\\\s*number\\\\s*\\\\)\\\\s*:\\\\s*number","label":{"it":"Parametro e risultato hanno un tipo","en":"Parameter and result have a type"}},{"re":"return\\\\s+n\\\\s*\\\\*\\\\s*2","label":{"it":"Restituisci il doppio","en":"You give back the double"}}],"hint":"function doppio(n: number): number {\\n  return n * 2;\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('ts','interfaces',3,2,'published','{"it":"Interfacce e type","en":"Interfaces and type"}','[{"t":"p","text":{"it":"Un’**interfaccia** descrive la forma di un oggetto. `?` rende una proprietà facoltativa, `readonly` la blocca. `type` dà un nome a un tipo qualsiasi.","en":"An **interface** describes the shape of an object. `?` makes a property optional, `readonly` locks it. `type` gives a name to any type."}},{"t":"code","code":"interface Utente {\\n  readonly id: number;\\n  nome: string;\\n  email?: string;\\n}\\ntype Punti = number;\\nconst u: Utente = { id: 1, nome: \\"Sav\\" };\\n\\ninterface Admin extends Utente {\\n  ruolo: string;\\n}","lang":"ts"},{"t":"p","text":{"it":"Se manca una proprietà obbligatoria o ne scrivi una sbagliata, l’errore appare subito, e l’editor completa i nomi per te.","en":"If a required property is missing or you write a wrong one, the error appears at once, and the editor completes the names for you."}}]','{"lang":"ts","prompt":{"it":"Crea l’interfaccia `Corso` con `titolo: string` e `livelli: number`.","en":"Create the interface `Corso` with `titolo: string` and `livelli: number`."},"start":"","html":"","checks":[{"re":"interface\\\\s+Corso","label":{"it":"L’interfaccia esiste","en":"The interface exists"}},{"re":"titolo\\\\s*:\\\\s*string","label":{"it":"`titolo` è una stringa","en":"`titolo` is a string"}},{"re":"livelli\\\\s*:\\\\s*number","label":{"it":"`livelli` è un numero","en":"`livelli` is a number"}}],"hint":"interface Corso {\\n  titolo: string;\\n  livelli: number;\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('ts','unions',4,3,'published','{"it":"Unioni e restringimento","en":"Unions and narrowing"}','[{"t":"p","text":{"it":"Un’**unione** accetta più tipi: `string | number`. Le unioni di valori creano scelte precise. Il **restringimento** usa un controllo per far capire a TypeScript quale tipo hai.","en":"A **union** accepts several types: `string | number`. Unions of values create precise choices. **Narrowing** uses a check to tell TypeScript which type you have."}},{"t":"code","code":"type Stato = \\"attesa\\" | \\"fatto\\" | \\"errore\\";\\nlet s: Stato = \\"fatto\\";\\n\\nfunction lunghezza(x: string | string[]): number {\\n  if (typeof x === \\"string\\") {\\n    return x.length;  // qui x è string\\n  }\\n  return x.length;    // qui x è string[]\\n}\\nlet nome: string | null = null;","lang":"ts"},{"t":"p","text":{"it":"Con `strictNullChecks` un valore che può essere `null` va controllato prima dell’uso: sparisce il classico errore «cannot read property of null».","en":"With `strictNullChecks` a value that may be `null` must be checked before use: the classic “cannot read property of null” error disappears."}}]','{"lang":"ts","prompt":{"it":"Crea il tipo `Tema` che accetta solo `\\"chiaro\\"` o `\\"scuro\\"`.","en":"Create the type `Tema` that accepts only `\\"chiaro\\"` or `\\"scuro\\"`."},"start":"","html":"","checks":[{"re":"type\\\\s+Tema\\\\s*=","label":{"it":"Il tipo esiste","en":"The type exists"}},{"re":"\\"chiaro\\"\\\\s*\\\\|\\\\s*\\"scuro\\"","label":{"it":"Accetta i due valori","en":"It accepts both values"}}],"hint":"type Tema = \\"chiaro\\" | \\"scuro\\";"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('ts','generics',5,3,'published','{"it":"Generici","en":"Generics"}','[{"t":"p","text":{"it":"Un **generico** è un tipo che fa da parametro: la stessa funzione lavora con tipi diversi senza perdere la precisione. Di solito si chiama `T`.","en":"A **generic** is a type acting as a parameter: the same function works with different types without losing precision. It is usually called `T`."}},{"t":"code","code":"function primo<T>(lista: T[]): T | undefined {\\n  return lista[0];\\n}\\nconst a = primo([1, 2]);     // number\\nconst b = primo([\\"x\\"]);      // string\\n\\ninterface Scatola<T> {\\n  contenuto: T;\\n}\\nconst s: Scatola<number> = { contenuto: 5 };","lang":"ts"},{"t":"p","text":{"it":"Esistono tipi di utilità già pronti: `Partial<T>` rende tutto facoltativo, `Pick<T, K>` sceglie delle proprietà, `Record<K, V>` descrive una mappa.","en":"Ready-made utility types exist: `Partial<T>` makes everything optional, `Pick<T, K>` picks properties, `Record<K, V>` describes a map."}}]','{"lang":"ts","prompt":{"it":"Scrivi `ultimo<T>(lista: T[])` che restituisce l’ultimo elemento.","en":"Write `ultimo<T>(lista: T[])` that gives back the last item."},"start":"","html":"","checks":[{"re":"ultimo\\\\s*<\\\\s*T\\\\s*>\\\\s*\\\\(\\\\s*lista\\\\s*:\\\\s*T\\\\[\\\\]\\\\s*\\\\)","label":{"it":"La funzione è generica","en":"The function is generic"}},{"re":"lista\\\\[lista\\\\.length\\\\s*-\\\\s*1\\\\]|lista\\\\.at\\\\(-1\\\\)","label":{"it":"Restituisci l’ultimo","en":"You give back the last one"}}],"hint":"function ultimo<T>(lista: T[]): T | undefined {\\n  return lista[lista.length - 1];\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('ts','tooling',6,3,'published','{"it":"Il compilatore e le classi","en":"The compiler and classes"}','[{"t":"p","text":{"it":"`tsconfig.json` regola il compilatore: `strict` attiva tutti i controlli. `tsc` compila. Nelle classi `private` e `public` limitano l’accesso, e un costruttore può dichiarare i campi da solo.","en":"`tsconfig.json` sets up the compiler: `strict` turns on all the checks. `tsc` compiles. In classes `private` and `public` limit access, and a constructor can declare fields by itself."}},{"t":"code","code":"// tsconfig.json\\n{\\n  \\"compilerOptions\\": {\\n    \\"target\\": \\"ES2022\\",\\n    \\"strict\\": true\\n  }\\n}\\nclass Eroe {\\n  constructor(public nome: string, private vite = 3) {}\\n  colpisci(): void { this.vite--; }\\n}","lang":"ts"},{"t":"p","text":{"it":"Per le librerie scritte in JavaScript esistono i pacchetti `@types`, che aggiungono i tipi. Un file `.d.ts` contiene solo tipi.","en":"For libraries written in JavaScript there are `@types` packages, which add the types. A `.d.ts` file holds only types."}}]','{"lang":"ts","prompt":{"it":"Scrivi una classe `Conto` con un campo `private saldo: number`.","en":"Write a class `Conto` with a `private saldo: number` field."},"start":"","html":"","checks":[{"re":"class\\\\s+Conto","label":{"it":"La classe esiste","en":"The class exists"}},{"re":"private\\\\s+saldo\\\\s*:\\\\s*number","label":{"it":"Il campo è privato","en":"The field is private"}}],"hint":"class Conto {\\n  private saldo: number = 0;\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('angular-base','components',1,2,'published','{"it":"Il primo componente","en":"The first component"}','[{"t":"p","text":{"it":"In Angular l’interfaccia è fatta di **componenti**: una classe TypeScript con il decoratore `@Component`, che indica il **selettore** (il tag da usare nell’HTML) e il **template**.","en":"In Angular the interface is made of **components**: a TypeScript class with the `@Component` decorator, which gives the **selector** (the tag to use in HTML) and the **template**."}},{"t":"code","code":"import { Component } from \\"@angular/core\\";\\n\\n@Component({\\n  selector: \\"app-saluto\\",\\n  standalone: true,\\n  template: `<h1>Ciao, {{ nome }}!</h1>`,\\n})\\nexport class SalutoComponent {\\n  nome = \\"Ada\\";\\n}","lang":"ts"},{"t":"p","text":{"it":"Le doppie graffe `{{ }}` mostrano nel template il valore di una proprietà della classe: è l’**interpolazione**.","en":"Double braces `{{ }}` show a class property in the template: it is **interpolation**."}}]','{"lang":"angular","prompt":{"it":"Completa il componente `app-carta` con un template che mostra `{{ titolo }}`.","en":"Complete the `app-carta` component with a template that shows `{{ titolo }}`."},"start":"@Component({\\n})\\nexport class CartaComponent {\\n  titolo = \\"Fucina\\";\\n}","html":"","checks":[{"re":"selector\\\\s*:\\\\s*[\\"'']app-carta[\\"'']","label":{"it":"Il selettore è giusto","en":"The selector is right"}},{"re":"template\\\\s*:[\\\\s\\\\S]*\\\\{\\\\{\\\\s*titolo\\\\s*\\\\}\\\\}","label":{"it":"Il template mostra il titolo","en":"The template shows the title"}}],"hint":"@Component({\\n  selector: \\"app-carta\\",\\n  template: `<h2>{{ titolo }}</h2>`,\\n})"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('angular-base','bindings',2,2,'published','{"it":"Binding di proprietà ed eventi","en":"Property and event binding"}','[{"t":"p","text":{"it":"Le **parentesi quadre** collegano una proprietà dell’elemento a un valore: `[disabled]=\\"occupato\\"`. Le **tonde** ascoltano un evento: `(click)=\\"salva()\\"`.","en":"**Square brackets** bind an element property to a value: `[disabled]=\\"occupato\\"`. **Round brackets** listen to an event: `(click)=\\"salva()\\"`."}},{"t":"code","code":"@Component({\\n  selector: \\"app-contatore\\",\\n  template: `\\n    <p>Clic: {{ n }}</p>\\n    <button (click)=\\"piu()\\" [disabled]=\\"n >= 10\\">+1</button>\\n  `,\\n})\\nexport class ContatoreComponent {\\n  n = 0;\\n  piu() { this.n++; }\\n}","lang":"ts"},{"t":"p","text":{"it":"Dati verso la vista con `[ ]`, eventi verso la classe con `( )`. Insieme, `[(ngModel)]` crea un collegamento nei due sensi per i campi dei moduli.","en":"Data to the view with `[ ]`, events to the class with `( )`. Together, `[(ngModel)]` makes a two-way link for form fields."}}]','{"lang":"angular","prompt":{"it":"Al bottone collega `(click)=\\"salva()\\"` e `[disabled]=\\"vuoto\\"`.","en":"Bind `(click)=\\"salva()\\"` and `[disabled]=\\"vuoto\\"` to the button."},"start":"<button>Salva</button>","html":"","checks":[{"re":"\\\\(click\\\\)\\\\s*=\\\\s*\\"salva\\\\(\\\\)\\"","label":{"it":"Ascolta il clic","en":"It listens to the click"}},{"re":"\\\\[disabled\\\\]\\\\s*=\\\\s*\\"vuoto\\"","label":{"it":"Si disattiva","en":"It disables itself"}}],"hint":"<button (click)=\\"salva()\\" [disabled]=\\"vuoto\\">Salva</button>"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('angular-base','control-flow',3,2,'published','{"it":"@if e @for","en":"@if and @for"}','[{"t":"p","text":{"it":"Il nuovo **control flow** di Angular scrive condizioni e cicli direttamente nel template: `@if` mostra un blocco solo se la condizione è vera, `@for` ripete un blocco per ogni elemento.","en":"Angular’s new **control flow** writes conditions and loops right in the template: `@if` shows a block only if the condition is true, `@for` repeats a block for each item."}},{"t":"code","code":"@if (corsi.length > 0) {\\n  <ul>\\n    @for (c of corsi; track c.id) {\\n      <li>{{ c.titolo }}</li>\\n    }\\n  </ul>\\n} @else {\\n  <p>Nessun corso.</p>\\n}","lang":"html"},{"t":"p","text":{"it":"`track` dice ad Angular come riconoscere ogni elemento: così aggiorna solo le righe cambiate.","en":"`track` tells Angular how to recognise each item: so it only updates the rows that changed."}}]','{"lang":"angular","prompt":{"it":"Ripeti un `<li>` per ogni `u` di `utenti` con `@for`, usando `track u.id`.","en":"Repeat an `<li>` for each `u` in `utenti` with `@for`, using `track u.id`."},"start":"<ul>\\n</ul>","html":"","checks":[{"re":"@for\\\\s*\\\\(\\\\s*u\\\\s+of\\\\s+utenti\\\\s*;\\\\s*track\\\\s+u\\\\.id\\\\s*\\\\)","label":{"it":"Il ciclo è giusto","en":"The loop is right"}},{"re":"<li>[\\\\s\\\\S]*\\\\{\\\\{[\\\\s\\\\S]*\\\\}\\\\}[\\\\s\\\\S]*</li>","label":{"it":"Il `<li>` mostra un valore","en":"The `<li>` shows a value"}}],"hint":"@for (u of utenti; track u.id) {\\n  <li>{{ u.nome }}</li>\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('angular-base','signals',4,3,'published','{"it":"I signal","en":"Signals"}','[{"t":"p","text":{"it":"Un **signal** è un valore che avvisa quando cambia. Si crea con `signal(0)`, si legge chiamandolo (`conta()`), si cambia con `set` o `update`. `computed` deriva un valore che si aggiorna da solo.","en":"A **signal** is a value that tells when it changes. You create it with `signal(0)`, read it by calling it (`conta()`), change it with `set` or `update`. `computed` derives a value that updates by itself."}},{"t":"code","code":"import { Component, signal, computed } from \\"@angular/core\\";\\n\\n@Component({\\n  selector: \\"app-carrello\\",\\n  template: `<p>{{ pezzi() }} pezzi · {{ totale() }} €</p>\\n             <button (click)=\\"aggiungi()\\">+</button>`,\\n})\\nexport class CarrelloComponent {\\n  pezzi = signal(0);\\n  totale = computed(() => this.pezzi() * 5);\\n  aggiungi() { this.pezzi.update(n => n + 1); }\\n}","lang":"ts"},{"t":"p","text":{"it":"Angular sa esattamente quali parti della pagina dipendono da un signal e aggiorna solo quelle.","en":"Angular knows exactly which parts of the page depend on a signal and updates only those."}}]','{"lang":"angular","prompt":{"it":"Crea `voti = signal(0)` e `doppio = computed(() => this.voti() * 2)`.","en":"Create `voti = signal(0)` and `doppio = computed(() => this.voti() * 2)`."},"start":"export class VotiComponent {\\n}","html":"","checks":[{"re":"voti\\\\s*=\\\\s*signal\\\\s*\\\\(\\\\s*0\\\\s*\\\\)","label":{"it":"Il signal esiste","en":"The signal exists"}},{"re":"doppio\\\\s*=\\\\s*computed\\\\s*\\\\(\\\\s*\\\\(\\\\)\\\\s*=>\\\\s*this\\\\.voti\\\\(\\\\)\\\\s*\\\\*\\\\s*2\\\\s*\\\\)","label":{"it":"Il valore derivato è giusto","en":"The derived value is right"}}],"hint":"voti = signal(0);\\ndoppio = computed(() => this.voti() * 2);"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('angular-base','services',5,3,'published','{"it":"Servizi e dati","en":"Services and data"}','[{"t":"p","text":{"it":"Un **servizio** contiene la logica condivisa (dati, chiamate al server) ed è segnato con `@Injectable`. I componenti lo ricevono con `inject()`: è la **dependency injection**.","en":"A **service** holds shared logic (data, server calls) and is marked with `@Injectable`. Components receive it with `inject()`: it is **dependency injection**."}},{"t":"code","code":"@Injectable({ providedIn: \\"root\\" })\\nexport class CorsiService {\\n  private http = inject(HttpClient);\\n  elenco() {\\n    return this.http.get<Corso[]>(\\"/api/corsi\\");\\n  }\\n}\\n\\nexport class ElencoComponent {\\n  private corsi = inject(CorsiService);\\n  dati = toSignal(this.corsi.elenco(), { initialValue: [] });\\n}","lang":"ts"},{"t":"p","text":{"it":"`providedIn: \\"root\\"` crea un solo esemplare per tutta l’app. `HttpClient` restituisce un Observable; `toSignal` lo trasforma in un signal da usare nel template.","en":"`providedIn: \\"root\\"` creates a single instance for the whole app. `HttpClient` returns an Observable; `toSignal` turns it into a signal to use in the template."}}]','{"lang":"angular","prompt":{"it":"Segna `MeteoService` con `@Injectable({ providedIn: \\"root\\" })`.","en":"Mark `MeteoService` with `@Injectable({ providedIn: \\"root\\" })`."},"start":"export class MeteoService {}","html":"","checks":[{"re":"@Injectable\\\\s*\\\\(\\\\s*\\\\{\\\\s*providedIn\\\\s*:\\\\s*[\\"'']root[\\"'']\\\\s*\\\\}\\\\s*\\\\)\\\\s*export\\\\s+class\\\\s+MeteoService","label":{"it":"Il servizio è iniettabile in tutta l’app","en":"The service is injectable app-wide"}}],"hint":"@Injectable({ providedIn: \\"root\\" })\\nexport class MeteoService {}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('angular-intermediate','io',1,2,'published','{"it":"Input e output","en":"Inputs and outputs"}','[{"t":"p","text":{"it":"Un componente figlio riceve dati con `input()` e manda eventi al padre con `output()`. Il padre li collega con le quadre e le tonde, come per gli elementi HTML.","en":"A child component receives data with `input()` and sends events to the parent with `output()`. The parent binds them with square and round brackets, as with HTML elements."}},{"t":"code","code":"export class VotoComponent {\\n  stelle = input.required<number>();\\n  cambia = output<number>();\\n  scegli(n: number) { this.cambia.emit(n); }\\n}\\n\\n<!-- nel padre -->\\n<app-voto [stelle]=\\"voto()\\" (cambia)=\\"voto.set($event)\\" />","lang":"ts"},{"t":"p","text":{"it":"`$event` contiene il valore emesso dal figlio. Il flusso è sempre lo stesso: dati in giù, eventi in su.","en":"`$event` holds the value emitted by the child. The flow is always the same: data down, events up."}}]','{"lang":"angular","prompt":{"it":"Nel componente dichiara `titolo = input.required<string>()` e `chiudi = output<void>()`.","en":"In the component declare `titolo = input.required<string>()` and `chiudi = output<void>()`."},"start":"export class AvvisoComponent {\\n}","html":"","checks":[{"re":"titolo\\\\s*=\\\\s*input\\\\.required<string>\\\\(\\\\)","label":{"it":"C’è l’input","en":"There is the input"}},{"re":"chiudi\\\\s*=\\\\s*output<void>\\\\(\\\\)","label":{"it":"C’è l’output","en":"There is the output"}}],"hint":"titolo = input.required<string>();\\nchiudi = output<void>();"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('angular-intermediate','routing',2,2,'published','{"it":"Le rotte","en":"Routing"}','[{"t":"p","text":{"it":"Il **router** associa un indirizzo a un componente. Le rotte si elencano in un array; `<router-outlet />` è il punto della pagina dove compare il componente scelto, e `routerLink` crea i collegamenti.","en":"The **router** maps an address to a component. Routes are listed in an array; `<router-outlet />` is the spot where the chosen component appears, and `routerLink` makes the links."}},{"t":"code","code":"export const routes: Routes = [\\n  { path: \\"\\", component: HomeComponent },\\n  { path: \\"corsi/:id\\", component: CorsoComponent },\\n  { path: \\"**\\", component: NonTrovatoComponent },\\n];\\n\\n<a routerLink=\\"/corsi/42\\">Apri il corso</a>\\n<router-outlet />","lang":"ts"},{"t":"p","text":{"it":"`:id` è un parametro: il componente lo legge con `input()` se attivi `withComponentInputBinding()`. `**` cattura ogni indirizzo che non esiste.","en":"`:id` is a parameter: the component reads it with `input()` if you enable `withComponentInputBinding()`. `**` catches every address that does not exist."}}]','{"lang":"angular","prompt":{"it":"Aggiungi la rotta `{ path: \\"profilo\\", component: ProfiloComponent }`.","en":"Add the route `{ path: \\"profilo\\", component: ProfiloComponent }`."},"start":"export const routes: Routes = [\\n];","html":"","checks":[{"re":"path\\\\s*:\\\\s*[\\"'']profilo[\\"'']\\\\s*,\\\\s*component\\\\s*:\\\\s*ProfiloComponent","label":{"it":"La rotta esiste","en":"The route exists"}}],"hint":"{ path: \\"profilo\\", component: ProfiloComponent },"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('angular-intermediate','forms',3,2,'published','{"it":"Moduli reattivi","en":"Reactive forms"}','[{"t":"p","text":{"it":"Con i **moduli reattivi** il modulo è descritto nella classe: `FormGroup` raccoglie i campi, `FormControl` è un campo con il suo valore e i suoi **validatori**.","en":"With **reactive forms** the form is described in the class: `FormGroup` gathers the fields, `FormControl` is a field with its value and its **validators**."}},{"t":"code","code":"modulo = new FormGroup({\\n  email: new FormControl(\\"\\", [Validators.required, Validators.email]),\\n  eta: new FormControl(18, Validators.min(14)),\\n});\\n\\n<form [formGroup]=\\"modulo\\" (ngSubmit)=\\"invia()\\">\\n  <input formControlName=\\"email\\" />\\n  <button [disabled]=\\"modulo.invalid\\">Invia</button>\\n</form>","lang":"ts"},{"t":"p","text":{"it":"`modulo.invalid` è vero finché un campo non rispetta le regole: il bottone si attiva solo quando tutto è a posto.","en":"`modulo.invalid` is true as long as a field breaks a rule: the button turns on only when everything is right."}}]','{"lang":"angular","prompt":{"it":"Crea `nome: new FormControl(\\"\\", Validators.required)` dentro il `FormGroup`.","en":"Create `nome: new FormControl(\\"\\", Validators.required)` inside the `FormGroup`."},"start":"modulo = new FormGroup({\\n});","html":"","checks":[{"re":"nome\\\\s*:\\\\s*new\\\\s+FormControl\\\\s*\\\\(\\\\s*[\\"''][\\"'']\\\\s*,\\\\s*\\\\[?\\\\s*Validators\\\\.required","label":{"it":"Il campo è obbligatorio","en":"The field is required"}}],"hint":"modulo = new FormGroup({\\n  nome: new FormControl(\\"\\", Validators.required),\\n});"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('angular-intermediate','rxjs',4,3,'published','{"it":"RxJS e Observable","en":"RxJS and Observables"}','[{"t":"p","text":{"it":"Un **Observable** è un flusso di valori nel tempo: una richiesta, i tasti premuti, un timer. Gli **operatori** di RxJS lo trasformano in una catena con `pipe`.","en":"An **Observable** is a stream of values over time: a request, keystrokes, a timer. RxJS **operators** transform it in a chain with `pipe`."}},{"t":"code","code":"this.ricerca.valueChanges.pipe(\\n  debounceTime(300),\\n  map(t => t.trim()),\\n  filter(t => t.length > 1),\\n  switchMap(t => this.http.get<Corso[]>(`/api/cerca?q=${t}`)),\\n).subscribe(risultati => this.trovati.set(risultati));","lang":"ts"},{"t":"p","text":{"it":"`debounceTime` aspetta che l’utente smetta di scrivere, `switchMap` annulla la richiesta vecchia quando ne parte una nuova.","en":"`debounceTime` waits until the user stops typing, `switchMap` cancels the old request when a new one starts."}}]','{"lang":"angular","prompt":{"it":"Aggiungi `debounceTime(300)` dentro la `pipe`.","en":"Add `debounceTime(300)` inside the `pipe`."},"start":"testo$.pipe(\\n  map(t => t.trim()),\\n).subscribe(console.log);","html":"","checks":[{"re":"pipe\\\\s*\\\\(\\\\s*debounceTime\\\\s*\\\\(\\\\s*300\\\\s*\\\\)","label":{"it":"Aspetta la pausa per primo","en":"It waits for the pause first"}}],"hint":"testo$.pipe(\\n  debounceTime(300),\\n  map(t => t.trim()),\\n).subscribe(console.log);"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('angular-intermediate','guards',5,3,'published','{"it":"Guardie e intercettori","en":"Guards and interceptors"}','[{"t":"p","text":{"it":"Una **guardia** decide se si può entrare in una rotta: `canActivate` restituisce `true`, `false` o un altro indirizzo. Un **intercettore** modifica tutte le richieste HTTP, per esempio aggiungendo un token.","en":"A **guard** decides whether you may enter a route: `canActivate` returns `true`, `false` or another address. An **interceptor** changes every HTTP request, for example adding a token."}},{"t":"code","code":"export const soloUtenti: CanActivateFn = () => {\\n  const auth = inject(AuthService);\\n  return auth.loggato() ? true : inject(Router).parseUrl(\\"/login\\");\\n};\\n\\n{ path: \\"profilo\\", component: ProfiloComponent, canActivate: [soloUtenti] }\\n\\nexport const conToken: HttpInterceptorFn = (req, next) =>\\n  next(req.clone({ setHeaders: { Authorization: `Bearer ${token()}` } }));","lang":"ts"},{"t":"p","text":{"it":"Le guardie migliorano l’esperienza, ma la sicurezza vera resta sul server: ogni API deve controllare chi la chiama.","en":"Guards improve the experience, but real security stays on the server: every API must check who calls it."}}]','{"lang":"angular","prompt":{"it":"Proteggi la rotta `admin` con `canActivate: [soloAdmin]`.","en":"Protect the `admin` route with `canActivate: [soloAdmin]`."},"start":"{ path: \\"admin\\", component: AdminComponent }","html":"","checks":[{"re":"path\\\\s*:\\\\s*[\\"'']admin[\\"''][^}]*canActivate\\\\s*:\\\\s*\\\\[\\\\s*soloAdmin\\\\s*\\\\]","label":{"it":"La rotta è protetta","en":"The route is protected"}}],"hint":"{ path: \\"admin\\", component: AdminComponent, canActivate: [soloAdmin] }"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('vue-base','sfc',1,1,'published','{"it":"Il componente in un file","en":"The single-file component"}','[{"t":"p","text":{"it":"Un componente Vue vive in un file `.vue` con tre blocchi: `<script setup>` per la logica, `<template>` per l’HTML e `<style scoped>` per lo stile che vale solo lì.","en":"A Vue component lives in a `.vue` file with three blocks: `<script setup>` for logic, `<template>` for HTML and `<style scoped>` for styles that apply only there."}},{"t":"code","code":"<script setup>\\nconst nome = \\"Ada\\";\\n</script>\\n\\n<template>\\n  <h1>Ciao, {{ nome }}!</h1>\\n</template>\\n\\n<style scoped>\\nh1 { color: tomato; }\\n</style>","lang":"vue"},{"t":"p","text":{"it":"Nel template le doppie graffe mostrano un valore. Tutto ciò che dichiari in `<script setup>` è subito usabile nel template.","en":"In the template, double braces show a value. Everything declared in `<script setup>` can be used in the template right away."}}]','{"lang":"vue","prompt":{"it":"Nel template mostra `{{ titolo }}` dentro un `<h2>`.","en":"In the template show `{{ titolo }}` inside an `<h2>`."},"start":"<script setup>\\nconst titolo = \\"Fucina\\";\\n</script>\\n\\n<template>\\n</template>","html":"","checks":[{"re":"<template>[\\\\s\\\\S]*<h2>\\\\s*\\\\{\\\\{\\\\s*titolo\\\\s*\\\\}\\\\}\\\\s*</h2>[\\\\s\\\\S]*</template>","label":{"it":"Il titolo è nel template","en":"The title is in the template"}}],"hint":"<template>\\n  <h2>{{ titolo }}</h2>\\n</template>"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('vue-base','reactivity',2,1,'published','{"it":"Dati reattivi","en":"Reactive data"}','[{"t":"p","text":{"it":"`ref()` crea un dato **reattivo**: quando cambia, la pagina si aggiorna da sola. Nello script si legge e si scrive con `.value`; nel template no, Vue lo fa per te.","en":"`ref()` creates **reactive** data: when it changes, the page updates by itself. In the script you read and write it with `.value`; in the template you do not, Vue does it for you."}},{"t":"code","code":"<script setup>\\nimport { ref, computed } from \\"vue\\";\\n\\nconst conta = ref(0);\\nconst doppio = computed(() => conta.value * 2);\\nfunction piu() { conta.value++; }\\n</script>\\n\\n<template>\\n  <button @click=\\"piu\\">{{ conta }} · {{ doppio }}</button>\\n</template>","lang":"vue"},{"t":"p","text":{"it":"`computed` calcola un valore dagli altri e lo ricorda finché non cambiano.","en":"`computed` works out a value from the others and remembers it until they change."}}]','{"lang":"vue","prompt":{"it":"Crea `const voti = ref(0)` e `const meta = computed(() => voti.value / 2)`.","en":"Create `const voti = ref(0)` and `const meta = computed(() => voti.value / 2)`."},"start":"<script setup>\\nimport { ref, computed } from \\"vue\\";\\n</script>","html":"","checks":[{"re":"const\\\\s+voti\\\\s*=\\\\s*ref\\\\s*\\\\(\\\\s*0\\\\s*\\\\)","label":{"it":"Il ref esiste","en":"The ref exists"}},{"re":"const\\\\s+meta\\\\s*=\\\\s*computed\\\\s*\\\\(\\\\s*\\\\(\\\\)\\\\s*=>\\\\s*voti\\\\.value\\\\s*/\\\\s*2\\\\s*\\\\)","label":{"it":"Il computed è giusto","en":"The computed is right"}}],"hint":"const voti = ref(0);\\nconst meta = computed(() => voti.value / 2);"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('vue-base','directives',3,1,'published','{"it":"Direttive","en":"Directives"}','[{"t":"p","text":{"it":"Le **direttive** sono attributi speciali che iniziano con `v-`. `v-if` mostra un elemento solo se la condizione è vera, `v-show` lo nasconde con il CSS, `v-bind` (abbreviato `:`) collega un attributo.","en":"**Directives** are special attributes starting with `v-`. `v-if` shows an element only if the condition is true, `v-show` hides it with CSS, `v-bind` (short `:`) binds an attribute."}},{"t":"code","code":"<img :src=\\"foto\\" :alt=\\"descrizione\\" />\\n<p v-if=\\"errore\\" class=\\"rosso\\">{{ errore }}</p>\\n<p v-else>Tutto a posto</p>\\n<div v-show=\\"aperto\\">Menu</div>","lang":"vue"},{"t":"p","text":{"it":"`v-if` crea e distrugge l’elemento; `v-show` lo tiene ma cambia `display`. Usa `v-show` per qualcosa che si apre e chiude spesso.","en":"`v-if` creates and destroys the element; `v-show` keeps it but changes `display`. Use `v-show` for something that opens and closes often."}}]','{"lang":"vue","prompt":{"it":"Mostra il `<p>` solo se `caricando` è vero, con `v-if`.","en":"Show the `<p>` only if `caricando` is true, with `v-if`."},"start":"<p>Caricamento…</p>","html":"","checks":[{"re":"<p\\\\s+v-if\\\\s*=\\\\s*\\"caricando\\"\\\\s*>","label":{"it":"C’è la condizione","en":"The condition is there"}}],"hint":"<p v-if=\\"caricando\\">Caricamento…</p>"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('vue-base','events',4,2,'published','{"it":"Eventi e moduli","en":"Events and forms"}','[{"t":"p","text":{"it":"`v-on:click`, abbreviato `@click`, chiama una funzione. I **modificatori** cambiano il comportamento: `@submit.prevent` blocca il ricaricamento della pagina.","en":"`v-on:click`, short `@click`, calls a function. **Modifiers** change the behaviour: `@submit.prevent` stops the page from reloading."}},{"t":"code","code":"<script setup>\\nimport { ref } from \\"vue\\";\\nconst email = ref(\\"\\");\\nfunction invia() { alert(\\"Iscritto: \\" + email.value); }\\n</script>\\n\\n<template>\\n  <form @submit.prevent=\\"invia\\">\\n    <input v-model=\\"email\\" type=\\"email\\" />\\n    <button>Iscriviti</button>\\n  </form>\\n</template>","lang":"vue"},{"t":"p","text":{"it":"`v-model` collega un campo a un dato nei due sensi: scrivi nel campo e il dato cambia, cambi il dato e il campo si aggiorna.","en":"`v-model` links a field to data both ways: type in the field and the data changes, change the data and the field updates."}}]','{"lang":"vue","prompt":{"it":"Collega l’input a `nome` con `v-model` e il bottone a `saluta` con `@click`.","en":"Bind the input to `nome` with `v-model` and the button to `saluta` with `@click`."},"start":"<input />\\n<button>Saluta</button>","html":"","checks":[{"re":"<input[^>]*v-model\\\\s*=\\\\s*\\"nome\\"","label":{"it":"L’input è collegato","en":"The input is bound"}},{"re":"<button[^>]*@click\\\\s*=\\\\s*\\"saluta(\\\\(\\\\))?\\"","label":{"it":"Il bottone chiama `saluta`","en":"The button calls `saluta`"}}],"hint":"<input v-model=\\"nome\\" />\\n<button @click=\\"saluta\\">Saluta</button>"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('vue-base','lists',5,2,'published','{"it":"Liste e componenti figli","en":"Lists and child components"}','[{"t":"p","text":{"it":"`v-for` ripete un elemento per ogni voce di un array; `:key` dà a ogni voce un’identità. I componenti figli ricevono dati con le **props**, dichiarate con `defineProps`.","en":"`v-for` repeats an element for each item of an array; `:key` gives each item an identity. Child components receive data through **props**, declared with `defineProps`."}},{"t":"code","code":"<!-- Corso.vue -->\\n<script setup>\\ndefineProps({ titolo: String, livelli: Number });\\n</script>\\n<template><li>{{ titolo }} · {{ livelli }}</li></template>\\n\\n<!-- App.vue -->\\n<ul>\\n  <Corso v-for=\\"c in corsi\\" :key=\\"c.id\\" :titolo=\\"c.titolo\\" :livelli=\\"c.livelli\\" />\\n</ul>","lang":"vue"},{"t":"p","text":{"it":"Le props scendono dal padre al figlio e il figlio non le modifica: se deve avvisare il padre, emette un evento con `defineEmits`.","en":"Props go down from parent to child and the child does not change them: to tell the parent something, it emits an event with `defineEmits`."}}]','{"lang":"vue","prompt":{"it":"Ripeti un `<li>` per ogni `p` di `prodotti` con `v-for` e `:key=\\"p.id\\"`.","en":"Repeat an `<li>` for each `p` in `prodotti` with `v-for` and `:key=\\"p.id\\"`."},"start":"<ul>\\n  <li>{{ p.nome }}</li>\\n</ul>","html":"","checks":[{"re":"<li[^>]*v-for\\\\s*=\\\\s*\\"p\\\\s+in\\\\s+prodotti\\"","label":{"it":"Il ciclo è giusto","en":"The loop is right"}},{"re":"<li[^>]*:key\\\\s*=\\\\s*\\"p\\\\.id\\"","label":{"it":"Ogni voce ha la sua chiave","en":"Each item has its key"}}],"hint":"<li v-for=\\"p in prodotti\\" :key=\\"p.id\\">{{ p.nome }}</li>"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('vue-intermediate','composables',1,2,'published','{"it":"I composable","en":"Composables"}','[{"t":"p","text":{"it":"Un **composable** è una funzione che inizia per `use` e raccoglie logica riutilizzabile con `ref` e `computed`. Più componenti la chiamano e ognuno riceve il suo stato.","en":"A **composable** is a function starting with `use` that packs reusable logic with `ref` and `computed`. Several components call it and each gets its own state."}},{"t":"code","code":"// useContatore.js\\nimport { ref } from \\"vue\\";\\n\\nexport function useContatore(inizio = 0) {\\n  const n = ref(inizio);\\n  const piu = () => n.value++;\\n  const azzera = () => (n.value = inizio);\\n  return { n, piu, azzera };\\n}\\n\\n// in un componente\\nconst { n, piu } = useContatore(10);","lang":"js"},{"t":"p","text":{"it":"È il modo di Vue di condividere comportamento senza copiare codice tra i componenti.","en":"It is Vue’s way of sharing behaviour without copying code between components."}}]','{"lang":"vue","prompt":{"it":"Scrivi `useInterruttore()` che crea `acceso = ref(false)` e restituisce `{ acceso, cambia }`.","en":"Write `useInterruttore()` that creates `acceso = ref(false)` and returns `{ acceso, cambia }`."},"start":"import { ref } from \\"vue\\";","html":"","checks":[{"re":"function\\\\s+useInterruttore\\\\s*\\\\(","label":{"it":"La funzione esiste","en":"The function exists"}},{"re":"acceso\\\\s*=\\\\s*ref\\\\s*\\\\(\\\\s*false\\\\s*\\\\)","label":{"it":"Lo stato parte spento","en":"The state starts off"}},{"re":"return\\\\s*\\\\{\\\\s*acceso\\\\s*,\\\\s*cambia\\\\s*\\\\}","label":{"it":"Restituisce stato e funzione","en":"It returns state and function"}}],"hint":"export function useInterruttore() {\\n  const acceso = ref(false);\\n  const cambia = () => (acceso.value = !acceso.value);\\n  return { acceso, cambia };\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('vue-intermediate','watch',2,2,'published','{"it":"Watcher e ciclo di vita","en":"Watchers and lifecycle"}','[{"t":"p","text":{"it":"`watch` esegue codice quando un dato cambia: utile per salvare, cercare o chiamare il server. `onMounted` esegue codice quando il componente compare nella pagina.","en":"`watch` runs code when some data changes: handy for saving, searching or calling the server. `onMounted` runs code when the component appears on the page."}},{"t":"code","code":"import { ref, watch, onMounted } from \\"vue\\";\\n\\nconst tema = ref(localStorage.getItem(\\"tema\\") ?? \\"chiaro\\");\\n\\nwatch(tema, (nuovo, vecchio) => {\\n  localStorage.setItem(\\"tema\\", nuovo);\\n});\\n\\nonMounted(() => console.log(\\"Componente pronto\\"));","lang":"js"},{"t":"p","text":{"it":"`computed` calcola un valore; `watch` fa qualcosa (un effetto). Se ti serve un risultato da mostrare, usa `computed`.","en":"`computed` works out a value; `watch` does something (a side effect). If you need a result to show, use `computed`."}}]','{"lang":"vue","prompt":{"it":"Scrivi un `watch` su `filtro` che chiama `cerca(nuovo)`.","en":"Write a `watch` on `filtro` that calls `cerca(nuovo)`."},"start":"const filtro = ref(\\"\\");","html":"","checks":[{"re":"watch\\\\s*\\\\(\\\\s*filtro\\\\s*,\\\\s*\\\\(?\\\\s*nuovo","label":{"it":"Osserva `filtro`","en":"It watches `filtro`"}},{"re":"cerca\\\\s*\\\\(\\\\s*nuovo\\\\s*\\\\)","label":{"it":"Chiama la ricerca","en":"It calls the search"}}],"hint":"watch(filtro, (nuovo) => {\\n  cerca(nuovo);\\n});"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('vue-intermediate','router',3,2,'published','{"it":"Vue Router","en":"Vue Router"}','[{"t":"p","text":{"it":"**Vue Router** collega gli indirizzi ai componenti. `<RouterLink to=\\"/corsi\\">` crea un collegamento senza ricaricare, `<RouterView />` è il punto dove appare la pagina.","en":"**Vue Router** maps addresses to components. `<RouterLink to=\\"/corsi\\">` makes a link without reloading, `<RouterView />` is where the page appears."}},{"t":"code","code":"const router = createRouter({\\n  history: createWebHistory(),\\n  routes: [\\n    { path: \\"/\\", component: Home },\\n    { path: \\"/corsi/:id\\", component: Corso },\\n  ],\\n});\\n\\n// dentro Corso.vue\\nconst route = useRoute();\\nconst id = computed(() => route.params.id);","lang":"js"},{"t":"p","text":{"it":"`useRoute()` legge l’indirizzo attuale e i parametri; `useRouter()` permette di spostarsi via codice con `router.push(\\"/\\")`.","en":"`useRoute()` reads the current address and its parameters; `useRouter()` lets you move in code with `router.push(\\"/\\")`."}}]','{"lang":"vue","prompt":{"it":"Aggiungi la rotta `{ path: \\"/profilo\\", component: Profilo }`.","en":"Add the route `{ path: \\"/profilo\\", component: Profilo }`."},"start":"routes: [\\n  { path: \\"/\\", component: Home },\\n]","html":"","checks":[{"re":"path\\\\s*:\\\\s*[\\"'']/profilo[\\"'']\\\\s*,\\\\s*component\\\\s*:\\\\s*Profilo","label":{"it":"La rotta esiste","en":"The route exists"}}],"hint":"{ path: \\"/profilo\\", component: Profilo },"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('vue-intermediate','pinia',4,3,'published','{"it":"Stato condiviso con Pinia","en":"Shared state with Pinia"}','[{"t":"p","text":{"it":"Quando molti componenti devono vedere gli stessi dati (l’utente, il carrello) si usa uno **store**. Con **Pinia** si definisce con `defineStore` e si usa in ogni componente con la sua funzione.","en":"When many components must see the same data (the user, the cart) you use a **store**. With **Pinia** you define it with `defineStore` and use it in any component through its function."}},{"t":"code","code":"export const useCarrello = defineStore(\\"carrello\\", () => {\\n  const pezzi = ref([]);\\n  const totale = computed(() => pezzi.value.reduce((s, p) => s + p.prezzo, 0));\\n  function aggiungi(p) { pezzi.value.push(p); }\\n  return { pezzi, totale, aggiungi };\\n});\\n\\n// in qualsiasi componente\\nconst carrello = useCarrello();\\ncarrello.aggiungi({ nome: \\"Corso\\", prezzo: 10 });","lang":"js"},{"t":"p","text":{"it":"A differenza di un composable, lo store è **unico**: tutti i componenti vedono gli stessi `pezzi`.","en":"Unlike a composable, the store is **single**: every component sees the same `pezzi`."}}]','{"lang":"vue","prompt":{"it":"Crea `useTema = defineStore(\\"tema\\", () => { ... })` con `const scuro = ref(false)` restituito.","en":"Create `useTema = defineStore(\\"tema\\", () => { ... })` with `const scuro = ref(false)` returned."},"start":"import { defineStore } from \\"pinia\\";","html":"","checks":[{"re":"useTema\\\\s*=\\\\s*defineStore\\\\s*\\\\(\\\\s*[\\"'']tema[\\"'']","label":{"it":"Lo store esiste","en":"The store exists"}},{"re":"scuro\\\\s*=\\\\s*ref\\\\s*\\\\(\\\\s*false\\\\s*\\\\)","label":{"it":"Lo stato parte chiaro","en":"The state starts light"}},{"re":"return\\\\s*\\\\{\\\\s*scuro","label":{"it":"Lo stato è restituito","en":"The state is returned"}}],"hint":"export const useTema = defineStore(\\"tema\\", () => {\\n  const scuro = ref(false);\\n  return { scuro };\\n});"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('vue-intermediate','fetch',5,3,'published','{"it":"Dati dal server","en":"Data from the server"}','[{"t":"p","text":{"it":"Per caricare dati si usa `fetch` dentro una funzione `async`, tenendo tre stati: **caricamento**, **errore** e **dati**. Il template mostra uno dei tre.","en":"To load data you use `fetch` inside an `async` function, keeping three states: **loading**, **error** and **data**. The template shows one of them."}},{"t":"code","code":"const corsi = ref([]);\\nconst carica = ref(true);\\nconst errore = ref(null);\\n\\nonMounted(async () => {\\n  try {\\n    const r = await fetch(\\"/api/corsi\\");\\n    if (!r.ok) throw new Error(\\"Errore \\" + r.status);\\n    corsi.value = await r.json();\\n  } catch (e) {\\n    errore.value = e.message;\\n  } finally {\\n    carica.value = false;\\n  }\\n});","lang":"js"},{"t":"p","text":{"it":"`fetch` non dà errore con le risposte 404 o 500: va controllato `r.ok`.","en":"`fetch` does not throw on 404 or 500 responses: you must check `r.ok`."}}]','{"lang":"vue","prompt":{"it":"Controlla `if (!r.ok)` e lancia un errore prima di leggere il JSON.","en":"Check `if (!r.ok)` and throw an error before reading the JSON."},"start":"const r = await fetch(\\"/api/note\\");\\nnote.value = await r.json();","html":"","checks":[{"re":"if\\\\s*\\\\(\\\\s*!\\\\s*r\\\\.ok\\\\s*\\\\)\\\\s*throw","label":{"it":"Controlli la risposta","en":"You check the response"}}],"hint":"const r = await fetch(\\"/api/note\\");\\nif (!r.ok) throw new Error(\\"Errore \\" + r.status);\\nnote.value = await r.json();"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('php-base','hello',1,1,'published','{"it":"Ciao dal server","en":"Hello from the server"}','[{"t":"p","text":{"it":"**PHP** gira sul server e produce la pagina prima che arrivi al browser. Il codice sta tra `<?php` e `?>`. Le variabili iniziano con `$` e ogni istruzione finisce con `;`.","en":"**PHP** runs on the server and produces the page before it reaches the browser. Code lives between `<?php` and `?>`. Variables start with `$` and every statement ends with `;`."}},{"t":"code","code":"<?php\\n$nome = \\"Sav\\";\\n$punti = 10;\\necho \\"Ciao $nome, hai $punti punti\\";\\necho ''Virgolette singole: $nome'';\\n?>\\n<p><?= $nome ?></p>","lang":"php"},{"t":"p","text":{"it":"Tra virgolette doppie le variabili vengono sostituite, tra singole no. `<?=` è la scorciatoia per stampare un valore nell’HTML.","en":"Between double quotes variables are replaced, between single quotes they are not. `<?=` is the shortcut for printing a value in HTML."}}]','{"lang":"php","prompt":{"it":"Crea `$nome` e stampalo con `echo` dentro un saluto tra virgolette doppie.","en":"Create `$nome` and print it with `echo` inside a greeting between double quotes."},"start":"<?php","html":"","checks":[{"re":"\\\\$nome\\\\s*=","label":{"it":"Crei `$nome`","en":"You create `$nome`"}},{"re":"echo\\\\s+\\"[^\\"]*\\\\$nome","label":{"it":"Lo stampi","en":"You print it"}}],"hint":"<?php\\n$nome = \\"Sav\\";\\necho \\"Ciao $nome\\";"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('php-base','logic',2,1,'published','{"it":"Condizioni e cicli","en":"Conditions and loops"}','[{"t":"p","text":{"it":"`if`, `else`, `for` e `while` funzionano come in JavaScript. Le stringhe si uniscono con il punto. Per confrontare usa `===`.","en":"`if`, `else`, `for` and `while` work as in JavaScript. Strings join with a dot. To compare use `===`."}},{"t":"code","code":"<?php\\n$voto = 8;\\nif ($voto >= 6) {\\n    echo \\"Promosso\\";\\n} else {\\n    echo \\"Riprova\\";\\n}\\nfor ($i = 1; $i <= 3; $i++) {\\n    echo \\"Giro \\" . $i . \\"<br>\\";\\n}\\n$esito = match (true) {\\n    $voto >= 9 => \\"Ottimo\\",\\n    default => \\"Bene\\",\\n};","lang":"php"},{"t":"p","text":{"it":"`match` è un confronto compatto che restituisce un valore. Il punto `.` unisce i testi: `+` farebbe una somma.","en":"`match` is a compact comparison that gives back a value. The dot `.` joins text: `+` would add numbers."}}]','{"lang":"php","prompt":{"it":"Con un ciclo `for`, stampa i numeri da 1 a 5.","en":"With a `for` loop, print the numbers from 1 to 5."},"start":"<?php","html":"","checks":[{"re":"for\\\\s*\\\\(\\\\s*\\\\$i\\\\s*=\\\\s*1\\\\s*;\\\\s*\\\\$i\\\\s*<=\\\\s*5\\\\s*;\\\\s*\\\\$i\\\\+\\\\+\\\\s*\\\\)","label":{"it":"Il ciclo va da 1 a 5","en":"The loop goes from 1 to 5"}},{"re":"echo\\\\s+\\\\$i","label":{"it":"Stampi `$i`","en":"You print `$i`"}}],"hint":"<?php\\nfor ($i = 1; $i <= 5; $i++) {\\n    echo $i;\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('php-base','arrays',3,1,'published','{"it":"Array","en":"Arrays"}','[{"t":"p","text":{"it":"Gli array PHP fanno due lavori: liste e coppie chiave-valore. `foreach` li scorre. `count` dice quanti elementi ci sono.","en":"PHP arrays do two jobs: lists and key-value pairs. `foreach` walks them. `count` says how many items there are."}},{"t":"code","code":"<?php\\n$corsi = [\\"HTML\\", \\"CSS\\"];\\n$corsi[] = \\"PHP\\";\\n\\n$utente = [\\"nome\\" => \\"Sav\\", \\"punti\\" => 10];\\necho $utente[\\"nome\\"];\\n\\nforeach ($utente as $chiave => $valore) {\\n    echo \\"$chiave: $valore<br>\\";\\n}\\necho count($corsi); // 3\\nin_array(\\"CSS\\", $corsi); // true","lang":"php"},{"t":"p","text":{"it":"`$lista[] = x` aggiunge in fondo. `=>` lega una chiave al suo valore.","en":"`$lista[] = x` adds to the end. `=>` ties a key to its value."}}]','{"lang":"php","prompt":{"it":"Crea l’array associativo `$libro` con `titolo` e stampa il titolo.","en":"Create the associative array `$libro` with `titolo` and print the title."},"start":"<?php","html":"","checks":[{"re":"\\\\$libro\\\\s*=\\\\s*\\\\[\\\\s*[\\"'']titolo[\\"'']\\\\s*=>","label":{"it":"L’array ha la chiave","en":"The array has the key"}},{"re":"echo\\\\s+\\\\$libro\\\\[\\\\s*[\\"'']titolo[\\"'']\\\\s*\\\\]","label":{"it":"Stampi il titolo","en":"You print the title"}}],"hint":"<?php\\n$libro = [\\"titolo\\" => \\"Fucina\\"];\\necho $libro[\\"titolo\\"];"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('php-base','functions',4,2,'published','{"it":"Funzioni e stringhe","en":"Functions and strings"}','[{"t":"p","text":{"it":"Le funzioni si dichiarano con `function` e possono avere tipi per parametri e risultato. PHP offre molte funzioni pronte per i testi.","en":"Functions are declared with `function` and can have types for parameters and result. PHP offers many ready-made functions for text."}},{"t":"code","code":"<?php\\nfunction somma(int $a, int $b = 1): int {\\n    return $a + $b;\\n}\\necho somma(2, 3);\\n\\nstrlen(\\"ciao\\");          // 4\\nstrtoupper(\\"ciao\\");      // \\"CIAO\\"\\nstr_replace(\\"a\\", \\"o\\", \\"casa\\"); // \\"coso\\"\\nexplode(\\",\\", \\"a,b\\");     // [\\"a\\", \\"b\\"]\\ntrim(\\"  ciao  \\");        // \\"ciao\\"","lang":"php"},{"t":"p","text":{"it":"Le variabili esterne non si vedono dentro una funzione: si passano come parametri.","en":"Outer variables are not visible inside a function: pass them as parameters."}}]','{"lang":"php","prompt":{"it":"Scrivi `function saluta(string $nome): string` che restituisce `\\"Ciao \\" . $nome`.","en":"Write `function saluta(string $nome): string` that gives back `\\"Ciao \\" . $nome`."},"start":"<?php","html":"","checks":[{"re":"function\\\\s+saluta\\\\s*\\\\(\\\\s*string\\\\s+\\\\$nome\\\\s*\\\\)\\\\s*:\\\\s*string","label":{"it":"La firma è giusta","en":"The signature is right"}},{"re":"return\\\\s+\\"Ciao \\"\\\\s*\\\\.\\\\s*\\\\$nome","label":{"it":"Restituisci il saluto","en":"You give back the greeting"}}],"hint":"<?php\\nfunction saluta(string $nome): string {\\n    return \\"Ciao \\" . $nome;\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('php-base','forms',5,2,'published','{"it":"Moduli e sicurezza","en":"Forms and security"}','[{"t":"p","text":{"it":"I dati di un modulo arrivano in `$_POST` o `$_GET`. **Non fidarti mai** di ciò che arriva: controllalo e, prima di stamparlo, proteggilo con `htmlspecialchars`.","en":"Form data arrives in `$_POST` or `$_GET`. **Never trust** what arrives: check it and, before printing it, protect it with `htmlspecialchars`."}},{"t":"code","code":"<?php\\n$nome = trim($_POST[\\"nome\\"] ?? \\"\\");\\nif ($nome === \\"\\") {\\n    echo \\"Scrivi il nome\\";\\n} else {\\n    echo \\"Ciao \\" . htmlspecialchars($nome);\\n}\\n$email = filter_var($_POST[\\"email\\"] ?? \\"\\", FILTER_VALIDATE_EMAIL);","lang":"php"},{"t":"p","text":{"it":"Senza `htmlspecialchars`, un utente potrebbe inserire un tag `<script>` che verrebbe eseguito: si chiama **XSS**. `??` dà un valore se il campo manca.","en":"Without `htmlspecialchars`, a user could insert a `<script>` tag that would run: it is called **XSS**. `??` gives a value if the field is missing."}}]','{"lang":"php","prompt":{"it":"Leggi `$_POST[\\"nome\\"]` con `??` e stampalo protetto da `htmlspecialchars`.","en":"Read `$_POST[\\"nome\\"]` with `??` and print it protected by `htmlspecialchars`."},"start":"<?php","html":"","checks":[{"re":"\\\\$_POST\\\\[\\\\s*[\\"'']nome[\\"'']\\\\s*\\\\]\\\\s*\\\\?\\\\?","label":{"it":"Leggi il campo in sicurezza","en":"You read the field safely"}},{"re":"echo\\\\s+htmlspecialchars\\\\(","label":{"it":"Proteggi il testo","en":"You protect the text"}}],"hint":"<?php\\n$nome = $_POST[\\"nome\\"] ?? \\"\\";\\necho htmlspecialchars($nome);"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('php-base','files-sessions',6,2,'published','{"it":"Include, sessioni e cookie","en":"Includes, sessions and cookies"}','[{"t":"p","text":{"it":"`require` inserisce un altro file: comodo per testate e funzioni condivise. Le **sessioni** ricordano un utente tra le pagine, i **cookie** salvano piccoli dati nel browser.","en":"`require` inserts another file: handy for shared headers and functions. **Sessions** remember a user across pages, **cookies** keep small data in the browser."}},{"t":"code","code":"<?php\\nrequire __DIR__ . \\"/header.php\\";\\n\\nsession_start();\\n$_SESSION[\\"utente\\"] = \\"Sav\\";\\n\\nsetcookie(\\"tema\\", \\"scuro\\", [\\n    \\"expires\\" => time() + 86400,\\n    \\"httponly\\" => true,\\n    \\"samesite\\" => \\"Lax\\",\\n]);\\nheader(\\"Location: home.php\\");\\nexit;","lang":"php"},{"t":"p","text":{"it":"`session_start` e `header` vanno chiamati prima di stampare qualsiasi cosa. Dopo un `header(\\"Location: …\\")` scrivi sempre `exit`.","en":"`session_start` and `header` must be called before printing anything. After a `header(\\"Location: …\\")` always write `exit`."}}]','{"lang":"php","prompt":{"it":"Avvia la sessione e salva `\\"Sav\\"` in `$_SESSION[\\"utente\\"]`.","en":"Start the session and save `\\"Sav\\"` in `$_SESSION[\\"utente\\"]`."},"start":"<?php","html":"","checks":[{"re":"session_start\\\\(\\\\)","label":{"it":"Avvii la sessione","en":"You start the session"}},{"re":"\\\\$_SESSION\\\\[\\\\s*[\\"'']utente[\\"'']\\\\s*\\\\]\\\\s*=","label":{"it":"Salvi l’utente","en":"You save the user"}}],"hint":"<?php\\nsession_start();\\n$_SESSION[\\"utente\\"] = \\"Sav\\";"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('php-intermediate','classes',1,2,'published','{"it":"Classi e oggetti","en":"Classes and objects"}','[{"t":"p","text":{"it":"Una classe è lo stampo degli oggetti. Si accede a proprietà e metodi con `->`. Le visibilità `public`, `protected` e `private` decidono chi può usarli.","en":"A class is the mould of objects. You reach properties and methods with `->`. The visibilities `public`, `protected` and `private` decide who can use them."}},{"t":"code","code":"<?php\\nclass Eroe {\\n    public function __construct(\\n        public string $nome,\\n        private int $vite = 3,\\n    ) {}\\n\\n    public function colpisci(): void {\\n        $this->vite--;\\n    }\\n}\\n$e = new Eroe(\\"Ada\\");\\n$e->colpisci();\\necho $e->nome;","lang":"php"},{"t":"p","text":{"it":"La **promozione nel costruttore** dichiara e assegna le proprietà in un colpo. `$this` è l’oggetto stesso.","en":"**Constructor promotion** declares and assigns properties in one go. `$this` is the object itself."}}]','{"lang":"php","prompt":{"it":"Crea la classe `Gatto` con un costruttore che riceve `public string $nome`.","en":"Create the class `Gatto` with a constructor taking `public string $nome`."},"start":"<?php","html":"","checks":[{"re":"class\\\\s+Gatto","label":{"it":"La classe esiste","en":"The class exists"}},{"re":"__construct\\\\s*\\\\(\\\\s*public\\\\s+string\\\\s+\\\\$nome","label":{"it":"Il costruttore è giusto","en":"The constructor is right"}}],"hint":"<?php\\nclass Gatto {\\n    public function __construct(public string $nome) {}\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('php-intermediate','pdo',2,2,'published','{"it":"Database con PDO","en":"Databases with PDO"}','[{"t":"p","text":{"it":"**PDO** collega PHP a un database. Le **query preparate** separano il comando dai dati: è la difesa contro la **SQL injection**. Non inserire mai una variabile dentro il testo di una query.","en":"**PDO** connects PHP to a database. **Prepared queries** keep the command apart from the data: it is the defence against **SQL injection**. Never put a variable inside the text of a query."}},{"t":"code","code":"<?php\\n$pdo = new PDO($dsn, $utente, $password, [\\n    PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION,\\n]);\\n$st = $pdo->prepare(\\"SELECT nome FROM utenti WHERE id = ?\\");\\n$st->execute([$id]);\\n$riga = $st->fetch();\\n\\n$st = $pdo->prepare(\\"INSERT INTO corsi (titolo) VALUES (?)\\");\\n$st->execute([\\"PHP\\"]);","lang":"php"},{"t":"p","text":{"it":"`fetch` legge una riga, `fetchAll` tutte. Il `?` è un segnaposto: il valore viaggia separato e non può cambiare il comando.","en":"`fetch` reads one row, `fetchAll` all of them. `?` is a placeholder: the value travels apart and cannot change the command."}}]','{"lang":"php","prompt":{"it":"Prepara `SELECT * FROM corsi WHERE id = ?` ed eseguila con `[$id]`.","en":"Prepare `SELECT * FROM corsi WHERE id = ?` and run it with `[$id]`."},"start":"<?php","html":"","checks":[{"re":"\\\\$pdo->prepare\\\\(\\\\s*\\"SELECT \\\\* FROM corsi WHERE id = \\\\?\\"\\\\s*\\\\)","label":{"it":"La query è preparata","en":"The query is prepared"}},{"re":"->execute\\\\(\\\\s*\\\\[\\\\s*\\\\$id\\\\s*\\\\]\\\\s*\\\\)","label":{"it":"La esegui con il dato","en":"You run it with the data"}}],"hint":"<?php\\n$st = $pdo->prepare(\\"SELECT * FROM corsi WHERE id = ?\\");\\n$st->execute([$id]);"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('php-intermediate','passwords',3,2,'published','{"it":"Password e accessi","en":"Passwords and logins"}','[{"t":"p","text":{"it":"Le password non si salvano mai in chiaro. `password_hash` crea un’impronta sicura, `password_verify` controlla un tentativo. Un’impronta non si può riportare al testo originale.","en":"Passwords are never saved in clear text. `password_hash` creates a safe fingerprint, `password_verify` checks an attempt. A fingerprint cannot be turned back into the original text."}},{"t":"code","code":"<?php\\n$impronta = password_hash($password, PASSWORD_DEFAULT);\\n\\nif (password_verify($tentativo, $impronta)) {\\n    session_regenerate_id(true);\\n    $_SESSION[\\"id\\"] = $utente[\\"id\\"];\\n}\\n$token = bin2hex(random_bytes(32));","lang":"php"},{"t":"p","text":{"it":"Dopo l’accesso rigenera l’id di sessione. Per valori segreti usa `random_bytes`: `rand` è prevedibile. Limita anche i tentativi per fermare chi prova a indovinare.","en":"After login regenerate the session id. For secret values use `random_bytes`: `rand` is predictable. Also limit attempts to stop those trying to guess."}}]','{"lang":"php","prompt":{"it":"Crea l’impronta di `$password` con `password_hash` e `PASSWORD_DEFAULT`.","en":"Create the fingerprint of `$password` with `password_hash` and `PASSWORD_DEFAULT`."},"start":"<?php","html":"","checks":[{"re":"password_hash\\\\(\\\\s*\\\\$password\\\\s*,\\\\s*PASSWORD_DEFAULT\\\\s*\\\\)","label":{"it":"Usi `password_hash`","en":"You use `password_hash`"}}],"hint":"<?php\\n$impronta = password_hash($password, PASSWORD_DEFAULT);"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('php-intermediate','json-api',4,3,'published','{"it":"Costruire un’API JSON","en":"Building a JSON API"}','[{"t":"p","text":{"it":"Un’API risponde con dati invece che con pagine. Imposti il tipo di contenuto, il codice di stato e stampi il JSON. Il corpo di una richiesta si legge da `php://input`.","en":"An API answers with data instead of pages. You set the content type, the status code and print the JSON. The body of a request is read from `php://input`."}},{"t":"code","code":"<?php\\nheader(\\"Content-Type: application/json; charset=utf-8\\");\\n\\n$dati = json_decode(file_get_contents(\\"php://input\\"), true);\\nif (!is_array($dati) || empty($dati[\\"nome\\"])) {\\n    http_response_code(422);\\n    echo json_encode([\\"errore\\" => \\"Nome mancante\\"]);\\n    exit;\\n}\\necho json_encode([\\"ok\\" => true, \\"nome\\" => $dati[\\"nome\\"]]);","lang":"php"},{"t":"p","text":{"it":"Con `true`, `json_decode` restituisce array invece di oggetti. Usa i codici giusti: `200` riuscito, `401` non autenticato, `404` non trovato, `422` dati non validi.","en":"With `true`, `json_decode` gives back arrays instead of objects. Use the right codes: `200` success, `401` not signed in, `404` not found, `422` invalid data."}}]','{"lang":"php","prompt":{"it":"Imposta l’intestazione JSON e stampa `[\\"ok\\" => true]` con `json_encode`.","en":"Set the JSON header and print `[\\"ok\\" => true]` with `json_encode`."},"start":"<?php","html":"","checks":[{"re":"header\\\\(\\\\s*\\"Content-Type:\\\\s*application\\\\/json","label":{"it":"L’intestazione è giusta","en":"The header is right"}},{"re":"echo\\\\s+json_encode\\\\(","label":{"it":"Stampi il JSON","en":"You print the JSON"}}],"hint":"<?php\\nheader(\\"Content-Type: application/json\\");\\necho json_encode([\\"ok\\" => true]);"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('php-intermediate','errors',5,3,'published','{"it":"Errori ed eccezioni","en":"Errors and exceptions"}','[{"t":"p","text":{"it":"Quando qualcosa va storto, `throw` lancia un’eccezione e `catch` la gestisce. In produzione gli errori si scrivono nei log e non si mostrano mai ai visitatori.","en":"When something goes wrong, `throw` raises an exception and `catch` handles it. In production errors are written to logs and never shown to visitors."}},{"t":"code","code":"<?php\\ndeclare(strict_types=1);\\n\\nfunction dividi(int $a, int $b): float {\\n    if ($b === 0) {\\n        throw new InvalidArgumentException(\\"Divisione per zero\\");\\n    }\\n    return $a / $b;\\n}\\ntry {\\n    echo dividi(1, 0);\\n} catch (InvalidArgumentException $e) {\\n    error_log($e->getMessage());\\n    echo \\"Riprova\\";\\n} finally {\\n    echo \\"Fine\\";\\n}","lang":"php"},{"t":"p","text":{"it":"`strict_types` impedisce conversioni silenziose: passare un testo a un `int` diventa un errore. `Throwable` raccoglie tutti gli errori ed eccezioni.","en":"`strict_types` prevents silent conversions: passing text to an `int` becomes an error. `Throwable` gathers all errors and exceptions."}}]','{"lang":"php","prompt":{"it":"Con `try` e `catch (Exception $e)`, chiama `rischio()` e scrivi il messaggio con `error_log`.","en":"With `try` and `catch (Exception $e)`, call `rischio()` and write the message with `error_log`."},"start":"<?php","html":"","checks":[{"re":"try\\\\s*\\\\{[\\\\s\\\\S]*rischio\\\\(\\\\)","label":{"it":"Provi `rischio()`","en":"You try `rischio()`"}},{"re":"catch\\\\s*\\\\(\\\\s*Exception\\\\s+\\\\$e\\\\s*\\\\)","label":{"it":"Catturi l’eccezione","en":"You catch the exception"}},{"re":"error_log\\\\(","label":{"it":"Scrivi nel log","en":"You write to the log"}}],"hint":"<?php\\ntry {\\n    rischio();\\n} catch (Exception $e) {\\n    error_log($e->getMessage());\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('php-intermediate','project',6,3,'published','{"it":"Progetti ordinati","en":"Tidy projects"}','[{"t":"p","text":{"it":"Un progetto serio usa **Composer** per le librerie e i **namespace** per non far scontrare i nomi. Le credenziali stanno fuori dal codice pubblico, in un file escluso da git o nelle variabili d’ambiente.","en":"A serious project uses **Composer** for libraries and **namespaces** to stop names clashing. Credentials stay out of public code, in a file excluded from git or in environment variables."}},{"t":"code","code":"<?php\\nnamespace Fucina\\\\Corsi;\\n\\nuse Fucina\\\\Db\\\\Connessione;\\n\\nrequire __DIR__ . \\"/vendor/autoload.php\\";\\n\\n$password = getenv(\\"DB_PASSWORD\\");\\n\\nfinal class Catalogo {\\n    public function __construct(private Connessione $db) {}\\n}","lang":"php"},{"t":"p","text":{"it":"Passare le dipendenze dal costruttore si chiama **iniezione delle dipendenze**: il codice diventa più facile da provare. `vendor/autoload.php` carica le classi da solo.","en":"Passing dependencies through the constructor is called **dependency injection**: code becomes easier to test. `vendor/autoload.php` loads classes by itself."}}]','{"lang":"php","prompt":{"it":"Dichiara il namespace `Fucina\\\\Corsi` e leggi la password con `getenv(\\"DB_PASSWORD\\")`.","en":"Declare the namespace `Fucina\\\\Corsi` and read the password with `getenv(\\"DB_PASSWORD\\")`."},"start":"<?php","html":"","checks":[{"re":"namespace\\\\s+Fucina\\\\\\\\Corsi","label":{"it":"Il namespace è giusto","en":"The namespace is right"}},{"re":"getenv\\\\(\\\\s*\\"DB_PASSWORD\\"\\\\s*\\\\)","label":{"it":"Leggi la variabile","en":"You read the variable"}}],"hint":"<?php\\nnamespace Fucina\\\\Corsi;\\n$password = getenv(\\"DB_PASSWORD\\");"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('php-advanced','namespaces',1,2,'published','{"it":"Namespace e Composer","en":"Namespaces and Composer"}','[{"t":"p","text":{"it":"Un **namespace** è il cognome di una classe: due classi `Utente` possono convivere se stanno in namespace diversi. `use` importa una classe per chiamarla con il nome corto.","en":"A **namespace** is the surname of a class: two `Utente` classes can live together in different namespaces. `use` imports a class so you can call it by its short name."}},{"t":"code","code":"<?php\\nnamespace App\\\\Corsi;\\n\\nuse App\\\\Utenti\\\\Utente;\\n\\nfinal class Iscrizione {\\n    public function __construct(public Utente $chi) {}\\n}","lang":"php"},{"t":"p","text":{"it":"**Composer** scarica le librerie e crea l’**autoload**: con lo standard PSR-4 il namespace `App\\\\` corrisponde alla cartella `src/`, e ogni classe si carica da sola quando serve. Basta un `require \\"vendor/autoload.php\\";`.","en":"**Composer** downloads libraries and creates the **autoloader**: with the PSR-4 standard the namespace `App\\\\` matches the `src/` folder, and every class loads by itself when needed. One `require \\"vendor/autoload.php\\";` is enough."}}]','{"lang":"php","prompt":{"it":"Dichiara il namespace `App\\\\Corsi` e importa `App\\\\Utenti\\\\Utente`.","en":"Declare the namespace `App\\\\Corsi` and import `App\\\\Utenti\\\\Utente`."},"start":"<?php","html":"","checks":[{"re":"namespace\\\\s+App\\\\\\\\Corsi\\\\s*;","label":{"it":"Il namespace è dichiarato","en":"The namespace is declared"}},{"re":"use\\\\s+App\\\\\\\\Utenti\\\\\\\\Utente\\\\s*;","label":{"it":"La classe è importata","en":"The class is imported"}}],"hint":"<?php\\nnamespace App\\\\Corsi;\\n\\nuse App\\\\Utenti\\\\Utente;"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('php-advanced','interfaces',2,2,'published','{"it":"Interfacce, astratte e trait","en":"Interfaces, abstracts and traits"}','[{"t":"p","text":{"it":"Un’**interfaccia** è un contratto: elenca i metodi che una classe promette di avere. Una classe **astratta** dà una base comune ma non si può istanziare. Un **trait** è un pezzo di codice da riusare in più classi.","en":"An **interface** is a contract: it lists the methods a class promises to have. An **abstract** class gives a shared base but cannot be instantiated. A **trait** is a piece of code reused in several classes."}},{"t":"code","code":"<?php\\ninterface Pagabile {\\n    public function totale(): float;\\n}\\n\\ntrait ConData {\\n    public function oggi(): string { return date(\\"Y-m-d\\"); }\\n}\\n\\nfinal class Ordine implements Pagabile {\\n    use ConData;\\n    public function totale(): float { return 42.0; }\\n}","lang":"php"},{"t":"p","text":{"it":"Programmare verso le interfacce rende il codice sostituibile: una funzione che chiede `Pagabile` accetta qualsiasi classe che rispetta il contratto.","en":"Coding against interfaces makes code swappable: a function that asks for `Pagabile` accepts any class that keeps the contract."}}]','{"lang":"php","prompt":{"it":"Crea l’interfaccia `Stampabile` con il metodo `stampa(): string`, e la classe `Report` che la implementa.","en":"Create the interface `Stampabile` with the method `stampa(): string`, and the class `Report` that implements it."},"start":"<?php","html":"","checks":[{"re":"interface\\\\s+Stampabile","label":{"it":"L’interfaccia esiste","en":"The interface exists"}},{"re":"function\\\\s+stampa\\\\s*\\\\(\\\\s*\\\\)\\\\s*:\\\\s*string","label":{"it":"Il metodo ha il tipo giusto","en":"The method has the right type"}},{"re":"class\\\\s+Report\\\\s+implements\\\\s+Stampabile","label":{"it":"`Report` la implementa","en":"`Report` implements it"}}],"hint":"<?php\\ninterface Stampabile {\\n    public function stampa(): string;\\n}\\n\\nclass Report implements Stampabile {\\n    public function stampa(): string { return \\"ok\\"; }\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('php-advanced','enums',3,2,'published','{"it":"Enum, readonly e match","en":"Enums, readonly and match"}','[{"t":"p","text":{"it":"Un **enum** elenca i soli valori possibili di qualcosa: niente più stringhe scritte male. Una proprietà **readonly** si assegna una volta sola e poi non cambia.","en":"An **enum** lists the only possible values of something: no more misspelt strings. A **readonly** property is set once and never changes."}},{"t":"code","code":"<?php\\nenum Stato: string {\\n    case Bozza = \\"draft\\";\\n    case Pubblicato = \\"published\\";\\n}\\n\\nfinal class Lezione {\\n    public function __construct(public readonly Stato $stato) {}\\n}\\n\\n$etichetta = match ($lezione->stato) {\\n    Stato::Bozza => \\"Da finire\\",\\n    Stato::Pubblicato => \\"Online\\",\\n};","lang":"php"},{"t":"p","text":{"it":"`match` è un `switch` più rigoroso: confronta con `===`, restituisce un valore e dà errore se un caso manca.","en":"`match` is a stricter `switch`: it compares with `===`, returns a value and fails if a case is missing."}}]','{"lang":"php","prompt":{"it":"Crea l’enum `Livello: int` con i casi `Base = 1` e `Avanzato = 2`.","en":"Create the enum `Livello: int` with the cases `Base = 1` and `Avanzato = 2`."},"start":"<?php","html":"","checks":[{"re":"enum\\\\s+Livello\\\\s*:\\\\s*int","label":{"it":"L’enum ha valori interi","en":"The enum has int values"}},{"re":"case\\\\s+Base\\\\s*=\\\\s*1","label":{"it":"C’è `Base`","en":"There is `Base`"}},{"re":"case\\\\s+Avanzato\\\\s*=\\\\s*2","label":{"it":"C’è `Avanzato`","en":"There is `Avanzato`"}}],"hint":"<?php\\nenum Livello: int {\\n    case Base = 1;\\n    case Avanzato = 2;\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('php-advanced','generators',4,3,'published','{"it":"Closure e generatori","en":"Closures and generators"}','[{"t":"p","text":{"it":"Una **closure** è una funzione senza nome da passare come valore. La forma corta `fn($x) => $x * 2` vede da sola le variabili esterne.","en":"A **closure** is a nameless function passed around as a value. The short form `fn($x) => $x * 2` sees outer variables by itself."}},{"t":"code","code":"<?php\\n$iva = 0.22;\\n$lordi = array_map(fn($p) => $p * (1 + $iva), [10, 20]);\\n\\nfunction righe(string $file): Generator {\\n    $h = fopen($file, \\"r\\");\\n    while (($riga = fgets($h)) !== false) {\\n        yield trim($riga);\\n    }\\n    fclose($h);\\n}\\n\\nforeach (righe(\\"log.txt\\") as $riga) echo $riga;","lang":"php"},{"t":"p","text":{"it":"Un **generatore** usa `yield` per dare un valore alla volta: legge un file enorme senza caricarlo tutto in memoria.","en":"A **generator** uses `yield` to hand out one value at a time: it reads a huge file without loading it all into memory."}}]','{"lang":"php","prompt":{"it":"Scrivi il generatore `numeri(int $n)` che fa `yield` dei numeri da 1 a `$n`.","en":"Write the generator `numeri(int $n)` that yields the numbers from 1 to `$n`."},"start":"<?php","html":"","checks":[{"re":"function\\\\s+numeri\\\\s*\\\\(\\\\s*int\\\\s+\\\\$n\\\\s*\\\\)","label":{"it":"La funzione esiste","en":"The function exists"}},{"re":"yield\\\\s+\\\\$","label":{"it":"Usa `yield`","en":"It uses `yield`"}}],"hint":"<?php\\nfunction numeri(int $n): Generator {\\n    for ($i = 1; $i <= $n; $i++) {\\n        yield $i;\\n    }\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('php-advanced','testing',5,3,'published','{"it":"Test automatici","en":"Automated tests"}','[{"t":"p","text":{"it":"Un **test** è codice che controlla altro codice. Con **PHPUnit** ogni metodo che inizia per `test` prepara una situazione, esegue e verifica con le **asserzioni**.","en":"A **test** is code that checks other code. With **PHPUnit** every method starting with `test` sets up a situation, runs it and checks with **assertions**."}},{"t":"code","code":"<?php\\nuse PHPUnit\\\\Framework\\\\TestCase;\\n\\nfinal class CarrelloTest extends TestCase {\\n    public function testTotale(): void {\\n        $c = new Carrello();\\n        $c->aggiungi(10);\\n        $c->aggiungi(5);\\n        $this->assertSame(15, $c->totale());\\n    }\\n}","lang":"php"},{"t":"p","text":{"it":"Si lanciano con `vendor/bin/phpunit`. Quando cambi il codice, i test ti dicono subito se hai rotto qualcosa.","en":"You run them with `vendor/bin/phpunit`. When you change the code, tests tell you at once if you broke something."}}]','{"lang":"php","prompt":{"it":"Scrivi `testSomma()` che verifica con `assertSame` che `somma(2, 3)` dia `5`.","en":"Write `testSomma()` that checks with `assertSame` that `somma(2, 3)` gives `5`."},"start":"<?php\\nuse PHPUnit\\\\Framework\\\\TestCase;\\n\\nfinal class SommaTest extends TestCase {\\n}","html":"","checks":[{"re":"function\\\\s+testSomma\\\\s*\\\\(","label":{"it":"Il test esiste","en":"The test exists"}},{"re":"assertSame\\\\s*\\\\(\\\\s*5\\\\s*,\\\\s*somma\\\\s*\\\\(\\\\s*2\\\\s*,\\\\s*3\\\\s*\\\\)\\\\s*\\\\)","label":{"it":"L’asserzione è giusta","en":"The assertion is right"}}],"hint":"<?php\\npublic function testSomma(): void {\\n    $this->assertSame(5, somma(2, 3));\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('php-advanced','security',6,3,'published','{"it":"Sicurezza delle applicazioni","en":"Application security"}','[{"t":"p","text":{"it":"Tre regole d’oro: **mai fidarsi dell’input**, **escapare l’output** con `htmlspecialchars` (contro l’XSS) e **proteggere i moduli** con un token CSRF legato alla sessione.","en":"Three golden rules: **never trust input**, **escape output** with `htmlspecialchars` (against XSS) and **protect forms** with a CSRF token tied to the session."}},{"t":"code","code":"<?php\\nsession_start();\\n$_SESSION[\\"csrf\\"] ??= bin2hex(random_bytes(32));\\n\\nif ($_SERVER[\\"REQUEST_METHOD\\"] === \\"POST\\"\\n    && !hash_equals($_SESSION[\\"csrf\\"], $_POST[\\"csrf\\"] ?? \\"\\")) {\\n    http_response_code(403);\\n    exit(\\"Richiesta non valida\\");\\n}\\n\\necho htmlspecialchars($commento, ENT_QUOTES, \\"UTF-8\\");","lang":"php"},{"t":"p","text":{"it":"`hash_equals` confronta senza rivelare nulla con i tempi di risposta. Imposta anche intestazioni come `Content-Security-Policy` e cookie `HttpOnly` e `SameSite`.","en":"`hash_equals` compares without leaking anything through timing. Also set headers such as `Content-Security-Policy` and `HttpOnly`, `SameSite` cookies."}}]','{"lang":"php","prompt":{"it":"Stampa `$nome` con `htmlspecialchars($nome, ENT_QUOTES, \\"UTF-8\\")`.","en":"Print `$nome` with `htmlspecialchars($nome, ENT_QUOTES, \\"UTF-8\\")`."},"start":"<?php\\n$nome = $_GET[\\"nome\\"] ?? \\"\\";","html":"","checks":[{"re":"echo\\\\s+htmlspecialchars\\\\s*\\\\(\\\\s*\\\\$nome\\\\s*,\\\\s*ENT_QUOTES","label":{"it":"L’output è protetto","en":"The output is escaped"}}],"hint":"<?php\\necho htmlspecialchars($nome, ENT_QUOTES, \\"UTF-8\\");"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('python-base','hello',1,1,'published','{"it":"Ciao, Python","en":"Hello, Python"}','[{"t":"p","text":{"it":"Python si legge quasi come l’inglese. `print()` scrive sullo schermo, una **variabile** nasce quando le dai un valore con `=`. Non servono punti e virgola né tipi da dichiarare.","en":"Python reads almost like English. `print()` writes to the screen, a **variable** is born when you give it a value with `=`. No semicolons, no types to declare."}},{"t":"code","code":"nome = \\"Ada\\"\\neta = 36\\nprint(\\"Ciao\\", nome)\\nprint(f\\"{nome} ha {eta} anni\\")","lang":"python"},{"t":"p","text":{"it":"Le **f-string** (con la `f` davanti) mettono i valori dentro il testo tra graffe. I commenti iniziano con `#`.","en":"**f-strings** (with an `f` in front) put values inside the text between braces. Comments start with `#`."}}]','{"lang":"python","prompt":{"it":"Crea `citta = \\"Udine\\"` e stampa `f\\"Vivo a {citta}\\"`.","en":"Create `citta = \\"Udine\\"` and print `f\\"Vivo a {citta}\\"`."},"start":"","html":"","checks":[{"re":"citta\\\\s*=\\\\s*[\\"'']Udine[\\"'']","label":{"it":"La variabile esiste","en":"The variable exists"}},{"re":"print\\\\s*\\\\(\\\\s*f[\\"'']Vivo a \\\\{citta\\\\}[\\"'']\\\\s*\\\\)","label":{"it":"La stampi con una f-string","en":"You print it with an f-string"}}],"hint":"citta = \\"Udine\\"\\nprint(f\\"Vivo a {citta}\\")"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('python-base','conditions',2,1,'published','{"it":"Condizioni e indentazione","en":"Conditions and indentation"}','[{"t":"p","text":{"it":"`if`, `elif` ed `else` scelgono che cosa fare. In Python i blocchi non hanno graffe: li decide l’**indentazione**, di solito 4 spazi dopo i due punti.","en":"`if`, `elif` and `else` choose what to do. In Python blocks have no braces: **indentation** decides them, usually 4 spaces after the colon."}},{"t":"code","code":"voto = 8\\nif voto >= 9:\\n    print(\\"Ottimo\\")\\nelif voto >= 6:\\n    print(\\"Promosso\\")\\nelse:\\n    print(\\"Da ripassare\\")","lang":"python"},{"t":"p","text":{"it":"Gli operatori logici sono parole: `and`, `or`, `not`.","en":"Logical operators are words: `and`, `or`, `not`."}}]','{"lang":"python","prompt":{"it":"Se `eta >= 18` stampa `\\"Adulto\\"`, altrimenti `\\"Minore\\"`.","en":"If `eta >= 18` print `\\"Adulto\\"`, otherwise `\\"Minore\\"`."},"start":"eta = 20","html":"","checks":[{"re":"if\\\\s+eta\\\\s*>=\\\\s*18\\\\s*:","label":{"it":"La condizione è giusta","en":"The condition is right"}},{"re":"print\\\\s*\\\\(\\\\s*[\\"'']Adulto[\\"'']\\\\s*\\\\)","label":{"it":"Stampi “Adulto”","en":"You print “Adulto”"}},{"re":"else\\\\s*:\\\\s*\\\\n\\\\s+print\\\\s*\\\\(\\\\s*[\\"'']Minore[\\"'']\\\\s*\\\\)","label":{"it":"E “Minore” altrimenti","en":"And “Minore” otherwise"}}],"hint":"if eta >= 18:\\n    print(\\"Adulto\\")\\nelse:\\n    print(\\"Minore\\")"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('python-base','loops',3,1,'published','{"it":"Cicli","en":"Loops"}','[{"t":"p","text":{"it":"`for` ripete per ogni elemento di una sequenza; `range(5)` dà i numeri da 0 a 4. `while` ripete finché una condizione è vera.","en":"`for` repeats for each item of a sequence; `range(5)` gives the numbers from 0 to 4. `while` repeats while a condition is true."}},{"t":"code","code":"for i in range(1, 4):\\n    print(\\"Giro\\", i)\\n\\nn = 3\\nwhile n > 0:\\n    print(n)\\n    n -= 1\\nprint(\\"Via!\\")","lang":"python"},{"t":"p","text":{"it":"`break` esce dal ciclo, `continue` salta al giro successivo.","en":"`break` leaves the loop, `continue` skips to the next round."}}]','{"lang":"python","prompt":{"it":"Con `for` e `range(1, 6)` stampa i numeri da 1 a 5.","en":"With `for` and `range(1, 6)` print the numbers from 1 to 5."},"start":"","html":"","checks":[{"re":"for\\\\s+\\\\w+\\\\s+in\\\\s+range\\\\s*\\\\(\\\\s*1\\\\s*,\\\\s*6\\\\s*\\\\)\\\\s*:","label":{"it":"Il ciclo è giusto","en":"The loop is right"}},{"re":"print\\\\s*\\\\(\\\\s*\\\\w+\\\\s*\\\\)","label":{"it":"Stampi il numero","en":"You print the number"}}],"hint":"for n in range(1, 6):\\n    print(n)"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('python-base','lists',4,2,'published','{"it":"Liste e dizionari","en":"Lists and dictionaries"}','[{"t":"p","text":{"it":"Una **lista** tiene più valori in ordine: `[3, 5, 7]`. Si legge con l’indice (`lista[0]` è il primo) e si allunga con `append`. Un **dizionario** associa chiavi e valori: `{\\"nome\\": \\"Ada\\"}`.","en":"A **list** holds several values in order: `[3, 5, 7]`. You read it by index (`lista[0]` is the first) and grow it with `append`. A **dictionary** maps keys to values: `{\\"nome\\": \\"Ada\\"}`."}},{"t":"code","code":"frutta = [\\"mela\\", \\"pera\\"]\\nfrutta.append(\\"kiwi\\")\\nprint(frutta[0], len(frutta))\\n\\nutente = {\\"nome\\": \\"Ada\\", \\"eta\\": 36}\\nutente[\\"citta\\"] = \\"Londra\\"\\nfor chiave, valore in utente.items():\\n    print(chiave, valore)","lang":"python"},{"t":"p","text":{"it":"`lista[-1]` è l’ultimo elemento; `in` controlla se qualcosa c’è: `\\"pera\\" in frutta`.","en":"`lista[-1]` is the last item; `in` checks whether something is there: `\\"pera\\" in frutta`."}}]','{"lang":"python","prompt":{"it":"Crea `voti = [7, 8]`, aggiungi `9` con `append` e stampa `len(voti)`.","en":"Create `voti = [7, 8]`, add `9` with `append` and print `len(voti)`."},"start":"","html":"","checks":[{"re":"voti\\\\s*=\\\\s*\\\\[\\\\s*7\\\\s*,\\\\s*8\\\\s*\\\\]","label":{"it":"La lista esiste","en":"The list exists"}},{"re":"voti\\\\.append\\\\s*\\\\(\\\\s*9\\\\s*\\\\)","label":{"it":"Aggiungi il 9","en":"You add 9"}},{"re":"print\\\\s*\\\\(\\\\s*len\\\\s*\\\\(\\\\s*voti\\\\s*\\\\)\\\\s*\\\\)","label":{"it":"Stampi la lunghezza","en":"You print the length"}}],"hint":"voti = [7, 8]\\nvoti.append(9)\\nprint(len(voti))"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('python-base','functions',5,2,'published','{"it":"Funzioni","en":"Functions"}','[{"t":"p","text":{"it":"`def` crea una **funzione**: un pezzo di codice con un nome, che riceve **parametri** e restituisce un risultato con `return`. Un parametro può avere un valore predefinito.","en":"`def` creates a **function**: a named piece of code that takes **parameters** and gives back a result with `return`. A parameter can have a default value."}},{"t":"code","code":"def area(base, altezza=1):\\n    return base * altezza\\n\\nprint(area(4, 3))\\nprint(area(5))\\n\\ndef saluta(nome: str) -> str:\\n    return f\\"Ciao {nome}\\"","lang":"python"},{"t":"p","text":{"it":"Le annotazioni come `nome: str` e `-> str` documentano i tipi: Python non le impone, ma gli strumenti le controllano.","en":"Annotations such as `nome: str` and `-> str` document the types: Python does not enforce them, but tools check them."}}]','{"lang":"python","prompt":{"it":"Scrivi `def doppio(n):` che restituisce `n * 2`.","en":"Write `def doppio(n):` that returns `n * 2`."},"start":"","html":"","checks":[{"re":"def\\\\s+doppio\\\\s*\\\\(\\\\s*n\\\\s*\\\\)\\\\s*(->\\\\s*\\\\w+\\\\s*)?:","label":{"it":"La funzione esiste","en":"The function exists"}},{"re":"return\\\\s+n\\\\s*\\\\*\\\\s*2","label":{"it":"Restituisce il doppio","en":"It returns the double"}}],"hint":"def doppio(n):\\n    return n * 2"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('python-intermediate','comprehensions',1,2,'published','{"it":"Comprehension","en":"Comprehensions"}','[{"t":"p","text":{"it":"Una **list comprehension** costruisce una lista in una riga: `[espressione for x in sequenza if condizione]`. Esistono anche per dizionari e insiemi.","en":"A **list comprehension** builds a list in one line: `[expression for x in sequence if condition]`. They also exist for dicts and sets."}},{"t":"code","code":"numeri = [1, 2, 3, 4, 5, 6]\\npari = [n for n in numeri if n % 2 == 0]\\nquadrati = {n: n * n for n in numeri}\\nnomi = [\\"ada\\", \\"bea\\"]\\nmaiuscoli = [n.capitalize() for n in nomi]","lang":"python"},{"t":"p","text":{"it":"Sono più brevi e spesso più veloci di un ciclo con `append`, ma se diventano lunghe meglio tornare al `for`.","en":"They are shorter and often faster than a loop with `append`, but if they get long go back to a `for`."}}]','{"lang":"python","prompt":{"it":"Crea `lunghi = [p for p in parole if len(p) > 3]`.","en":"Create `lunghi = [p for p in parole if len(p) > 3]`."},"start":"parole = [\\"sole\\", \\"re\\", \\"mare\\", \\"tu\\"]","html":"","checks":[{"re":"lunghi\\\\s*=\\\\s*\\\\[\\\\s*p\\\\s+for\\\\s+p\\\\s+in\\\\s+parole\\\\s+if\\\\s+len\\\\s*\\\\(\\\\s*p\\\\s*\\\\)\\\\s*>\\\\s*3\\\\s*\\\\]","label":{"it":"La comprehension è giusta","en":"The comprehension is right"}}],"hint":"lunghi = [p for p in parole if len(p) > 3]"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('python-intermediate','files',2,2,'published','{"it":"File e with","en":"Files and with"}','[{"t":"p","text":{"it":"`open()` apre un file; con `with` il file si chiude da solo anche se c’è un errore. `\\"r\\"` legge, `\\"w\\"` scrive da capo, `\\"a\\"` aggiunge in fondo.","en":"`open()` opens a file; with `with` the file closes by itself even if there is an error. `\\"r\\"` reads, `\\"w\\"` writes from scratch, `\\"a\\"` appends."}},{"t":"code","code":"with open(\\"note.txt\\", \\"a\\", encoding=\\"utf-8\\") as f:\\n    f.write(\\"Nuova riga\\\\n\\")\\n\\nwith open(\\"note.txt\\", encoding=\\"utf-8\\") as f:\\n    for riga in f:\\n        print(riga.strip())\\n\\nimport json\\nwith open(\\"dati.json\\") as f:\\n    dati = json.load(f)","lang":"python"},{"t":"p","text":{"it":"Indica sempre `encoding=\\"utf-8\\"` per le lettere accentate. Il modulo `json` legge e scrive dati strutturati.","en":"Always give `encoding=\\"utf-8\\"` for accented letters. The `json` module reads and writes structured data."}}]','{"lang":"python","prompt":{"it":"Con `with open(\\"diario.txt\\", \\"a\\", encoding=\\"utf-8\\") as f:` scrivi `\\"Oggi\\\\n\\"`.","en":"With `with open(\\"diario.txt\\", \\"a\\", encoding=\\"utf-8\\") as f:` write `\\"Oggi\\\\n\\"`."},"start":"","html":"","checks":[{"re":"with\\\\s+open\\\\s*\\\\(\\\\s*[\\"'']diario\\\\.txt[\\"'']\\\\s*,\\\\s*[\\"'']a[\\"'']","label":{"it":"Apri in aggiunta","en":"You open for appending"}},{"re":"f\\\\.write\\\\s*\\\\(","label":{"it":"Scrivi nel file","en":"You write to the file"}}],"hint":"with open(\\"diario.txt\\", \\"a\\", encoding=\\"utf-8\\") as f:\\n    f.write(\\"Oggi\\\\n\\")"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('python-intermediate','exceptions',3,2,'published','{"it":"Eccezioni","en":"Exceptions"}','[{"t":"p","text":{"it":"Quando qualcosa va storto Python lancia un’**eccezione**. Con `try` / `except` la intercetti e decidi che cosa fare; `finally` gira sempre. `raise` lancia un’eccezione tua.","en":"When something goes wrong Python raises an **exception**. With `try` / `except` you catch it and decide what to do; `finally` always runs. `raise` throws your own exception."}},{"t":"code","code":"def leggi_eta(testo):\\n    try:\\n        eta = int(testo)\\n    except ValueError:\\n        print(\\"Non è un numero\\")\\n        return None\\n    if eta < 0:\\n        raise ValueError(\\"L’età non può essere negativa\\")\\n    return eta","lang":"python"},{"t":"p","text":{"it":"Intercetta solo gli errori che sai gestire: un `except:` vuoto nasconde anche i bug veri.","en":"Catch only the errors you can handle: a bare `except:` hides real bugs too."}}]','{"lang":"python","prompt":{"it":"Converti `testo` con `int` dentro `try`, e intercetta `ValueError` mettendo `n = 0`.","en":"Convert `testo` with `int` inside `try`, and catch `ValueError` setting `n = 0`."},"start":"testo = input()","html":"","checks":[{"re":"try\\\\s*:\\\\s*\\\\n\\\\s+n\\\\s*=\\\\s*int\\\\s*\\\\(\\\\s*testo\\\\s*\\\\)","label":{"it":"Provi la conversione","en":"You try the conversion"}},{"re":"except\\\\s+ValueError\\\\s*:\\\\s*\\\\n\\\\s+n\\\\s*=\\\\s*0","label":{"it":"Gestisci l’errore","en":"You handle the error"}}],"hint":"try:\\n    n = int(testo)\\nexcept ValueError:\\n    n = 0"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('python-intermediate','classes',4,3,'published','{"it":"Classi e dataclass","en":"Classes and dataclasses"}','[{"t":"p","text":{"it":"Una **classe** descrive un tipo di oggetto. `__init__` prepara l’oggetto, `self` è l’oggetto stesso. Con `@dataclass` Python scrive per te il costruttore e il confronto.","en":"A **class** describes a type of object. `__init__` sets up the object, `self` is the object itself. With `@dataclass` Python writes the constructor and comparison for you."}},{"t":"code","code":"from dataclasses import dataclass\\n\\nclass Conto:\\n    def __init__(self, titolare, saldo=0):\\n        self.titolare = titolare\\n        self.saldo = saldo\\n\\n    def versa(self, importo):\\n        self.saldo += importo\\n\\n@dataclass\\nclass Punto:\\n    x: int\\n    y: int","lang":"python"},{"t":"p","text":{"it":"Un metodo riceve sempre `self` come primo parametro; si chiama però senza: `conto.versa(10)`.","en":"A method always receives `self` as its first parameter; you call it without it though: `conto.versa(10)`."}}]','{"lang":"python","prompt":{"it":"Crea la dataclass `Libro` con i campi `titolo: str` e `pagine: int`.","en":"Create the dataclass `Libro` with the fields `titolo: str` and `pagine: int`."},"start":"from dataclasses import dataclass","html":"","checks":[{"re":"@dataclass\\\\s*\\\\n\\\\s*class\\\\s+Libro","label":{"it":"La dataclass esiste","en":"The dataclass exists"}},{"re":"titolo\\\\s*:\\\\s*str","label":{"it":"Il titolo è una stringa","en":"The title is a string"}},{"re":"pagine\\\\s*:\\\\s*int","label":{"it":"Le pagine sono un intero","en":"Pages are an int"}}],"hint":"@dataclass\\nclass Libro:\\n    titolo: str\\n    pagine: int"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('python-intermediate','modules',5,3,'published','{"it":"Moduli, pacchetti e venv","en":"Modules, packages and venv"}','[{"t":"p","text":{"it":"Ogni file `.py` è un **modulo** che si importa con `import`. Le librerie esterne si installano con `pip` dentro un **ambiente virtuale** (`venv`), così ogni progetto ha le sue versioni.","en":"Every `.py` file is a **module** you import with `import`. External libraries are installed with `pip` inside a **virtual environment** (`venv`), so every project has its own versions."}},{"t":"code","code":"# terminale\\npython -m venv .venv\\nsource .venv/bin/activate\\npip install requests\\n\\n# codice\\nimport requests\\nfrom math import sqrt\\n\\nr = requests.get(\\"https://api.github.com\\")\\nprint(r.status_code, sqrt(16))","lang":"python"},{"t":"p","text":{"it":"`if __name__ == \\"__main__\\":` esegue codice solo quando il file è lanciato direttamente, non quando viene importato.","en":"`if __name__ == \\"__main__\\":` runs code only when the file is launched directly, not when it is imported."}}]','{"lang":"python","prompt":{"it":"Importa `sqrt` da `math` e stampa `sqrt(81)`.","en":"Import `sqrt` from `math` and print `sqrt(81)`."},"start":"","html":"","checks":[{"re":"from\\\\s+math\\\\s+import\\\\s+sqrt","label":{"it":"Importi `sqrt`","en":"You import `sqrt`"}},{"re":"print\\\\s*\\\\(\\\\s*sqrt\\\\s*\\\\(\\\\s*81\\\\s*\\\\)\\\\s*\\\\)","label":{"it":"Stampi la radice","en":"You print the root"}}],"hint":"from math import sqrt\\nprint(sqrt(81))"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('python-advanced','generators',1,2,'published','{"it":"Iteratori e generatori","en":"Iterators and generators"}','[{"t":"p","text":{"it":"Un **generatore** è una funzione con `yield`: produce un valore alla volta e si ferma fino alla richiesta successiva. Così si possono scorrere sequenze enormi, o infinite, senza riempire la memoria.","en":"A **generator** is a function with `yield`: it produces one value at a time and pauses until the next request. So you can walk through huge, or endless, sequences without filling memory."}},{"t":"code","code":"def fibonacci():\\n    a, b = 0, 1\\n    while True:\\n        yield a\\n        a, b = b, a + b\\n\\nfrom itertools import islice\\nprint(list(islice(fibonacci(), 10)))\\n\\nsomma = sum(x * x for x in range(1_000_000))","lang":"python"},{"t":"p","text":{"it":"Le **generator expression** sono comprehension con le tonde: `(x * x for x in dati)` non crea nessuna lista.","en":"**Generator expressions** are comprehensions with round brackets: `(x * x for x in data)` builds no list at all."}}]','{"lang":"python","prompt":{"it":"Scrivi il generatore `pari(n)` che fa `yield` dei numeri pari da 0 a `n`.","en":"Write the generator `pari(n)` that yields the even numbers from 0 to `n`."},"start":"","html":"","checks":[{"re":"def\\\\s+pari\\\\s*\\\\(\\\\s*n\\\\s*\\\\)\\\\s*:","label":{"it":"La funzione esiste","en":"The function exists"}},{"re":"yield\\\\s+\\\\w+","label":{"it":"Usa `yield`","en":"It uses `yield`"}}],"hint":"def pari(n):\\n    for i in range(0, n + 1, 2):\\n        yield i"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('python-advanced','decorators',2,2,'published','{"it":"Decoratori","en":"Decorators"}','[{"t":"p","text":{"it":"Un **decoratore** è una funzione che avvolge un’altra funzione per aggiungerle qualcosa: misurare il tempo, controllare i permessi, ricordare i risultati. Si applica con la `@` sopra la definizione.","en":"A **decorator** is a function that wraps another function to add something to it: timing, permission checks, caching results. You apply it with `@` above the definition."}},{"t":"code","code":"import functools, time\\n\\ndef cronometro(funzione):\\n    @functools.wraps(funzione)\\n    def involucro(*args, **kwargs):\\n        inizio = time.perf_counter()\\n        risultato = funzione(*args, **kwargs)\\n        print(f\\"{funzione.__name__}: {time.perf_counter() - inizio:.3f}s\\")\\n        return risultato\\n    return involucro\\n\\n@cronometro\\ndef calcola(n):\\n    return sum(range(n))","lang":"python"},{"t":"p","text":{"it":"`*args` e `**kwargs` raccolgono qualsiasi argomento. `functools.wraps` conserva il nome e la documentazione della funzione originale. `@functools.cache` è un decoratore già pronto che ricorda i risultati.","en":"`*args` and `**kwargs` collect any arguments. `functools.wraps` keeps the name and docs of the original function. `@functools.cache` is a ready-made decorator that remembers results."}}]','{"lang":"python","prompt":{"it":"Applica `@functools.cache` alla funzione `fib(n)`.","en":"Apply `@functools.cache` to the function `fib(n)`."},"start":"import functools\\n\\ndef fib(n):\\n    return n if n < 2 else fib(n - 1) + fib(n - 2)","html":"","checks":[{"re":"@functools\\\\.cache\\\\s*\\\\n\\\\s*def\\\\s+fib","label":{"it":"La funzione è decorata","en":"The function is decorated"}}],"hint":"@functools.cache\\ndef fib(n):\\n    return n if n < 2 else fib(n - 1) + fib(n - 2)"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('python-advanced','typing',3,2,'published','{"it":"Tipi e Protocol","en":"Types and Protocols"}','[{"t":"p","text":{"it":"Le **annotazioni di tipo** rendono il codice più chiaro e permettono a strumenti come **mypy** di trovare errori prima di eseguire. `list[int]`, `dict[str, float]`, `str | None` descrivono i dati.","en":"**Type annotations** make code clearer and let tools such as **mypy** find errors before running. `list[int]`, `dict[str, float]`, `str | None` describe the data."}},{"t":"code","code":"from typing import Protocol\\n\\nclass Pagabile(Protocol):\\n    def totale(self) -> float: ...\\n\\ndef addebita(cosa: Pagabile, sconto: float | None = None) -> float:\\n    importo = cosa.totale()\\n    return importo * (1 - sconto) if sconto else importo\\n\\nvoti: dict[str, list[int]] = {\\"Ada\\": [8, 9]}","lang":"python"},{"t":"p","text":{"it":"Un **Protocol** descrive una forma: qualsiasi classe con un metodo `totale()` va bene, anche se non eredita nulla. È il “duck typing” controllato.","en":"A **Protocol** describes a shape: any class with a `totale()` method fits, even without inheriting anything. It is checked “duck typing”."}}]','{"lang":"python","prompt":{"it":"Annota `def media(voti: list[float]) -> float:`.","en":"Annotate `def media(voti: list[float]) -> float:`."},"start":"def media(voti):\\n    return sum(voti) / len(voti)","html":"","checks":[{"re":"def\\\\s+media\\\\s*\\\\(\\\\s*voti\\\\s*:\\\\s*list\\\\[float\\\\]\\\\s*\\\\)\\\\s*->\\\\s*float\\\\s*:","label":{"it":"Parametro e risultato hanno un tipo","en":"Parameter and result are typed"}}],"hint":"def media(voti: list[float]) -> float:\\n    return sum(voti) / len(voti)"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('python-advanced','async',4,3,'published','{"it":"async e await","en":"async and await"}','[{"t":"p","text":{"it":"Il codice **asincrono** fa più cose mentre aspetta: richieste di rete, file, database. Una funzione `async def` si mette in pausa con `await`; `asyncio.gather` ne esegue molte insieme.","en":"**Asynchronous** code does several things while waiting: network requests, files, databases. An `async def` function pauses with `await`; `asyncio.gather` runs many together."}},{"t":"code","code":"import asyncio\\n\\nasync def scarica(nome, secondi):\\n    await asyncio.sleep(secondi)\\n    return f\\"{nome} pronto\\"\\n\\nasync def main():\\n    risultati = await asyncio.gather(\\n        scarica(\\"A\\", 1), scarica(\\"B\\", 1), scarica(\\"C\\", 1),\\n    )\\n    print(risultati)\\n\\nasyncio.run(main())","lang":"python"},{"t":"p","text":{"it":"Le tre attese da un secondo finiscono insieme in circa un secondo, non tre. L’asincrono aiuta con le attese, non con i calcoli pesanti.","en":"The three one-second waits finish together in about one second, not three. Async helps with waiting, not with heavy computation."}}]','{"lang":"python","prompt":{"it":"Scrivi `async def saluta():` che fa `await asyncio.sleep(1)` e restituisce `\\"ciao\\"`.","en":"Write `async def saluta():` that does `await asyncio.sleep(1)` and returns `\\"ciao\\"`."},"start":"import asyncio","html":"","checks":[{"re":"async\\\\s+def\\\\s+saluta\\\\s*\\\\(\\\\s*\\\\)\\\\s*:","label":{"it":"La coroutine esiste","en":"The coroutine exists"}},{"re":"await\\\\s+asyncio\\\\.sleep\\\\s*\\\\(\\\\s*1\\\\s*\\\\)","label":{"it":"Aspetta un secondo","en":"It waits one second"}},{"re":"return\\\\s+[\\"'']ciao[\\"'']","label":{"it":"Restituisce “ciao”","en":"It returns “ciao”"}}],"hint":"async def saluta():\\n    await asyncio.sleep(1)\\n    return \\"ciao\\""}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('python-advanced','pytest',5,3,'published','{"it":"Context manager e pytest","en":"Context managers and pytest"}','[{"t":"p","text":{"it":"Un **context manager** prepara e chiude qualcosa intorno a un blocco `with`; il modo più semplice è `@contextmanager` con un `yield`. **pytest** trova le funzioni che iniziano per `test_` e controlla con `assert`.","en":"A **context manager** sets up and tears down something around a `with` block; the simplest way is `@contextmanager` with a `yield`. **pytest** finds functions starting with `test_` and checks with `assert`."}},{"t":"code","code":"from contextlib import contextmanager\\nimport pytest\\n\\n@contextmanager\\ndef cronometro():\\n    inizio = time.perf_counter()\\n    yield\\n    print(time.perf_counter() - inizio)\\n\\ndef test_somma():\\n    assert somma(2, 3) == 5\\n\\ndef test_divisione_per_zero():\\n    with pytest.raises(ZeroDivisionError):\\n        1 / 0","lang":"python"},{"t":"p","text":{"it":"Si lanciano con `pytest` dal terminale. Le **fixture** preparano dati riutilizzabili tra i test.","en":"You run them with `pytest` from the terminal. **Fixtures** prepare data reused across tests."}}]','{"lang":"python","prompt":{"it":"Scrivi `def test_doppio():` con `assert doppio(4) == 8`.","en":"Write `def test_doppio():` with `assert doppio(4) == 8`."},"start":"","html":"","checks":[{"re":"def\\\\s+test_doppio\\\\s*\\\\(\\\\s*\\\\)\\\\s*:","label":{"it":"Il test esiste","en":"The test exists"}},{"re":"assert\\\\s+doppio\\\\s*\\\\(\\\\s*4\\\\s*\\\\)\\\\s*==\\\\s*8","label":{"it":"L’asserzione è giusta","en":"The assertion is right"}}],"hint":"def test_doppio():\\n    assert doppio(4) == 8"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('java-base','main',1,1,'published','{"it":"Il primo programma","en":"The first program"}','[{"t":"p","text":{"it":"Ogni programma Java parte dal metodo `main` dentro una **classe**. `System.out.println` scrive una riga. Ogni istruzione finisce con il punto e virgola.","en":"Every Java program starts from the `main` method inside a **class**. `System.out.println` writes a line. Every statement ends with a semicolon."}},{"t":"code","code":"public class Ciao {\\n    public static void main(String[] args) {\\n        System.out.println(\\"Ciao, Java!\\");\\n    }\\n}","lang":"java"},{"t":"p","text":{"it":"Il file deve chiamarsi come la classe pubblica: `Ciao.java`. Si compila e si esegue con `java Ciao.java`.","en":"The file must be named like the public class: `Ciao.java`. You compile and run it with `java Ciao.java`."}}]','{"lang":"java","prompt":{"it":"Nel `main` stampa `\\"Benvenuto\\"` con `System.out.println`.","en":"In `main` print `\\"Benvenuto\\"` with `System.out.println`."},"start":"public class App {\\n    public static void main(String[] args) {\\n    }\\n}","html":"","checks":[{"re":"System\\\\.out\\\\.println\\\\s*\\\\(\\\\s*\\"Benvenuto\\"\\\\s*\\\\)\\\\s*;","label":{"it":"Stampi il saluto","en":"You print the greeting"}}],"hint":"System.out.println(\\"Benvenuto\\");"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('java-base','types',2,1,'published','{"it":"Tipi e variabili","en":"Types and variables"}','[{"t":"p","text":{"it":"Java è **tipizzato**: ogni variabile ha un tipo deciso alla dichiarazione. `int` per gli interi, `double` per i decimali, `boolean` per vero/falso, `String` per il testo. `var` lascia dedurre il tipo al compilatore.","en":"Java is **typed**: every variable has a type fixed when declared. `int` for whole numbers, `double` for decimals, `boolean` for true/false, `String` for text. `var` lets the compiler infer the type."}},{"t":"code","code":"int anni = 36;\\ndouble prezzo = 9.99;\\nboolean attivo = true;\\nString nome = \\"Ada\\";\\nvar citta = \\"Londra\\"; // String\\n\\nfinal int MAX = 10;   // costante\\nSystem.out.println(nome + \\" ha \\" + anni + \\" anni\\");","lang":"java"},{"t":"p","text":{"it":"`final` impedisce di cambiare il valore. Le stringhe si confrontano con `equals`, non con `==`.","en":"`final` prevents changing the value. Strings are compared with `equals`, not `==`."}}]','{"lang":"java","prompt":{"it":"Dichiara `int livelli = 6;` e `String corso = \\"Java\\";`.","en":"Declare `int livelli = 6;` and `String corso = \\"Java\\";`."},"start":"","html":"","checks":[{"re":"int\\\\s+livelli\\\\s*=\\\\s*6\\\\s*;","label":{"it":"C’è l’intero","en":"There is the int"}},{"re":"String\\\\s+corso\\\\s*=\\\\s*\\"Java\\"\\\\s*;","label":{"it":"C’è la stringa","en":"There is the string"}}],"hint":"int livelli = 6;\\nString corso = \\"Java\\";"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('java-base','control',3,1,'published','{"it":"Condizioni e cicli","en":"Conditions and loops"}','[{"t":"p","text":{"it":"`if`/`else` sceglie, `switch` confronta un valore con molti casi, `for` e `while` ripetono. I blocchi stanno tra graffe.","en":"`if`/`else` chooses, `switch` compares one value with many cases, `for` and `while` repeat. Blocks sit between braces."}},{"t":"code","code":"for (int i = 1; i <= 3; i++) {\\n    System.out.println(\\"Giro \\" + i);\\n}\\n\\nString giudizio = switch (voto) {\\n    case 10, 9 -> \\"Ottimo\\";\\n    case 8, 7, 6 -> \\"Promosso\\";\\n    default -> \\"Da ripassare\\";\\n};","lang":"java"},{"t":"p","text":{"it":"Lo `switch` con la freccia `->` restituisce un valore e non ha bisogno di `break`.","en":"The arrow `->` switch returns a value and needs no `break`."}}]','{"lang":"java","prompt":{"it":"Con un `for` da 1 a 5 stampa ogni numero.","en":"With a `for` from 1 to 5 print each number."},"start":"","html":"","checks":[{"re":"for\\\\s*\\\\(\\\\s*int\\\\s+\\\\w+\\\\s*=\\\\s*1\\\\s*;\\\\s*\\\\w+\\\\s*<=\\\\s*5\\\\s*;\\\\s*\\\\w+\\\\+\\\\+\\\\s*\\\\)","label":{"it":"Il ciclo è giusto","en":"The loop is right"}},{"re":"System\\\\.out\\\\.println\\\\s*\\\\(\\\\s*\\\\w+\\\\s*\\\\)","label":{"it":"Stampi il numero","en":"You print the number"}}],"hint":"for (int i = 1; i <= 5; i++) {\\n    System.out.println(i);\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('java-base','arrays',4,2,'published','{"it":"Array e liste","en":"Arrays and lists"}','[{"t":"p","text":{"it":"Un **array** ha una lunghezza fissa: `int[] voti = {7, 8, 9};`. Un `ArrayList` cresce quando serve, con `add` e `get`. Il ciclo **for-each** scorre ogni elemento.","en":"An **array** has a fixed length: `int[] voti = {7, 8, 9};`. An `ArrayList` grows as needed, with `add` and `get`. The **for-each** loop walks every item."}},{"t":"code","code":"int[] voti = {7, 8, 9};\\nSystem.out.println(voti.length);\\n\\nList<String> nomi = new ArrayList<>();\\nnomi.add(\\"Ada\\");\\nnomi.add(\\"Bea\\");\\nfor (String n : nomi) {\\n    System.out.println(n);\\n}","lang":"java"},{"t":"p","text":{"it":"Tra le parentesi angolari va il tipo degli elementi: `List<String>`. Gli indici partono da 0.","en":"The type of the items goes between angle brackets: `List<String>`. Indexes start from 0."}}]','{"lang":"java","prompt":{"it":"Crea `List<String> corsi = new ArrayList<>();` e aggiungi `\\"Java\\"`.","en":"Create `List<String> corsi = new ArrayList<>();` and add `\\"Java\\"`."},"start":"","html":"","checks":[{"re":"List<String>\\\\s+corsi\\\\s*=\\\\s*new\\\\s+ArrayList<>\\\\s*\\\\(\\\\s*\\\\)\\\\s*;","label":{"it":"La lista esiste","en":"The list exists"}},{"re":"corsi\\\\.add\\\\s*\\\\(\\\\s*\\"Java\\"\\\\s*\\\\)\\\\s*;","label":{"it":"Aggiungi “Java”","en":"You add “Java”"}}],"hint":"List<String> corsi = new ArrayList<>();\\ncorsi.add(\\"Java\\");"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('java-base','methods',5,2,'published','{"it":"Metodi","en":"Methods"}','[{"t":"p","text":{"it":"Un **metodo** è un blocco di codice con nome, parametri tipizzati e un tipo di ritorno (`void` se non restituisce nulla). I metodi `static` si chiamano dalla classe, senza creare oggetti.","en":"A **method** is a named block of code with typed parameters and a return type (`void` if it returns nothing). `static` methods are called on the class, without creating objects."}},{"t":"code","code":"public class Calcoli {\\n    static int quadrato(int n) {\\n        return n * n;\\n    }\\n\\n    static void saluta(String nome) {\\n        System.out.println(\\"Ciao \\" + nome);\\n    }\\n\\n    public static void main(String[] args) {\\n        saluta(\\"Ada\\");\\n        System.out.println(quadrato(4));\\n    }\\n}","lang":"java"},{"t":"p","text":{"it":"Due metodi possono avere lo stesso nome con parametri diversi: è l’**overloading**.","en":"Two methods can share a name with different parameters: it is **overloading**."}}]','{"lang":"java","prompt":{"it":"Scrivi `static int doppio(int n)` che restituisce `n * 2`.","en":"Write `static int doppio(int n)` that returns `n * 2`."},"start":"","html":"","checks":[{"re":"static\\\\s+int\\\\s+doppio\\\\s*\\\\(\\\\s*int\\\\s+n\\\\s*\\\\)","label":{"it":"La firma è giusta","en":"The signature is right"}},{"re":"return\\\\s+n\\\\s*\\\\*\\\\s*2\\\\s*;","label":{"it":"Restituisci il doppio","en":"You return the double"}}],"hint":"static int doppio(int n) {\\n    return n * 2;\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('java-intermediate','classes',1,2,'published','{"it":"Classi e oggetti","en":"Classes and objects"}','[{"t":"p","text":{"it":"Una **classe** è lo stampo, un **oggetto** è una copia creata con `new`. I campi `private` si leggono e cambiano solo attraverso metodi pubblici: è l’**incapsulamento**.","en":"A **class** is the mould, an **object** is a copy created with `new`. `private` fields are read and changed only through public methods: it is **encapsulation**."}},{"t":"code","code":"public class Conto {\\n    private double saldo;\\n    private final String titolare;\\n\\n    public Conto(String titolare) {\\n        this.titolare = titolare;\\n    }\\n\\n    public void versa(double importo) {\\n        if (importo > 0) saldo += importo;\\n    }\\n\\n    public double getSaldo() { return saldo; }\\n}\\n\\nConto c = new Conto(\\"Ada\\");\\nc.versa(50);","lang":"java"},{"t":"p","text":{"it":"Il **costruttore** ha il nome della classe e nessun tipo di ritorno. `this` indica l’oggetto attuale.","en":"The **constructor** has the class name and no return type. `this` is the current object."}}]','{"lang":"java","prompt":{"it":"Crea la classe `Gatto` con il campo `private String nome` e un costruttore che lo imposta.","en":"Create the class `Gatto` with the field `private String nome` and a constructor that sets it."},"start":"","html":"","checks":[{"re":"class\\\\s+Gatto","label":{"it":"La classe esiste","en":"The class exists"}},{"re":"private\\\\s+String\\\\s+nome\\\\s*;","label":{"it":"Il campo è privato","en":"The field is private"}},{"re":"Gatto\\\\s*\\\\(\\\\s*String\\\\s+nome\\\\s*\\\\)\\\\s*\\\\{\\\\s*this\\\\.nome\\\\s*=\\\\s*nome\\\\s*;","label":{"it":"Il costruttore lo imposta","en":"The constructor sets it"}}],"hint":"public class Gatto {\\n    private String nome;\\n    public Gatto(String nome) {\\n        this.nome = nome;\\n    }\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('java-intermediate','inheritance',2,2,'published','{"it":"Ereditarietà e polimorfismo","en":"Inheritance and polymorphism"}','[{"t":"p","text":{"it":"Con `extends` una classe eredita campi e metodi da un’altra e può **sovrascriverli** con `@Override`. Una variabile del tipo padre può contenere un figlio: è il **polimorfismo**.","en":"With `extends` a class inherits fields and methods from another and can **override** them with `@Override`. A variable of the parent type can hold a child: it is **polymorphism**."}},{"t":"code","code":"abstract class Animale {\\n    abstract String verso();\\n}\\n\\nclass Cane extends Animale {\\n    @Override String verso() { return \\"Bau\\"; }\\n}\\n\\nclass Gatto extends Animale {\\n    @Override String verso() { return \\"Miao\\"; }\\n}\\n\\nList<Animale> zoo = List.of(new Cane(), new Gatto());\\nfor (Animale a : zoo) System.out.println(a.verso());","lang":"java"},{"t":"p","text":{"it":"Una classe `abstract` non si istanzia e obbliga i figli a scrivere i metodi astratti. `super` chiama la versione del padre.","en":"An `abstract` class cannot be instantiated and forces children to write the abstract methods. `super` calls the parent’s version."}}]','{"lang":"java","prompt":{"it":"Crea `class Auto extends Veicolo` che sovrascrive `String tipo()` restituendo `\\"auto\\"`.","en":"Create `class Auto extends Veicolo` that overrides `String tipo()` returning `\\"auto\\"`."},"start":"","html":"","checks":[{"re":"class\\\\s+Auto\\\\s+extends\\\\s+Veicolo","label":{"it":"Auto eredita da Veicolo","en":"Auto inherits from Veicolo"}},{"re":"@Override\\\\s+(public\\\\s+)?String\\\\s+tipo\\\\s*\\\\(\\\\s*\\\\)","label":{"it":"Il metodo è sovrascritto","en":"The method is overridden"}},{"re":"return\\\\s+\\"auto\\"\\\\s*;","label":{"it":"Restituisce “auto”","en":"It returns “auto”"}}],"hint":"class Auto extends Veicolo {\\n    @Override\\n    String tipo() { return \\"auto\\"; }\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('java-intermediate','interfaces',3,2,'published','{"it":"Interfacce e record","en":"Interfaces and records"}','[{"t":"p","text":{"it":"Un’**interfaccia** dichiara che cosa un oggetto sa fare; una classe la rispetta con `implements` e può implementarne molte. Un **record** è una classe di soli dati, immutabile, scritta in una riga.","en":"An **interface** declares what an object can do; a class follows it with `implements` and can implement many. A **record** is a data-only, immutable class written in one line."}},{"t":"code","code":"interface Pagabile {\\n    double totale();\\n}\\n\\nrecord Prodotto(String nome, double prezzo) implements Pagabile {\\n    public double totale() { return prezzo * 1.22; }\\n}\\n\\nvar p = new Prodotto(\\"Libro\\", 10);\\nSystem.out.println(p.nome() + \\" \\" + p.totale());","lang":"java"},{"t":"p","text":{"it":"Il record crea da solo costruttore, metodi di lettura (`nome()`), `equals`, `hashCode` e `toString`.","en":"The record creates the constructor, accessors (`nome()`), `equals`, `hashCode` and `toString` by itself."}}]','{"lang":"java","prompt":{"it":"Crea `record Utente(String nome, int eta) {}`.","en":"Create `record Utente(String nome, int eta) {}`."},"start":"","html":"","checks":[{"re":"record\\\\s+Utente\\\\s*\\\\(\\\\s*String\\\\s+nome\\\\s*,\\\\s*int\\\\s+eta\\\\s*\\\\)","label":{"it":"Il record esiste","en":"The record exists"}}],"hint":"record Utente(String nome, int eta) {}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('java-intermediate','collections',4,3,'published','{"it":"Collezioni","en":"Collections"}','[{"t":"p","text":{"it":"Le **collezioni** principali sono `List` (ordinata, con doppioni), `Set` (senza doppioni) e `Map` (chiave → valore). Si dichiara l’interfaccia e si sceglie l’implementazione: `ArrayList`, `HashSet`, `HashMap`.","en":"The main **collections** are `List` (ordered, with duplicates), `Set` (no duplicates) and `Map` (key → value). You declare the interface and pick the implementation: `ArrayList`, `HashSet`, `HashMap`."}},{"t":"code","code":"Map<String, Integer> voti = new HashMap<>();\\nvoti.put(\\"Ada\\", 9);\\nvoti.put(\\"Bea\\", 8);\\nSystem.out.println(voti.get(\\"Ada\\"));\\nSystem.out.println(voti.getOrDefault(\\"Cleo\\", 0));\\n\\nSet<String> tag = new HashSet<>(List.of(\\"java\\", \\"java\\", \\"oop\\"));\\nSystem.out.println(tag.size()); // 2","lang":"java"},{"t":"p","text":{"it":"`getOrDefault` evita il `null` quando la chiave manca. Un `Set` scarta da solo i doppioni.","en":"`getOrDefault` avoids `null` when the key is missing. A `Set` drops duplicates by itself."}}]','{"lang":"java","prompt":{"it":"Crea `Map<String, Integer> eta = new HashMap<>();` e inserisci `\\"Ada\\"` con `36`.","en":"Create `Map<String, Integer> eta = new HashMap<>();` and put `\\"Ada\\"` with `36`."},"start":"","html":"","checks":[{"re":"Map<String,\\\\s*Integer>\\\\s+eta\\\\s*=\\\\s*new\\\\s+HashMap<>\\\\s*\\\\(\\\\s*\\\\)\\\\s*;","label":{"it":"La mappa esiste","en":"The map exists"}},{"re":"eta\\\\.put\\\\s*\\\\(\\\\s*\\"Ada\\"\\\\s*,\\\\s*36\\\\s*\\\\)\\\\s*;","label":{"it":"Inserisci la coppia","en":"You insert the pair"}}],"hint":"Map<String, Integer> eta = new HashMap<>();\\neta.put(\\"Ada\\", 36);"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('java-intermediate','exceptions',5,3,'published','{"it":"Eccezioni","en":"Exceptions"}','[{"t":"p","text":{"it":"Gli errori in Java sono **eccezioni**: si lanciano con `throw` e si catturano con `try`/`catch`. Le eccezioni **controllate** (come `IOException`) vanno gestite o dichiarate con `throws`.","en":"Errors in Java are **exceptions**: thrown with `throw` and caught with `try`/`catch`. **Checked** exceptions (like `IOException`) must be handled or declared with `throws`."}},{"t":"code","code":"try (var lettore = Files.newBufferedReader(Path.of(\\"dati.txt\\"))) {\\n    System.out.println(lettore.readLine());\\n} catch (IOException e) {\\n    System.out.println(\\"Impossibile leggere: \\" + e.getMessage());\\n}\\n\\nstatic void preleva(double importo) {\\n    if (importo <= 0) throw new IllegalArgumentException(\\"Importo non valido\\");\\n}","lang":"java"},{"t":"p","text":{"it":"Il **try-with-resources** chiude da solo file e connessioni alla fine del blocco.","en":"**try-with-resources** closes files and connections by itself at the end of the block."}}]','{"lang":"java","prompt":{"it":"Lancia `new IllegalArgumentException(\\"Età negativa\\")` se `eta < 0`.","en":"Throw `new IllegalArgumentException(\\"Età negativa\\")` if `eta < 0`."},"start":"static void setEta(int eta) {\\n}","html":"","checks":[{"re":"if\\\\s*\\\\(\\\\s*eta\\\\s*<\\\\s*0\\\\s*\\\\)\\\\s*\\\\{?\\\\s*throw\\\\s+new\\\\s+IllegalArgumentException\\\\s*\\\\(","label":{"it":"Lanci l’eccezione giusta","en":"You throw the right exception"}}],"hint":"if (eta < 0) throw new IllegalArgumentException(\\"Età negativa\\");"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('java-advanced','generics',1,2,'published','{"it":"Generics","en":"Generics"}','[{"t":"p","text":{"it":"I **generics** permettono di scrivere classi e metodi che funzionano con qualsiasi tipo, mantenendo i controlli del compilatore. La lettera tra parentesi angolari (`<T>`) è il tipo scelto da chi li usa.","en":"**Generics** let you write classes and methods that work with any type, keeping the compiler’s checks. The letter between angle brackets (`<T>`) is the type chosen by whoever uses them."}},{"t":"code","code":"class Scatola<T> {\\n    private T contenuto;\\n    void metti(T cosa) { contenuto = cosa; }\\n    T prendi() { return contenuto; }\\n}\\n\\nScatola<String> s = new Scatola<>();\\ns.metti(\\"libro\\");\\nString x = s.prendi();\\n\\nstatic <T extends Comparable<T>> T massimo(T a, T b) {\\n    return a.compareTo(b) >= 0 ? a : b;\\n}","lang":"java"},{"t":"p","text":{"it":"`T extends Comparable<T>` pone un **limite**: vanno bene solo i tipi confrontabili.","en":"`T extends Comparable<T>` sets a **bound**: only comparable types are allowed."}}]','{"lang":"java","prompt":{"it":"Crea `class Coppia<A, B>` con i campi `A primo;` e `B secondo;`.","en":"Create `class Coppia<A, B>` with the fields `A primo;` and `B secondo;`."},"start":"","html":"","checks":[{"re":"class\\\\s+Coppia\\\\s*<\\\\s*A\\\\s*,\\\\s*B\\\\s*>","label":{"it":"La classe è generica","en":"The class is generic"}},{"re":"A\\\\s+primo\\\\s*;","label":{"it":"C’è il primo","en":"There is the first"}},{"re":"B\\\\s+secondo\\\\s*;","label":{"it":"C’è il secondo","en":"There is the second"}}],"hint":"class Coppia<A, B> {\\n    A primo;\\n    B secondo;\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('java-advanced','streams',2,2,'published','{"it":"Lambda e stream","en":"Lambdas and streams"}','[{"t":"p","text":{"it":"Una **lambda** è una funzione breve senza nome: `x -> x * 2`. Gli **stream** elaborano una collezione come una catena: `filter` scarta, `map` trasforma, `collect` raccoglie il risultato.","en":"A **lambda** is a short nameless function: `x -> x * 2`. **Streams** process a collection as a chain: `filter` drops, `map` transforms, `collect` gathers the result."}},{"t":"code","code":"List<String> nomi = List.of(\\"ada\\", \\"bea\\", \\"carlo\\", \\"di\\");\\n\\nList<String> lunghi = nomi.stream()\\n    .filter(n -> n.length() > 2)\\n    .map(String::toUpperCase)\\n    .sorted()\\n    .toList();\\n\\nint somma = IntStream.rangeClosed(1, 10).sum();","lang":"java"},{"t":"p","text":{"it":"`String::toUpperCase` è un **riferimento a metodo**, una lambda ancora più corta. Uno stream non modifica la lista originale.","en":"`String::toUpperCase` is a **method reference**, an even shorter lambda. A stream does not change the original list."}}]','{"lang":"java","prompt":{"it":"Da `numeri` ottieni con uno stream la lista dei pari: `filter(n -> n % 2 == 0)` e `toList()`.","en":"From `numeri` get the list of evens with a stream: `filter(n -> n % 2 == 0)` and `toList()`."},"start":"List<Integer> numeri = List.of(1, 2, 3, 4);","html":"","checks":[{"re":"numeri\\\\.stream\\\\s*\\\\(\\\\s*\\\\)","label":{"it":"Parti dallo stream","en":"You start from the stream"}},{"re":"\\\\.filter\\\\s*\\\\(\\\\s*n\\\\s*->\\\\s*n\\\\s*%\\\\s*2\\\\s*==\\\\s*0\\\\s*\\\\)","label":{"it":"Filtri i pari","en":"You filter the evens"}},{"re":"\\\\.toList\\\\s*\\\\(\\\\s*\\\\)","label":{"it":"Raccogli in una lista","en":"You collect into a list"}}],"hint":"List<Integer> pari = numeri.stream()\\n    .filter(n -> n % 2 == 0)\\n    .toList();"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('java-advanced','optional',3,2,'published','{"it":"Optional e null","en":"Optional and null"}','[{"t":"p","text":{"it":"`NullPointerException` è l’errore più comune di Java. `Optional<T>` rende esplicito che un valore può mancare e offre metodi sicuri: `orElse`, `map`, `ifPresent`.","en":"`NullPointerException` is Java’s most common error. `Optional<T>` makes it explicit that a value may be missing and offers safe methods: `orElse`, `map`, `ifPresent`."}},{"t":"code","code":"Optional<Utente> trova(String email) {\\n    return utenti.stream()\\n        .filter(u -> u.email().equals(email))\\n        .findFirst();\\n}\\n\\nString nome = trova(\\"ada@example.com\\")\\n    .map(Utente::nome)\\n    .orElse(\\"Ospite\\");\\n\\ntrova(\\"x@y.it\\").ifPresent(u -> System.out.println(u.nome()));","lang":"java"},{"t":"p","text":{"it":"Usa `Optional` come valore di ritorno, non come campo o parametro: lì è meglio decidere chiaramente.","en":"Use `Optional` as a return value, not as a field or parameter: there it is better to decide clearly."}}]','{"lang":"java","prompt":{"it":"Restituisci il nome con `.map(Utente::nome).orElse(\\"Anonimo\\")`.","en":"Return the name with `.map(Utente::nome).orElse(\\"Anonimo\\")`."},"start":"Optional<Utente> u = cerca(id);","html":"","checks":[{"re":"\\\\.map\\\\s*\\\\(\\\\s*Utente::nome\\\\s*\\\\)\\\\s*\\\\.orElse\\\\s*\\\\(\\\\s*\\"Anonimo\\"\\\\s*\\\\)","label":{"it":"Usi map e orElse","en":"You use map and orElse"}}],"hint":"String nome = u.map(Utente::nome).orElse(\\"Anonimo\\");"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('java-advanced','concurrency',4,3,'published','{"it":"Concorrenza","en":"Concurrency"}','[{"t":"p","text":{"it":"Più **thread** lavorano insieme. Invece di crearli a mano, un **ExecutorService** gestisce un gruppo di thread; i **virtual thread** di Java 21 sono leggerissimi e se ne possono avere migliaia.","en":"Several **threads** work together. Instead of creating them by hand, an **ExecutorService** manages a pool of threads; Java 21 **virtual threads** are very light and you can have thousands."}},{"t":"code","code":"try (var executor = Executors.newVirtualThreadPerTaskExecutor()) {\\n    List<Future<String>> risultati = urls.stream()\\n        .map(url -> executor.submit(() -> scarica(url)))\\n        .toList();\\n    for (var f : risultati) System.out.println(f.get());\\n}\\n\\nAtomicInteger contatore = new AtomicInteger();\\ncontatore.incrementAndGet();","lang":"java"},{"t":"p","text":{"it":"Quando due thread toccano lo stesso dato servono strumenti sicuri come `AtomicInteger` o `ConcurrentHashMap`, altrimenti i risultati si mescolano.","en":"When two threads touch the same data you need safe tools such as `AtomicInteger` or `ConcurrentHashMap`, otherwise results get mixed up."}}]','{"lang":"java","prompt":{"it":"Crea `AtomicInteger visite = new AtomicInteger();` e incrementalo con `incrementAndGet()`.","en":"Create `AtomicInteger visite = new AtomicInteger();` and increment it with `incrementAndGet()`."},"start":"","html":"","checks":[{"re":"AtomicInteger\\\\s+visite\\\\s*=\\\\s*new\\\\s+AtomicInteger\\\\s*\\\\(\\\\s*\\\\)\\\\s*;","label":{"it":"Il contatore esiste","en":"The counter exists"}},{"re":"visite\\\\.incrementAndGet\\\\s*\\\\(\\\\s*\\\\)","label":{"it":"Lo incrementi","en":"You increment it"}}],"hint":"AtomicInteger visite = new AtomicInteger();\\nvisite.incrementAndGet();"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('java-advanced','junit',5,3,'published','{"it":"Test con JUnit","en":"Testing with JUnit"}','[{"t":"p","text":{"it":"**JUnit 5** è lo standard per i test in Java. Un metodo segnato con `@Test` verifica il codice con le asserzioni: `assertEquals`, `assertTrue`, `assertThrows`.","en":"**JUnit 5** is Java’s standard for tests. A method marked `@Test` checks code with assertions: `assertEquals`, `assertTrue`, `assertThrows`."}},{"t":"code","code":"import org.junit.jupiter.api.Test;\\nimport static org.junit.jupiter.api.Assertions.*;\\n\\nclass CarrelloTest {\\n    @Test\\n    void totaleConDuePezzi() {\\n        var c = new Carrello();\\n        c.aggiungi(10);\\n        c.aggiungi(5);\\n        assertEquals(15, c.totale());\\n    }\\n\\n    @Test\\n    void importoNegativo() {\\n        assertThrows(IllegalArgumentException.class, () -> new Carrello().aggiungi(-1));\\n    }\\n}","lang":"java"},{"t":"p","text":{"it":"In `assertEquals` va prima il valore **atteso**, poi quello ottenuto: così i messaggi di errore si leggono bene.","en":"In `assertEquals` the **expected** value comes first, then the actual one: so error messages read well."}}]','{"lang":"java","prompt":{"it":"Scrivi un `@Test` che verifica con `assertEquals(4, somma(2, 2))`.","en":"Write a `@Test` that checks with `assertEquals(4, somma(2, 2))`."},"start":"class SommaTest {\\n}","html":"","checks":[{"re":"@Test\\\\s+void\\\\s+\\\\w+\\\\s*\\\\(\\\\s*\\\\)","label":{"it":"Il test esiste","en":"The test exists"}},{"re":"assertEquals\\\\s*\\\\(\\\\s*4\\\\s*,\\\\s*somma\\\\s*\\\\(\\\\s*2\\\\s*,\\\\s*2\\\\s*\\\\)\\\\s*\\\\)","label":{"it":"L’asserzione è giusta","en":"The assertion is right"}}],"hint":"@Test\\nvoid somma() {\\n    assertEquals(4, somma(2, 2));\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('sql-base','tables',1,1,'published','{"it":"Tabelle e SELECT","en":"Tables and SELECT"}','[{"t":"p","text":{"it":"Un database relazionale tiene i dati in **tabelle**: righe (i record) e colonne (i campi). `SELECT` legge: dopo la parola si scrivono le colonne, dopo `FROM` la tabella.","en":"A relational database keeps data in **tables**: rows (records) and columns (fields). `SELECT` reads: after the word you list the columns, after `FROM` the table."}},{"t":"code","code":"SELECT nome, email\\nFROM utenti;\\n\\nSELECT * FROM corsi;","lang":"sql"},{"t":"p","text":{"it":"`*` significa tutte le colonne: comodo per esplorare, ma nel codice vero è meglio elencare solo quelle che servono. Le parole chiave si scrivono di solito in maiuscolo.","en":"`*` means every column: handy for exploring, but in real code it is better to list only the ones you need. Keywords are usually written in capitals."}}]','{"lang":"sql","prompt":{"it":"Leggi le colonne `titolo` e `livello` dalla tabella `corsi`.","en":"Read the columns `titolo` and `livello` from the table `corsi`."},"start":"","html":"","checks":[{"re":"SELECT\\\\s+titolo\\\\s*,\\\\s*livello\\\\s+FROM\\\\s+corsi","label":{"it":"La query è giusta","en":"The query is right"}}],"hint":"SELECT titolo, livello FROM corsi;"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('sql-base','where',2,1,'published','{"it":"Filtrare con WHERE","en":"Filtering with WHERE"}','[{"t":"p","text":{"it":"`WHERE` tiene solo le righe che rispettano una condizione. Si combinano con `AND` e `OR`; `LIKE` cerca nel testo con `%` come jolly, `IN` controlla un elenco, `BETWEEN` un intervallo.","en":"`WHERE` keeps only the rows that meet a condition. Combine with `AND` and `OR`; `LIKE` searches text with `%` as a wildcard, `IN` checks a list, `BETWEEN` a range."}},{"t":"code","code":"SELECT nome FROM utenti\\nWHERE citta = ''Udine'' AND eta >= 18;\\n\\nSELECT titolo FROM corsi WHERE titolo LIKE ''%HTML%'';\\nSELECT * FROM ordini WHERE stato IN (''nuovo'', ''pagato'');\\nSELECT * FROM voti WHERE voto BETWEEN 6 AND 8;","lang":"sql"},{"t":"p","text":{"it":"Il testo va tra apici singoli. Per cercare i valori mancanti si usa `IS NULL`, non `= NULL`.","en":"Text goes between single quotes. To find missing values use `IS NULL`, not `= NULL`."}}]','{"lang":"sql","prompt":{"it":"Dalla tabella `utenti` prendi il `nome` di chi ha `eta >= 18` e `citta = ''Roma''`.","en":"From the table `utenti` take the `nome` of those with `eta >= 18` and `citta = ''Roma''`."},"start":"","html":"","checks":[{"re":"SELECT\\\\s+nome\\\\s+FROM\\\\s+utenti\\\\s+WHERE","label":{"it":"C’è il filtro","en":"There is the filter"}},{"re":"eta\\\\s*>=\\\\s*18","label":{"it":"Maggiorenni","en":"Adults"}},{"re":"AND\\\\s+citta\\\\s*=\\\\s*''Roma''|citta\\\\s*=\\\\s*''Roma''\\\\s+AND","label":{"it":"Di Roma","en":"From Rome"}}],"hint":"SELECT nome FROM utenti WHERE eta >= 18 AND citta = ''Roma'';"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('sql-base','order',3,1,'published','{"it":"Ordinare e limitare","en":"Sorting and limiting"}','[{"t":"p","text":{"it":"`ORDER BY` ordina il risultato, crescente (`ASC`, il predefinito) o decrescente (`DESC`). `LIMIT` tiene solo le prime righe; `DISTINCT` toglie i doppioni.","en":"`ORDER BY` sorts the result, ascending (`ASC`, the default) or descending (`DESC`). `LIMIT` keeps only the first rows; `DISTINCT` removes duplicates."}},{"t":"code","code":"SELECT nome, punti FROM classifica\\nORDER BY punti DESC, nome ASC\\nLIMIT 10;\\n\\nSELECT DISTINCT citta FROM utenti;","lang":"sql"},{"t":"p","text":{"it":"L’ordine delle clausole è fisso: `SELECT`, `FROM`, `WHERE`, `ORDER BY`, `LIMIT`.","en":"The order of the clauses is fixed: `SELECT`, `FROM`, `WHERE`, `ORDER BY`, `LIMIT`."}}]','{"lang":"sql","prompt":{"it":"Prendi i 5 prodotti più cari: `ORDER BY prezzo DESC LIMIT 5`.","en":"Take the 5 most expensive products: `ORDER BY prezzo DESC LIMIT 5`."},"start":"SELECT nome, prezzo FROM prodotti","html":"","checks":[{"re":"ORDER\\\\s+BY\\\\s+prezzo\\\\s+DESC","label":{"it":"Ordini per prezzo decrescente","en":"You sort by price descending"}},{"re":"LIMIT\\\\s+5","label":{"it":"Tieni i primi 5","en":"You keep the first 5"}}],"hint":"SELECT nome, prezzo FROM prodotti ORDER BY prezzo DESC LIMIT 5;"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('sql-base','changes',4,2,'published','{"it":"Inserire, modificare, cancellare","en":"Insert, update, delete"}','[{"t":"p","text":{"it":"`INSERT INTO` aggiunge righe, `UPDATE … SET` modifica, `DELETE FROM` cancella. Con `UPDATE` e `DELETE` il `WHERE` è fondamentale: senza, tocchi **tutte** le righe.","en":"`INSERT INTO` adds rows, `UPDATE … SET` changes them, `DELETE FROM` deletes. With `UPDATE` and `DELETE` the `WHERE` is vital: without it you touch **every** row."}},{"t":"code","code":"INSERT INTO corsi (titolo, livello) VALUES (''SQL'', ''base'');\\n\\nUPDATE utenti SET citta = ''Trieste'' WHERE id = 7;\\n\\nDELETE FROM sessioni WHERE scadenza < NOW();","lang":"sql"},{"t":"p","text":{"it":"Prima di un `DELETE`, prova lo stesso `WHERE` con un `SELECT` per vedere quali righe toccheresti.","en":"Before a `DELETE`, try the same `WHERE` with a `SELECT` to see which rows you would touch."}}]','{"lang":"sql","prompt":{"it":"Imposta `attivo = 0` per l’utente con `id = 3`.","en":"Set `attivo = 0` for the user with `id = 3`."},"start":"","html":"","checks":[{"re":"UPDATE\\\\s+utenti\\\\s+SET\\\\s+attivo\\\\s*=\\\\s*0","label":{"it":"Modifichi il campo","en":"You change the field"}},{"re":"WHERE\\\\s+id\\\\s*=\\\\s*3","label":{"it":"Solo quell’utente","en":"Only that user"}}],"hint":"UPDATE utenti SET attivo = 0 WHERE id = 3;"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('sql-base','create',5,2,'published','{"it":"Creare tabelle","en":"Creating tables"}','[{"t":"p","text":{"it":"`CREATE TABLE` definisce una tabella: per ogni colonna un nome e un **tipo** (`INT`, `VARCHAR(100)`, `DATE`, `DECIMAL(8,2)`…). La **chiave primaria** identifica ogni riga in modo unico.","en":"`CREATE TABLE` defines a table: for each column a name and a **type** (`INT`, `VARCHAR(100)`, `DATE`, `DECIMAL(8,2)`…). The **primary key** identifies every row uniquely."}},{"t":"code","code":"CREATE TABLE corsi (\\n    id INT PRIMARY KEY AUTO_INCREMENT,\\n    titolo VARCHAR(120) NOT NULL,\\n    prezzo DECIMAL(8, 2) DEFAULT 0,\\n    creato_il DATE\\n);","lang":"sql"},{"t":"p","text":{"it":"`NOT NULL` obbliga a riempire il campo, `DEFAULT` dà un valore iniziale, `AUTO_INCREMENT` numera da solo le righe nuove.","en":"`NOT NULL` makes a field required, `DEFAULT` gives a starting value, `AUTO_INCREMENT` numbers new rows by itself."}}]','{"lang":"sql","prompt":{"it":"Crea la tabella `note` con `id INT PRIMARY KEY` e `testo VARCHAR(200) NOT NULL`.","en":"Create the table `note` with `id INT PRIMARY KEY` and `testo VARCHAR(200) NOT NULL`."},"start":"","html":"","checks":[{"re":"CREATE\\\\s+TABLE\\\\s+note\\\\s*\\\\(","label":{"it":"La tabella esiste","en":"The table exists"}},{"re":"id\\\\s+INT\\\\s+PRIMARY\\\\s+KEY","label":{"it":"C’è la chiave primaria","en":"There is the primary key"}},{"re":"testo\\\\s+VARCHAR\\\\s*\\\\(\\\\s*200\\\\s*\\\\)\\\\s+NOT\\\\s+NULL","label":{"it":"Il testo è obbligatorio","en":"The text is required"}}],"hint":"CREATE TABLE note (\\n    id INT PRIMARY KEY,\\n    testo VARCHAR(200) NOT NULL\\n);"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('sql-intermediate','aggregates',1,2,'published','{"it":"Funzioni di aggregazione","en":"Aggregate functions"}','[{"t":"p","text":{"it":"Le **funzioni di aggregazione** riassumono tante righe in un valore: `COUNT` conta, `SUM` somma, `AVG` fa la media, `MIN` e `MAX` trovano gli estremi.","en":"**Aggregate functions** sum up many rows into one value: `COUNT` counts, `SUM` adds, `AVG` averages, `MIN` and `MAX` find the extremes."}},{"t":"code","code":"SELECT COUNT(*) AS iscritti FROM utenti;\\nSELECT AVG(voto) AS media, MAX(voto) AS migliore FROM esami;\\nSELECT SUM(totale) FROM ordini WHERE stato = ''pagato'';","lang":"sql"},{"t":"p","text":{"it":"`AS` dà un nome leggibile alla colonna del risultato. `COUNT(colonna)` conta solo i valori non `NULL`.","en":"`AS` gives the result column a readable name. `COUNT(column)` counts only non-`NULL` values."}}]','{"lang":"sql","prompt":{"it":"Calcola `AVG(prezzo) AS medio` dalla tabella `prodotti`.","en":"Compute `AVG(prezzo) AS medio` from the table `prodotti`."},"start":"","html":"","checks":[{"re":"SELECT\\\\s+AVG\\\\s*\\\\(\\\\s*prezzo\\\\s*\\\\)\\\\s+AS\\\\s+medio\\\\s+FROM\\\\s+prodotti","label":{"it":"La media è giusta","en":"The average is right"}}],"hint":"SELECT AVG(prezzo) AS medio FROM prodotti;"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('sql-intermediate','group-by',2,2,'published','{"it":"GROUP BY e HAVING","en":"GROUP BY and HAVING"}','[{"t":"p","text":{"it":"`GROUP BY` divide le righe in gruppi e calcola un’aggregazione per ciascuno. `HAVING` filtra i **gruppi**, come `WHERE` filtra le righe.","en":"`GROUP BY` splits rows into groups and computes an aggregate for each. `HAVING` filters **groups**, as `WHERE` filters rows."}},{"t":"code","code":"SELECT citta, COUNT(*) AS utenti\\nFROM utenti\\nWHERE attivo = 1\\nGROUP BY citta\\nHAVING COUNT(*) >= 10\\nORDER BY utenti DESC;","lang":"sql"},{"t":"p","text":{"it":"Nel `SELECT` possono stare solo le colonne del `GROUP BY` e le aggregazioni.","en":"The `SELECT` may contain only the `GROUP BY` columns and aggregates."}}]','{"lang":"sql","prompt":{"it":"Conta gli ordini per `cliente_id` e tieni chi ne ha più di 3.","en":"Count orders per `cliente_id` and keep those with more than 3."},"start":"SELECT cliente_id, COUNT(*) AS ordini FROM ordini","html":"","checks":[{"re":"GROUP\\\\s+BY\\\\s+cliente_id","label":{"it":"Raggruppi per cliente","en":"You group by customer"}},{"re":"HAVING\\\\s+COUNT\\\\s*\\\\(\\\\s*\\\\*\\\\s*\\\\)\\\\s*>\\\\s*3","label":{"it":"Filtri i gruppi","en":"You filter the groups"}}],"hint":"SELECT cliente_id, COUNT(*) AS ordini FROM ordini\\nGROUP BY cliente_id\\nHAVING COUNT(*) > 3;"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('sql-intermediate','joins',3,2,'published','{"it":"Le JOIN","en":"Joins"}','[{"t":"p","text":{"it":"Una **JOIN** unisce le righe di due tabelle che hanno un valore in comune. `INNER JOIN` tiene solo le coppie che combaciano; `LEFT JOIN` tiene tutte le righe della prima tabella, anche senza corrispondenza.","en":"A **JOIN** combines rows of two tables sharing a value. `INNER JOIN` keeps only matching pairs; `LEFT JOIN` keeps every row of the first table, even without a match."}},{"t":"code","code":"SELECT u.nome, o.totale\\nFROM utenti u\\nINNER JOIN ordini o ON o.utente_id = u.id;\\n\\nSELECT u.nome, COUNT(o.id) AS ordini\\nFROM utenti u\\nLEFT JOIN ordini o ON o.utente_id = u.id\\nGROUP BY u.id, u.nome;","lang":"sql"},{"t":"p","text":{"it":"Le lettere `u` e `o` sono **alias** delle tabelle: accorciano la query e chiariscono da dove viene ogni colonna.","en":"The letters `u` and `o` are table **aliases**: they shorten the query and make clear where each column comes from."}}]','{"lang":"sql","prompt":{"it":"Unisci `corsi c` e `lezioni l` con `INNER JOIN lezioni l ON l.corso_id = c.id`.","en":"Join `corsi c` and `lezioni l` with `INNER JOIN lezioni l ON l.corso_id = c.id`."},"start":"SELECT c.titolo, l.titolo\\nFROM corsi c","html":"","checks":[{"re":"INNER\\\\s+JOIN\\\\s+lezioni\\\\s+l\\\\s+ON\\\\s+l\\\\.corso_id\\\\s*=\\\\s*c\\\\.id","label":{"it":"La JOIN è giusta","en":"The join is right"}}],"hint":"SELECT c.titolo, l.titolo\\nFROM corsi c\\nINNER JOIN lezioni l ON l.corso_id = c.id;"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('sql-intermediate','subqueries',4,3,'published','{"it":"Sottoquery","en":"Subqueries"}','[{"t":"p","text":{"it":"Una **sottoquery** è una `SELECT` dentro un’altra. Può dare un valore da confrontare, un elenco per `IN` o una tabella temporanea dopo `FROM`.","en":"A **subquery** is a `SELECT` inside another. It can give a value to compare, a list for `IN` or a temporary table after `FROM`."}},{"t":"code","code":"SELECT nome, prezzo FROM prodotti\\nWHERE prezzo > (SELECT AVG(prezzo) FROM prodotti);\\n\\nSELECT nome FROM utenti\\nWHERE id IN (SELECT utente_id FROM ordini WHERE totale > 100);\\n\\nSELECT * FROM utenti u\\nWHERE EXISTS (SELECT 1 FROM ordini o WHERE o.utente_id = u.id);","lang":"sql"},{"t":"p","text":{"it":"`EXISTS` risponde solo “c’è o non c’è?”: è spesso più veloce di `IN` su tabelle grandi.","en":"`EXISTS` only answers “is there or not?”: it is often faster than `IN` on big tables."}}]','{"lang":"sql","prompt":{"it":"Prendi gli studenti con voto sopra la media: `WHERE voto > (SELECT AVG(voto) FROM studenti)`.","en":"Take students above average: `WHERE voto > (SELECT AVG(voto) FROM studenti)`."},"start":"SELECT nome FROM studenti","html":"","checks":[{"re":"WHERE\\\\s+voto\\\\s*>\\\\s*\\\\(\\\\s*SELECT\\\\s+AVG\\\\s*\\\\(\\\\s*voto\\\\s*\\\\)\\\\s+FROM\\\\s+studenti\\\\s*\\\\)","label":{"it":"La sottoquery è giusta","en":"The subquery is right"}}],"hint":"SELECT nome FROM studenti\\nWHERE voto > (SELECT AVG(voto) FROM studenti);"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('sql-intermediate','keys',5,3,'published','{"it":"Chiavi esterne e indici","en":"Foreign keys and indexes"}','[{"t":"p","text":{"it":"Una **chiave esterna** collega una colonna alla chiave primaria di un’altra tabella e impedisce riferimenti a righe inesistenti. Un **indice** è come l’indice di un libro: rende veloci le ricerche su una colonna.","en":"A **foreign key** links a column to another table’s primary key and blocks references to missing rows. An **index** is like a book’s index: it makes searches on a column fast."}},{"t":"code","code":"CREATE TABLE ordini (\\n    id INT PRIMARY KEY AUTO_INCREMENT,\\n    utente_id INT NOT NULL,\\n    totale DECIMAL(8, 2),\\n    FOREIGN KEY (utente_id) REFERENCES utenti(id) ON DELETE CASCADE\\n);\\n\\nCREATE INDEX ix_ordini_utente ON ordini (utente_id);","lang":"sql"},{"t":"p","text":{"it":"`ON DELETE CASCADE` cancella gli ordini quando sparisce l’utente. Gli indici velocizzano le letture ma rallentano un po’ le scritture: mettili sulle colonne che usi in `WHERE` e `JOIN`.","en":"`ON DELETE CASCADE` deletes orders when the user disappears. Indexes speed up reads but slow writes a little: put them on columns used in `WHERE` and `JOIN`."}}]','{"lang":"sql","prompt":{"it":"Crea l’indice `ix_utenti_email` sulla colonna `email` di `utenti`.","en":"Create the index `ix_utenti_email` on the `email` column of `utenti`."},"start":"","html":"","checks":[{"re":"CREATE\\\\s+(UNIQUE\\\\s+)?INDEX\\\\s+ix_utenti_email\\\\s+ON\\\\s+utenti\\\\s*\\\\(\\\\s*email\\\\s*\\\\)","label":{"it":"L’indice è giusto","en":"The index is right"}}],"hint":"CREATE INDEX ix_utenti_email ON utenti (email);"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('sql-advanced','cte',1,2,'published','{"it":"CTE con WITH","en":"CTEs with WITH"}','[{"t":"p","text":{"it":"Una **CTE** (Common Table Expression) dà un nome a una sottoquery con `WITH`, così la query principale resta leggibile. Con `WITH RECURSIVE` si percorrono strutture ad albero, come categorie e sottocategorie.","en":"A **CTE** (Common Table Expression) names a subquery with `WITH`, so the main query stays readable. With `WITH RECURSIVE` you walk tree structures, like categories and subcategories."}},{"t":"code","code":"WITH spese AS (\\n    SELECT utente_id, SUM(totale) AS speso\\n    FROM ordini\\n    GROUP BY utente_id\\n)\\nSELECT u.nome, s.speso\\nFROM utenti u JOIN spese s ON s.utente_id = u.id\\nWHERE s.speso > 500;\\n\\nWITH RECURSIVE numeri(n) AS (\\n    SELECT 1\\n    UNION ALL\\n    SELECT n + 1 FROM numeri WHERE n < 10\\n)\\nSELECT n FROM numeri;","lang":"sql"},{"t":"p","text":{"it":"Una CTE ricorsiva ha un punto di partenza, `UNION ALL`, e un passo che richiama sé stesso finché la condizione lo permette.","en":"A recursive CTE has a starting point, `UNION ALL`, and a step that calls itself while the condition allows."}}]','{"lang":"sql","prompt":{"it":"Crea la CTE `attivi AS (SELECT * FROM utenti WHERE attivo = 1)` e poi `SELECT COUNT(*) FROM attivi`.","en":"Create the CTE `attivi AS (SELECT * FROM utenti WHERE attivo = 1)` then `SELECT COUNT(*) FROM attivi`."},"start":"","html":"","checks":[{"re":"WITH\\\\s+attivi\\\\s+AS\\\\s*\\\\(\\\\s*SELECT\\\\s+\\\\*\\\\s+FROM\\\\s+utenti\\\\s+WHERE\\\\s+attivo\\\\s*=\\\\s*1\\\\s*\\\\)","label":{"it":"La CTE è giusta","en":"The CTE is right"}},{"re":"SELECT\\\\s+COUNT\\\\s*\\\\(\\\\s*\\\\*\\\\s*\\\\)\\\\s+FROM\\\\s+attivi","label":{"it":"La usi","en":"You use it"}}],"hint":"WITH attivi AS (SELECT * FROM utenti WHERE attivo = 1)\\nSELECT COUNT(*) FROM attivi;"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('sql-advanced','windows',2,2,'published','{"it":"Funzioni finestra","en":"Window functions"}','[{"t":"p","text":{"it":"Le **funzioni finestra** calcolano un valore per ogni riga guardando un gruppo di righe vicine, senza raggrupparle. `OVER (PARTITION BY … ORDER BY …)` definisce la finestra.","en":"**Window functions** compute a value for each row by looking at a group of nearby rows, without collapsing them. `OVER (PARTITION BY … ORDER BY …)` defines the window."}},{"t":"code","code":"SELECT nome, corso, voto,\\n       RANK() OVER (PARTITION BY corso ORDER BY voto DESC) AS posizione,\\n       AVG(voto) OVER (PARTITION BY corso) AS media_corso,\\n       SUM(importo) OVER (ORDER BY giorno) AS totale_progressivo\\nFROM esami;","lang":"sql"},{"t":"p","text":{"it":"`ROW_NUMBER` numera le righe, `RANK` gestisce i pari merito, `LAG` e `LEAD` leggono la riga precedente o successiva.","en":"`ROW_NUMBER` numbers rows, `RANK` handles ties, `LAG` and `LEAD` read the previous or next row."}}]','{"lang":"sql","prompt":{"it":"Numera i prodotti per prezzo decrescente: `ROW_NUMBER() OVER (ORDER BY prezzo DESC) AS pos`.","en":"Number products by descending price: `ROW_NUMBER() OVER (ORDER BY prezzo DESC) AS pos`."},"start":"SELECT nome, prezzo\\nFROM prodotti;","html":"","checks":[{"re":"ROW_NUMBER\\\\s*\\\\(\\\\s*\\\\)\\\\s+OVER\\\\s*\\\\(\\\\s*ORDER\\\\s+BY\\\\s+prezzo\\\\s+DESC\\\\s*\\\\)\\\\s+AS\\\\s+pos","label":{"it":"La finestra è giusta","en":"The window is right"}}],"hint":"SELECT nome, prezzo, ROW_NUMBER() OVER (ORDER BY prezzo DESC) AS pos\\nFROM prodotti;"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('sql-advanced','transactions',3,2,'published','{"it":"Transazioni","en":"Transactions"}','[{"t":"p","text":{"it":"Una **transazione** raccoglie più comandi in un blocco “tutto o niente”: con `COMMIT` diventano definitivi, con `ROLLBACK` si annullano tutti. Garantisce le proprietà **ACID**.","en":"A **transaction** groups several commands into an “all or nothing” block: `COMMIT` makes them permanent, `ROLLBACK` undoes them all. It guarantees the **ACID** properties."}},{"t":"code","code":"START TRANSACTION;\\n\\nUPDATE conti SET saldo = saldo - 100 WHERE id = 1;\\nUPDATE conti SET saldo = saldo + 100 WHERE id = 2;\\n\\n-- se tutto è andato bene\\nCOMMIT;\\n-- altrimenti\\n-- ROLLBACK;","lang":"sql"},{"t":"p","text":{"it":"Senza transazione, un errore tra i due `UPDATE` lascerebbe sparire 100 euro. I livelli di **isolamento** decidono che cosa vedono le transazioni che girano insieme.","en":"Without a transaction, an error between the two `UPDATE`s would make 100 euros vanish. **Isolation** levels decide what concurrent transactions can see."}}]','{"lang":"sql","prompt":{"it":"Racchiudi i due `UPDATE` tra `START TRANSACTION;` e `COMMIT;`.","en":"Wrap the two `UPDATE`s between `START TRANSACTION;` and `COMMIT;`."},"start":"UPDATE magazzino SET pezzi = pezzi - 1 WHERE id = 5;\\nUPDATE ordini SET stato = ''spedito'' WHERE id = 9;","html":"","checks":[{"re":"^\\\\s*START\\\\s+TRANSACTION\\\\s*;","label":{"it":"Apri la transazione","en":"You open the transaction"}},{"re":"COMMIT\\\\s*;\\\\s*$","label":{"it":"La confermi alla fine","en":"You commit at the end"}}],"hint":"START TRANSACTION;\\nUPDATE magazzino SET pezzi = pezzi - 1 WHERE id = 5;\\nUPDATE ordini SET stato = ''spedito'' WHERE id = 9;\\nCOMMIT;"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('sql-advanced','views',4,3,'published','{"it":"Viste e procedure","en":"Views and procedures"}','[{"t":"p","text":{"it":"Una **vista** è una query salvata con un nome: si interroga come una tabella. Serve a nascondere la complessità o a mostrare solo alcune colonne. Una **procedura** salva un blocco di comandi da richiamare con `CALL`.","en":"A **view** is a saved query with a name: you query it like a table. It hides complexity or shows only some columns. A **procedure** saves a block of commands to run with `CALL`."}},{"t":"code","code":"CREATE VIEW classifica_mensile AS\\nSELECT u.nome, SUM(p.punti) AS punti\\nFROM punteggi p JOIN utenti u ON u.id = p.utente_id\\nWHERE p.giorno >= CURRENT_DATE - INTERVAL 30 DAY\\nGROUP BY u.id, u.nome;\\n\\nSELECT * FROM classifica_mensile ORDER BY punti DESC LIMIT 10;","lang":"sql"},{"t":"p","text":{"it":"La vista non copia i dati: ogni volta rilegge le tabelle. Per dati pesanti esistono le viste **materializzate** (in PostgreSQL) che salvano il risultato.","en":"A view copies no data: it re-reads the tables every time. For heavy data there are **materialized** views (in PostgreSQL) that store the result."}}]','{"lang":"sql","prompt":{"it":"Crea la vista `corsi_pubblicati` con `SELECT * FROM corsi WHERE stato = ''published''`.","en":"Create the view `corsi_pubblicati` with `SELECT * FROM corsi WHERE stato = ''published''`."},"start":"","html":"","checks":[{"re":"CREATE\\\\s+(OR\\\\s+REPLACE\\\\s+)?VIEW\\\\s+corsi_pubblicati\\\\s+AS","label":{"it":"La vista esiste","en":"The view exists"}},{"re":"SELECT\\\\s+\\\\*\\\\s+FROM\\\\s+corsi\\\\s+WHERE\\\\s+stato\\\\s*=\\\\s*''published''","label":{"it":"La query è giusta","en":"The query is right"}}],"hint":"CREATE VIEW corsi_pubblicati AS\\nSELECT * FROM corsi WHERE stato = ''published'';"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('sql-advanced','explain',5,3,'published','{"it":"EXPLAIN e prestazioni","en":"EXPLAIN and performance"}','[{"t":"p","text":{"it":"`EXPLAIN` mostra come il database eseguirà una query: quali indici usa e quante righe legge. Una “scansione completa” su una tabella grande è il segnale che manca un indice.","en":"`EXPLAIN` shows how the database will run a query: which indexes it uses and how many rows it reads. A “full scan” on a big table signals a missing index."}},{"t":"code","code":"EXPLAIN SELECT * FROM ordini WHERE utente_id = 42;\\n\\n-- se non usa indici:\\nCREATE INDEX ix_ordini_utente ON ordini (utente_id);\\n\\n-- indice composto: l’ordine delle colonne conta\\nCREATE INDEX ix_ordini_utente_data ON ordini (utente_id, creato_il);","lang":"sql"},{"t":"p","text":{"it":"Un indice composto serve le query che filtrano sulla prima colonna (da sola o con la seconda), non quelle che filtrano solo sulla seconda. Evita funzioni sulle colonne indicizzate in `WHERE`: `YEAR(data) = 2026` non usa l’indice, `data >= ''2026-01-01''` sì.","en":"A composite index serves queries filtering on the first column (alone or with the second), not those filtering only on the second. Avoid functions on indexed columns in `WHERE`: `YEAR(data) = 2026` skips the index, `data >= ''2026-01-01''` uses it."}}]','{"lang":"sql","prompt":{"it":"Analizza `SELECT * FROM lezioni WHERE corso = ''sql-base''` con `EXPLAIN`.","en":"Analyse `SELECT * FROM lezioni WHERE corso = ''sql-base''` with `EXPLAIN`."},"start":"SELECT * FROM lezioni WHERE corso = ''sql-base'';","html":"","checks":[{"re":"^\\\\s*EXPLAIN\\\\s+SELECT\\\\s+\\\\*\\\\s+FROM\\\\s+lezioni","label":{"it":"Chiedi il piano","en":"You ask for the plan"}}],"hint":"EXPLAIN SELECT * FROM lezioni WHERE corso = ''sql-base'';"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('r-base','vectors',1,1,'published','{"it":"Valori e vettori","en":"Values and vectors"}','[{"t":"p","text":{"it":"In R si assegna con la freccia `<-`. Il mattone di base è il **vettore**, creato con `c()`: una serie di valori dello stesso tipo. Le operazioni lavorano su tutto il vettore insieme.","en":"In R you assign with the arrow `<-`. The basic brick is the **vector**, made with `c()`: a series of values of the same type. Operations work on the whole vector at once."}},{"t":"code","code":"voti <- c(7, 8, 6, 9)\\nvoti * 10        # 70 80 60 90\\nlength(voti)     # 4\\nvoti[1]          # 7: gli indici partono da 1\\nnomi <- c(\\"Ada\\", \\"Bea\\")\\nprint(paste(\\"Ciao\\", nomi))","lang":"r"},{"t":"p","text":{"it":"Attenzione: in R gli indici partono da **1**, non da 0. `paste` unisce testi.","en":"Careful: in R indexes start at **1**, not 0. `paste` joins texts."}}]','{"lang":"r","prompt":{"it":"Crea `altezze <- c(170, 165, 180)` e stampa `mean(altezze)`.","en":"Create `altezze <- c(170, 165, 180)` and print `mean(altezze)`."},"start":"","html":"","checks":[{"re":"altezze\\\\s*<-\\\\s*c\\\\s*\\\\(\\\\s*170\\\\s*,\\\\s*165\\\\s*,\\\\s*180\\\\s*\\\\)","label":{"it":"Il vettore esiste","en":"The vector exists"}},{"re":"mean\\\\s*\\\\(\\\\s*altezze\\\\s*\\\\)","label":{"it":"Calcoli la media","en":"You compute the mean"}}],"hint":"altezze <- c(170, 165, 180)\\nprint(mean(altezze))"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('r-base','dataframes',2,1,'published','{"it":"Data frame","en":"Data frames"}','[{"t":"p","text":{"it":"Un **data frame** è una tabella: ogni colonna è un vettore, ogni riga un’osservazione. Si leggono le colonne con `$` e si filtrano le righe con le parentesi quadre.","en":"A **data frame** is a table: each column is a vector, each row an observation. You read columns with `$` and filter rows with square brackets."}},{"t":"code","code":"studenti <- data.frame(\\n  nome = c(\\"Ada\\", \\"Bea\\", \\"Cleo\\"),\\n  voto = c(8, 6, 9)\\n)\\nstudenti$voto\\nstudenti[studenti$voto >= 8, ]\\nnrow(studenti)\\ndati <- read.csv(\\"vendite.csv\\")","lang":"r"},{"t":"p","text":{"it":"In `tabella[righe, colonne]` lasciare vuota una parte significa “tutte”. `read.csv` carica un file CSV in un data frame.","en":"In `table[rows, columns]` leaving a part empty means “all”. `read.csv` loads a CSV file into a data frame."}}]','{"lang":"r","prompt":{"it":"Dal data frame `auto` tieni le righe con `prezzo < 20000`.","en":"From the data frame `auto` keep the rows with `prezzo < 20000`."},"start":"","html":"","checks":[{"re":"auto\\\\s*\\\\[\\\\s*auto\\\\$prezzo\\\\s*<\\\\s*20000\\\\s*,\\\\s*\\\\]","label":{"it":"Il filtro è giusto","en":"The filter is right"}}],"hint":"economiche <- auto[auto$prezzo < 20000, ]"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('r-base','functions',3,1,'published','{"it":"Funzioni e controllo","en":"Functions and control"}','[{"t":"p","text":{"it":"Una funzione si crea con `function` e si assegna a un nome. `if`/`else` sceglie, `for` ripete; spesso però in R si evitano i cicli usando le operazioni sui vettori o `sapply`.","en":"A function is made with `function` and assigned to a name. `if`/`else` chooses, `for` repeats; in R you often avoid loops by using vector operations or `sapply`."}},{"t":"code","code":"giudizio <- function(voto) {\\n  if (voto >= 6) \\"promosso\\" else \\"bocciato\\"\\n}\\ngiudizio(7)\\n\\nquadrati <- sapply(1:5, function(x) x^2)\\nfor (n in c(\\"Ada\\", \\"Bea\\")) print(n)","lang":"r"},{"t":"p","text":{"it":"L’ultima espressione di una funzione è il suo risultato: non serve scrivere `return`. `1:5` crea la sequenza da 1 a 5.","en":"A function’s last expression is its result: no need to write `return`. `1:5` creates the sequence from 1 to 5."}}]','{"lang":"r","prompt":{"it":"Scrivi `doppio <- function(x) x * 2`.","en":"Write `doppio <- function(x) x * 2`."},"start":"","html":"","checks":[{"re":"doppio\\\\s*<-\\\\s*function\\\\s*\\\\(\\\\s*x\\\\s*\\\\)\\\\s*\\\\{?\\\\s*x\\\\s*\\\\*\\\\s*2","label":{"it":"La funzione è giusta","en":"The function is right"}}],"hint":"doppio <- function(x) x * 2"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('r-base','stats',4,2,'published','{"it":"Statistiche di base","en":"Basic statistics"}','[{"t":"p","text":{"it":"R nasce per la statistica: `mean`, `median`, `sd` (deviazione standard), `min`, `max`, `quantile` e `summary` riassumono un vettore in un attimo. `table` conta le occorrenze.","en":"R was born for statistics: `mean`, `median`, `sd` (standard deviation), `min`, `max`, `quantile` and `summary` sum up a vector in a moment. `table` counts occurrences."}},{"t":"code","code":"eta <- c(23, 31, 27, 45, 31, 38)\\nmean(eta)\\nmedian(eta)\\nsd(eta)\\nsummary(eta)\\ntable(c(\\"rosso\\", \\"blu\\", \\"rosso\\"))\\nmean(c(5, NA, 7), na.rm = TRUE)","lang":"r"},{"t":"p","text":{"it":"`NA` è un valore mancante: molte funzioni restituiscono `NA` se ne trovano uno, a meno di `na.rm = TRUE`.","en":"`NA` is a missing value: many functions return `NA` if they find one, unless you pass `na.rm = TRUE`."}}]','{"lang":"r","prompt":{"it":"Calcola `median(tempi, na.rm = TRUE)`.","en":"Compute `median(tempi, na.rm = TRUE)`."},"start":"tempi <- c(12, NA, 9, 15)","html":"","checks":[{"re":"median\\\\s*\\\\(\\\\s*tempi\\\\s*,\\\\s*na\\\\.rm\\\\s*=\\\\s*TRUE\\\\s*\\\\)","label":{"it":"La mediana ignora i mancanti","en":"The median ignores missing values"}}],"hint":"median(tempi, na.rm = TRUE)"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('r-base','plots',5,2,'published','{"it":"Primi grafici","en":"First plots"}','[{"t":"p","text":{"it":"Con R base si disegna subito: `plot` per i punti, `hist` per gli istogrammi, `barplot` per le barre, `boxplot` per la distribuzione. Gli argomenti `main`, `xlab`, `col` danno titolo, etichette e colori.","en":"Base R draws right away: `plot` for points, `hist` for histograms, `barplot` for bars, `boxplot` for distribution. The arguments `main`, `xlab`, `col` give title, labels and colours."}},{"t":"code","code":"ore <- c(1, 2, 3, 4, 5)\\nvoti <- c(5, 6, 6.5, 8, 9)\\nplot(ore, voti, main = \\"Studio e voti\\",\\n     xlab = \\"Ore di studio\\", ylab = \\"Voto\\", col = \\"tomato\\", pch = 19)\\n\\nhist(rnorm(200), col = \\"skyblue\\", main = \\"Distribuzione\\")","lang":"r"},{"t":"p","text":{"it":"`rnorm(200)` genera 200 numeri casuali con distribuzione normale: utile per provare.","en":"`rnorm(200)` generates 200 random normally distributed numbers: handy for trying things out."}}]','{"lang":"r","prompt":{"it":"Disegna `hist(pesi, main = \\"Pesi\\", col = \\"orange\\")`.","en":"Draw `hist(pesi, main = \\"Pesi\\", col = \\"orange\\")`."},"start":"pesi <- c(60, 72, 65, 80, 68)","html":"","checks":[{"re":"hist\\\\s*\\\\(\\\\s*pesi\\\\s*,","label":{"it":"È un istogramma dei pesi","en":"It is a histogram of the weights"}},{"re":"main\\\\s*=\\\\s*\\"Pesi\\"","label":{"it":"Ha il titolo","en":"It has the title"}},{"re":"col\\\\s*=\\\\s*\\"orange\\"","label":{"it":"Ha il colore","en":"It has the colour"}}],"hint":"hist(pesi, main = \\"Pesi\\", col = \\"orange\\")"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('r-intermediate','pipe',1,2,'published','{"it":"Pipe e dplyr","en":"Pipes and dplyr"}','[{"t":"p","text":{"it":"Il **pipe** `|>` passa il risultato a sinistra come primo argomento della funzione a destra: le operazioni si leggono dall’alto in basso. **dplyr** offre verbi chiari: `filter`, `select`, `mutate`, `arrange`.","en":"The **pipe** `|>` passes the left result as the first argument of the function on the right: operations read top to bottom. **dplyr** offers clear verbs: `filter`, `select`, `mutate`, `arrange`."}},{"t":"code","code":"library(dplyr)\\n\\nvendite |>\\n  filter(regione == \\"Nord\\") |>\\n  mutate(totale = prezzo * pezzi) |>\\n  select(prodotto, totale) |>\\n  arrange(desc(totale))","lang":"r"},{"t":"p","text":{"it":"Dentro i verbi di dplyr le colonne si scrivono senza `$` né virgolette.","en":"Inside dplyr verbs, columns are written without `$` or quotes."}}]','{"lang":"r","prompt":{"it":"Da `clienti` tieni con `filter(eta >= 30)` e scegli `select(nome, citta)`, usando `|>`.","en":"From `clienti` keep with `filter(eta >= 30)` and pick `select(nome, citta)`, using `|>`."},"start":"","html":"","checks":[{"re":"clienti\\\\s*\\\\|>\\\\s*filter\\\\s*\\\\(\\\\s*eta\\\\s*>=\\\\s*30\\\\s*\\\\)","label":{"it":"Filtri con il pipe","en":"You filter with the pipe"}},{"re":"\\\\|>\\\\s*select\\\\s*\\\\(\\\\s*nome\\\\s*,\\\\s*citta\\\\s*\\\\)","label":{"it":"Scegli le colonne","en":"You pick the columns"}}],"hint":"clienti |>\\n  filter(eta >= 30) |>\\n  select(nome, citta)"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('r-intermediate','summarise',2,2,'published','{"it":"Raggruppare e riassumere","en":"Grouping and summarising"}','[{"t":"p","text":{"it":"`group_by` divide i dati in gruppi; `summarise` calcola un valore per ciascuno. `n()` conta le righe del gruppo.","en":"`group_by` splits data into groups; `summarise` computes one value for each. `n()` counts the group’s rows."}},{"t":"code","code":"vendite |>\\n  group_by(regione) |>\\n  summarise(\\n    ordini = n(),\\n    incasso = sum(totale),\\n    medio = mean(totale)\\n  ) |>\\n  arrange(desc(incasso))","lang":"r"},{"t":"p","text":{"it":"È l’equivalente del `GROUP BY` di SQL, scritto con verbi.","en":"It is the equivalent of SQL’s `GROUP BY`, written with verbs."}}]','{"lang":"r","prompt":{"it":"Raggruppa `voti` per `corso` e calcola `media = mean(voto)`.","en":"Group `voti` by `corso` and compute `media = mean(voto)`."},"start":"voti |>","html":"","checks":[{"re":"group_by\\\\s*\\\\(\\\\s*corso\\\\s*\\\\)","label":{"it":"Raggruppi per corso","en":"You group by course"}},{"re":"summarise\\\\s*\\\\(\\\\s*media\\\\s*=\\\\s*mean\\\\s*\\\\(\\\\s*voto\\\\s*\\\\)\\\\s*\\\\)","label":{"it":"Calcoli la media","en":"You compute the mean"}}],"hint":"voti |>\\n  group_by(corso) |>\\n  summarise(media = mean(voto))"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('r-intermediate','ggplot',3,2,'published','{"it":"Grafici con ggplot2","en":"Plots with ggplot2"}','[{"t":"p","text":{"it":"**ggplot2** costruisce i grafici a strati: i dati, l’**estetica** (`aes`: quale colonna va su x, y, colore) e una **geometria** (`geom_point`, `geom_col`, `geom_line`), unite dal `+`.","en":"**ggplot2** builds plots in layers: the data, the **aesthetics** (`aes`: which column goes to x, y, colour) and a **geometry** (`geom_point`, `geom_col`, `geom_line`), joined with `+`."}},{"t":"code","code":"library(ggplot2)\\n\\nggplot(studenti, aes(x = ore, y = voto, colour = corso)) +\\n  geom_point(size = 3) +\\n  geom_smooth(method = \\"lm\\") +\\n  labs(title = \\"Studio e voti\\", x = \\"Ore\\", y = \\"Voto\\") +\\n  theme_minimal()","lang":"r"},{"t":"p","text":{"it":"Ogni `+` aggiunge un pezzo: punti, una linea di tendenza, titoli, un tema.","en":"Each `+` adds a piece: points, a trend line, titles, a theme."}}]','{"lang":"r","prompt":{"it":"Disegna `ggplot(auto, aes(x = km, y = prezzo)) + geom_point()`.","en":"Draw `ggplot(auto, aes(x = km, y = prezzo)) + geom_point()`."},"start":"library(ggplot2)","html":"","checks":[{"re":"ggplot\\\\s*\\\\(\\\\s*auto\\\\s*,\\\\s*aes\\\\s*\\\\(\\\\s*x\\\\s*=\\\\s*km\\\\s*,\\\\s*y\\\\s*=\\\\s*prezzo\\\\s*\\\\)\\\\s*\\\\)","label":{"it":"Dati ed estetica","en":"Data and aesthetics"}},{"re":"\\\\+\\\\s*geom_point\\\\s*\\\\(\\\\s*\\\\)","label":{"it":"Aggiungi i punti","en":"You add the points"}}],"hint":"ggplot(auto, aes(x = km, y = prezzo)) + geom_point()"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('r-intermediate','tidy',4,3,'published','{"it":"Dati ordinati","en":"Tidy data"}','[{"t":"p","text":{"it":"Nei **dati ordinati** ogni colonna è una variabile e ogni riga un’osservazione. `pivot_longer` trasforma tante colonne (un anno per colonna) in righe; `pivot_wider` fa il contrario. `left_join` unisce due tabelle.","en":"In **tidy data** each column is a variable and each row an observation. `pivot_longer` turns many columns (one year per column) into rows; `pivot_wider` does the opposite. `left_join` joins two tables."}},{"t":"code","code":"library(tidyr)\\n\\nlarghi <- data.frame(paese = c(\\"IT\\", \\"FR\\"), `2024` = c(3, 4), `2025` = c(5, 6), check.names = FALSE)\\n\\nlunghi <- larghi |>\\n  pivot_longer(cols = -paese, names_to = \\"anno\\", values_to = \\"valore\\")\\n\\ncompleti <- lunghi |> left_join(nomi_paesi, by = \\"paese\\")","lang":"r"},{"t":"p","text":{"it":"I dati lunghi sono quelli che ggplot2 e dplyr preferiscono: una riga per ogni misura.","en":"Long data is what ggplot2 and dplyr prefer: one row per measurement."}}]','{"lang":"r","prompt":{"it":"Trasforma `meteo` con `pivot_longer(cols = -citta, names_to = \\"mese\\", values_to = \\"gradi\\")`.","en":"Reshape `meteo` with `pivot_longer(cols = -citta, names_to = \\"mese\\", values_to = \\"gradi\\")`."},"start":"library(tidyr)","html":"","checks":[{"re":"pivot_longer\\\\s*\\\\(","label":{"it":"Usi pivot_longer","en":"You use pivot_longer"}},{"re":"names_to\\\\s*=\\\\s*\\"mese\\"","label":{"it":"I nomi vanno in “mese”","en":"Names go to “mese”"}},{"re":"values_to\\\\s*=\\\\s*\\"gradi\\"","label":{"it":"I valori in “gradi”","en":"Values go to “gradi”"}}],"hint":"meteo |>\\n  pivot_longer(cols = -citta, names_to = \\"mese\\", values_to = \\"gradi\\")"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('r-intermediate','models',5,3,'published','{"it":"Un modello lineare","en":"A linear model"}','[{"t":"p","text":{"it":"`lm(y ~ x, data = …)` cerca la retta che meglio spiega `y` a partire da `x`. `summary` mostra coefficienti, **p-value** e **R²**; `predict` stima nuovi valori.","en":"`lm(y ~ x, data = …)` finds the line that best explains `y` from `x`. `summary` shows coefficients, **p-values** and **R²**; `predict` estimates new values."}},{"t":"code","code":"modello <- lm(voto ~ ore, data = studenti)\\nsummary(modello)\\ncoef(modello)\\n\\nnuovi <- data.frame(ore = c(2, 6))\\npredict(modello, nuovi)","lang":"r"},{"t":"p","text":{"it":"La **tilde** `~` si legge “in funzione di”. R² vicino a 1 indica che il modello spiega bene i dati; ma correlazione non è causalità.","en":"The **tilde** `~` reads “as a function of”. R² close to 1 means the model fits the data well; but correlation is not causation."}}]','{"lang":"r","prompt":{"it":"Crea `modello <- lm(prezzo ~ metri, data = case)` e mostra `summary(modello)`.","en":"Create `modello <- lm(prezzo ~ metri, data = case)` and show `summary(modello)`."},"start":"","html":"","checks":[{"re":"modello\\\\s*<-\\\\s*lm\\\\s*\\\\(\\\\s*prezzo\\\\s*~\\\\s*metri\\\\s*,\\\\s*data\\\\s*=\\\\s*case\\\\s*\\\\)","label":{"it":"Il modello è giusto","en":"The model is right"}},{"re":"summary\\\\s*\\\\(\\\\s*modello\\\\s*\\\\)","label":{"it":"Ne mostri il riassunto","en":"You show its summary"}}],"hint":"modello <- lm(prezzo ~ metri, data = case)\\nsummary(modello)"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('flutter-base','dart',1,1,'published','{"it":"Un assaggio di Dart","en":"A taste of Dart"}','[{"t":"p","text":{"it":"Flutter si scrive in **Dart**. Le variabili si dichiarano con il tipo o con `var`/`final`; `final` non cambia più. Le stringhe accettano valori con `$nome` o `${espressione}`.","en":"Flutter is written in **Dart**. Variables are declared with a type or with `var`/`final`; `final` never changes again. Strings take values with `$nome` or `${expression}`."}},{"t":"code","code":"void main() {\\n  final String nome = \\"Ada\\";\\n  var anni = 36;\\n  int? telefono;            // può essere null\\n  print(\\"Ciao $nome, tra un anno ne avrai ${anni + 1}\\");\\n  final voti = [7, 8, 9];\\n  print(voti.where((v) => v > 7).toList());\\n}","lang":"dart"},{"t":"p","text":{"it":"Dart è **null-safe**: una variabile può contenere `null` solo se il tipo ha il punto di domanda (`int?`).","en":"Dart is **null-safe**: a variable can hold `null` only if its type has a question mark (`int?`)."}}]','{"lang":"dart","prompt":{"it":"Dichiara `final citta = \\"Udine\\";` e stampa `\\"Vivo a $citta\\"`.","en":"Declare `final citta = \\"Udine\\";` and print `\\"Vivo a $citta\\"`."},"start":"void main() {\\n}","html":"","checks":[{"re":"final\\\\s+(String\\\\s+)?citta\\\\s*=\\\\s*\\"Udine\\"\\\\s*;","label":{"it":"La variabile esiste","en":"The variable exists"}},{"re":"print\\\\s*\\\\(\\\\s*\\"Vivo a \\\\$citta\\"\\\\s*\\\\)\\\\s*;","label":{"it":"La stampi","en":"You print it"}}],"hint":"final citta = \\"Udine\\";\\nprint(\\"Vivo a $citta\\");"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('flutter-base','widgets',2,1,'published','{"it":"Tutto è un widget","en":"Everything is a widget"}','[{"t":"p","text":{"it":"In Flutter l’interfaccia è un **albero di widget**: testi, bottoni, colonne, margini. Un `StatelessWidget` non cambia: il suo metodo `build` restituisce i widget da mostrare.","en":"In Flutter the interface is a **tree of widgets**: texts, buttons, columns, margins. A `StatelessWidget` does not change: its `build` method returns the widgets to show."}},{"t":"code","code":"void main() => runApp(const App());\\n\\nclass App extends StatelessWidget {\\n  const App({super.key});\\n\\n  @override\\n  Widget build(BuildContext context) {\\n    return MaterialApp(\\n      home: Scaffold(\\n        appBar: AppBar(title: const Text(\\"Fucina\\")),\\n        body: const Center(child: Text(\\"Ciao!\\")),\\n      ),\\n    );\\n  }\\n}","lang":"dart"},{"t":"p","text":{"it":"`MaterialApp` dà lo stile Material, `Scaffold` la struttura della pagina (barra, corpo, bottone flottante). `const` dice a Flutter che quel widget non cambierà mai.","en":"`MaterialApp` gives the Material style, `Scaffold` the page structure (bar, body, floating button). `const` tells Flutter the widget will never change."}}]','{"lang":"dart","prompt":{"it":"Nel `body` metti `Center(child: Text(\\"Benvenuto\\"))`.","en":"In the `body` put `Center(child: Text(\\"Benvenuto\\"))`."},"start":"Scaffold(\\n  body: ,\\n)","html":"","checks":[{"re":"body\\\\s*:\\\\s*(const\\\\s+)?Center\\\\s*\\\\(\\\\s*child\\\\s*:\\\\s*(const\\\\s+)?Text\\\\s*\\\\(\\\\s*\\"Benvenuto\\"\\\\s*\\\\)\\\\s*\\\\)","label":{"it":"Il testo è centrato","en":"The text is centred"}}],"hint":"Scaffold(\\n  body: Center(child: Text(\\"Benvenuto\\")),\\n)"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('flutter-base','layout',3,1,'published','{"it":"Layout","en":"Layout"}','[{"t":"p","text":{"it":"`Column` mette i figli uno sotto l’altro, `Row` uno accanto all’altro. `Padding` aggiunge spazio, `SizedBox` crea uno spazio fisso, `Expanded` fa occupare lo spazio rimasto.","en":"`Column` stacks children vertically, `Row` side by side. `Padding` adds space, `SizedBox` creates a fixed gap, `Expanded` takes the remaining space."}},{"t":"code","code":"Padding(\\n  padding: const EdgeInsets.all(16),\\n  child: Column(\\n    crossAxisAlignment: CrossAxisAlignment.start,\\n    children: [\\n      const Text(\\"Titolo\\", style: TextStyle(fontSize: 24)),\\n      const SizedBox(height: 8),\\n      Row(children: [\\n        const Icon(Icons.star),\\n        Expanded(child: Text(descrizione)),\\n      ]),\\n    ],\\n  ),\\n)","lang":"dart"},{"t":"p","text":{"it":"Come in Flexbox, c’è un asse principale (`mainAxisAlignment`) e uno trasversale (`crossAxisAlignment`).","en":"As in Flexbox, there is a main axis (`mainAxisAlignment`) and a cross axis (`crossAxisAlignment`)."}}]','{"lang":"dart","prompt":{"it":"Crea una `Row` con `children: [Icon(Icons.home), Text(\\"Casa\\")]`.","en":"Create a `Row` with `children: [Icon(Icons.home), Text(\\"Casa\\")]`."},"start":"","html":"","checks":[{"re":"Row\\\\s*\\\\(\\\\s*children\\\\s*:\\\\s*\\\\[","label":{"it":"È una riga","en":"It is a row"}},{"re":"Icon\\\\s*\\\\(\\\\s*Icons\\\\.home\\\\s*\\\\)","label":{"it":"C’è l’icona","en":"There is the icon"}},{"re":"Text\\\\s*\\\\(\\\\s*\\"Casa\\"\\\\s*\\\\)","label":{"it":"C’è il testo","en":"There is the text"}}],"hint":"Row(children: [Icon(Icons.home), Text(\\"Casa\\")])"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('flutter-base','state',4,2,'published','{"it":"Stato e setState","en":"State and setState"}','[{"t":"p","text":{"it":"Un `StatefulWidget` può cambiare nel tempo. Lo stato vive in una classe `State`; quando cambi un valore lo fai dentro `setState`, così Flutter ridisegna il widget.","en":"A `StatefulWidget` can change over time. Its state lives in a `State` class; when you change a value you do it inside `setState`, so Flutter redraws the widget."}},{"t":"code","code":"class Contatore extends StatefulWidget {\\n  const Contatore({super.key});\\n  @override\\n  State<Contatore> createState() => _ContatoreState();\\n}\\n\\nclass _ContatoreState extends State<Contatore> {\\n  int n = 0;\\n\\n  @override\\n  Widget build(BuildContext context) {\\n    return ElevatedButton(\\n      onPressed: () => setState(() => n++),\\n      child: Text(\\"Clic: $n\\"),\\n    );\\n  }\\n}","lang":"dart"},{"t":"p","text":{"it":"Il trattino basso davanti al nome (`_ContatoreState`) rende la classe privata al file.","en":"The underscore in front of the name (`_ContatoreState`) makes the class private to the file."}}]','{"lang":"dart","prompt":{"it":"Nel bottone chiama `setState(() => acceso = !acceso)`.","en":"In the button call `setState(() => acceso = !acceso)`."},"start":"ElevatedButton(\\n  onPressed: () {},\\n  child: Text(acceso ? \\"Spegni\\" : \\"Accendi\\"),\\n)","html":"","checks":[{"re":"setState\\\\s*\\\\(\\\\s*\\\\(\\\\)\\\\s*(=>|\\\\{)\\\\s*acceso\\\\s*=\\\\s*!\\\\s*acceso","label":{"it":"Cambi lo stato","en":"You change the state"}}],"hint":"onPressed: () => setState(() => acceso = !acceso),"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('flutter-base','navigation',5,2,'published','{"it":"Liste e navigazione","en":"Lists and navigation"}','[{"t":"p","text":{"it":"`ListView.builder` crea solo le righe visibili, anche con migliaia di elementi. `Navigator.push` apre una nuova pagina sopra quella attuale; `Navigator.pop` torna indietro.","en":"`ListView.builder` builds only the visible rows, even with thousands of items. `Navigator.push` opens a new page on top of the current one; `Navigator.pop` goes back."}},{"t":"code","code":"ListView.builder(\\n  itemCount: corsi.length,\\n  itemBuilder: (context, i) => ListTile(\\n    title: Text(corsi[i].titolo),\\n    trailing: const Icon(Icons.chevron_right),\\n    onTap: () => Navigator.push(\\n      context,\\n      MaterialPageRoute(builder: (_) => CorsoPage(corso: corsi[i])),\\n    ),\\n  ),\\n)","lang":"dart"},{"t":"p","text":{"it":"Per app più grandi si usano router con indirizzi, come il pacchetto `go_router`.","en":"Larger apps use routers with addresses, such as the `go_router` package."}}]','{"lang":"dart","prompt":{"it":"Nel `onTap` torna indietro con `Navigator.pop(context)`.","en":"In `onTap` go back with `Navigator.pop(context)`."},"start":"ListTile(\\n  title: Text(\\"Chiudi\\"),\\n  onTap: () {},\\n)","html":"","checks":[{"re":"onTap\\\\s*:\\\\s*\\\\(\\\\)\\\\s*(=>|\\\\{)\\\\s*Navigator\\\\.pop\\\\s*\\\\(\\\\s*context\\\\s*\\\\)","label":{"it":"Torni indietro","en":"You go back"}}],"hint":"onTap: () => Navigator.pop(context),"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('flutter-intermediate','forms',1,2,'published','{"it":"Moduli e validazione","en":"Forms and validation"}','[{"t":"p","text":{"it":"Un `Form` raccoglie più `TextFormField`; ogni campo ha un `validator` che restituisce un messaggio d’errore o `null` se va bene. Una `GlobalKey<FormState>` permette di validare tutto insieme.","en":"A `Form` gathers several `TextFormField`s; each field has a `validator` returning an error message, or `null` when fine. A `GlobalKey<FormState>` lets you validate everything at once."}},{"t":"code","code":"final _chiave = GlobalKey<FormState>();\\n\\nForm(\\n  key: _chiave,\\n  child: Column(children: [\\n    TextFormField(\\n      decoration: const InputDecoration(labelText: \\"Email\\"),\\n      validator: (v) => (v == null || !v.contains(\\"@\\")) ? \\"Email non valida\\" : null,\\n    ),\\n    ElevatedButton(\\n      onPressed: () {\\n        if (_chiave.currentState!.validate()) salva();\\n      },\\n      child: const Text(\\"Invia\\"),\\n    ),\\n  ]),\\n)","lang":"dart"},{"t":"p","text":{"it":"Un `TextEditingController` legge e cambia il testo di un campo da codice.","en":"A `TextEditingController` reads and changes a field’s text from code."}}]','{"lang":"dart","prompt":{"it":"Aggiungi un `validator` che restituisce `\\"Obbligatorio\\"` se `v` è vuoto, altrimenti `null`.","en":"Add a `validator` returning `\\"Obbligatorio\\"` if `v` is empty, otherwise `null`."},"start":"TextFormField(\\n  decoration: const InputDecoration(labelText: \\"Nome\\"),\\n)","html":"","checks":[{"re":"validator\\\\s*:\\\\s*\\\\(\\\\s*v\\\\s*\\\\)\\\\s*=>","label":{"it":"C’è il validator","en":"There is the validator"}},{"re":"\\"Obbligatorio\\"\\\\s*:\\\\s*null","label":{"it":"Messaggio o null","en":"Message or null"}}],"hint":"validator: (v) => (v == null || v.isEmpty) ? \\"Obbligatorio\\" : null,"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('flutter-intermediate','async',2,2,'published','{"it":"Future e dati dalla rete","en":"Futures and network data"}','[{"t":"p","text":{"it":"Le operazioni lente restituiscono un `Future`. Con `async`/`await` si scrivono come codice normale. `FutureBuilder` mostra un widget diverso mentre aspetta, in caso di errore o con i dati.","en":"Slow operations return a `Future`. With `async`/`await` you write them like normal code. `FutureBuilder` shows a different widget while waiting, on error or with data."}},{"t":"code","code":"Future<List<String>> caricaCorsi() async {\\n  final r = await http.get(Uri.parse(\\"https://example.com/api/corsi\\"));\\n  if (r.statusCode != 200) throw Exception(\\"Errore ${r.statusCode}\\");\\n  return List<String>.from(jsonDecode(r.body));\\n}\\n\\nFutureBuilder<List<String>>(\\n  future: caricaCorsi(),\\n  builder: (context, snap) {\\n    if (snap.hasError) return Text(\\"Errore: ${snap.error}\\");\\n    if (!snap.hasData) return const CircularProgressIndicator();\\n    return Text(\\"${snap.data!.length} corsi\\");\\n  },\\n)","lang":"dart"},{"t":"p","text":{"it":"Per i flussi continui (chat, sensori) esiste `Stream` con il suo `StreamBuilder`.","en":"For continuous flows (chat, sensors) there is `Stream` with its `StreamBuilder`."}}]','{"lang":"dart","prompt":{"it":"Scrivi `Future<String> saluto() async` che fa `await Future.delayed(Duration(seconds: 1))` e restituisce `\\"Ciao\\"`.","en":"Write `Future<String> saluto() async` that does `await Future.delayed(Duration(seconds: 1))` and returns `\\"Ciao\\"`."},"start":"","html":"","checks":[{"re":"Future<String>\\\\s+saluto\\\\s*\\\\(\\\\s*\\\\)\\\\s+async","label":{"it":"La funzione è asincrona","en":"The function is async"}},{"re":"await\\\\s+Future\\\\.delayed\\\\s*\\\\(","label":{"it":"Aspetta","en":"It waits"}},{"re":"return\\\\s+\\"Ciao\\"\\\\s*;","label":{"it":"Restituisce “Ciao”","en":"It returns “Ciao”"}}],"hint":"Future<String> saluto() async {\\n  await Future.delayed(const Duration(seconds: 1));\\n  return \\"Ciao\\";\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('flutter-intermediate','state-management',3,2,'published','{"it":"Gestire lo stato","en":"Managing state"}','[{"t":"p","text":{"it":"Quando più schermate condividono dati, `setState` non basta. Una soluzione semplice è un `ChangeNotifier` con il pacchetto **provider**: lo stato vive in una classe che avvisa chi la ascolta con `notifyListeners()`.","en":"When several screens share data, `setState` is not enough. A simple solution is a `ChangeNotifier` with the **provider** package: state lives in a class that tells its listeners with `notifyListeners()`."}},{"t":"code","code":"class Carrello extends ChangeNotifier {\\n  final List<String> _pezzi = [];\\n  int get totale => _pezzi.length;\\n  void aggiungi(String p) {\\n    _pezzi.add(p);\\n    notifyListeners();\\n  }\\n}\\n\\n// in main: ChangeNotifierProvider(create: (_) => Carrello(), child: const App())\\n// in un widget:\\nfinal n = context.watch<Carrello>().totale;\\ncontext.read<Carrello>().aggiungi(\\"Corso\\");","lang":"dart"},{"t":"p","text":{"it":"`watch` ridisegna il widget quando lo stato cambia; `read` lo usa senza ascoltare, per esempio dentro un `onPressed`.","en":"`watch` redraws the widget when state changes; `read` uses it without listening, e.g. inside an `onPressed`."}}]','{"lang":"dart","prompt":{"it":"Nel metodo `aggiungi` chiama `notifyListeners();` dopo aver cambiato la lista.","en":"In the `aggiungi` method call `notifyListeners();` after changing the list."},"start":"void aggiungi(String p) {\\n  _pezzi.add(p);\\n}","html":"","checks":[{"re":"_pezzi\\\\.add\\\\s*\\\\(\\\\s*p\\\\s*\\\\)\\\\s*;\\\\s*notifyListeners\\\\s*\\\\(\\\\s*\\\\)\\\\s*;","label":{"it":"Avvisi dopo il cambio","en":"You notify after the change"}}],"hint":"void aggiungi(String p) {\\n  _pezzi.add(p);\\n  notifyListeners();\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('flutter-intermediate','themes',4,3,'published','{"it":"Temi e adattamento","en":"Themes and adaptation"}','[{"t":"p","text":{"it":"`ThemeData` definisce colori e testi di tutta l’app; `ColorScheme.fromSeed` crea una palette da un solo colore. Con `darkTheme` e `themeMode` l’app segue il tema chiaro o scuro del sistema.","en":"`ThemeData` defines colours and text for the whole app; `ColorScheme.fromSeed` makes a palette from one colour. With `darkTheme` and `themeMode` the app follows the system’s light or dark theme."}},{"t":"code","code":"MaterialApp(\\n  theme: ThemeData(colorScheme: ColorScheme.fromSeed(seedColor: Colors.deepOrange)),\\n  darkTheme: ThemeData(\\n    colorScheme: ColorScheme.fromSeed(seedColor: Colors.deepOrange, brightness: Brightness.dark),\\n  ),\\n  themeMode: ThemeMode.system,\\n  home: const Home(),\\n)\\n\\nfinal largo = MediaQuery.sizeOf(context).width > 700;","lang":"dart"},{"t":"p","text":{"it":"`MediaQuery` dice quanto è grande lo schermo: utile per mostrare una colonna sul telefono e due sul tablet.","en":"`MediaQuery` tells how big the screen is: handy for showing one column on a phone and two on a tablet."}}]','{"lang":"dart","prompt":{"it":"Imposta `themeMode: ThemeMode.system` nella `MaterialApp`.","en":"Set `themeMode: ThemeMode.system` in the `MaterialApp`."},"start":"MaterialApp(\\n  theme: ThemeData.light(),\\n  darkTheme: ThemeData.dark(),\\n  home: const Home(),\\n)","html":"","checks":[{"re":"themeMode\\\\s*:\\\\s*ThemeMode\\\\.system","label":{"it":"Segue il tema del sistema","en":"It follows the system theme"}}],"hint":"themeMode: ThemeMode.system,"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('flutter-intermediate','storage',5,3,'published','{"it":"Salvare sul dispositivo","en":"Saving on the device"}','[{"t":"p","text":{"it":"Per piccole preferenze c’è `shared_preferences`: chiave e valore, come il localStorage del web. Per dati strutturati si usa un database locale come **SQLite** (pacchetto `sqflite`).","en":"For small preferences there is `shared_preferences`: key and value, like the web’s localStorage. For structured data use a local database such as **SQLite** (the `sqflite` package)."}},{"t":"code","code":"final prefs = await SharedPreferences.getInstance();\\nawait prefs.setBool(\\"tema_scuro\\", true);\\nfinal scuro = prefs.getBool(\\"tema_scuro\\") ?? false;\\n\\nfinal db = await openDatabase(\\"note.db\\", version: 1,\\n  onCreate: (db, v) => db.execute(\\"CREATE TABLE note (id INTEGER PRIMARY KEY, testo TEXT)\\"));\\nawait db.insert(\\"note\\", {\\"testo\\": \\"Comprare il pane\\"});","lang":"dart"},{"t":"p","text":{"it":"Non salvare mai password o token in chiaro: per i segreti esiste `flutter_secure_storage`, che usa il portachiavi del sistema.","en":"Never store passwords or tokens in clear text: for secrets there is `flutter_secure_storage`, which uses the system keychain."}}]','{"lang":"dart","prompt":{"it":"Salva `await prefs.setString(\\"lingua\\", \\"it\\");`.","en":"Save `await prefs.setString(\\"lingua\\", \\"it\\");`."},"start":"final prefs = await SharedPreferences.getInstance();","html":"","checks":[{"re":"await\\\\s+prefs\\\\.setString\\\\s*\\\\(\\\\s*\\"lingua\\"\\\\s*,\\\\s*\\"it\\"\\\\s*\\\\)\\\\s*;","label":{"it":"Salvi la lingua","en":"You save the language"}}],"hint":"await prefs.setString(\\"lingua\\", \\"it\\");"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('swift-base','values',1,1,'published','{"it":"Costanti e variabili","en":"Constants and variables"}','[{"t":"p","text":{"it":"In Swift `let` crea una **costante** (non cambia), `var` una **variabile**. Il tipo si deduce dal valore, ma si può scrivere: `let nome: String = \\"Ada\\"`. I valori entrano nel testo con `\\\\(valore)`.","en":"In Swift `let` creates a **constant** (it does not change), `var` a **variable**. The type is inferred from the value, but you can write it: `let nome: String = \\"Ada\\"`. Values enter text with `\\\\(value)`."}},{"t":"code","code":"let nome = \\"Ada\\"\\nvar anni = 36\\nanni += 1\\nlet altezza: Double = 1.68\\nprint(\\"\\\\(nome) ha \\\\(anni) anni\\")","lang":"swift"},{"t":"p","text":{"it":"Preferisci `let`: il compilatore ti avvisa se una `var` non viene mai cambiata.","en":"Prefer `let`: the compiler warns you if a `var` is never changed."}}]','{"lang":"swift","prompt":{"it":"Crea `let corso = \\"Swift\\"` e `var livello = 1`.","en":"Create `let corso = \\"Swift\\"` and `var livello = 1`."},"start":"","html":"","checks":[{"re":"let\\\\s+corso\\\\s*(:\\\\s*String\\\\s*)?=\\\\s*\\"Swift\\"","label":{"it":"La costante esiste","en":"The constant exists"}},{"re":"var\\\\s+livello\\\\s*(:\\\\s*Int\\\\s*)?=\\\\s*1","label":{"it":"La variabile esiste","en":"The variable exists"}}],"hint":"let corso = \\"Swift\\"\\nvar livello = 1"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('swift-base','optionals',2,1,'published','{"it":"Optional","en":"Optionals"}','[{"t":"p","text":{"it":"Un **optional** (`String?`) può contenere un valore oppure `nil`. Prima di usarlo va “scartato”: `if let` o `guard let` lo aprono in sicurezza, `??` dà un valore di riserva.","en":"An **optional** (`String?`) can hold a value or `nil`. Before using it you “unwrap” it: `if let` or `guard let` open it safely, `??` gives a fallback."}},{"t":"code","code":"var soprannome: String? = nil\\n\\nif let s = soprannome {\\n    print(\\"Ciao \\\\(s)\\")\\n} else {\\n    print(\\"Nessun soprannome\\")\\n}\\n\\nlet mostrato = soprannome ?? \\"Ospite\\"\\n\\nfunc saluta(_ nome: String?) {\\n    guard let nome else { return }\\n    print(\\"Ciao \\\\(nome)\\")\\n}","lang":"swift"},{"t":"p","text":{"it":"Il punto esclamativo (`soprannome!`) forza l’apertura e fa crashare l’app se il valore è `nil`: usalo solo se sei certo.","en":"The exclamation mark (`soprannome!`) forces unwrapping and crashes the app if the value is `nil`: use it only when certain."}}]','{"lang":"swift","prompt":{"it":"Scarta `email` con `if let e = email { print(e) }`.","en":"Unwrap `email` with `if let e = email { print(e) }`."},"start":"let email: String? = cercaEmail()","html":"","checks":[{"re":"if\\\\s+let\\\\s+e\\\\s*=\\\\s*email\\\\s*\\\\{","label":{"it":"Lo scarti in sicurezza","en":"You unwrap it safely"}},{"re":"print\\\\s*\\\\(\\\\s*e\\\\s*\\\\)","label":{"it":"Lo usi","en":"You use it"}}],"hint":"if let e = email {\\n    print(e)\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('swift-base','control',3,1,'published','{"it":"Condizioni e cicli","en":"Conditions and loops"}','[{"t":"p","text":{"it":"`if` non vuole parentesi intorno alla condizione ma sempre le graffe. `switch` deve coprire tutti i casi e non “cade” nel successivo. `for-in` scorre intervalli e collezioni.","en":"`if` needs no brackets around the condition but always braces. `switch` must cover every case and does not “fall through”. `for-in` walks ranges and collections."}},{"t":"code","code":"for i in 1...3 {\\n    print(\\"Giro \\\\(i)\\")\\n}\\n\\nswitch voto {\\ncase 9...10: print(\\"Ottimo\\")\\ncase 6..<9: print(\\"Promosso\\")\\ndefault: print(\\"Da ripassare\\")\\n}","lang":"swift"},{"t":"p","text":{"it":"`1...3` include il 3, `1..<3` no. `while` ripete finché la condizione è vera.","en":"`1...3` includes 3, `1..<3` does not. `while` repeats while the condition is true."}}]','{"lang":"swift","prompt":{"it":"Con `for n in 1...5` stampa ogni `n`.","en":"With `for n in 1...5` print each `n`."},"start":"","html":"","checks":[{"re":"for\\\\s+n\\\\s+in\\\\s+1\\\\s*\\\\.\\\\.\\\\.\\\\s*5\\\\s*\\\\{","label":{"it":"Il ciclo è giusto","en":"The loop is right"}},{"re":"print\\\\s*\\\\(\\\\s*n\\\\s*\\\\)","label":{"it":"Stampi n","en":"You print n"}}],"hint":"for n in 1...5 {\\n    print(n)\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('swift-base','collections',4,2,'published','{"it":"Array e dizionari","en":"Arrays and dictionaries"}','[{"t":"p","text":{"it":"Un **array** `[Int]` tiene valori in ordine; un **dizionario** `[String: Int]` associa chiavi e valori; un **Set** non ha doppioni. Con `let` sono immutabili, con `var` si possono cambiare.","en":"An **array** `[Int]` holds values in order; a **dictionary** `[String: Int]` maps keys to values; a **Set** has no duplicates. With `let` they are immutable, with `var` they can change."}},{"t":"code","code":"var voti = [7, 8]\\nvoti.append(9)\\nprint(voti.count, voti.first ?? 0)\\n\\nvar eta: [String: Int] = [\\"Ada\\": 36]\\neta[\\"Bea\\"] = 28\\nfor (nome, anni) in eta {\\n    print(nome, anni)\\n}\\n\\nlet alti = voti.filter { $0 > 7 }","lang":"swift"},{"t":"p","text":{"it":"Leggere un dizionario dà un optional: la chiave potrebbe mancare. `$0` è il primo argomento in una closure breve.","en":"Reading a dictionary gives an optional: the key might be missing. `$0` is the first argument in a short closure."}}]','{"lang":"swift","prompt":{"it":"Crea `var colori = [\\"rosso\\"]` e aggiungi `\\"blu\\"` con `append`.","en":"Create `var colori = [\\"rosso\\"]` and add `\\"blu\\"` with `append`."},"start":"","html":"","checks":[{"re":"var\\\\s+colori\\\\s*(:\\\\s*\\\\[String\\\\]\\\\s*)?=\\\\s*\\\\[\\\\s*\\"rosso\\"\\\\s*\\\\]","label":{"it":"L’array esiste","en":"The array exists"}},{"re":"colori\\\\.append\\\\s*\\\\(\\\\s*\\"blu\\"\\\\s*\\\\)","label":{"it":"Aggiungi il blu","en":"You add blue"}}],"hint":"var colori = [\\"rosso\\"]\\ncolori.append(\\"blu\\")"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('swift-base','functions',5,2,'published','{"it":"Funzioni e closure","en":"Functions and closures"}','[{"t":"p","text":{"it":"`func` crea una funzione. Ogni parametro ha un’**etichetta** usata nella chiamata; `_` la toglie. Il tipo di ritorno segue la freccia `->`.","en":"`func` creates a function. Each parameter has a **label** used at the call; `_` removes it. The return type follows the arrow `->`."}},{"t":"code","code":"func area(base: Double, altezza: Double) -> Double {\\n    base * altezza\\n}\\narea(base: 3, altezza: 2)\\n\\nfunc saluta(_ nome: String, da mittente: String = \\"Fucina\\") -> String {\\n    \\"Ciao \\\\(nome), da \\\\(mittente)\\"\\n}\\nsaluta(\\"Ada\\")\\n\\nlet raddoppia = { (n: Int) in n * 2 }","lang":"swift"},{"t":"p","text":{"it":"Se il corpo è una sola espressione, `return` si può omettere. Una **closure** è una funzione senza nome tra graffe.","en":"If the body is a single expression, `return` can be omitted. A **closure** is a nameless function between braces."}}]','{"lang":"swift","prompt":{"it":"Scrivi `func doppio(_ n: Int) -> Int` che restituisce `n * 2`.","en":"Write `func doppio(_ n: Int) -> Int` that returns `n * 2`."},"start":"","html":"","checks":[{"re":"func\\\\s+doppio\\\\s*\\\\(\\\\s*_\\\\s+n\\\\s*:\\\\s*Int\\\\s*\\\\)\\\\s*->\\\\s*Int","label":{"it":"La firma è giusta","en":"The signature is right"}},{"re":"(return\\\\s+)?n\\\\s*\\\\*\\\\s*2","label":{"it":"Restituisce il doppio","en":"It returns the double"}}],"hint":"func doppio(_ n: Int) -> Int {\\n    n * 2\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('swift-intermediate','structs',1,2,'published','{"it":"Struct e classi","en":"Structs and classes"}','[{"t":"p","text":{"it":"Una **struct** è un tipo per **valore**: copiandola ottieni un oggetto indipendente. Una **class** è un tipo per **riferimento**: due variabili possono puntare allo stesso oggetto. In Swift si preferiscono le struct.","en":"A **struct** is a **value** type: copying it gives an independent object. A **class** is a **reference** type: two variables can point to the same object. In Swift structs are preferred."}},{"t":"code","code":"struct Punto {\\n    var x: Double\\n    var y: Double\\n    func distanza() -> Double { (x * x + y * y).squareRoot() }\\n    mutating func sposta(dx: Double) { x += dx }\\n}\\n\\nvar a = Punto(x: 3, y: 4)\\nvar b = a\\nb.sposta(dx: 1)   // a non cambia\\n\\nfinal class Sessione {\\n    var utente: String\\n    init(utente: String) { self.utente = utente }\\n}","lang":"swift"},{"t":"p","text":{"it":"Una struct riceve gratis un costruttore con tutti i campi. Un metodo che la modifica va segnato `mutating`.","en":"A struct gets a memberwise initializer for free. A method that changes it must be marked `mutating`."}}]','{"lang":"swift","prompt":{"it":"Crea `struct Libro` con `let titolo: String` e `var pagine: Int`.","en":"Create `struct Libro` with `let titolo: String` and `var pagine: Int`."},"start":"","html":"","checks":[{"re":"struct\\\\s+Libro\\\\s*\\\\{","label":{"it":"La struct esiste","en":"The struct exists"}},{"re":"let\\\\s+titolo\\\\s*:\\\\s*String","label":{"it":"Il titolo è costante","en":"The title is constant"}},{"re":"var\\\\s+pagine\\\\s*:\\\\s*Int","label":{"it":"Le pagine possono cambiare","en":"Pages can change"}}],"hint":"struct Libro {\\n    let titolo: String\\n    var pagine: Int\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('swift-intermediate','protocols',2,2,'published','{"it":"Protocolli ed estensioni","en":"Protocols and extensions"}','[{"t":"p","text":{"it":"Un **protocollo** elenca ciò che un tipo deve offrire; struct, classi ed enum possono adottarlo. Un’**estensione** aggiunge metodi a un tipo esistente, anche a quelli di sistema.","en":"A **protocol** lists what a type must offer; structs, classes and enums can adopt it. An **extension** adds methods to an existing type, even system ones."}},{"t":"code","code":"protocol Descrivibile {\\n    var descrizione: String { get }\\n}\\n\\nstruct Corso: Descrivibile, Identifiable {\\n    let id = UUID()\\n    let titolo: String\\n    var descrizione: String { \\"Corso di \\\\(titolo)\\" }\\n}\\n\\nextension Int {\\n    var alQuadrato: Int { self * self }\\n}\\nprint(5.alQuadrato)","lang":"swift"},{"t":"p","text":{"it":"`Identifiable`, `Equatable`, `Codable` sono protocolli di sistema molto usati: il terzo trasforma i dati in JSON e ritorno.","en":"`Identifiable`, `Equatable`, `Codable` are widely used system protocols: the third turns data into JSON and back."}}]','{"lang":"swift","prompt":{"it":"Crea `protocol Volante { func vola() }` e `struct Uccello: Volante` che lo implementa.","en":"Create `protocol Volante { func vola() }` and `struct Uccello: Volante` implementing it."},"start":"","html":"","checks":[{"re":"protocol\\\\s+Volante\\\\s*\\\\{\\\\s*func\\\\s+vola\\\\s*\\\\(\\\\s*\\\\)","label":{"it":"Il protocollo esiste","en":"The protocol exists"}},{"re":"struct\\\\s+Uccello\\\\s*:\\\\s*Volante","label":{"it":"Uccello lo adotta","en":"Uccello adopts it"}},{"re":"func\\\\s+vola\\\\s*\\\\(\\\\s*\\\\)\\\\s*\\\\{","label":{"it":"Implementa il metodo","en":"It implements the method"}}],"hint":"protocol Volante { func vola() }\\n\\nstruct Uccello: Volante {\\n    func vola() { print(\\"Volo!\\") }\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('swift-intermediate','enums',3,2,'published','{"it":"Enum e errori","en":"Enums and errors"}','[{"t":"p","text":{"it":"Gli **enum** di Swift possono avere **valori associati**: ogni caso porta dati suoi. Gli errori sono tipi che adottano `Error`; una funzione che può fallire è `throws` e si chiama con `try` dentro `do`/`catch`.","en":"Swift **enums** can have **associated values**: each case carries its own data. Errors are types adopting `Error`; a function that may fail is `throws` and is called with `try` inside `do`/`catch`."}},{"t":"code","code":"enum Stato {\\n    case caricamento\\n    case pronto(dati: [String])\\n    case errore(String)\\n}\\n\\nenum ErroreLogin: Error { case passwordErrata, contoBloccato }\\n\\nfunc entra(_ pw: String) throws -> String {\\n    guard pw == \\"segreta\\" else { throw ErroreLogin.passwordErrata }\\n    return \\"Benvenuto\\"\\n}\\n\\ndo {\\n    print(try entra(\\"1234\\"))\\n} catch ErroreLogin.passwordErrata {\\n    print(\\"Password errata\\")\\n}","lang":"swift"},{"t":"p","text":{"it":"`try?` trasforma l’errore in `nil`: comodo quando non serve sapere perché è fallito.","en":"`try?` turns the error into `nil`: handy when you do not need to know why it failed."}}]','{"lang":"swift","prompt":{"it":"Crea `enum Meteo { case sole, pioggia(mm: Int) }`.","en":"Create `enum Meteo { case sole, pioggia(mm: Int) }`."},"start":"","html":"","checks":[{"re":"enum\\\\s+Meteo\\\\s*\\\\{","label":{"it":"L’enum esiste","en":"The enum exists"}},{"re":"case\\\\s+sole","label":{"it":"C’è il sole","en":"There is sun"}},{"re":"pioggia\\\\s*\\\\(\\\\s*mm\\\\s*:\\\\s*Int\\\\s*\\\\)","label":{"it":"La pioggia ha i millimetri","en":"Rain carries millimetres"}}],"hint":"enum Meteo {\\n    case sole, pioggia(mm: Int)\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('swift-intermediate','concurrency',4,3,'published','{"it":"async e await","en":"async and await"}','[{"t":"p","text":{"it":"Una funzione `async` può sospendersi mentre aspetta (la rete, il disco) senza bloccare l’app. Si chiama con `await`. `async let` avvia più attese insieme.","en":"An `async` function can suspend while waiting (network, disk) without blocking the app. You call it with `await`. `async let` starts several waits together."}},{"t":"code","code":"struct Corso: Codable { let titolo: String }\\n\\nfunc caricaCorsi() async throws -> [Corso] {\\n    let url = URL(string: \\"https://example.com/api/corsi\\")!\\n    let (dati, _) = try await URLSession.shared.data(from: url)\\n    return try JSONDecoder().decode([Corso].self, from: dati)\\n}\\n\\nasync let corsi = caricaCorsi()\\nasync let profilo = caricaProfilo()\\nlet (c, p) = try await (corsi, profilo)","lang":"swift"},{"t":"p","text":{"it":"L’interfaccia va aggiornata dal **main actor**: in SwiftUI succede da solo, altrove si usa `@MainActor`.","en":"The interface must be updated from the **main actor**: in SwiftUI this happens by itself, elsewhere you use `@MainActor`."}}]','{"lang":"swift","prompt":{"it":"Scrivi `func saluto() async -> String` che fa `try? await Task.sleep(for: .seconds(1))` e restituisce `\\"Ciao\\"`.","en":"Write `func saluto() async -> String` that does `try? await Task.sleep(for: .seconds(1))` and returns `\\"Ciao\\"`."},"start":"","html":"","checks":[{"re":"func\\\\s+saluto\\\\s*\\\\(\\\\s*\\\\)\\\\s+async\\\\s*->\\\\s*String","label":{"it":"La funzione è asincrona","en":"The function is async"}},{"re":"await\\\\s+Task\\\\.sleep","label":{"it":"Aspetta","en":"It waits"}},{"re":"return\\\\s+\\"Ciao\\"","label":{"it":"Restituisce “Ciao”","en":"It returns “Ciao”"}}],"hint":"func saluto() async -> String {\\n    try? await Task.sleep(for: .seconds(1))\\n    return \\"Ciao\\"\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('swift-intermediate','swiftui',5,3,'published','{"it":"SwiftUI","en":"SwiftUI"}','[{"t":"p","text":{"it":"**SwiftUI** descrive l’interfaccia come una struct che adotta `View`. `@State` tiene un valore che, quando cambia, ridisegna la vista. Gli stack (`VStack`, `HStack`) dispongono gli elementi.","en":"**SwiftUI** describes the interface as a struct adopting `View`. `@State` holds a value that redraws the view when it changes. Stacks (`VStack`, `HStack`) lay out the elements."}},{"t":"code","code":"struct ContatoreView: View {\\n    @State private var n = 0\\n\\n    var body: some View {\\n        VStack(spacing: 12) {\\n            Text(\\"Clic: \\\\(n)\\")\\n                .font(.title)\\n            Button(\\"Più uno\\") { n += 1 }\\n                .buttonStyle(.borderedProminent)\\n        }\\n        .padding()\\n    }\\n}","lang":"swift"},{"t":"p","text":{"it":"I **modificatori** (`.font`, `.padding`) si concatenano e restituiscono una vista nuova. `List` e `NavigationStack` creano elenchi e navigazione.","en":"**Modifiers** (`.font`, `.padding`) chain and return a new view. `List` and `NavigationStack` create lists and navigation."}}]','{"lang":"swift","prompt":{"it":"Nella vista dichiara `@State private var acceso = false` e un `Toggle(\\"Luce\\", isOn: $acceso)`.","en":"In the view declare `@State private var acceso = false` and a `Toggle(\\"Luce\\", isOn: $acceso)`."},"start":"struct LuceView: View {\\n    var body: some View {\\n    }\\n}","html":"","checks":[{"re":"@State\\\\s+(private\\\\s+)?var\\\\s+acceso\\\\s*=\\\\s*false","label":{"it":"C’è lo stato","en":"There is the state"}},{"re":"Toggle\\\\s*\\\\(\\\\s*\\"Luce\\"\\\\s*,\\\\s*isOn\\\\s*:\\\\s*\\\\$acceso\\\\s*\\\\)","label":{"it":"Il toggle è collegato","en":"The toggle is bound"}}],"hint":"@State private var acceso = false\\n\\nvar body: some View {\\n    Toggle(\\"Luce\\", isOn: $acceso)\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('kotlin-base','values',1,1,'published','{"it":"val e var","en":"val and var"}','[{"t":"p","text":{"it":"`val` crea un valore che non cambia, `var` una variabile. Il tipo si deduce o si scrive dopo i due punti. I **template** inseriscono valori nel testo con `$nome` o `${espressione}`.","en":"`val` creates a value that does not change, `var` a variable. The type is inferred or written after a colon. **Templates** put values in text with `$nome` or `${expression}`."}},{"t":"code","code":"fun main() {\\n    val nome = \\"Ada\\"\\n    var anni: Int = 36\\n    anni++\\n    println(\\"Ciao $nome, hai ${anni} anni\\")\\n}","lang":"kotlin"},{"t":"p","text":{"it":"Niente punti e virgola a fine riga. Il programma parte da `fun main()`.","en":"No semicolons at the end of lines. The program starts from `fun main()`."}}]','{"lang":"kotlin","prompt":{"it":"Dichiara `val corso = \\"Kotlin\\"` e stampa `\\"Studio $corso\\"`.","en":"Declare `val corso = \\"Kotlin\\"` and print `\\"Studio $corso\\"`."},"start":"fun main() {\\n}","html":"","checks":[{"re":"val\\\\s+corso\\\\s*(:\\\\s*String\\\\s*)?=\\\\s*\\"Kotlin\\"","label":{"it":"Il valore esiste","en":"The value exists"}},{"re":"println\\\\s*\\\\(\\\\s*\\"Studio \\\\$corso\\"\\\\s*\\\\)","label":{"it":"Lo stampi","en":"You print it"}}],"hint":"val corso = \\"Kotlin\\"\\nprintln(\\"Studio $corso\\")"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('kotlin-base','nulls',2,1,'published','{"it":"Sicurezza sui null","en":"Null safety"}','[{"t":"p","text":{"it":"Un tipo con il punto di domanda (`String?`) può essere `null`. Per usarlo ci sono la **chiamata sicura** `?.`, l’**operatore Elvis** `?:` per un valore di riserva, e i controlli con `if`.","en":"A type with a question mark (`String?`) can be `null`. To use it there is the **safe call** `?.`, the **Elvis operator** `?:` for a fallback, and checks with `if`."}},{"t":"code","code":"var soprannome: String? = null\\n\\nval lunghezza = soprannome?.length        // null\\nval mostrato = soprannome ?: \\"Ospite\\"     // \\"Ospite\\"\\n\\nif (soprannome != null) {\\n    println(soprannome.uppercase())       // qui è sicuro\\n}","lang":"kotlin"},{"t":"p","text":{"it":"`!!` forza il valore e lancia un’eccezione se è `null`: va evitato.","en":"`!!` forces the value and throws if it is `null`: avoid it."}}]','{"lang":"kotlin","prompt":{"it":"Crea `val nome = input ?: \\"Anonimo\\"`.","en":"Create `val nome = input ?: \\"Anonimo\\"`."},"start":"val input: String? = readlnOrNull()","html":"","checks":[{"re":"val\\\\s+nome\\\\s*=\\\\s*input\\\\s*\\\\?:\\\\s*\\"Anonimo\\"","label":{"it":"Usi Elvis","en":"You use Elvis"}}],"hint":"val nome = input ?: \\"Anonimo\\""}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('kotlin-base','control',3,1,'published','{"it":"if e when","en":"if and when"}','[{"t":"p","text":{"it":"In Kotlin `if` è un’**espressione**: restituisce un valore. `when` sostituisce lo `switch` ed è molto più flessibile: accetta valori, intervalli e condizioni.","en":"In Kotlin `if` is an **expression**: it returns a value. `when` replaces `switch` and is far more flexible: it accepts values, ranges and conditions."}},{"t":"code","code":"val voto = 8\\nval esito = if (voto >= 6) \\"promosso\\" else \\"bocciato\\"\\n\\nval giudizio = when (voto) {\\n    10, 9 -> \\"Ottimo\\"\\n    in 6..8 -> \\"Buono\\"\\n    else -> \\"Da ripassare\\"\\n}\\n\\nfor (i in 1..3) println(i)\\nfor (i in 10 downTo 0 step 5) println(i)","lang":"kotlin"},{"t":"p","text":{"it":"`1..3` include il 3; `until` lo esclude; `downTo` e `step` contano all’indietro o a salti.","en":"`1..3` includes 3; `until` excludes it; `downTo` and `step` count backwards or in jumps."}}]','{"lang":"kotlin","prompt":{"it":"Scrivi `val taglia = when { altezza < 160 -> \\"S\\"; altezza < 180 -> \\"M\\"; else -> \\"L\\" }` su più righe.","en":"Write `val taglia = when { altezza < 160 -> \\"S\\"; altezza < 180 -> \\"M\\"; else -> \\"L\\" }` on several lines."},"start":"val altezza = 172","html":"","checks":[{"re":"val\\\\s+taglia\\\\s*=\\\\s*when\\\\s*\\\\{","label":{"it":"Usi when","en":"You use when"}},{"re":"altezza\\\\s*<\\\\s*160\\\\s*->\\\\s*\\"S\\"","label":{"it":"Primo caso","en":"First case"}},{"re":"else\\\\s*->\\\\s*\\"L\\"","label":{"it":"Caso finale","en":"Last case"}}],"hint":"val taglia = when {\\n    altezza < 160 -> \\"S\\"\\n    altezza < 180 -> \\"M\\"\\n    else -> \\"L\\"\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('kotlin-base','collections',4,2,'published','{"it":"Collezioni","en":"Collections"}','[{"t":"p","text":{"it":"`listOf` crea una lista che non si modifica, `mutableListOf` una che si modifica. Lo stesso per `mapOf`/`mutableMapOf` e `setOf`. Le funzioni `filter`, `map`, `sumOf` lavorano con le **lambda** e `it`.","en":"`listOf` makes a list that cannot change, `mutableListOf` one that can. The same goes for `mapOf`/`mutableMapOf` and `setOf`. `filter`, `map`, `sumOf` work with **lambdas** and `it`."}},{"t":"code","code":"val voti = listOf(6, 8, 9, 5)\\nval promossi = voti.filter { it >= 6 }\\nval doppi = voti.map { it * 2 }\\n\\nval carrello = mutableListOf(\\"libro\\")\\ncarrello.add(\\"penna\\")\\n\\nval eta = mapOf(\\"Ada\\" to 36, \\"Bea\\" to 28)\\nprintln(eta[\\"Ada\\"])","lang":"kotlin"},{"t":"p","text":{"it":"`it` è il nome automatico dell’unico parametro di una lambda. `to` crea una coppia chiave-valore.","en":"`it` is the automatic name of a lambda’s single parameter. `to` creates a key-value pair."}}]','{"lang":"kotlin","prompt":{"it":"Da `prezzi` ottieni `val scontati = prezzi.map { it * 0.9 }`.","en":"From `prezzi` get `val scontati = prezzi.map { it * 0.9 }`."},"start":"val prezzi = listOf(10.0, 20.0)","html":"","checks":[{"re":"val\\\\s+scontati\\\\s*=\\\\s*prezzi\\\\.map\\\\s*\\\\{\\\\s*it\\\\s*\\\\*\\\\s*0\\\\.9\\\\s*\\\\}","label":{"it":"La trasformazione è giusta","en":"The transformation is right"}}],"hint":"val scontati = prezzi.map { it * 0.9 }"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('kotlin-base','functions',5,2,'published','{"it":"Funzioni","en":"Functions"}','[{"t":"p","text":{"it":"`fun` crea una funzione; i parametri hanno tipo, possono avere valori predefiniti e si possono passare per nome. Una funzione di una sola espressione si scrive con `=`.","en":"`fun` creates a function; parameters are typed, can have default values and can be passed by name. A single-expression function is written with `=`."}},{"t":"code","code":"fun area(base: Double, altezza: Double = 1.0): Double = base * altezza\\n\\nfun saluta(nome: String, punto: String = \\"!\\") {\\n    println(\\"Ciao $nome$punto\\")\\n}\\n\\narea(3.0, 2.0)\\narea(altezza = 4.0, base = 2.0)\\nsaluta(\\"Ada\\")\\n\\nfun String.urla() = uppercase() + \\"!\\"\\nprintln(\\"ciao\\".urla())","lang":"kotlin"},{"t":"p","text":{"it":"Le **funzioni di estensione** aggiungono metodi a tipi esistenti, come `String.urla()`.","en":"**Extension functions** add methods to existing types, like `String.urla()`."}}]','{"lang":"kotlin","prompt":{"it":"Scrivi `fun doppio(n: Int): Int = n * 2`.","en":"Write `fun doppio(n: Int): Int = n * 2`."},"start":"","html":"","checks":[{"re":"fun\\\\s+doppio\\\\s*\\\\(\\\\s*n\\\\s*:\\\\s*Int\\\\s*\\\\)\\\\s*(:\\\\s*Int\\\\s*)?(=\\\\s*n\\\\s*\\\\*\\\\s*2|\\\\{\\\\s*return\\\\s+n\\\\s*\\\\*\\\\s*2)","label":{"it":"La funzione è giusta","en":"The function is right"}}],"hint":"fun doppio(n: Int): Int = n * 2"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('kotlin-intermediate','classes',1,2,'published','{"it":"Classi e data class","en":"Classes and data classes"}','[{"t":"p","text":{"it":"Il costruttore principale sta nella riga della classe: `class Conto(val titolare: String)`. Una **data class** è fatta per contenere dati: Kotlin genera `equals`, `toString` e `copy`.","en":"The primary constructor sits on the class line: `class Conto(val titolare: String)`. A **data class** is made to hold data: Kotlin generates `equals`, `toString` and `copy`."}},{"t":"code","code":"class Conto(val titolare: String, saldoIniziale: Double = 0.0) {\\n    var saldo = saldoIniziale\\n        private set\\n    fun versa(importo: Double) { require(importo > 0); saldo += importo }\\n}\\n\\ndata class Utente(val nome: String, val eta: Int)\\n\\nval a = Utente(\\"Ada\\", 36)\\nval b = a.copy(eta = 37)\\nprintln(a == Utente(\\"Ada\\", 36))   // true","lang":"kotlin"},{"t":"p","text":{"it":"`private set` permette di leggere `saldo` da fuori ma di cambiarlo solo dentro la classe. Le classi sono `final` per impostazione: per estenderle servono `open`.","en":"`private set` lets outsiders read `saldo` but change it only inside the class. Classes are `final` by default: to extend them you need `open`."}}]','{"lang":"kotlin","prompt":{"it":"Crea `data class Prodotto(val nome: String, val prezzo: Double)`.","en":"Create `data class Prodotto(val nome: String, val prezzo: Double)`."},"start":"","html":"","checks":[{"re":"data\\\\s+class\\\\s+Prodotto\\\\s*\\\\(\\\\s*val\\\\s+nome\\\\s*:\\\\s*String\\\\s*,\\\\s*val\\\\s+prezzo\\\\s*:\\\\s*Double\\\\s*\\\\)","label":{"it":"La data class è giusta","en":"The data class is right"}}],"hint":"data class Prodotto(val nome: String, val prezzo: Double)"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('kotlin-intermediate','sealed',2,2,'published','{"it":"Interfacce e sealed class","en":"Interfaces and sealed classes"}','[{"t":"p","text":{"it":"Un’**interfaccia** dichiara funzioni che le classi implementano. Una **sealed class** (o interface) elenca tutti i sottotipi possibili: perfetta per stati come caricamento, successo, errore. Con `when` il compilatore controlla che tu li gestisca tutti.","en":"An **interface** declares functions classes implement. A **sealed class** (or interface) lists every possible subtype: perfect for states like loading, success, error. With `when` the compiler checks you handle them all."}},{"t":"code","code":"sealed interface Stato {\\n    data object Caricamento : Stato\\n    data class Pronto(val corsi: List<String>) : Stato\\n    data class Errore(val messaggio: String) : Stato\\n}\\n\\nfun descrivi(s: Stato) = when (s) {\\n    is Stato.Caricamento -> \\"Attendi…\\"\\n    is Stato.Pronto -> \\"${s.corsi.size} corsi\\"\\n    is Stato.Errore -> \\"Errore: ${s.messaggio}\\"\\n}","lang":"kotlin"},{"t":"p","text":{"it":"Dopo `is Stato.Pronto` Kotlin sa che `s` è un `Pronto`: è lo **smart cast**, niente conversioni a mano.","en":"After `is Stato.Pronto` Kotlin knows `s` is a `Pronto`: it is the **smart cast**, no manual casting."}}]','{"lang":"kotlin","prompt":{"it":"Crea `sealed interface Risultato` con `data class Ok(val valore: Int) : Risultato`.","en":"Create `sealed interface Risultato` with `data class Ok(val valore: Int) : Risultato`."},"start":"","html":"","checks":[{"re":"sealed\\\\s+(interface|class)\\\\s+Risultato","label":{"it":"Il tipo è sealed","en":"The type is sealed"}},{"re":"data\\\\s+class\\\\s+Ok\\\\s*\\\\(\\\\s*val\\\\s+valore\\\\s*:\\\\s*Int\\\\s*\\\\)\\\\s*:\\\\s*Risultato","label":{"it":"Ok è un Risultato","en":"Ok is a Risultato"}}],"hint":"sealed interface Risultato {\\n    data class Ok(val valore: Int) : Risultato\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('kotlin-intermediate','coroutines',3,2,'published','{"it":"Coroutine","en":"Coroutines"}','[{"t":"p","text":{"it":"Le **coroutine** eseguono lavoro lento senza bloccare: una funzione `suspend` può mettersi in pausa. `launch` avvia un lavoro, `async`/`await` uno che restituisce un valore, dentro uno **scope** che ne controlla la vita.","en":"**Coroutines** run slow work without blocking: a `suspend` function can pause. `launch` starts a job, `async`/`await` one that returns a value, inside a **scope** that controls its lifetime."}},{"t":"code","code":"suspend fun caricaUtente(id: Int): Utente {\\n    delay(500)                    // non blocca il thread\\n    return api.utente(id)\\n}\\n\\nfun main() = runBlocking {\\n    val a = async { caricaUtente(1) }\\n    val b = async { caricaUtente(2) }\\n    println(\\"${a.await().nome} e ${b.await().nome}\\")\\n}","lang":"kotlin"},{"t":"p","text":{"it":"In Android si usano `viewModelScope` e `lifecycleScope`: quando la schermata sparisce, i lavori si annullano da soli.","en":"On Android you use `viewModelScope` and `lifecycleScope`: when the screen goes away, jobs cancel by themselves."}}]','{"lang":"kotlin","prompt":{"it":"Scrivi `suspend fun saluto(): String` che fa `delay(1000)` e restituisce `\\"Ciao\\"`.","en":"Write `suspend fun saluto(): String` that does `delay(1000)` and returns `\\"Ciao\\"`."},"start":"","html":"","checks":[{"re":"suspend\\\\s+fun\\\\s+saluto\\\\s*\\\\(\\\\s*\\\\)\\\\s*:\\\\s*String","label":{"it":"La funzione è sospendibile","en":"The function is suspending"}},{"re":"delay\\\\s*\\\\(\\\\s*1000\\\\s*\\\\)","label":{"it":"Aspetta un secondo","en":"It waits one second"}},{"re":"return\\\\s+\\"Ciao\\"","label":{"it":"Restituisce “Ciao”","en":"It returns “Ciao”"}}],"hint":"suspend fun saluto(): String {\\n    delay(1000)\\n    return \\"Ciao\\"\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('kotlin-intermediate','flow',4,3,'published','{"it":"Flow","en":"Flow"}','[{"t":"p","text":{"it":"Un **Flow** è un flusso di valori nel tempo, come un elenco che arriva un pezzo alla volta. Si trasforma con `map` e `filter` e si raccoglie con `collect`. `StateFlow` tiene sempre l’ultimo valore: ideale per lo stato di una schermata.","en":"A **Flow** is a stream of values over time, like a list arriving one piece at a time. You transform it with `map` and `filter` and gather it with `collect`. `StateFlow` always holds the latest value: ideal for a screen’s state."}},{"t":"code","code":"fun conto(): Flow<Int> = flow {\\n    for (i in 3 downTo 1) {\\n        emit(i)\\n        delay(1000)\\n    }\\n}\\n\\nconto().map { \\"Mancano $it\\" }.collect { println(it) }\\n\\nclass CorsiViewModel : ViewModel() {\\n    private val _stato = MutableStateFlow<Stato>(Stato.Caricamento)\\n    val stato: StateFlow<Stato> = _stato\\n}","lang":"kotlin"},{"t":"p","text":{"it":"La versione `Mutable` resta privata nel ViewModel; fuori si espone quella in sola lettura.","en":"The `Mutable` version stays private in the ViewModel; outside you expose the read-only one."}}]','{"lang":"kotlin","prompt":{"it":"Crea `private val _conta = MutableStateFlow(0)` e `val conta: StateFlow<Int> = _conta`.","en":"Create `private val _conta = MutableStateFlow(0)` and `val conta: StateFlow<Int> = _conta`."},"start":"","html":"","checks":[{"re":"private\\\\s+val\\\\s+_conta\\\\s*=\\\\s*MutableStateFlow\\\\s*\\\\(\\\\s*0\\\\s*\\\\)","label":{"it":"Lo stato modificabile è privato","en":"The mutable state is private"}},{"re":"val\\\\s+conta\\\\s*:\\\\s*StateFlow<Int>\\\\s*=\\\\s*_conta","label":{"it":"Esponi la sola lettura","en":"You expose read-only"}}],"hint":"private val _conta = MutableStateFlow(0)\\nval conta: StateFlow<Int> = _conta"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('kotlin-intermediate','compose',5,3,'published','{"it":"Jetpack Compose","en":"Jetpack Compose"}','[{"t":"p","text":{"it":"**Jetpack Compose** descrive l’interfaccia Android con funzioni `@Composable`. `remember { mutableStateOf(…) }` tiene uno stato che, quando cambia, ridisegna solo ciò che serve. `Column`, `Row` e `Box` dispongono gli elementi.","en":"**Jetpack Compose** describes the Android interface with `@Composable` functions. `remember { mutableStateOf(…) }` holds state that, when it changes, redraws only what is needed. `Column`, `Row` and `Box` lay out the elements."}},{"t":"code","code":"@Composable\\nfun Contatore() {\\n    var n by remember { mutableStateOf(0) }\\n    Column(\\n        modifier = Modifier.padding(16.dp),\\n        horizontalAlignment = Alignment.CenterHorizontally,\\n    ) {\\n        Text(\\"Clic: $n\\", style = MaterialTheme.typography.titleLarge)\\n        Button(onClick = { n++ }) { Text(\\"Più uno\\") }\\n    }\\n}","lang":"kotlin"},{"t":"p","text":{"it":"Il **Modifier** concatena dimensioni, margini, sfondi e clic. `LazyColumn` mostra liste lunghe in modo efficiente.","en":"The **Modifier** chains size, padding, backgrounds and clicks. `LazyColumn` shows long lists efficiently."}}]','{"lang":"kotlin","prompt":{"it":"Nella composable dichiara `var testo by remember { mutableStateOf(\\"\\") }` e un `TextField(value = testo, onValueChange = { testo = it })`.","en":"In the composable declare `var testo by remember { mutableStateOf(\\"\\") }` and a `TextField(value = testo, onValueChange = { testo = it })`."},"start":"@Composable\\nfun Campo() {\\n}","html":"","checks":[{"re":"var\\\\s+testo\\\\s+by\\\\s+remember\\\\s*\\\\{\\\\s*mutableStateOf\\\\s*\\\\(\\\\s*\\"\\"\\\\s*\\\\)\\\\s*\\\\}","label":{"it":"C’è lo stato","en":"There is the state"}},{"re":"TextField\\\\s*\\\\(\\\\s*value\\\\s*=\\\\s*testo\\\\s*,\\\\s*onValueChange\\\\s*=\\\\s*\\\\{\\\\s*testo\\\\s*=\\\\s*it\\\\s*\\\\}","label":{"it":"Il campo è collegato","en":"The field is bound"}}],"hint":"var testo by remember { mutableStateOf(\\"\\") }\\nTextField(value = testo, onValueChange = { testo = it })"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('rust-base','hello',1,1,'published','{"it":"Ciao, Cargo","en":"Hello, Cargo"}','[{"t":"p","text":{"it":"**Cargo** crea e compila i progetti Rust: `cargo new ciao` prepara la cartella, `cargo run` compila ed esegue. Il programma parte da `fn main()`; `println!` (con il punto esclamativo, è una **macro**) stampa.","en":"**Cargo** creates and builds Rust projects: `cargo new ciao` sets up the folder, `cargo run` builds and runs. The program starts from `fn main()`; `println!` (with the exclamation mark, it is a **macro**) prints."}},{"t":"code","code":"fn main() {\\n    let nome = \\"Ada\\";\\n    let anni = 36;\\n    println!(\\"Ciao, {nome}! Hai {} anni.\\", anni);\\n}","lang":"rust"},{"t":"p","text":{"it":"Le graffe `{}` nel testo vengono riempite dagli argomenti, o direttamente dal nome di una variabile come `{nome}`.","en":"Braces `{}` in the text are filled by the arguments, or directly by a variable name like `{nome}`."}}]','{"lang":"rust","prompt":{"it":"Nel `main` stampa `\\"Ciao, Rust!\\"` con `println!`.","en":"In `main` print `\\"Ciao, Rust!\\"` with `println!`."},"start":"fn main() {\\n}","html":"","checks":[{"re":"println!\\\\s*\\\\(\\\\s*\\"Ciao, Rust!\\"\\\\s*\\\\)\\\\s*;","label":{"it":"Stampi il saluto","en":"You print the greeting"}}],"hint":"println!(\\"Ciao, Rust!\\");"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('rust-base','variables',2,1,'published','{"it":"Variabili e tipi","en":"Variables and types"}','[{"t":"p","text":{"it":"In Rust le variabili sono **immutabili** per impostazione: per cambiarle serve `let mut`. I tipi si deducono o si scrivono: `i32` (intero), `f64` (decimale), `bool`, `char`, `&str` e `String` per il testo.","en":"In Rust variables are **immutable** by default: to change one you need `let mut`. Types are inferred or written: `i32` (integer), `f64` (decimal), `bool`, `char`, `&str` and `String` for text."}},{"t":"code","code":"let x = 5;            // immutabile\\nlet mut conta = 0;    // modificabile\\nconta += 1;\\n\\nlet prezzo: f64 = 9.99;\\nlet attivo: bool = true;\\nlet saluto: &str = \\"ciao\\";\\nlet mut nome = String::from(\\"Ada\\");\\nnome.push_str(\\" Lovelace\\");\\n\\nlet x = x * 2;        // shadowing: una nuova x","lang":"rust"},{"t":"p","text":{"it":"Lo **shadowing** dichiara una nuova variabile con lo stesso nome, anche di tipo diverso.","en":"**Shadowing** declares a new variable with the same name, even of a different type."}}]','{"lang":"rust","prompt":{"it":"Dichiara `let mut punti = 0;` e poi `punti += 10;`.","en":"Declare `let mut punti = 0;` then `punti += 10;`."},"start":"fn main() {\\n}","html":"","checks":[{"re":"let\\\\s+mut\\\\s+punti\\\\s*(:\\\\s*\\\\w+\\\\s*)?=\\\\s*0\\\\s*;","label":{"it":"La variabile è modificabile","en":"The variable is mutable"}},{"re":"punti\\\\s*\\\\+=\\\\s*10\\\\s*;","label":{"it":"La aumenti","en":"You increase it"}}],"hint":"let mut punti = 0;\\npunti += 10;"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('rust-base','control',3,1,'published','{"it":"Controllo del flusso","en":"Control flow"}','[{"t":"p","text":{"it":"`if` è un’espressione e restituisce un valore. `loop` ripete per sempre (si esce con `break`), `while` finché la condizione è vera, `for` scorre intervalli e collezioni.","en":"`if` is an expression and returns a value. `loop` repeats forever (exit with `break`), `while` while the condition holds, `for` walks ranges and collections."}},{"t":"code","code":"let voto = 8;\\nlet esito = if voto >= 6 { \\"promosso\\" } else { \\"bocciato\\" };\\n\\nfor i in 1..=3 {\\n    println!(\\"Giro {i}\\");\\n}\\n\\nlet mut n = 0;\\nlet risultato = loop {\\n    n += 1;\\n    if n == 5 { break n * 10; }\\n};","lang":"rust"},{"t":"p","text":{"it":"`1..=3` include il 3, `1..3` no. `break` in un `loop` può restituire un valore.","en":"`1..=3` includes 3, `1..3` does not. `break` in a `loop` can return a value."}}]','{"lang":"rust","prompt":{"it":"Con `for i in 1..=5` stampa ogni `i`.","en":"With `for i in 1..=5` print each `i`."},"start":"fn main() {\\n}","html":"","checks":[{"re":"for\\\\s+i\\\\s+in\\\\s+1\\\\s*\\\\.\\\\.=\\\\s*5\\\\s*\\\\{","label":{"it":"Il ciclo è giusto","en":"The loop is right"}},{"re":"println!\\\\s*\\\\(","label":{"it":"Stampi","en":"You print"}}],"hint":"for i in 1..=5 {\\n    println!(\\"{i}\\");\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('rust-base','functions',4,2,'published','{"it":"Funzioni","en":"Functions"}','[{"t":"p","text":{"it":"`fn` crea una funzione; parametri e risultato hanno sempre un tipo (`-> i32`). L’ultima espressione **senza punto e virgola** è il valore restituito.","en":"`fn` creates a function; parameters and result always have a type (`-> i32`). The last expression **without a semicolon** is the returned value."}},{"t":"code","code":"fn area(base: f64, altezza: f64) -> f64 {\\n    base * altezza\\n}\\n\\nfn segno(n: i32) -> &''static str {\\n    if n < 0 { return \\"negativo\\"; }\\n    \\"positivo o zero\\"\\n}\\n\\nfn main() {\\n    println!(\\"{}\\", area(3.0, 2.0));\\n}","lang":"rust"},{"t":"p","text":{"it":"Se aggiungi il punto e virgola all’ultima riga diventa un’istruzione e la funzione non restituisce più nulla: errore.","en":"If you add a semicolon to the last line it becomes a statement and the function returns nothing: error."}}]','{"lang":"rust","prompt":{"it":"Scrivi `fn doppio(n: i32) -> i32` che restituisce `n * 2`.","en":"Write `fn doppio(n: i32) -> i32` that returns `n * 2`."},"start":"","html":"","checks":[{"re":"fn\\\\s+doppio\\\\s*\\\\(\\\\s*n\\\\s*:\\\\s*i32\\\\s*\\\\)\\\\s*->\\\\s*i32","label":{"it":"La firma è giusta","en":"The signature is right"}},{"re":"n\\\\s*\\\\*\\\\s*2","label":{"it":"Restituisci il doppio","en":"You return the double"}}],"hint":"fn doppio(n: i32) -> i32 {\\n    n * 2\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('rust-base','ownership',5,2,'published','{"it":"Ownership e prestiti","en":"Ownership and borrowing"}','[{"t":"p","text":{"it":"Ogni valore in Rust ha un solo **proprietario**. Assegnarlo a un’altra variabile lo **sposta**: la prima non si può più usare. Per usarlo senza prenderlo si **presta** con un riferimento: `&valore` (lettura) o `&mut valore` (modifica).","en":"Every value in Rust has a single **owner**. Assigning it to another variable **moves** it: the first can no longer be used. To use it without taking it you **borrow** with a reference: `&value` (read) or `&mut value` (write)."}},{"t":"code","code":"let a = String::from(\\"ciao\\");\\nlet b = a;              // a è stato spostato in b\\n// println!(\\"{a}\\");     // errore: a non è più valido\\n\\nfn lunghezza(s: &String) -> usize { s.len() }\\nfn urla(s: &mut String) { s.push_str(\\"!\\"); }\\n\\nlet mut testo = String::from(\\"Fucina\\");\\nlet n = lunghezza(&testo);\\nurla(&mut testo);","lang":"rust"},{"t":"p","text":{"it":"Regola d’oro: tanti riferimenti in lettura **oppure** uno solo in scrittura, mai insieme. Così Rust evita interi tipi di bug già in compilazione, senza garbage collector.","en":"Golden rule: many read references **or** a single write reference, never both. This is how Rust prevents whole kinds of bugs at compile time, with no garbage collector."}}]','{"lang":"rust","prompt":{"it":"Scrivi `fn conta(s: &str) -> usize` che restituisce `s.len()`.","en":"Write `fn conta(s: &str) -> usize` that returns `s.len()`."},"start":"","html":"","checks":[{"re":"fn\\\\s+conta\\\\s*\\\\(\\\\s*s\\\\s*:\\\\s*&str\\\\s*\\\\)\\\\s*->\\\\s*usize","label":{"it":"Prende in prestito il testo","en":"It borrows the text"}},{"re":"s\\\\.len\\\\s*\\\\(\\\\s*\\\\)","label":{"it":"Restituisce la lunghezza","en":"It returns the length"}}],"hint":"fn conta(s: &str) -> usize {\\n    s.len()\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('rust-intermediate','structs',1,2,'published','{"it":"Struct e impl","en":"Structs and impl"}','[{"t":"p","text":{"it":"Una **struct** raggruppa campi con nome. I metodi si scrivono in un blocco `impl`: il primo parametro `&self` (o `&mut self`) è l’istanza. Le funzioni senza `self`, come `new`, si chiamano con `Tipo::`.","en":"A **struct** groups named fields. Methods go in an `impl` block: the first parameter `&self` (or `&mut self`) is the instance. Functions without `self`, like `new`, are called with `Type::`."}},{"t":"code","code":"#[derive(Debug, Clone)]\\nstruct Conto {\\n    titolare: String,\\n    saldo: f64,\\n}\\n\\nimpl Conto {\\n    fn new(titolare: &str) -> Self {\\n        Self { titolare: titolare.to_string(), saldo: 0.0 }\\n    }\\n    fn versa(&mut self, importo: f64) {\\n        self.saldo += importo;\\n    }\\n}\\n\\nlet mut c = Conto::new(\\"Ada\\");\\nc.versa(50.0);\\nprintln!(\\"{:?}\\", c);","lang":"rust"},{"t":"p","text":{"it":"`#[derive(Debug)]` fa scrivere a Rust il codice per stampare la struct con `{:?}`.","en":"`#[derive(Debug)]` makes Rust write the code to print the struct with `{:?}`."}}]','{"lang":"rust","prompt":{"it":"Crea `struct Punto { x: i32, y: i32 }` con `impl Punto` e il metodo `fn somma(&self) -> i32`.","en":"Create `struct Punto { x: i32, y: i32 }` with `impl Punto` and the method `fn somma(&self) -> i32`."},"start":"","html":"","checks":[{"re":"struct\\\\s+Punto\\\\s*\\\\{\\\\s*x\\\\s*:\\\\s*i32\\\\s*,\\\\s*y\\\\s*:\\\\s*i32\\\\s*,?\\\\s*\\\\}","label":{"it":"La struct esiste","en":"The struct exists"}},{"re":"impl\\\\s+Punto\\\\s*\\\\{","label":{"it":"C’è il blocco impl","en":"There is the impl block"}},{"re":"fn\\\\s+somma\\\\s*\\\\(\\\\s*&self\\\\s*\\\\)\\\\s*->\\\\s*i32","label":{"it":"Il metodo è giusto","en":"The method is right"}}],"hint":"struct Punto { x: i32, y: i32 }\\n\\nimpl Punto {\\n    fn somma(&self) -> i32 { self.x + self.y }\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('rust-intermediate','enums',2,2,'published','{"it":"Enum e match","en":"Enums and match"}','[{"t":"p","text":{"it":"Un **enum** elenca le varianti possibili, e ognuna può portare dati. `match` controlla tutte le varianti: il compilatore protesta se ne dimentichi una.","en":"An **enum** lists the possible variants, and each can carry data. `match` checks every variant: the compiler complains if you forget one."}},{"t":"code","code":"enum Forma {\\n    Cerchio(f64),\\n    Rettangolo { base: f64, altezza: f64 },\\n    Punto,\\n}\\n\\nfn area(f: &Forma) -> f64 {\\n    match f {\\n        Forma::Cerchio(r) => 3.14 * r * r,\\n        Forma::Rettangolo { base, altezza } => base * altezza,\\n        Forma::Punto => 0.0,\\n    }\\n}","lang":"rust"},{"t":"p","text":{"it":"`_` nel `match` cattura tutti i casi rimanenti. `if let` è comodo quando ti interessa una sola variante.","en":"`_` in `match` catches all remaining cases. `if let` is handy when you care about just one variant."}}]','{"lang":"rust","prompt":{"it":"Completa `match semaforo` con `Luce::Rosso => \\"fermo\\"`, `Luce::Verde => \\"vai\\"` e `_ => \\"attenzione\\"`.","en":"Complete `match semaforo` with `Luce::Rosso => \\"fermo\\"`, `Luce::Verde => \\"vai\\"` and `_ => \\"attenzione\\"`."},"start":"let azione = match semaforo {\\n};","html":"","checks":[{"re":"Luce::Rosso\\\\s*=>\\\\s*\\"fermo\\"","label":{"it":"Caso rosso","en":"Red case"}},{"re":"Luce::Verde\\\\s*=>\\\\s*\\"vai\\"","label":{"it":"Caso verde","en":"Green case"}},{"re":"_\\\\s*=>\\\\s*\\"attenzione\\"","label":{"it":"Tutti gli altri","en":"All the others"}}],"hint":"let azione = match semaforo {\\n    Luce::Rosso => \\"fermo\\",\\n    Luce::Verde => \\"vai\\",\\n    _ => \\"attenzione\\",\\n};"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('rust-intermediate','option-result',3,2,'published','{"it":"Option e Result","en":"Option and Result"}','[{"t":"p","text":{"it":"Rust non ha `null`: un valore che può mancare è un `Option<T>` (`Some(valore)` o `None`). Un’operazione che può fallire restituisce un `Result<T, E>` (`Ok` o `Err`). L’operatore `?` passa l’errore a chi ha chiamato.","en":"Rust has no `null`: a value that may be missing is an `Option<T>` (`Some(value)` or `None`). An operation that may fail returns a `Result<T, E>` (`Ok` or `Err`). The `?` operator passes the error up to the caller."}},{"t":"code","code":"fn primo_pari(v: &[i32]) -> Option<i32> {\\n    v.iter().copied().find(|n| n % 2 == 0)\\n}\\n\\nfn leggi_eta(testo: &str) -> Result<u8, std::num::ParseIntError> {\\n    let eta: u8 = testo.trim().parse()?;\\n    Ok(eta)\\n}\\n\\nlet x = primo_pari(&[1, 3, 4]).unwrap_or(0);\\nmatch leggi_eta(\\"36\\") {\\n    Ok(e) => println!(\\"{e} anni\\"),\\n    Err(err) => println!(\\"Errore: {err}\\"),\\n}","lang":"rust"},{"t":"p","text":{"it":"`unwrap()` estrae il valore ma fa crashare il programma se c’è `None` o `Err`: meglio `match`, `unwrap_or` o `?`.","en":"`unwrap()` extracts the value but crashes the program on `None` or `Err`: better `match`, `unwrap_or` or `?`."}}]','{"lang":"rust","prompt":{"it":"Scrivi `fn dividi(a: f64, b: f64) -> Option<f64>` che restituisce `None` se `b == 0.0`, altrimenti `Some(a / b)`.","en":"Write `fn dividi(a: f64, b: f64) -> Option<f64>` returning `None` if `b == 0.0`, otherwise `Some(a / b)`."},"start":"","html":"","checks":[{"re":"fn\\\\s+dividi\\\\s*\\\\(\\\\s*a\\\\s*:\\\\s*f64\\\\s*,\\\\s*b\\\\s*:\\\\s*f64\\\\s*\\\\)\\\\s*->\\\\s*Option<f64>","label":{"it":"La firma è giusta","en":"The signature is right"}},{"re":"None","label":{"it":"C’è il caso vuoto","en":"There is the empty case"}},{"re":"Some\\\\s*\\\\(\\\\s*a\\\\s*/\\\\s*b\\\\s*\\\\)","label":{"it":"E il risultato","en":"And the result"}}],"hint":"fn dividi(a: f64, b: f64) -> Option<f64> {\\n    if b == 0.0 { None } else { Some(a / b) }\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('rust-intermediate','collections',4,3,'published','{"it":"Vec, HashMap e iteratori","en":"Vec, HashMap and iterators"}','[{"t":"p","text":{"it":"`Vec<T>` è una lista che cresce, `HashMap<K, V>` associa chiavi e valori. Gli **iteratori** (`iter`, `map`, `filter`, `sum`, `collect`) trasformano le collezioni senza cicli scritti a mano, ed è codice veloce quanto un ciclo.","en":"`Vec<T>` is a growable list, `HashMap<K, V>` maps keys to values. **Iterators** (`iter`, `map`, `filter`, `sum`, `collect`) transform collections with no hand-written loops, and the code is as fast as a loop."}},{"t":"code","code":"use std::collections::HashMap;\\n\\nlet mut voti = vec![7, 8, 9];\\nvoti.push(6);\\nlet promossi: Vec<i32> = voti.iter().copied().filter(|v| *v >= 6).collect();\\nlet totale: i32 = voti.iter().sum();\\n\\nlet mut eta: HashMap<&str, u32> = HashMap::new();\\neta.insert(\\"Ada\\", 36);\\n*eta.entry(\\"Bea\\").or_insert(0) += 1;","lang":"rust"},{"t":"p","text":{"it":"Le **closure** si scrivono tra barre verticali: `|v| *v >= 6`. `entry(...).or_insert(...)` inserisce un valore solo se la chiave manca.","en":"**Closures** are written between vertical bars: `|v| *v >= 6`. `entry(...).or_insert(...)` inserts a value only if the key is missing."}}]','{"lang":"rust","prompt":{"it":"Da `numeri` ottieni `let doppi: Vec<i32> = numeri.iter().map(|n| n * 2).collect();`.","en":"From `numeri` get `let doppi: Vec<i32> = numeri.iter().map(|n| n * 2).collect();`."},"start":"let numeri = vec![1, 2, 3];","html":"","checks":[{"re":"let\\\\s+doppi\\\\s*:\\\\s*Vec<i32>\\\\s*=\\\\s*numeri\\\\.iter\\\\s*\\\\(\\\\s*\\\\)","label":{"it":"Parti dall’iteratore","en":"You start from the iterator"}},{"re":"\\\\.map\\\\s*\\\\(\\\\s*\\\\|n\\\\|\\\\s*n\\\\s*\\\\*\\\\s*2\\\\s*\\\\)","label":{"it":"Raddoppi","en":"You double"}},{"re":"\\\\.collect\\\\s*\\\\(\\\\s*\\\\)","label":{"it":"Raccogli","en":"You collect"}}],"hint":"let doppi: Vec<i32> = numeri.iter().map(|n| n * 2).collect();"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('rust-intermediate','traits',5,3,'published','{"it":"Trait e generics","en":"Traits and generics"}','[{"t":"p","text":{"it":"Un **trait** descrive un comportamento che i tipi possono implementare, come un’interfaccia. Le funzioni **generiche** accettano qualsiasi tipo che implementi un trait: `fn stampa<T: Display>(x: T)`.","en":"A **trait** describes a behaviour types can implement, like an interface. **Generic** functions accept any type that implements a trait: `fn stampa<T: Display>(x: T)`."}},{"t":"code","code":"trait Descrivi {\\n    fn descrizione(&self) -> String;\\n    fn breve(&self) -> String { self.descrizione().chars().take(10).collect() }\\n}\\n\\nstruct Corso { titolo: String }\\n\\nimpl Descrivi for Corso {\\n    fn descrizione(&self) -> String { format!(\\"Corso di {}\\", self.titolo) }\\n}\\n\\nfn mostra(x: &impl Descrivi) {\\n    println!(\\"{}\\", x.descrizione());\\n}","lang":"rust"},{"t":"p","text":{"it":"Un trait può avere metodi già pronti (come `breve`). `#[derive(Debug, Clone, PartialEq)]` implementa da solo i trait più comuni.","en":"A trait can have ready-made methods (like `breve`). `#[derive(Debug, Clone, PartialEq)]` implements the most common traits automatically."}}]','{"lang":"rust","prompt":{"it":"Implementa `impl Saluta for Gatto` con `fn saluta(&self) -> String { String::from(\\"Miao\\") }`.","en":"Implement `impl Saluta for Gatto` with `fn saluta(&self) -> String { String::from(\\"Miao\\") }`."},"start":"trait Saluta { fn saluta(&self) -> String; }\\nstruct Gatto;","html":"","checks":[{"re":"impl\\\\s+Saluta\\\\s+for\\\\s+Gatto\\\\s*\\\\{","label":{"it":"Implementi il trait","en":"You implement the trait"}},{"re":"fn\\\\s+saluta\\\\s*\\\\(\\\\s*&self\\\\s*\\\\)\\\\s*->\\\\s*String\\\\s*\\\\{","label":{"it":"Il metodo ha un corpo","en":"The method has a body"}}],"hint":"impl Saluta for Gatto {\\n    fn saluta(&self) -> String { String::from(\\"Miao\\") }\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('rust-advanced','lifetimes',1,3,'published','{"it":"Lifetime","en":"Lifetimes"}','[{"t":"p","text":{"it":"Un **lifetime** dice al compilatore per quanto tempo un riferimento resta valido. Quando una funzione riceve più riferimenti e ne restituisce uno, l’annotazione `''a` collega le loro durate.","en":"A **lifetime** tells the compiler how long a reference stays valid. When a function takes several references and returns one, the `''a` annotation links their lifetimes."}},{"t":"code","code":"fn piu_lunga<''a>(a: &''a str, b: &''a str) -> &''a str {\\n    if a.len() >= b.len() { a } else { b }\\n}\\n\\nstruct Estratto<''a> {\\n    testo: &''a str,\\n}","lang":"rust"},{"t":"p","text":{"it":"La firma dice: il risultato vive al massimo quanto il più breve tra `a` e `b`. Nella maggior parte dei casi Rust deduce i lifetime da solo.","en":"The signature says: the result lives at most as long as the shorter of `a` and `b`. In most cases Rust infers lifetimes by itself."}}]','{"lang":"rust","prompt":{"it":"Scrivi la firma `fn primo<''a>(v: &''a [i32]) -> &''a i32`.","en":"Write the signature `fn primo<''a>(v: &''a [i32]) -> &''a i32`."},"start":"","html":"","checks":[{"re":"fn\\\\s+primo\\\\s*<\\\\s*''a\\\\s*>\\\\s*\\\\(\\\\s*v\\\\s*:\\\\s*&''a\\\\s*\\\\[i32\\\\]\\\\s*\\\\)\\\\s*->\\\\s*&''a\\\\s+i32","label":{"it":"La firma collega i lifetime","en":"The signature links the lifetimes"}}],"hint":"fn primo<''a>(v: &''a [i32]) -> &''a i32 {\\n    &v[0]\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('rust-advanced','smart-pointers',2,3,'published','{"it":"Smart pointer","en":"Smart pointers"}','[{"t":"p","text":{"it":"`Box<T>` mette un valore nello heap (utile per strutture ricorsive). `Rc<T>` permette più proprietari dello stesso valore in un thread; `Arc<T>` lo stesso tra thread. `RefCell` e `Mutex` permettono di modificare dentro un valore condiviso.","en":"`Box<T>` puts a value on the heap (handy for recursive structures). `Rc<T>` allows several owners of the same value in one thread; `Arc<T>` the same across threads. `RefCell` and `Mutex` let you change things inside a shared value."}},{"t":"code","code":"use std::rc::Rc;\\nuse std::sync::{Arc, Mutex};\\n\\nenum Lista { Nodo(i32, Box<Lista>), Fine }\\n\\nlet condiviso = Rc::new(String::from(\\"Fucina\\"));\\nlet altro = Rc::clone(&condiviso);\\nprintln!(\\"{}\\", Rc::strong_count(&condiviso)); // 2\\n\\nlet contatore = Arc::new(Mutex::new(0));\\n*contatore.lock().unwrap() += 1;","lang":"rust"},{"t":"p","text":{"it":"`Rc::clone` non copia il dato: aumenta un contatore. Quando l’ultimo proprietario sparisce, il valore viene liberato.","en":"`Rc::clone` does not copy the data: it increments a counter. When the last owner goes away, the value is freed."}}]','{"lang":"rust","prompt":{"it":"Crea `let dati = Arc::new(Mutex::new(Vec::<i32>::new()));`.","en":"Create `let dati = Arc::new(Mutex::new(Vec::<i32>::new()));`."},"start":"use std::sync::{Arc, Mutex};","html":"","checks":[{"re":"let\\\\s+dati\\\\s*=\\\\s*Arc::new\\\\s*\\\\(\\\\s*Mutex::new\\\\s*\\\\(","label":{"it":"Dati condivisi e protetti","en":"Shared, protected data"}}],"hint":"let dati = Arc::new(Mutex::new(Vec::<i32>::new()));"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('rust-advanced','threads',3,3,'published','{"it":"Thread e canali","en":"Threads and channels"}','[{"t":"p","text":{"it":"`thread::spawn` avvia un thread; `join` aspetta che finisca. I thread comunicano bene con i **canali**: uno manda con `send`, l’altro riceve con `recv`. Il compilatore impedisce le data race.","en":"`thread::spawn` starts a thread; `join` waits for it to finish. Threads communicate well through **channels**: one sends with `send`, the other receives with `recv`. The compiler prevents data races."}},{"t":"code","code":"use std::sync::mpsc;\\nuse std::thread;\\n\\nlet (tx, rx) = mpsc::channel();\\n\\nfor id in 0..3 {\\n    let tx = tx.clone();\\n    thread::spawn(move || {\\n        tx.send(format!(\\"lavoratore {id} ha finito\\")).unwrap();\\n    });\\n}\\ndrop(tx);\\n\\nfor messaggio in rx {\\n    println!(\\"{messaggio}\\");\\n}","lang":"rust"},{"t":"p","text":{"it":"`move` sposta nel thread le variabili che usa. `mpsc` significa “più produttori, un consumatore”.","en":"`move` moves into the thread the variables it uses. `mpsc` means “multiple producers, single consumer”."}}]','{"lang":"rust","prompt":{"it":"Avvia un thread con `let h = thread::spawn(move || { println!(\\"ciao\\"); });` e poi `h.join().unwrap();`.","en":"Start a thread with `let h = thread::spawn(move || { println!(\\"ciao\\"); });` then `h.join().unwrap();`."},"start":"use std::thread;","html":"","checks":[{"re":"let\\\\s+h\\\\s*=\\\\s*thread::spawn\\\\s*\\\\(\\\\s*move\\\\s*\\\\|\\\\|","label":{"it":"Avvii il thread","en":"You start the thread"}},{"re":"h\\\\.join\\\\s*\\\\(\\\\s*\\\\)\\\\s*\\\\.unwrap\\\\s*\\\\(\\\\s*\\\\)","label":{"it":"Aspetti la fine","en":"You wait for the end"}}],"hint":"let h = thread::spawn(move || {\\n    println!(\\"ciao\\");\\n});\\nh.join().unwrap();"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('rust-advanced','async',4,3,'published','{"it":"Async con Tokio","en":"Async with Tokio"}','[{"t":"p","text":{"it":"Il codice `async` di Rust ha bisogno di un **runtime** che lo esegua: il più usato è **Tokio**. `#[tokio::main]` prepara il runtime, `.await` aspetta un futuro, `tokio::join!` ne esegue più insieme.","en":"Rust `async` code needs a **runtime** to run it: the most used is **Tokio**. `#[tokio::main]` sets up the runtime, `.await` waits for a future, `tokio::join!` runs several together."}},{"t":"code","code":"use tokio::time::{sleep, Duration};\\n\\nasync fn scarica(nome: &str) -> String {\\n    sleep(Duration::from_millis(500)).await;\\n    format!(\\"{nome} pronto\\")\\n}\\n\\n#[tokio::main]\\nasync fn main() {\\n    let (a, b) = tokio::join!(scarica(\\"A\\"), scarica(\\"B\\"));\\n    println!(\\"{a}, {b}\\");\\n}","lang":"rust"},{"t":"p","text":{"it":"Un futuro non fa nulla finché non viene atteso: è **pigro**. Per lavori di calcolo pesante meglio i thread.","en":"A future does nothing until awaited: it is **lazy**. For heavy computation threads are better."}}]','{"lang":"rust","prompt":{"it":"Scrivi `async fn saluto() -> String` che restituisce `String::from(\\"ciao\\")`, e chiamalo con `.await`.","en":"Write `async fn saluto() -> String` returning `String::from(\\"ciao\\")`, and call it with `.await`."},"start":"","html":"","checks":[{"re":"async\\\\s+fn\\\\s+saluto\\\\s*\\\\(\\\\s*\\\\)\\\\s*->\\\\s*String","label":{"it":"La funzione è async","en":"The function is async"}},{"re":"saluto\\\\s*\\\\(\\\\s*\\\\)\\\\s*\\\\.await","label":{"it":"La attendi","en":"You await it"}}],"hint":"async fn saluto() -> String {\\n    String::from(\\"ciao\\")\\n}\\n\\nlet s = saluto().await;"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('rust-advanced','tests-crates',5,3,'published','{"it":"Test, crate e Cargo","en":"Tests, crates and Cargo"}','[{"t":"p","text":{"it":"I test stanno accanto al codice in un modulo `#[cfg(test)]`; ogni funzione `#[test]` usa `assert_eq!` e `assert!`. `cargo test` li esegue tutti. Le librerie si chiamano **crate** e si aggiungono con `cargo add`.","en":"Tests sit next to the code in a `#[cfg(test)]` module; each `#[test]` function uses `assert_eq!` and `assert!`. `cargo test` runs them all. Libraries are called **crates** and you add them with `cargo add`."}},{"t":"code","code":"pub fn somma(a: i32, b: i32) -> i32 { a + b }\\n\\n#[cfg(test)]\\nmod test {\\n    use super::*;\\n\\n    #[test]\\n    fn somma_due_numeri() {\\n        assert_eq!(somma(2, 3), 5);\\n    }\\n\\n    #[test]\\n    #[should_panic]\\n    fn divisione_per_zero() {\\n        let _ = 1 / std::hint::black_box(0);\\n    }\\n}\\n\\n// terminale: cargo add serde --features derive","lang":"rust"},{"t":"p","text":{"it":"`cargo clippy` suggerisce miglioramenti, `cargo fmt` formatta il codice come tutti i progetti Rust.","en":"`cargo clippy` suggests improvements, `cargo fmt` formats code like every Rust project."}}]','{"lang":"rust","prompt":{"it":"Scrivi un `#[test]` chiamato `doppio_di_due` con `assert_eq!(doppio(2), 4);`.","en":"Write a `#[test]` named `doppio_di_due` with `assert_eq!(doppio(2), 4);`."},"start":"#[cfg(test)]\\nmod test {\\n    use super::*;\\n}","html":"","checks":[{"re":"#\\\\[test\\\\]\\\\s*fn\\\\s+doppio_di_due\\\\s*\\\\(\\\\s*\\\\)","label":{"it":"Il test esiste","en":"The test exists"}},{"re":"assert_eq!\\\\s*\\\\(\\\\s*doppio\\\\s*\\\\(\\\\s*2\\\\s*\\\\)\\\\s*,\\\\s*4\\\\s*\\\\)","label":{"it":"L’asserzione è giusta","en":"The assertion is right"}}],"hint":"#[test]\\nfn doppio_di_due() {\\n    assert_eq!(doppio(2), 4);\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('vala-base','hello',1,1,'published','{"it":"Il primo programma","en":"The first program"}','[{"t":"p","text":{"it":"**Vala** ha una sintassi simile a C# ma viene tradotto in C e compilato: programmi veloci e senza macchina virtuale. Il punto di partenza è `main`; `print` scrive (senza andare a capo da solo).","en":"**Vala** has a C#-like syntax but is translated to C and compiled: fast programs with no virtual machine. The starting point is `main`; `print` writes (without adding a newline by itself)."}},{"t":"code","code":"void main () {\\n    string nome = \\"Ada\\";\\n    print (\\"Ciao, %s!\\\\n\\", nome);\\n    stdout.printf (\\"Due più due fa %d\\\\n\\", 2 + 2);\\n}\\n\\n// terminale: valac ciao.vala && ./ciao","lang":"vala"},{"t":"p","text":{"it":"`%s` inserisce un testo, `%d` un intero. Lo stile GNOME mette uno spazio prima delle parentesi delle chiamate.","en":"`%s` inserts text, `%d` an integer. GNOME style puts a space before the brackets of calls."}}]','{"lang":"vala","prompt":{"it":"Nel `main` stampa `\\"Benvenuto\\\\n\\"` con `print`.","en":"In `main` print `\\"Benvenuto\\\\n\\"` with `print`."},"start":"void main () {\\n}","html":"","checks":[{"re":"print\\\\s*\\\\(\\\\s*\\"Benvenuto\\\\\\\\n\\"\\\\s*\\\\)\\\\s*;","label":{"it":"Stampi il saluto","en":"You print the greeting"}}],"hint":"void main () {\\n    print (\\"Benvenuto\\\\n\\");\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('vala-base','types',2,1,'published','{"it":"Tipi e variabili","en":"Types and variables"}','[{"t":"p","text":{"it":"I tipi principali sono `int`, `double`, `bool`, `char` e `string`. `var` deduce il tipo. `const` crea una costante. Le stringhe con il segno `@` davanti accettano valori con `$nome`.","en":"The main types are `int`, `double`, `bool`, `char` and `string`. `var` infers the type. `const` creates a constant. Strings prefixed with `@` accept values with `$nome`."}},{"t":"code","code":"int pezzi = 3;\\ndouble prezzo = 9.5;\\nbool pronto = true;\\nvar citta = \\"Udine\\";          // string\\nconst int MAX = 10;\\n\\nstring riepilogo = @\\"$pezzi pezzi a $prezzo euro\\";\\nstring? soprannome = null;    // può essere null","lang":"vala"},{"t":"p","text":{"it":"Come in altri linguaggi moderni, un tipo con `?` può valere `null`; senza punto di domanda no.","en":"As in other modern languages, a type with `?` can be `null`; without the question mark it cannot."}}]','{"lang":"vala","prompt":{"it":"Dichiara `int livelli = 6;` e `string corso = \\"Vala\\";`.","en":"Declare `int livelli = 6;` and `string corso = \\"Vala\\";`."},"start":"","html":"","checks":[{"re":"int\\\\s+livelli\\\\s*=\\\\s*6\\\\s*;","label":{"it":"C’è l’intero","en":"There is the int"}},{"re":"string\\\\s+corso\\\\s*=\\\\s*\\"Vala\\"\\\\s*;","label":{"it":"C’è la stringa","en":"There is the string"}}],"hint":"int livelli = 6;\\nstring corso = \\"Vala\\";"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('vala-base','control',3,1,'published','{"it":"Condizioni e cicli","en":"Conditions and loops"}','[{"t":"p","text":{"it":"`if`/`else`, `switch`, `while`, `for` funzionano come in C#. `foreach` scorre gli elementi di un array o di una lista.","en":"`if`/`else`, `switch`, `while`, `for` work as in C#. `foreach` walks the items of an array or a list."}},{"t":"code","code":"for (int i = 1; i <= 3; i++) {\\n    print (\\"Giro %d\\\\n\\", i);\\n}\\n\\nstring[] frutta = { \\"mela\\", \\"pera\\", \\"kiwi\\" };\\nforeach (string f in frutta) {\\n    print (\\"%s\\\\n\\", f);\\n}\\n\\nswitch (voto) {\\n    case 10:\\n        print (\\"Perfetto\\\\n\\");\\n        break;\\n    default:\\n        print (\\"Bene\\\\n\\");\\n        break;\\n}","lang":"vala"},{"t":"p","text":{"it":"Nello `switch` ogni caso finisce con `break`.","en":"In `switch` each case ends with `break`."}}]','{"lang":"vala","prompt":{"it":"Con `foreach (string n in nomi)` stampa ogni nome.","en":"With `foreach (string n in nomi)` print each name."},"start":"string[] nomi = { \\"Ada\\", \\"Bea\\" };","html":"","checks":[{"re":"foreach\\\\s*\\\\(\\\\s*(string|var)\\\\s+n\\\\s+in\\\\s+nomi\\\\s*\\\\)","label":{"it":"Il ciclo è giusto","en":"The loop is right"}},{"re":"print\\\\s*\\\\(","label":{"it":"Stampi","en":"You print"}}],"hint":"foreach (string n in nomi) {\\n    print (\\"%s\\\\n\\", n);\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('vala-base','methods',4,2,'published','{"it":"Metodi","en":"Methods"}','[{"t":"p","text":{"it":"Un metodo ha un tipo di ritorno (`void` se non restituisce nulla), un nome e parametri tipizzati. I parametri con valore predefinito si possono omettere nella chiamata.","en":"A method has a return type (`void` if it returns nothing), a name and typed parameters. Parameters with a default value can be left out of the call."}},{"t":"code","code":"int quadrato (int n) {\\n    return n * n;\\n}\\n\\nstring saluta (string nome, string punto = \\"!\\") {\\n    return @\\"Ciao $nome$punto\\";\\n}\\n\\nvoid main () {\\n    print (\\"%d\\\\n\\", quadrato (4));\\n    print (\\"%s\\\\n\\", saluta (\\"Ada\\"));\\n}","lang":"vala"},{"t":"p","text":{"it":"I metodi fuori dalle classi si chiamano funzioni; dentro una classe diventano metodi dell’oggetto.","en":"Methods outside classes are called functions; inside a class they become the object’s methods."}}]','{"lang":"vala","prompt":{"it":"Scrivi `int doppio (int n)` che restituisce `n * 2`.","en":"Write `int doppio (int n)` that returns `n * 2`."},"start":"","html":"","checks":[{"re":"int\\\\s+doppio\\\\s*\\\\(\\\\s*int\\\\s+n\\\\s*\\\\)","label":{"it":"La firma è giusta","en":"The signature is right"}},{"re":"return\\\\s+n\\\\s*\\\\*\\\\s*2\\\\s*;","label":{"it":"Restituisci il doppio","en":"You return the double"}}],"hint":"int doppio (int n) {\\n    return n * 2;\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('vala-base','classes',5,2,'published','{"it":"Classi e GObject","en":"Classes and GObject"}','[{"t":"p","text":{"it":"Le classi che ereditano da `Object` sono **GObject**: il sistema a oggetti di GNOME. Hanno **proprietà** con `get`/`set`, un costruttore e possono emettere **segnali**.","en":"Classes inheriting from `Object` are **GObjects**: GNOME’s object system. They have **properties** with `get`/`set`, a constructor and can emit **signals**."}},{"t":"code","code":"public class Conto : Object {\\n    public string titolare { get; construct; }\\n    public double saldo { get; private set; default = 0; }\\n\\n    public signal void cambiato (double nuovo);\\n\\n    public Conto (string titolare) {\\n        Object (titolare: titolare);\\n    }\\n\\n    public void versa (double importo) {\\n        saldo += importo;\\n        cambiato (saldo);\\n    }\\n}\\n\\nvar c = new Conto (\\"Ada\\");\\nc.cambiato.connect ((s) => print (\\"Saldo: %.2f\\\\n\\", s));\\nc.versa (50);","lang":"vala"},{"t":"p","text":{"it":"Un **segnale** avvisa chi si è collegato con `connect`: è il modo in cui i bottoni GTK dicono “sono stato cliccato”.","en":"A **signal** notifies whoever connected with `connect`: it is how GTK buttons say “I was clicked”."}}]','{"lang":"vala","prompt":{"it":"Crea `public class Gatto : Object` con la proprietà `public string nome { get; set; }`.","en":"Create `public class Gatto : Object` with the property `public string nome { get; set; }`."},"start":"","html":"","checks":[{"re":"public\\\\s+class\\\\s+Gatto\\\\s*:\\\\s*Object","label":{"it":"La classe è un GObject","en":"The class is a GObject"}},{"re":"public\\\\s+string\\\\s+nome\\\\s*\\\\{\\\\s*get\\\\s*;\\\\s*set\\\\s*;\\\\s*\\\\}","label":{"it":"C’è la proprietà","en":"There is the property"}}],"hint":"public class Gatto : Object {\\n    public string nome { get; set; }\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('vala-intermediate','interfaces',1,2,'published','{"it":"Interfacce ed ereditarietà","en":"Interfaces and inheritance"}','[{"t":"p","text":{"it":"Una classe eredita da una sola classe ma può implementare più **interfacce**. I metodi da ridefinire sono `virtual` (o `abstract`) nella classe madre e `override` nella figlia.","en":"A class inherits from one class but can implement several **interfaces**. Methods to redefine are `virtual` (or `abstract`) in the parent and `override` in the child."}},{"t":"code","code":"public interface Descrivibile : Object {\\n    public abstract string descrivi ();\\n}\\n\\npublic abstract class Animale : Object, Descrivibile {\\n    public abstract string verso ();\\n    public string descrivi () { return \\"Fa \\" + verso (); }\\n}\\n\\npublic class Cane : Animale {\\n    public override string verso () { return \\"bau\\"; }\\n}","lang":"vala"},{"t":"p","text":{"it":"Una classe `abstract` non si istanzia: serve da base comune.","en":"An `abstract` class cannot be instantiated: it serves as a shared base."}}]','{"lang":"vala","prompt":{"it":"Crea `public class Gatto : Animale` con `public override string verso () { return \\"miao\\"; }`.","en":"Create `public class Gatto : Animale` with `public override string verso () { return \\"miao\\"; }`."},"start":"","html":"","checks":[{"re":"public\\\\s+class\\\\s+Gatto\\\\s*:\\\\s*Animale","label":{"it":"Gatto è un Animale","en":"Gatto is an Animale"}},{"re":"public\\\\s+override\\\\s+string\\\\s+verso\\\\s*\\\\(\\\\s*\\\\)","label":{"it":"Ridefinisce il verso","en":"It redefines the sound"}},{"re":"return\\\\s+\\"miao\\"\\\\s*;","label":{"it":"Restituisce “miao”","en":"It returns “miao”"}}],"hint":"public class Gatto : Animale {\\n    public override string verso () { return \\"miao\\"; }\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('vala-intermediate','collections',2,2,'published','{"it":"Collezioni","en":"Collections"}','[{"t":"p","text":{"it":"Oltre agli array, GLib offre `GenericArray` e `HashTable`; la libreria **Gee** aggiunge `ArrayList`, `HashMap` e `HashSet`, comode e tipizzate con i generics.","en":"Besides arrays, GLib offers `GenericArray` and `HashTable`; the **Gee** library adds `ArrayList`, `HashMap` and `HashSet`, handy and typed with generics."}},{"t":"code","code":"var nomi = new Gee.ArrayList<string> ();\\nnomi.add (\\"Ada\\");\\nnomi.add (\\"Bea\\");\\nforeach (var n in nomi) print (\\"%s\\\\n\\", n);\\n\\nvar eta = new Gee.HashMap<string, int> ();\\neta[\\"Ada\\"] = 36;\\nif (eta.has_key (\\"Ada\\")) print (\\"%d\\\\n\\", eta[\\"Ada\\"]);","lang":"vala"},{"t":"p","text":{"it":"Per usare Gee si compila con `--pkg gee-0.8`. Le parentesi angolari indicano il tipo degli elementi.","en":"To use Gee you compile with `--pkg gee-0.8`. Angle brackets give the type of the items."}}]','{"lang":"vala","prompt":{"it":"Crea `var colori = new Gee.ArrayList<string> ();` e aggiungi `\\"blu\\"`.","en":"Create `var colori = new Gee.ArrayList<string> ();` and add `\\"blu\\"`."},"start":"","html":"","checks":[{"re":"var\\\\s+colori\\\\s*=\\\\s*new\\\\s+Gee\\\\.ArrayList<string>\\\\s*\\\\(\\\\s*\\\\)\\\\s*;","label":{"it":"La lista esiste","en":"The list exists"}},{"re":"colori\\\\.add\\\\s*\\\\(\\\\s*\\"blu\\"\\\\s*\\\\)\\\\s*;","label":{"it":"Aggiungi il blu","en":"You add blue"}}],"hint":"var colori = new Gee.ArrayList<string> ();\\ncolori.add (\\"blu\\");"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('vala-intermediate','errors',3,2,'published','{"it":"Errori","en":"Errors"}','[{"t":"p","text":{"it":"In Vala gli errori sono dichiarati con `errordomain`. Un metodo che può fallire lo dice con `throws`; chi lo chiama usa `try`/`catch`.","en":"In Vala errors are declared with `errordomain`. A method that may fail says so with `throws`; the caller uses `try`/`catch`."}},{"t":"code","code":"errordomain ErroreConto {\\n    SALDO_INSUFFICIENTE,\\n    IMPORTO_NON_VALIDO\\n}\\n\\nvoid preleva (double importo) throws ErroreConto {\\n    if (importo <= 0) throw new ErroreConto.IMPORTO_NON_VALIDO (\\"Importo %.2f non valido\\", importo);\\n}\\n\\ntry {\\n    preleva (-5);\\n} catch (ErroreConto e) {\\n    print (\\"Errore: %s\\\\n\\", e.message);\\n}","lang":"vala"},{"t":"p","text":{"it":"Anche le funzioni di GLib per file e rete lanciano errori: `FileUtils.get_contents` va sempre dentro un `try`.","en":"GLib functions for files and networking throw errors too: `FileUtils.get_contents` always goes inside a `try`."}}]','{"lang":"vala","prompt":{"it":"Chiama `leggi ()` dentro `try` e stampa `e.message` nel `catch (Error e)`.","en":"Call `leggi ()` inside `try` and print `e.message` in `catch (Error e)`."},"start":"","html":"","checks":[{"re":"try\\\\s*\\\\{\\\\s*leggi\\\\s*\\\\(\\\\s*\\\\)\\\\s*;","label":{"it":"Provi la chiamata","en":"You try the call"}},{"re":"catch\\\\s*\\\\(\\\\s*Error\\\\s+e\\\\s*\\\\)\\\\s*\\\\{[\\\\s\\\\S]*e\\\\.message","label":{"it":"Gestisci l’errore","en":"You handle the error"}}],"hint":"try {\\n    leggi ();\\n} catch (Error e) {\\n    print (\\"%s\\\\n\\", e.message);\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('vala-intermediate','async',4,3,'published','{"it":"Metodi asincroni","en":"Async methods"}','[{"t":"p","text":{"it":"Un metodo `async` può mettersi in pausa con `yield` senza bloccare l’interfaccia, per esempio mentre legge un file o la rete. Si avvia con `.begin` e si raccoglie il risultato con `.end`.","en":"An `async` method can pause with `yield` without blocking the interface, for example while reading a file or the network. You start it with `.begin` and collect the result with `.end`."}},{"t":"code","code":"async string leggi_titolo (File file) throws Error {\\n    uint8[] dati;\\n    yield file.load_contents_async (null, out dati, null);\\n    return ((string) dati).split (\\"\\\\n\\")[0];\\n}\\n\\nleggi_titolo.begin (File.new_for_path (\\"note.txt\\"), (obj, res) => {\\n    try {\\n        print (\\"%s\\\\n\\", leggi_titolo.end (res));\\n    } catch (Error e) {\\n        print (\\"Errore: %s\\\\n\\", e.message);\\n    }\\n});","lang":"vala"},{"t":"p","text":{"it":"Dentro un altro metodo `async` basta scrivere `yield leggi_titolo (file)`.","en":"Inside another `async` method you just write `yield leggi_titolo (file)`."}}]','{"lang":"vala","prompt":{"it":"Dichiara `async void aggiorna () { yield carica_dati (); }`.","en":"Declare `async void aggiorna () { yield carica_dati (); }`."},"start":"","html":"","checks":[{"re":"async\\\\s+void\\\\s+aggiorna\\\\s*\\\\(\\\\s*\\\\)","label":{"it":"Il metodo è async","en":"The method is async"}},{"re":"yield\\\\s+carica_dati\\\\s*\\\\(\\\\s*\\\\)\\\\s*;","label":{"it":"Aspetta i dati","en":"It waits for the data"}}],"hint":"async void aggiorna () {\\n    yield carica_dati ();\\n}"}');
INSERT INTO `fc_lessons` (`course`,`slug`,`sort`,`difficulty`,`status`,`title`,`body`,`task`) VALUES ('vala-intermediate','gtk',5,3,'published','{"it":"Una finestra GTK","en":"A GTK window"}','[{"t":"p","text":{"it":"**GTK** disegna le finestre di GNOME. Un’app parte da `Gtk.Application`; al segnale `activate` crea una `Gtk.ApplicationWindow` con dentro i widget, come `Gtk.Box`, `Gtk.Label` e `Gtk.Button`.","en":"**GTK** draws GNOME’s windows. An app starts from `Gtk.Application`; on the `activate` signal it creates a `Gtk.ApplicationWindow` holding widgets such as `Gtk.Box`, `Gtk.Label` and `Gtk.Button`."}},{"t":"code","code":"int main (string[] args) {\\n    var app = new Gtk.Application (\\"it.esempio.Contatore\\", ApplicationFlags.DEFAULT_FLAGS);\\n    app.activate.connect (() => {\\n        var n = 0;\\n        var etichetta = new Gtk.Label (\\"0\\");\\n        var bottone = new Gtk.Button.with_label (\\"Più uno\\");\\n        bottone.clicked.connect (() => etichetta.label = (++n).to_string ());\\n\\n        var box = new Gtk.Box (Gtk.Orientation.VERTICAL, 12);\\n        box.append (etichetta);\\n        box.append (bottone);\\n\\n        var finestra = new Gtk.ApplicationWindow (app) { title = \\"Contatore\\", child = box };\\n        finestra.present ();\\n    });\\n    return app.run (args);\\n}","lang":"vala"},{"t":"p","text":{"it":"Si compila con `valac --pkg gtk4 contatore.vala`. Per app complete GNOME usa **Meson** e **libadwaita**.","en":"You compile with `valac --pkg gtk4 contatore.vala`. For full apps GNOME uses **Meson** and **libadwaita**."}}]','{"lang":"vala","prompt":{"it":"Collega il bottone: `bottone.clicked.connect (() => print (\\"Clic!\\\\n\\"));`.","en":"Connect the button: `bottone.clicked.connect (() => print (\\"Clic!\\\\n\\"));`."},"start":"var bottone = new Gtk.Button.with_label (\\"Prova\\");","html":"","checks":[{"re":"bottone\\\\.clicked\\\\.connect\\\\s*\\\\(\\\\s*\\\\(\\\\s*\\\\)\\\\s*=>","label":{"it":"Ascolti il clic","en":"You listen to the click"}}],"hint":"bottone.clicked.connect (() => print (\\"Clic!\\\\n\\"));"}');
