INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'html-intermediate' AND slug = 'rich-text'),2,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"In HTML dieci spazi di fila si vedono come uno","en":"In HTML ten spaces in a row show as one"},true],[{"it":"`<pre>` usa di solito un carattere monospaziato","en":"`<pre>` usually uses a monospaced font"},true],[{"it":"`<abbr>` usa `title` per il significato","en":"`<abbr>` uses `title` for the meaning"},true],[{"it":"`<mark>` crea un link","en":"`<mark>` creates a link"},false],[{"it":"`<code>` esegue il codice","en":"`<code>` runs the code"},false]],"why":{"it":"Sono tag di significato: non eseguono nulla.","en":"They are tags of meaning: they run nothing."}}');
