INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'units'),1,'match','{"prompt":{"it":"Abbina ogni elemento al suo significato.","en":"Match each item with its meaning."},"pairs":[["px",{"it":"Fisso","en":"Fixed"}],["%",{"it":"Rispetto al contenitore","en":"Relative to the container"}],["rem",{"it":"Rispetto alla radice","en":"Relative to the root"}],["vw",{"it":"Rispetto allo schermo","en":"Relative to the screen"}],["em",{"it":"Rispetto al testo dell’elemento","en":"Relative to the element’s text"}]],"why":{"it":"Scegli l’unità in base a che cosa deve seguire la misura.","en":"Pick the unit by what the size should follow."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-base' AND slug = 'units'),2,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"`1rem` di solito vale 16px","en":"`1rem` is usually 16px"},true],[{"it":"`100vw` è tutta la larghezza dello schermo","en":"`100vw` is the full width of the screen"},true],[{"it":"`px` si adatta allo schermo","en":"`px` adapts to the screen"},false],[{"it":"`%` di un’altezza funziona sempre","en":"`%` of a height always works"},false]],"why":{"it":"Una percentuale d’altezza serve un genitore con altezza definita.","en":"A height percentage needs a parent with a defined height."}}');
INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-intermediate' AND slug = 'combinators'),1,'match','{"prompt":{"it":"Abbina ogni elemento al suo significato.","en":"Match each item with its meaning."},"pairs":[["a b",{"it":"`b` dentro `a`","en":"`b` inside `a`"}],["a > b",{"it":"`b` figlio diretto","en":"`b` direct child"}],["a + b",{"it":"`b` subito dopo","en":"`b` right after"}],["a ~ b",{"it":"`b` fratelli successivi","en":"`b` following siblings"}],["a, b",{"it":"Sia `a` che `b`","en":"Both `a` and `b`"}]],"why":{"it":"Un simbolo cambia tutto il significato.","en":"One symbol changes the whole meaning."}}');
