INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'css-animations' AND slug = 'timing'),2,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"`animation-delay` aspetta prima di partire","en":"`animation-delay` waits before starting"},true],[{"it":"`ease-out` accelera alla fine","en":"`ease-out` speeds up at the end"},false],[{"it":"`cubic-bezier` può creare un rimbalzo","en":"`cubic-bezier` can create a bounce"},true],[{"it":"`linear` è perfetta per ogni cosa","en":"`linear` is perfect for everything"},false]],"why":{"it":"Il movimento naturale raramente è lineare.","en":"Natural movement is rarely linear."}}');
