INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'scss' AND slug = 'architecture'),2,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"`_bottoni.scss` è un parziale","en":"`_bottoni.scss` is a partial"},true],[{"it":"Ogni parziale diventa un `.css`","en":"Every partial becomes a `.css`"},false],[{"it":"`@use` si scrive in cima al file","en":"`@use` goes at the top of the file"},true],[{"it":"Dividere i file rallenta il sito","en":"Splitting files slows the site down"},false]],"why":{"it":"Tanti file per chi scrive, uno solo per chi visita.","en":"Many files for the author, one for the visitor."}}');
