INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'php-intermediate' AND slug = 'pdo'),1,'bug','{"prompt":{"it":"Tocca la riga con l’errore.","en":"Tap the line with the mistake."},"lines":["$id = $_GET[\\"id\\"];","$st = $pdo->query(\\"SELECT * FROM utenti WHERE id = $id\\");","$riga = $st->fetch();"],"bug":1,"fix":"$st = $pdo->prepare(\\"SELECT * FROM utenti WHERE id = ?\\");","why":{"it":"Una variabile dentro la query apre alla SQL injection: serve `prepare`.","en":"A variable inside the query opens the door to SQL injection: use `prepare`."}}');
