INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'rust-intermediate' AND slug = 'traits'),1,'blanks','{"prompt":{"it":"Completa il codice con le tessere giuste.","en":"Complete the code with the right tiles."},"code":"___ Area { fn area(&self) -> f64; }\\nimpl Area ___ Quadrato {\\n    fn area(&self) -> f64 { self.lato * self.lato }\\n}\\nfn stampa<T: ___>(x: &T) { println!(\\"{}\\", x.area()); }","gaps":["trait","for","Area"],"extra":["interface","with","impl"],"why":{"it":"Definisci, implementa, vincola.","en":"Define, implement, bound."}}');
