INSERT INTO `fc_drills` (lesson_id, sort, kind, data) VALUES ((SELECT id FROM `fc_lessons` WHERE course = 'rust-advanced' AND slug = 'lifetimes'),2,'flash','{"prompt":{"it":"Vero o falso? Rispondi prima che scada il tempo!","en":"True or false? Answer before time runs out!"},"cards":[[{"it":"Un riferimento non può vivere più del valore","en":"A reference cannot outlive its value"},true],[{"it":"I lifetime cambiano la velocità del programma","en":"Lifetimes change the program’s speed"},false],[{"it":"Le struct con riferimenti hanno bisogno di lifetime","en":"Structs holding references need lifetimes"},true]],"why":{"it":"I lifetime sono solo controlli.","en":"Lifetimes are only checks."}}');
